window.__DICT_CHUNKS__=window.__DICT_CHUNKS__||{};window.__DICT_CHUNKS__["T"]={"6857":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiː ʃɜːt $ -ʃɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a soft shirt with short sleeves and no collar:</div><ul class=\"examples\"><li><em>She was wearing jeans and a T-shirt.</em></li></ul></div>","6858":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ta‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteɪbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[furniture]</strong> a piece of furniture with a flat top supported by legs: → coffee table, dressing table</div><ul class=\"examples\"><li><em>The food was served on long tables.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[restaurant]</strong> a table for people to eat at in a restaurant:</div><ul class=\"examples\"><li><em>I&#x27;ve booked a table for two.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[sport/game]</strong> <strong>snooker/billiard/ping-pong etc table</strong> a special table for playing a particular indoor sport or game on</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[list]</strong> a list of numbers, facts, or information arranged in rows across and down a page</div><ul class=\"examples\"><li><strong><em>table of</strong>: a table of results / the table of contents</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>on the table</strong> an offer, idea etc that is on the table has been officially suggested and someone is considering it:</div><ul class=\"examples\"><li><em>The offer on the table is a 10% wage increase.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>turn the tables (on somebody)</strong> to change a situation completely, so that someone loses an advantage and you gain one:</div><ul class=\"examples\"><li><em>The tables were turned in the second half, when Leeds United scored from the penalty spot.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>under the table</strong> <em>informal</em> money that is paid under the table is paid secretly and illegally:</div><ul class=\"examples\"><li><em>Payments were made under the table to local officials.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[maths]</strong> <strong>times table</strong> a list that young children learn, in which all the numbers between 1 and 12 are multiplied by each other <em>SYN multiplication table</em></div><ul class=\"examples\"><li><strong><em>three/four etc times table</strong>: He’s 12 years old and still doesn’t know his three times table.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[group]</strong> the group of people sitting around a table:</div><ul class=\"examples\"><li><em>His stories kept the whole table amused.</em></li></ul></div>","6859":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ta‧ble‧spoon</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteɪbəlspuːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large spoon used for serving food</div><div class=\"sense\"><span class=\"snum\">2</span> (also ta‧ble‧spoon‧ful /-spuːnfʊl/) (written abbreviation tbsp or tbs) the amount that a tablespoon can hold, used as a unit for measuring food or liquid in cooking</div><ul class=\"examples\"><li><strong><em>tablespoon of</strong>: two tablespoons of flour</em></li></ul></div>","6860":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tab‧let</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtæblɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small round hard piece of medicine which you swallow <em>SYN pill</em>:</div><ul class=\"examples\"><li><em>She took a couple of headache tablets.</em></li><li><strong><em>vitamin/sleeping/indigestion etc tablet</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a small hard piece of a substance, especially one that dissolves in water:</div><ul class=\"examples\"><li><em>water purification tablets</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a flat piece of stone or clay with words cut into it, for example above someone’s grave</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>be written/set/cast in tablets of stone</strong> <em>British English</em> used to say that something does not change:</div><ul class=\"examples\"><li><em>The programme should not be set in tablets of stone, but improved continuously.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>American English</em> a set of pieces of paper for writing on that are glued together at the top SYN pad<em>British English</em></div><div class=\"sense\"><span class=\"snum\">6</span> (also tablet computer) a computer that you can carry with you which has a touch screen and does not have a separate keyboard</div></div>","6861":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tack‧le</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtækəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to try to deal with a difficult problem: ► see thesaurus at deal</div><ul class=\"examples\"><li><em>There is more than one way to tackle the problem.</em></li><li><em>It took twelve fire engines to tackle the blaze.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to try to take the ball away from an opponent in a game such as football or hockey</div><div class=\"subsense\"><span class=\"subnum\">b)</span> to force someone to the ground so that they stop running, in a game such as American football or rugby</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> <em>British English</em> to talk to someone in order to deal with a difficult problem</div><ul class=\"examples\"><li><strong><em>tackle somebody about something</strong>: When I tackled Susan about it, she admitted she’d made a mistake.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to start fighting someone, especially a criminal:</div><ul class=\"examples\"><li><em>I certainly couldn’t tackle both of them on my own.</em></li></ul></div>","6862":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tækt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the ability to be careful about what you say or do, so that you do not upset or embarrass other people → tactful, tactless:</div><ul class=\"examples\"><li><em>With great tact, Clive persuaded her to apologize.</em></li></ul></div>","6863":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tac‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtæktɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a method that you use to achieve something:</div><ul class=\"examples\"><li><em>a tactic employed to speed up the peace process</em></li><li><em>Republicans accuse Democrats of using delaying tactics (=something you do in order to give yourself more time) to prevent a final vote on the bill.</em></li><li><em>Shock tactics are being used in an attempt to stop drink drivers.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>tactics</strong> <span class=\"gram\">[plural]</span> the science of arranging and moving military forces in a battle</div></div>","6864":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tac‧tic‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtæktɪkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to what you do to achieve what you want, especially as part of a game or large plan:</div><ul class=\"examples\"><li><em>Two players were substituted for tactical reasons.</em></li><li><strong><em>tactical move/decision/ploy</strong>: a tactical decision to send in troops</em></li><li><strong><em>tactical error/mistake/blunder</strong> (=a mistake that will harm your plans later)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>tactical weapon/missile</strong> a missile that is sent a short distance in military battle</div><div class=\"sense\"><span class=\"snum\">3</span> relating to the way military forces are arranged in a battle</div></div>","6865":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tæɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[small piece of paper etc]</strong> <span class=\"gram\">[countable]</span> a small piece of paper, plastic etc attached to something to show what it is, who owns it, what it costs etc → dog tag</div><ul class=\"examples\"><li><strong><em>name/identity/price tag</strong>: All the staff wore name tags.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[game]</strong> <span class=\"gram\">[uncountable]</span> a children’s game in which one player chases and tries to touch the others</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[electronic object]</strong> (also electronic tag) <span class=\"gram\">[countable]</span> <em>British English</em> a piece of equipment that you attach to an animal or person, especially someone who has just left prison, so that you always know where they are</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[computer]</strong> <span class=\"gram\">[countable]</span> a computer code attached to a word or phrase in a computer document in order to arrange the data in a particular way</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[name]</strong> <span class=\"gram\">[countable]</span> a word or phrase which is used to describe a person, group, or thing, but which is often unfair or not correct:</div><ul class=\"examples\"><li><em>His speed earned him the tag of ‘the runner’.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[grammar]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> a tag question</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[name painted on wall]</strong> <span class=\"gram\">[countable]</span> <em>especially American English</em> <em>informal</em> someone’s name that they paint illegally on a wall, vehicle etc</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[car]</strong> <em>American English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>tags</strong> <span class=\"gram\">[plural]</span> <em>informal</em> the license plates on a car</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> a small piece of sticky plastic with a date on it that you put on your car’s license plate to show that the car is legally allowed on the road in that year</div></div>","6866":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /teɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[animal]</strong> the part that sticks out at the back of an animal’s body, and that it can move:</div><ul class=\"examples\"><li><em>The dog wagged its tail.</em></li><li><strong><em>white-tailed/long-tailed etc</strong>: a white-tailed eagle</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[aircraft]</strong> the back part of an aircraft</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[shirt]</strong> the bottom part of your shirt at the back, that you put inside your trousers</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[back part]</strong> <span class=\"gram\">[usually singular]</span> the back or last part of something, especially something that is moving away from you:</div><ul class=\"examples\"><li><em>We saw the tail of the procession disappearing round the corner.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>tails</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[plural]</span> a man’s jacket which is short at the front and divides into two long pieces at the back, worn to very formal events <em>SYN tailcoat</em></div><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[uncountable]</span> <em>spoken</em> said when you are tossing a coin (=throwing it up in the air to decide which of two things you will do or choose) <em>OPP heads</em></div><div class=\"sense\"><span class=\"snum\">6</span> <strong>the tail end of something</strong> the last part of an event, situation, or period of time</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>be on somebody’s tail</strong> <em>informal</em> to be following someone closely</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[follow]</strong> <em>informal</em> someone who is employed to watch and follow someone, especially a criminal</div><ul class=\"examples\"><li><strong><em>put a tail on somebody</strong> (=order someone to follow another person)</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>turn tail</strong> <em>informal</em> to run away because you are too frightened to fight or attack</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>with your tail between your legs</strong> embarrassed or unhappy because you have failed or been defeated</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>it’s (a case of) the tail wagging the dog</strong> <em>informal</em> used to say that an unimportant thing is wrongly controlling a situation</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>chase tail</strong> <em>American English</em> <em>informal</em> to try to get a woman to have sex with you</div></div>","6867":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tai‧lor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteɪlə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make something so that it is exactly right for someone’s particular needs or for a particular purpose</div><ul class=\"examples\"><li><strong><em>tailor something to something</strong>: Treatment is tailored to the needs of each patient.</em></li><li><strong><em>tailor something to meet/suit somebody’s needs/requirements</strong>: The classes are tailored to suit learners’ needs.</em></li><li><strong><em>tailor something for somebody</strong>: We tailored the part specifically for her.</em></li></ul></div>","6868":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /teɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense took /tʊk/, past participle taken /ˈteɪkən/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[move]</strong> <span class=\"gram\">[transitive]</span> to move or go with someone or something from one place to another <em>OPP bring</em> ► see thesaurus at bring, lead</div><ul class=\"examples\"><li><strong><em>take somebody/something to/into etc something</strong>: Barney took us to the airport. / Would you mind taking Susie home? / When he refused to give his name, he was taken into custody. / My job has taken me all over the world.</em></li><li><strong><em>take somebody/something with you</strong>: His wife went to Australia, taking the children with her.</em></li><li><strong><em>take somebody something</strong>: I have to take Steve the money tonight.</em></li><li><strong><em>take somebody to do something</strong>: He took me to meet his parents.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[action]</strong> <span class=\"gram\">[transitive]</span> used with a noun instead of using a verb to describe an action. For example, if you take a walk, you walk somewhere:</div><ul class=\"examples\"><li><em>Would you like to take a look?</em></li><li><em>Mike’s just taking a shower.</em></li><li><em>Sara took a deep breath.</em></li><li><em>I waved, but he didn’t take any notice (=pretended not to notice).</em>British English**</li><li><em>Please take a seat (=sit down).</em></li><li><strong><em>take a picture/photograph/photo</strong>: Would you mind taking a photo of us together?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[remove]</strong> <span class=\"gram\">[transitive]</span> to remove something from a place → take ► see thesaurus at steal</div><ul class=\"examples\"><li><strong><em>take something off/from etc something</strong>: Take your feet off the seats. / Someone’s taken a pen from my desk.</em></li><li><em>Police say money and jewellery were taken in the raid.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[time/money/effort etc]</strong> <span class=\"gram\">[transitive]</span> if something takes a particular amount of time, money, effort etc, that amount of time etc is needed for it to happen or succeed:</div><ul class=\"examples\"><li><em>How long is this going to take?</em></li><li><em>Organizing a successful street party takes a lot of energy.</em></li><li><strong><em>take (somebody) something (to do something)</strong>: Repairs take time to carry out. / It took a few minutes for his eyes to adjust to the dark.</em></li><li><strong><em>take (somebody) ages/forever<em>informal</em></strong>: It took me ages to find a present for Dad.</em></li><li><strong><em>take some doing<em>British English</em></strong> </em>informal<em> (=need a lot of time or effort): Catching up four goals will take some doing.</em></li><li><strong><em>take courage/guts</strong>: It takes courage to admit you are wrong.</em></li><li><strong><em>have what it takes<em>informal</em></strong> (=to have the qualities that are needed for success): Neil’s got what it takes to be a great footballer.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[accept]</strong> <span class=\"gram\">[transitive]</span> to accept or choose something that is offered, suggested, or given to you:</div><ul class=\"examples\"><li><em>Will you take the job?</em></li><li><em>Do you take American Express?</em></li><li><em>If you take my advice, you’ll see a doctor.</em></li><li><em>Our helpline takes 3.5 million calls (=telephone calls) a year.</em></li><li><em>Some doctors are unwilling to take new patients without a referral.</em></li><li><em>Liz found his criticisms hard to take.</em></li><li><em>I just can’t take any more (=can’t deal with a bad situation any longer).</em></li><li><em>Staff have agreed to take a 2% pay cut.</em></li><li><strong><em>take a hammering/beating</strong> (=be forced to accept defeat or a bad situation): Small businesses took a hammering in the last recession.</em></li><li><strong><em>I take your point/point taken</strong> (=used to say that you accept someone’s opinion)</em></li><li><strong><em>take somebody’s word for it/take it from somebody</strong> (=accept that what someone says is true): That’s the truth – take it from me.</em></li><li><strong><em>take the credit/blame/responsibility</strong>: He’s the kind of man who makes things happen but lets others take the credit.</em></li><li><strong><em>take it as read/given</strong> (=assume that something is correct or certain, because you are sure that this is the case): It isn’t official yet, but you can take it as read that you’ve got the contract.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[hold something]</strong> <span class=\"gram\">[transitive]</span> to get hold of something in your hands:</div><ul class=\"examples\"><li><em>Let me take your coat.</em></li><li><em>Can you take this package while I get my wallet?</em></li><li><strong><em>take somebody/something in/by something</strong>: I just wanted to take him in my arms.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[travel]</strong> <span class=\"gram\">[transitive]</span> to use a particular form of transport or a particular road in order to go somewhere:</div><ul class=\"examples\"><li><em>Let’s take a cab.</em></li><li><em>I took the first plane out.</em></li><li><em>Take the M6 to Junction 19.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[study]</strong> <span class=\"gram\">[transitive]</span> to study a particular subject in school or college for an examination: ► see thesaurus at study</div><ul class=\"examples\"><li><em>Are you taking French next year?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[test]</strong> <span class=\"gram\">[transitive]</span> to do an examination or test SYN sit<em>British English</em>:</div><ul class=\"examples\"><li><em>Applicants are asked to take a written test.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[suitable]</strong> <span class=\"gram\">[transitive]</span> to be the correct or suitable size, type etc for a particular person or thing: GRAMMAR: Using the progressiveIn this meaning, take is not used in the progressive. You say: · I take size 12. ✗Don’t say: I’m taking size 12.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><em>a car that takes low sulphur fuel</em></li><li><em>What size shoe do you take?</em></li><li><em>The elevator takes a maximum of 32 people.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[collect]</strong> <span class=\"gram\">[transitive]</span> to collect or gather something for a particular purpose:</div><ul class=\"examples\"><li><em>Investigators will take samples of the wreckage to identify the cause.</em></li><li><strong><em>take something from something</strong>: The police took a statement from both witnesses.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[consider]</strong> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> to react to someone or something or consider them in a particular way</div><ul class=\"examples\"><li><strong><em>take somebody/something seriously/badly/personally etc</strong>: I was joking, but he took me seriously. / Ben took the news very badly.</em></li><li><em>She does not take kindly to criticism (=reacts badly to criticism).</em></li><li><strong><em>take something as something</strong>: I’ll take that remark as a compliment.</em></li><li><strong><em>take something as evidence/proof (of something)</strong>: The presence of dust clouds has been taken as evidence of recent star formation.</em></li><li><strong><em>take somebody/something to be something</strong>: I took her to be his daughter.</em></li><li><strong><em>take somebody/something for something</strong>: Of course I won’t tell anyone! What do you take me for? (=what sort of person do you think I am?)</em></li><li><em>I take it (=I assume) you’ve heard that Rick’s resigned.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[feelings]</strong> <span class=\"gram\">[transitive usually + adverb]</span> to have or experience a particular feeling</div><ul class=\"examples\"><li><strong><em>take delight/pleasure/pride etc in (doing) something</strong>: You should take pride in your work. / At first, he took no interest in the baby.</em></li><li><strong><em>take pity on somebody</strong>: She stood feeling lost until an elderly man took pity on her.</em></li><li><strong><em>take offence</strong> (=feel offended): Don’t take offence. Roger says things like that to everybody.</em></li><li><strong><em>take comfort from/in (doing) something</strong>: Investors can take comfort from the fact that the World Bank is underwriting the shares.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[control]</strong> <span class=\"gram\">[transitive]</span> to get possession or control of something:</div><ul class=\"examples\"><li><em>Enemy forces have taken the airport.</em></li><li><em>Both boys were taken prisoner.</em></li><li><strong><em>take control/charge/power</strong>: The communists took power in 1948. / Youngsters need to take control of their own lives.</em></li><li><strong><em>take the lead</strong> (=in a race, competition etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[medicine/drugs]</strong> <span class=\"gram\">[transitive]</span> to swallow, breathe in, inject etc a drug or medicine:</div><ul class=\"examples\"><li><em>The doctor will ask whether you are taking any medication.</em></li><li><em>Take two tablets before bedtime.</em></li><li><strong><em>take drugs</strong> (=take illegal drugs): Most teenagers start taking drugs through boredom.</em></li><li><em>She took an overdose after a row with her boyfriend.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>do you take sugar/milk?</strong> <em>British English</em> <em>spoken</em> used to ask someone whether they like to have sugar or milk in a drink such as tea or coffee</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>[level]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to make someone or something go to a higher level or position</div><ul class=\"examples\"><li><strong><em>take something to/into something</strong>: The latest raise takes his salary into six figures.</em></li><li><em>Even if you have the talent to take you to the top, there’s no guarantee you’ll get there.</em></li><li><em>If you want to take it further, you should consult an attorney.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>[measure]</strong> <span class=\"gram\">[transitive]</span> to measure the amount, level, rate etc of something:</div><ul class=\"examples\"><li><em>Take the patient’s pulse first.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>[numbers]</strong> <span class=\"gram\">[transitive]</span> to make a number smaller by a particular amount <em>SYN subtract</em></div><ul class=\"examples\"><li><strong><em>take something away/take something (away) from something</strong>: ‘Take four from nine and what do you get?’ ‘Five.’ / Ten take away nine equals one.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>[money]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> if a shop, business etc takes a particular amount of money, it receives that amount of money from its customers SYN take in<em>American English</em>:</div><ul class=\"examples\"><li><em>The stall took £25 on Saturday.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>somebody can take it or leave it</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to neither like nor dislike something:</div><ul class=\"examples\"><li><em>To some people, smoking is addictive. Others can take it or leave it.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that you do not care whether someone accepts your offer or not</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>take somebody/something (for example)</strong> used to give an example of something you have just been talking about: ► see thesaurus at example</div><ul class=\"examples\"><li><em>People love British cars. Take the Mini. In Japan, it still sells more than all the other British cars put together.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>[teach]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> to teach a particular group of students in a school or college</div><ul class=\"examples\"><li><strong><em>take somebody for something</strong>: Who takes you for English?</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>[write]</strong> <span class=\"gram\">[transitive]</span> to write down information:</div><ul class=\"examples\"><li><em>Let me take your email address.</em></li><li><em>Sue offered to take notes.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>take somebody out of themselves</strong> <em>British English</em> to make someone forget their problems and feel more confident:</div><ul class=\"examples\"><li><em>Alf said joining the club would take me out of myself.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>take a lot out of you/take it out of you</strong> to make you very tired:</div><ul class=\"examples\"><li><em>Looking after a baby really takes it out of you.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>take it upon/on yourself to do something</strong> <em>formal</em> to decide to do something without getting someone’s permission or approval first:</div><ul class=\"examples\"><li><em>Reg took it upon himself to hand the press a list of names.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>take something to bits/pieces</strong> <em>British English</em> to separate something into its different parts:</div><ul class=\"examples\"><li><em>how to take an engine to bits</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>be taken with/by something</strong> to be attracted by a particular idea, plan, or person:</div><ul class=\"examples\"><li><em>I’m quite taken by the idea of Christmas in Berlin.</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>be taken ill/sick</strong> <em>formal</em> to suddenly become ill</div><div class=\"sense\"><span class=\"snum\">31</span> <strong>[sex]</strong> <span class=\"gram\">[transitive]</span> <em>literary</em> if a man takes someone, he has sex with them</div><div class=\"sense\"><span class=\"snum\">32</span> <strong>take a bend/fence/corner etc</strong> to try to get over or around something in a particular way:</div><ul class=\"examples\"><li><em>He took the bend at over 60 and lost control.</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>[have an effect]</strong> <span class=\"gram\">[intransitive]</span> if a treatment, dye, drug etc takes, it begins to work successfully</div></div>","6869":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> take‧o‧ver</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteɪkˌəʊvə $ -ˌoʊvər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when one company takes control of another by buying more than half its shares:</div><ul class=\"examples\"><li><em>Thornbury has announced a takeover bid of a regional TV company.</em></li><li><em>He prevented a hostile takeover (=when the takeover is not wanted by the company being bought) of the company.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an act of getting control of a country or political organization, using force:</div><ul class=\"examples\"><li><em>a communist takeover</em></li></ul></div>","6870":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /teɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a story about exciting imaginary events ► see thesaurus at story</div><ul class=\"examples\"><li><strong><em>tale of</strong>: tales of adventure</em></li><li><em>a book of old Japanese folk tales (=traditional stories)</em></li><li><em>a fairy tale by Hans Christian Andersen</em></li><li><em>a cautionary tale (=one that is told to warn people about the dangers of something)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a description of interesting or exciting things that happened to someone, often one which is not completely true about every detail</div><ul class=\"examples\"><li><strong><em>tale of/about</strong>: tales of her life in post-war Berlin</em></li><li><strong><em>tale of/about how</strong>: He was in the middle of telling me a long tale about how he once met Bob Dylan.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>tell tales</strong> <em>British English</em> to tell someone in authority about something wrong that someone else has done SYN tattle<em>American English</em></div><ul class=\"examples\"><li><strong><em>tale to</strong>: Don’t go telling tales to the teacher!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>tale of woe</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a description of events that made you unhappy</div><div class=\"subsense\"><span class=\"subnum\">b)</span> a series of bad things that happened to someone:</div><ul class=\"examples\"><li><em>The England team’s tale of woe continued, and they lost the next three games.</em></li></ul></div>","6871":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tal‧ent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtælənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a natural ability to do something well: ► see thesaurus at skill</div><ul class=\"examples\"><li><em>He has a lot of talent, and his work is fresh and interesting.</em></li><li><strong><em>talent for</strong>: She showed a talent for acting at an early age.</em></li><li><em>a persuasive speaker with a natural talent for leadership</em></li><li><em>His latest book reveals hidden talents.</em></li><li><em>Sadly, she inherited none of her father’s musical talent.</em></li><li><em>Your brother is a man of many talents.</em></li><li><em>There’s a wealth of talent in English football.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a person or people with a natural ability or skill:</div><ul class=\"examples\"><li><em>Britain’s footballing talent</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>British English</em> <em>informal</em> sexually attractive people</div></div>","6872":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tal‧ent‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtæləntɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">having a natural ability to do something well → gifted: ► see thesaurus at skilful</div><ul class=\"examples\"><li><em>a talented actor</em></li></ul></div>","6873":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɔːk $ tɒːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[conversation]</strong> <span class=\"gram\">[intransitive]</span> to say things to someone as part of a conversation:</div><ul class=\"examples\"><li><em>I could hear Sarah and Andy talking in the next room.</em></li><li><strong><em>talk about</strong>: English people love to talk about the weather. / All through the afternoon, they sat and talked about their trip.</em></li><li><strong><em>talk to</strong>: She spent a long time talking to him. / She’s very easy to talk to.</em></li><li><strong><em>talk with</strong>: I got the truth from talking with Elena.</em></li><li><strong><em>talk together</strong>: They were talking together in the hall.</em></li><li><em>Sue and Bob still aren’t talking (=are refusing to talk to each other).</em></li><li><strong><em>talk in a low voice/a whisper etc</strong>: They were talking in low voices, and I couldn’t catch what they were saying.</em></li><li><strong><em>talk of</strong> (=used especially in formal or literary contexts): We talked of old times.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[serious subject]</strong> <span class=\"gram\">[intransitive, transitive]</span> to discuss something serious or important with someone: RegisterIn written English, people usually say that they are going to discuss, deal with, or address a subject rather than talk about it:· In this essay I will discuss the problem of over-population.</div><ul class=\"examples\"><li><em>Joe, we need to talk.</em></li><li><em>Is there somewhere we can talk in private?</em></li><li><strong><em>talk to</strong>: You should talk to a lawyer.</em></li><li><strong><em>talk about</strong>: We’ve been talking about getting married.</em></li><li><strong><em>talk with</strong>: Parents should talk with their children about drug abuse.</em></li><li><strong><em>talk sport/politics/business etc</strong>: ‘Let’s not talk politics now,’ said Hugh impatiently.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[say words]</strong> <span class=\"gram\">[intransitive]</span> to produce words and express thoughts, opinions, ideas etc:</div><ul class=\"examples\"><li><em>She was talking so fast I could hardly understand her.</em></li><li><em>How do babies learn to talk?</em></li><li><em>Some residents were frightened to talk publicly.</em></li><li><strong><em>talk (in) French/German etc</strong>: They started talking in Spanish.</em></li><li><em>Don’t let Dad hear you talking like that (=expressing things in a particular way).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[a speech]</strong> <span class=\"gram\">[intransitive]</span> to give a speech</div><ul class=\"examples\"><li><strong><em>talk on/about</strong>: Professor Davis will talk about ‘Trends in Network Computing’.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[secret information]</strong> <span class=\"gram\">[intransitive]</span> if someone who has secret information talks, they tell someone else about it:</div><ul class=\"examples\"><li><em>Even under torture, Maskell refused to talk.</em></li><li><em>He tried to stop his ex-wife from talking on live TV.</em></li><li><em>We should stop meeting like this. People will talk.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>talk sense/rubbish/nonsense etc</strong> <em>spoken</em> used to say that you think someone is saying something sensible, something stupid etc:</div><ul class=\"examples\"><li><em>You do talk rubbish sometimes, Jules.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>talk (some) sense into somebody</strong> to persuade someone to behave sensibly:</div><ul class=\"examples\"><li><em>She hoped Father McCormack would be able to talk some sense into her son.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>talk to yourself</strong> to say your thoughts out loud:</div><ul class=\"examples\"><li><em>‘What did you say?’ ‘Sorry, I was just talking to myself.’</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>know what you are talking about</strong> <em>spoken</em> to know a lot about a particular subject:</div><ul class=\"examples\"><li><em>I worked in hotels for years, so I know what I’m talking about.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>talk the hind leg(s) off a donkey</strong> <em>informal</em> to talk a lot, especially about unimportant things</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>talk about lazy/cheap/hungry etc</strong> <em>spoken</em> used to emphasize that someone or something is very lazy, cheap, hungry etc:</div><ul class=\"examples\"><li><em>Talk about lucky. That’s the second time he’s won this week!</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>talking of/about something</strong> <em>spoken</em> used to say more about a subject that someone has just mentioned:</div><ul class=\"examples\"><li><em>Talking of Venice, have you seen the masks I bought there last year?</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>what are you talking about?</strong> <em>spoken</em> used when you think what someone has said is stupid or wrong:</div><ul class=\"examples\"><li><em>What are you talking about? We got there in plenty of time.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>I’m talking to you!</strong> <em>spoken</em> used when you are angry that the person you are talking to is not paying attention:</div><ul class=\"examples\"><li><em>Rob! I’m talking to you!</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>be like talking to a brick wall</strong> <em>spoken</em> used to say that it is annoying to speak to someone because they do not pay attention to you</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>talk somebody’s ear off</strong> <em>American English</em> <em>spoken</em> to talk too much to someone</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>talk trash</strong> <em>American English</em> <em>informal</em> to say rude or offensive things to or about someone, especially to opponents in a sports competition:</div><ul class=\"examples\"><li><em>Both teams were talking trash on the court.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>talk the talk</strong> <em>American English</em> <em>informal</em> to say the things that people expect or think are necessary in a particular situation: → walk the walk at walk1(12)</div><ul class=\"examples\"><li><em>She didn’t talk the talk of feminism, but her career was the most important thing in her life.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>I’m/we’re/you’re talking (about) something</strong> <em>spoken</em> used in conversation to emphasize a fact or remind someone of it:</div><ul class=\"examples\"><li><em>I’m not talking about ancient history, I’m talking about last season’s performance.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>now you’re talking</strong> <em>spoken</em> used to say that you think someone’s suggestion is a good idea:</div><ul class=\"examples\"><li><em>‘Fancy an ice cream?’ ‘Now you’re talking.’</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>look who’s talking,</strong> (also you’re a fine one to talk, you can talk) <em>spoken</em> used to tell someone they should not criticize someone else’s behaviour because their own behaviour is just as bad:</div><ul class=\"examples\"><li><em>‘Peggy shouldn’t smoke so much.’ ‘Look who’s talking!’</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>we’re/you’re talking £500/three days etc</strong> <em>spoken</em> used to tell someone how much something will cost, how long something will take to do etc:</div><ul class=\"examples\"><li><em>To do a proper job, you’re talking £750 minimum.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>talk your way out of something</strong> <em>informal</em> to escape from a bad or embarrassing situation by giving explanations, excuses etc:</div><ul class=\"examples\"><li><em>She’s good at talking her way out of trouble.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>talk nineteen to the dozen</strong> <em>British English</em> <em>informal</em>, talk a blue streak<em>American English</em> <em>informal</em> to talk very quickly without stopping</div><div class=\"sense\"><span class=\"snum\">25</span> <strong>talk in riddles</strong> to deliberately talk in a strange and confusing way:</div><ul class=\"examples\"><li><em>Stop talking in riddles and explain what’s going on.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>talk tough (on something)</strong> <em>informal</em> to give people your opinions very strongly:</div><ul class=\"examples\"><li><em>The president is talking tough on crime.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>talk shop</strong> if people talk shop, they talk about their work when there are people present who are not interested or involved in it – used to show disapproval:</div><ul class=\"examples\"><li><em>Are you two going to talk shop all night?</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>talk dirty (to somebody)</strong> <em>informal</em> to talk in a sexual way to someone in order to make them feel sexually excited</div><div class=\"sense\"><span class=\"snum\">29</span> <strong>be talking through your hat</strong> <em>British English</em> <em>informal</em> if someone is talking through their hat, they say stupid things about something that they do not understand</div><div class=\"sense\"><span class=\"snum\">30</span> <strong>talk smack</strong> <em>American English</em> <em>informal</em> to criticize someone or something in an unpleasant way</div><div class=\"sense\"><span class=\"snum\">31</span> <strong>talk to the hand</strong> <em>spoken</em> <em>informal</em> used to tell someone rudely that you do not want to listen to anything he or she is going to say to you. When people use this expression, they also usually turn their face away from the other person and hold the palm of their hand out towards them.</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[conversation]</strong> <span class=\"gram\">[countable]</span> a conversation:</div><ul class=\"examples\"><li><em>After a long talk, we decided on divorce.</em></li><li><em>John, I’d like to have a talk with you.</em></li><li><strong><em>talk about</strong>: We must have a talk about money.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[discussion]</strong> <strong>talks</strong> <span class=\"gram\">[plural]</span> formal discussions between governments, organizations etc</div><ul class=\"examples\"><li><strong><em>peace/trade etc talks</strong>: The peace talks look promising.</em></li><li><em>The president held talks with Chinese officials.</em></li><li><strong><em>talk with</strong>: Talks with the rebels have failed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[speech]</strong> <span class=\"gram\">[countable]</span> a speech: ► see thesaurus at speech</div><ul class=\"examples\"><li><em>an entertaining talk</em></li><li><strong><em>talk on/about</strong>: a talk on local history</em></li><li><strong><em>give/do/deliver a talk</strong>: Dr Howard will give a talk on herbal medicine.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[news]</strong> <span class=\"gram\">[uncountable]</span> information or news that people talk about and hear about a lot, but that is not official</div><ul class=\"examples\"><li><strong><em>talk of</strong>: Tickets sold so quickly there’s talk of a second concert.</em></li><li><strong><em>talk of doing something</strong>: the administration’s talk of reducing weapons</em></li><li><strong><em>talk that</strong>: There’s talk that she’s difficult to work with.</em></li><li><strong><em>just/only talk</strong>: It’s just talk. He’ll never do it.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[type of conversation]</strong> <span class=\"gram\">[uncountable]</span> type of conversation:</div><ul class=\"examples\"><li><em>That’s enough of that kind of talk.</em></li><li><em>persuasive sales talk</em></li><li><em>That’s fighting talk (=brave and confident words) from Italy’s manager.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be all talk</strong> <em>spoken</em> someone who is all talk talks a lot about what they intend to do, but never actually does it</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>be the talk of the town/Paris etc</strong> someone who is the talk of the town has done something bad, shocking, exciting etc and everyone is talking about them:</div><ul class=\"examples\"><li><em>She’s the talk of London’s theatre-goers since her last performance.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>talk is cheap</strong> used to say that you do not believe someone will do what they say</div></div></div>","6874":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> talk‧a‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɔːkətɪv $ ˈtɒːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">someone who is talkative talks a lot <em>OPP quiet</em></div></div>","6875":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɔːl $ tɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(comparative taller, superlative tallest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a person, building, tree etc that is tall is a greater height than normal: ► see thesaurus at high</div><ul class=\"examples\"><li><em>He was young and tall.</em></li><li><em>a house surrounded by tall trees</em></li><li><em>This bush grows tall very quickly.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> you use ‘tall’ to say or ask what the height of something or someone is</div><ul class=\"examples\"><li><strong><em>6ft/2m/12 inches etc tall</strong>: He’s only 5 feet tall.</em></li><li><em>How tall is that building?</em></li><li><em>She’s a little taller than her sister.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> a tall drink contains a small amount of alcohol mixed with a large amount of a non-alcoholic drink</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>a tall order</strong> <em>informal</em> a request or piece of work that is almost impossible:</div><ul class=\"examples\"><li><em>Finding a replacement is going to be a tall order.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>tall story/tale</strong> a story that is so unlikely that it is difficult to believe</div></div>","6876":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tan‧gi‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtændʒəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> clear enough or definite enough to be easily seen or noticed <em>OPP intangible</em>:</div><ul class=\"examples\"><li><em>The scheme must have tangible benefits for the unemployed.</em></li><li><strong><em>tangible evidence/proof</strong>: He has no tangible evidence of John’s guilt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>tangible assets/property</strong> property such as buildings, equipment etc</div><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> if something is tangible, you can touch or feel it:</div><ul class=\"examples\"><li><em>The silence of the countryside was almost tangible.</em></li></ul></div>","6877":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tæŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large container for storing liquid or gas:</div><ul class=\"examples\"><li><em>The water tank is leaking.</em></li><li><em>Somehow the chemical got from a storage tank into water supplies.</em></li><li><strong><em>fish/marine/breeding tank</strong> (=for keeping or breeding fish in)</em></li><li><em>the plane’s fuel tank</em></li><li><strong><em>petrol tank<em>British English,</em></strong> <strong>gas tank</em>American English</strong>**</li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also tankful) the amount of liquid or gas held in a tank:</div><ul class=\"examples\"><li><em>We set off next day on a full tank.</em></li><li><strong><em>tank of</strong>: a tankful of petrol</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a heavy military vehicle that has a large gun and runs on two metal belts fitted over its wheels</div><div class=\"sense\"><span class=\"snum\">4</span> a large artificial pool for storing water</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>in the tank</strong> <em>American English</em> <em>informal</em> failing and losing money</div><ul class=\"examples\"><li><strong><em>be/go in the tank</strong>: Sales can’t keep going up, but that doesn’t mean the industry is going in the tank.</em></li></ul></div>","6878":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tæp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[water/gas]</strong> <span class=\"gram\">[countable]</span> <em>especially British English</em> a piece of equipment for controlling the flow of water, gas etc from a pipe or container SYN faucet<em>American English</em>:</div><ul class=\"examples\"><li><em>Tap water (=water that comes out of a tap) is usually heavily treated with chemicals.</em></li><li><em>She went into the bathroom and turned on the taps.</em></li><li><strong><em>kitchen/bath/garden tap</strong>: I washed my hands under the kitchen tap.</em></li><li><strong><em>cold/hot tap</strong> (=the tap that cold or hot water comes from)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[a light hit]</strong> <span class=\"gram\">[countable]</span> an act of hitting something lightly, especially to get someone’s attention</div><ul class=\"examples\"><li><strong><em>tap at/on</strong>: She felt a tap on her shoulder. / There was a tap at the door.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on tap</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> beer that is on tap comes from a barrel</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>informal</em> something that is on tap is ready to use when you need it:</div><ul class=\"examples\"><li><em>We’ve got all the information on tap.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[dancing]</strong> <span class=\"gram\">[uncountable]</span> (also tap dancing) dancing in which you wear special shoes with pieces of metal on the bottom which make a loud sharp sound on the floor</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[telephone]</strong> <span class=\"gram\">[countable]</span> an act of secretly listening to someone’s telephone, using electronic equipment:</div><ul class=\"examples\"><li><em>The police had put a tap on his phone line.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[barrel]</strong> <span class=\"gram\">[countable]</span> a specially shaped object used for letting liquid out of a barrel, especially beer</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[tune]</strong> <strong>taps</strong> <span class=\"gram\">[plural]</span> a song or tune played on the bugle at night in an army camp, and at military funerals</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle tapped, present participle tapping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[hit lightly]</strong> <span class=\"gram\">[intransitive, transitive]</span> to hit your fingers lightly on something, for example to get someone’s attention ► see thesaurus at hit</div><ul class=\"examples\"><li><strong><em>tap somebody on the shoulder/arm/chest etc</strong>: He turned as someone tapped him on the shoulder.</em></li><li><strong><em>tap on</strong>: I went up and tapped on the window.</em></li><li><strong><em>tap something on/against/from etc something</strong>: Mark tapped his fingers on the tabletop impatiently. / She tapped ash from her cigarette.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[music]</strong> <span class=\"gram\">[transitive]</span> to make a regular pattern of sounds with your fingers or feet, especially when you are listening to music:</div><ul class=\"examples\"><li><em>She tapped her feet in time to the music.</em></li><li><em>a toe-tapping tune</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[energy/money]</strong> <span class=\"gram\">[transitive]</span> (also tap into) to use or take what is needed from something such as an energy supply or an amount of money:</div><ul class=\"examples\"><li><em>People are tapping into the power supply illegally.</em></li><li><em>We hope that additional sources of funding can be tapped.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[ideas]</strong> <span class=\"gram\">[transitive]</span> (also tap into) to make as much use as possible of the ideas, experience, knowledge etc that a group of people has:</div><ul class=\"examples\"><li><em>Your adviser’s experience is there to be tapped.</em></li><li><em>helping people tap into training opportunities</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[telephone]</strong> <span class=\"gram\">[transitive]</span> to listen secretly to someone’s telephone by using a special piece of electronic equipment:</div><ul class=\"examples\"><li><em>Murray’s phone calls to Australia were tapped.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[tree]</strong> <span class=\"gram\">[transitive]</span> to get liquid from the trunk of a tree by making a hole in it</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[player]</strong> <span class=\"gram\">[transitive]</span> (also tap up) <em>British English</em> <em>informal</em> if a football club taps a player from another team, it illegally tries to persuade that player to join its team</div></div></div>","6879":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /teɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[for recording]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[uncountable]</span> narrow plastic material covered with a special magnetic substance, on which you can record sounds, pictures, or computer information</div><ul class=\"examples\"><li><strong><em>on tape</strong> (=recorded on tape): We’ve got the film on tape. / I hate hearing my voice on tape.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> a special plastic box containing a length of tape that you can record sound on <em>SYN cassette</em>:</div><ul class=\"examples\"><li><em>I’ll listen to the tape tomorrow.</em></li><li><em>William lent me some of his Beatles tapes.</em></li><li><strong><em>tape of</strong>: We played a tape of African music and began dancing.</em></li><li><em>Bring me a blank tape and I’ll record it for you.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <span class=\"gram\">[countable]</span> a special plastic box containing a length of tape that you can record sound and pictures on <em>SYN videotape</em></div><div class=\"sense\"><span class=\"snum\">2</span> <strong>[sticky material]</strong> <span class=\"gram\">[uncountable]</span> a narrow length of plastic that is sticky on one side and is used to stick things together SYN Sellotape<em>British English</em>, Scotch tape<em>American English</em>:</div><ul class=\"examples\"><li><em>a photo stuck to the wall with tape</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[thin piece of material]</strong> <span class=\"gram\">[countable, uncountable]</span> a long thin piece of plastic or cloth used for purposes such as marking out an area of ground or tying things together:</div><ul class=\"examples\"><li><em>Crime-scene tape marked out the position of the murdered man.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the tape</strong> a string stretched out across the finishing line in a race and broken by the winner</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[for measuring]</strong> <span class=\"gram\">[countable]</span> a tape measure</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[record something]</strong> <span class=\"gram\">[intransitive, transitive]</span> (also tape record) to record sound or pictures onto a tape:</div><ul class=\"examples\"><li><em>Would you mind if I taped this conversation?</em></li><li><em>Quiet – the machine’s still taping.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[stick something]</strong> <span class=\"gram\">[transitive]</span> to stick something onto something else using tape</div><ul class=\"examples\"><li><strong><em>tape something to something</strong>: There were two pictures taped to the side of the fridge.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[fasten something]</strong> <span class=\"gram\">[transitive]</span> (also tape up) to fasten a package, box etc with sticky tape</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[injury]</strong> <span class=\"gram\">[transitive]</span> (also tape up) <em>especially American English</em> to tie a bandage firmly around an injured part of someone’s body SYN strap<em>British English</em>: GRAMMAR Tape is often passive in this meaning.</div><ul class=\"examples\"><li><em>His ankle had been taped.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>have (got) something/somebody taped</strong> <em>British English</em> <em>informal</em> to understand someone or something completely and know how to deal with them:</div><ul class=\"examples\"><li><em>You can’t fool Liz – she’s got you taped.</em></li></ul></div></div>","6880":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tar‧get</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɑːɡɪt $ ˈtɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[aim]</strong> something that you are trying to achieve, such as a total, an amount, or a time <em>SYN goal</em> ► see thesaurus at aim</div><ul class=\"examples\"><li><strong><em>sales/attainment/growth etc targets</strong>: demanding financial targets</em></li><li><strong><em>target of</strong>: the target of a one-third reduction in road accidents</em></li><li><strong><em>target for</strong>: Higher degrees in English are a target for foreign students.</em></li><li><em>There is no target date for completion of the new project.</em></li><li><em>The government may fail to meet (=achieve) its target of recycling 25% of domestic waste.</em></li><li><em>Jiang set annual growth targets of 8–9%.</em></li><li><strong><em>on target</strong> (=likely to achieve a target): The company says that growth of 10% is on target.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[object of attack]</strong> an object, person, or place that is deliberately chosen to be attacked</div><ul class=\"examples\"><li><strong><em>target for/of</strong>: Railway stations are prime targets (=very likely targets) for bombs.</em></li><li><strong><em>easy/soft target</strong>: Cars without security devices are an easy target for the thief.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[object of an action]</strong> the person or place that is most directly affected by an action, especially a bad one</div><ul class=\"examples\"><li><strong><em>target for/of</strong>: The area has become a prime target for supermarket development. / The country is a target of criticism for its human rights record.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[shooting]</strong> something that you practise shooting at, especially a round board with circles on it:</div><ul class=\"examples\"><li><em>The area is used by the army for target practice.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>target audience/group/area etc</strong> a limited group, area etc that a plan, idea etc is aimed at:</div><ul class=\"examples\"><li><em>Our target audience is men aged between 18 and 35.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>target language</strong> the language that you are learning or that you are translating into</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make something have an effect on a particular limited group or area:</div><ul class=\"examples\"><li><em>The advertisement was designed to target a mass audience.</em></li><li><strong><em>target something on/at somebody/something</strong>: a new benefit targeted on low-income families / The programme is targeted at improving the health of women of all ages.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to aim something at a target</div><ul class=\"examples\"><li><strong><em>target something on/at somebody/something</strong>: The missiles are targeted at several key military sites.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to choose a particular person or place to do something to, especially to attack them or criticize them:</div><ul class=\"examples\"><li><em>It’s clear that smaller, more vulnerable banks have been targeted.</em></li><li><em>He was targeted by terrorists for a second time last night.</em></li></ul></div></div>","6881":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tar‧iff</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtærɪf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a tax on goods coming into a country or going out of a country</div><ul class=\"examples\"><li><strong><em>tariff on</strong>: The government may impose tariffs on imports.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> a list of fixed prices charged by a hotel or restaurant, for example for the cost of meals or rooms</div><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> a list or system of prices which mobile phone companies charge for the services they provide</div></div>","6882":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɑːsk $ tæsk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a piece of work that must be done, especially one that is difficult or unpleasant or that must be done regularly <em>SYN job</em> RegisterIn everyday English, people usually say job rather than task:· I was given the job of building the fire.</div><ul class=\"examples\"><li><strong><em>task of</strong>: The task of the union representative is to fight on behalf of the members. / Sara had the task of preparing the agenda for meetings. / I was given the task of building a fire. / the skills required to carry out these tasks / He soon realized the scale of the task he had undertaken. / Our first task is to gather information. / Monkeys can be taught to do simple tasks. / They have the unenviable task of supervising the most dangerous prison in the country. / Volunteers had the thankless task of distributing campaign leaflets. / Trying to bring up a small daughter on your own is no easy task.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>take someone to task</strong> to strongly criticize somebody for something they have done</div><ul class=\"examples\"><li><strong><em>task for</strong>: He was taken to task for not reporting the problem earlier.</em></li></ul></div>","6883":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /teɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[food]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable, uncountable]</span> the feeling that is produced by a particular food or drink when you put it in your mouth <em>SYN flavour</em>:</div><ul class=\"examples\"><li><em>The medicine had a slightly bitter taste.</em></li><li><strong><em>taste of</strong>: I don’t really like the taste of meat anymore.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[uncountable]</span> the sense by which you know one food from another:</div><ul class=\"examples\"><li><em>Some birds have a highly developed sense of taste.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <strong>have a taste (of something)</strong> if you have a taste of some food or drink, you put a small amount in your mouth to try it:</div><ul class=\"examples\"><li><em>You must have a taste of the fruitcake.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[what you like]</strong> <span class=\"gram\">[countable, uncountable]</span> the kind of things that someone likes</div><ul class=\"examples\"><li><strong><em>taste in</strong>: He asked about my taste in music.</em></li><li><strong><em>taste for</strong>: While she was in France she developed a taste for fine wines.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[judgment]</strong> <span class=\"gram\">[uncountable]</span> someone’s judgment when they choose clothes, decorations etc</div><ul class=\"examples\"><li><strong><em>have good/bad etc taste</strong>: She has such good taste.</em></li><li><strong><em>taste in</strong>: Some people have really bad taste in clothes.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[what is acceptable/not offensive]</strong> <span class=\"gram\">[uncountable]</span> the quality of being acceptable and not offensive:</div><ul class=\"examples\"><li><em>All television companies accept the need to maintain standards of taste and decency.</em></li><li><strong><em>be in bad/poor etc taste</strong> (=likely to offend people): She acknowledged her remark had been in bad taste.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[experience]</strong> <span class=\"gram\">[usually singular]</span> a short experience of something that shows you what it is like</div><ul class=\"examples\"><li><strong><em>taste of</strong>: Schoolchildren can get a taste of the countryside first-hand.</em></li><li><em>It gave him his first taste of acting for the big screen.</em></li><li><em>The autumn storms gave us a taste of what was to come (=showed what would happen later).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[feeling]</strong> <span class=\"gram\">[singular]</span> the feeling that you have after an experience, especially a bad experience:</div><ul class=\"examples\"><li><em>The way he spoke to those children left a nasty taste in my mouth.</em></li><li><em>the bitter taste of failure</em></li><li><em>the sweet taste of victory</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>... to taste</strong> if you add salt, spices etc to taste, you add as much as you think makes it taste right – used in instructions in cook books:</div><ul class=\"examples\"><li><em>Add salt to taste.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[linking verb]</span> to have a particular kind of taste GRAMMARLinking verbsTaste is a linking verb in this meaning. It links the subject of the sentence with an adjective: · The soup tastes salty.· Fresh strawberries always taste delicious.Using the progressive• The verb taste is not usually used in the progressive. You say: · I tasted blood.· It tastes sour. ✗Don’t say: I was tasting blood. | It is tasting sour.• You often say someone can taste something when describing what they taste: · I could taste blood.• The present participle tasting is used to form adjectives such as sweet-tasting and foul-tasting.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><strong><em>taste good/delicious/sweet/fresh etc</strong>: Mmm! This tastes good! / The food tasted better than it looked.</em></li><li><strong><em>taste awful/disgusting etc</strong>: The coffee tasted awful.</em></li><li><strong><em>taste of something</strong>: This yoghurt tastes of strawberries. / It didn’t taste much of ginger.</em></li><li><strong><em>taste like something</strong>: It tastes just like champagne to me. / What does pumpkin taste like (=how would you describe its taste)?</em></li><li><strong><em>sweet-tasting/bitter-tasting etc</strong>: a sweet-tasting soup</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to experience or recognize the taste of food or drink:</div><ul class=\"examples\"><li><em>She could taste blood.</em></li><li><em>Can you taste the difference?</em></li><li><em>It was like nothing I’d ever tasted before.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to eat or drink a small amount of something to see what it is like:</div><ul class=\"examples\"><li><em>It’s always best to keep tasting the food while you’re cooking it.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>taste success/freedom/victory etc</strong> to have a short experience of something that you want more of:</div><ul class=\"examples\"><li><em>There was a lot of hard work before we first tasted success.</em></li></ul></div></div>","6884":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tast‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteɪsti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(comparative tastier, superlative tastiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> food that is tasty has a good taste, but is not sweet: → tasteful ► see thesaurus at taste</div><ul class=\"examples\"><li><em>a simple but tasty meal</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> tasty news, gossip etc is especially interesting and often connected with sex or surprising behaviour</div><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> <em>informal</em> sexually attractive</div></div>","6885":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tæks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable, uncountable]</span> an amount of money that you must pay to the government according to your income, property, goods etc and that is used to pay for public services</div><ul class=\"examples\"><li><strong><em>tax on</strong>: a tax on fuel</em></li><li><em>He already pays 40% tax on his income.</em></li><li><strong><em>before/after tax</strong>: profits before tax of £85.9m</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to charge a tax on something</div><ul class=\"examples\"><li><strong><em>tax something at 10%/a higher rate etc</strong>: They may be taxed at a higher rate.</em></li><li><strong><em>tax somebody on something</strong>: The individual is taxed on the amount of dividend received.</em></li><li><em>Cigarettes are heavily taxed in Britain.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> to pay the sum of money charged each year for using a vehicle on British roads → car tax, road tax</div><div class=\"sense\"><span class=\"snum\">3</span> to make someone have to work hard or make an effort</div><ul class=\"examples\"><li><strong><em>tax somebody’s patience/strength etc</strong>: The kids are really taxing my patience today.</em></li><li><em>It shouldn’t tax your brain too much.</em></li></ul></div></div>","6886":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tax‧a‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /tækˈseɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the system of charging taxes:</div><ul class=\"examples\"><li><em>the government’s economic and taxation policy</em></li><li><strong><em>direct taxation</strong> (=tax on income)</em></li><li><strong><em>indirect taxation</strong> (=tax on things you buy)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> money collected from taxes:</div><ul class=\"examples\"><li><em>higher levels of taxation</em></li></ul></div>","6887":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tax‧i</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtæksi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a car and driver that you pay to take you somewhere <em>SYN cab</em>:</div><ul class=\"examples\"><li><em>They sent me home in a taxi.</em></li></ul></div>","6888":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tax‧pay‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtæksˌpeɪə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a person that pays tax:</div><ul class=\"examples\"><li><em>The proposal could cost the taxpayer (=all ordinary people who pay tax) another £18m a year.</em></li></ul></div>","6889":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tiː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[drink/leaves]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable, uncountable]</span> a hot brown drink made by pouring boiling water onto the dried leaves from a particular Asian bush, or a cup of this drink:</div><ul class=\"examples\"><li><em>Would you like a cup of tea or coffee?</em></li><li><em>Do you take milk and sugar in your tea?</em></li><li><em>I’d like two teas and a piece of chocolate cake, please.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[uncountable]</span> dried, finely cut leaves that are used to make tea</div><div class=\"subsense\"><span class=\"subnum\">c)</span> <span class=\"gram\">[uncountable]</span> bushes whose leaves are used to make tea:</div><ul class=\"examples\"><li><em>tea plantations</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>mint/camomile etc tea</strong> a hot drink made by pouring boiling water onto leaves or flowers, sometimes used as a medicine</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[meal]</strong> <span class=\"gram\">[countable, uncountable]</span> <em>British English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a small meal of cake or biscuits eaten in the afternoon with a cup of tea:</div><ul class=\"examples\"><li><em>We serve lunch and afternoon tea.</em></li><li><em>We stopped for a cream tea on the way home (=tea and cream cakes).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used in some parts of Britain to mean a large meal that is eaten early in the evening: → high tea</div><ul class=\"examples\"><li><em>We had baked beans on toast for tea.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>tea and sympathy</strong> <em>British English</em> kindness and attention that you give someone when they are upset</div></div>","6890":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tiːtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\">(past tense and past participle taught /tɔːt $ tɒːt/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[school/college etc]</strong> <span class=\"gram\">[intransitive, transitive]</span> to give lessons in a school, college, or university, or to help someone learn about something by giving them information → learn</div><ul class=\"examples\"><li><strong><em>teach at</strong>: Neil teaches at the Guildhall School of Music in London.</em></li><li><strong><em>teach (somebody) English/mathematics/history etc</strong>: He taught geography at the local secondary school.</em></li><li><strong><em>teach somebody (something) about something</strong>: We were never taught anything about other religions.</em></li><li><strong><em>teach something to somebody</strong>: I’m teaching English to Italian students.</em></li><li><strong><em>teach school/college etc<em>American English</em></strong> (=teach in a school etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[show somebody how]</strong> <span class=\"gram\">[transitive]</span> to show someone how to do something</div><ul class=\"examples\"><li><strong><em>teach somebody (how) to do something</strong>: My father taught me to swim. / different methods of teaching children how to read</em></li><li><strong><em>teach somebody something</strong>: Can you teach me one of your card tricks?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[change somebody’s ideas]</strong> <span class=\"gram\">[transitive]</span> to show or tell someone how they should behave or what they should think</div><ul class=\"examples\"><li><strong><em>teach somebody to do something</strong>: When I was young, we were taught to treat older people with respect.</em></li><li><strong><em>teach somebody something</strong>: No one ever taught him the difference between right and wrong.</em></li><li><strong><em>teach somebody that</strong>: He taught me that the easy option isn’t always the best one.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[experience shows something]</strong> <span class=\"gram\">[transitive]</span> if an experience or situation teaches you something, it helps you to understand something about life</div><ul class=\"examples\"><li><strong><em>teach somebody to do something</strong>: Experience has taught me to avoid certain areas of the city.</em></li><li><strong><em>teach somebody that</strong>: It’s certainly taught me that work and money aren’t the most important things in life.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>that’ll teach you (to do something)</strong> <em>spoken</em> used when something unpleasant has just happened to someone because they acted stupidly:</div><ul class=\"examples\"><li><em>That’ll teach you to be late!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>teach somebody a lesson</strong> <em>informal</em> if someone or something teaches you a lesson, you are punished for something you have done, so that you will not want to do it again</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>you can’t teach an old dog new tricks</strong> used to say that older people often do not want to change the way they do things</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>teach your grandmother (to suck eggs)</strong> <em>British English</em> to give someone advice about something that they already know</div></div>","6891":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> teach‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiːtʃə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone whose job is to teach, especially in a school:</div><ul class=\"examples\"><li><em>a primary school teacher</em></li><li><strong><em>language/history/science etc teacher</em></strong></li><li><strong><em>teacher training/education</strong> (=professional training to become a teacher)</em></li></ul></div>","6892":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> teach‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiːtʃɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the work or profession of a teacher:</div><ul class=\"examples\"><li><em>Mrs Ward had many years of experience in teaching.</em></li><li><em>She’s thinking of going into teaching (=becoming a teacher).</em></li><li><strong><em>language/science etc teaching</strong>: extra funding for English teaching in schools</em></li><li><strong><em>the teaching profession</em></strong></li><li><strong><em>teaching methods/materials etc</em></strong></li><li><strong><em>teaching practice<em>British English,</em></strong> <strong>student teaching</em>American English</strong><em> (=a period of teaching done by someone who is training to be a teacher)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also teachings<span class=\"gram\">[plural]</span>) the moral, religious, or political ideas of a particular person or group which are taught to other people</div><ul class=\"examples\"><li><strong><em>teaching of</strong>: the teachings of Gandhi</em></li><li><strong><em>religious/Christian/Buddhist etc teachings</em></strong></li></ul></div>","6893":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tiːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a group of people who play a game or sport together against another group: ► see thesaurus at group</div><ul class=\"examples\"><li><em>Which team do you support?</em></li><li><strong><em>in a team<em>British English</em></strong> <strong>, on a team</em>American English</strong><em>: Bobby Charlton was in the team that won the World Cup.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a group of people who have been chosen to work together to do a particular job</div><ul class=\"examples\"><li><strong><em>team of</strong>: a team of experts</em></li><li><strong><em>management/research/sales etc team</strong>: a senior member of the design team</em></li><li><em>Our success lies in working together as a team.</em></li><li><em>It was a tremendous team effort.</em></li><li><em>You need to choose a team leader.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> two or more animals that are used to pull a vehicle</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to put two things or people together, because they will look good or work well together</div><ul class=\"examples\"><li><strong><em>team something with something</strong>: black trousers teamed with a bright shirt</em></li></ul></div></div>","6894":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈteam-mate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiːm-meɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who belongs to the same team as you:</div><ul class=\"examples\"><li><em>He finished just ahead of his Ferrari team-mate.</em></li></ul></div>","6895":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> team‧work</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiːmwɜːk $ -wɜːrk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">when a group of people work effectively together:</div><ul class=\"examples\"><li><em>We want to encourage good teamwork and communication.</em></li></ul></div>","6896":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tea‧pot</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiːpɒt $ -pɑːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a container for making and serving tea, which has a handle and a spout1(1)</div></div>","6897":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɪə $ tɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually plural]</span> a drop of salty liquid that comes out of your eye when you are crying:</div><ul class=\"examples\"><li><em>The children were all in tears.</em></li><li><em>She came home in floods of tears.</em></li><li><em>I could see that Sam was close to tears.</em></li><li><em>Bridget suddenly burst into tears and ran out.</em></li><li><em>He was fighting back tears as he spoke.</em></li><li><em>A lot of people were moved to tears by his story.</em></li><li><em>He kissed her cheek, a gesture that brought tears to her eyes.</em></li><li><em>I must admit I shed a few tears when the school closed.</em></li><li><em>I saw grown men reduced to tears that day.</em></li><li><em>‘Please don’t talk like that,’ Ellen implored him, her eyes filling with tears.</em></li><li><em>By this time, tears were streaming down my face.</em></li><li><em>The tears he shed were tears of joy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>it’ll (all) end in tears</strong> <em>British English</em> <em>spoken</em> used to warn someone that something they are doing will cause problems or arguments between people</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /teə $ ter/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(past tense tore /tɔː $ tɔːr/, past participle torn /tɔːn $ tɔːrn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[paper/cloth]</strong> ► see thesaurus at break</div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[transitive]</span> to damage something such as paper or cloth by pulling it hard or letting it touch something sharp <em>SYN rip</em>:</div><ul class=\"examples\"><li><em>Be careful not to tear the paper.</em></li><li><em>His clothes were old and torn.</em></li><li><strong><em>tear something on something</strong>: She realized she had torn her jacket on a nail.</em></li><li><strong><em>tear something off</strong>: Tear off the slip at the bottom of this page and send it back to us.</em></li><li><strong><em>tear something out (of something)</strong>: He tore a page out of his notebook and handed it to her.</em></li><li><em>The dog had torn a huge hole in the tent.</em></li><li><em>He picked up the envelope and tore it open.</em></li><li><em>She tore the letter to pieces and threw it in the bin.</em></li><li><em>Most of her clothes had been torn to shreds.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive]</span> if paper or cloth tears, it splits and a hole appears, because it has been pulled too hard or has touched something sharp:</div><ul class=\"examples\"><li><em>The paper is old and tears easily.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[move quickly]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to run or drive somewhere very quickly, especially in a dangerous or careless way: ► see thesaurus at run</div><ul class=\"examples\"><li><em>She tore back into the house.</em></li><li><em>We tore down to the hospital.</em></li><li><em>He tore off into town.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[remove something]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to pull something violently from a person or place</div><ul class=\"examples\"><li><strong><em>tear something from somebody/something</strong>: He tore the letter from my hand. / A bridge was torn from the bank by the floodwaters.</em></li><li><strong><em>tear something off something</strong>: High winds nearly tore the roof off the house.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be torn</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if you are torn, you are unable to decide what to do because you have different feelings or different things that you want</div><ul class=\"examples\"><li><strong><em>tear between</strong>: She was torn between her love of dancing and her fear of performing in public.</em></li><li><em>He was torn two ways.</em></li><li><em>Jess was torn by anger and worry.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a country or group is torn, it is divided because people in it have very different ideas and are arguing or fighting with each other:</div><ul class=\"examples\"><li><em>The country was torn by civil war.</em></li><li><em>She spent two months in the war-torn city.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[muscle]</strong> <span class=\"gram\">[transitive]</span> to damage a muscle or ligament:</div><ul class=\"examples\"><li><em>She had torn a muscle in her leg.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>tear loose</strong> to move violently and no longer be attached to something:</div><ul class=\"examples\"><li><em>One end had torn loose.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>tear somebody/something to shreds/pieces</strong> <em>informal</em> to criticize someone or something very severely:</div><ul class=\"examples\"><li><em>He tore her arguments to shreds.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>tear somebody off a strip/tear a strip off somebody</strong> <em>British English</em> <em>informal</em> to talk to someone very angrily because they have done something wrong</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>tear somebody limb from limb</strong> <em>literary</em> to attack someone in a very violent way</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>be tearing your hair out</strong> <em>British English</em> <em>informal</em> to feel anxious and upset because you are worried, or because you have to deal with something that is very difficult:</div><ul class=\"examples\"><li><em>I’ve been tearing my hair out trying to get done in time.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be in a tearing hurry</strong> <em>British English</em> to be doing something very quickly because you are late</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>tear somebody’s heart (out)/tear at somebody’s heart</strong> to make someone feel extremely upset:</div><ul class=\"examples\"><li><em>The thought of her out there alone tore at my heart.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>that’s torn it!</strong> <em>British English</em> <em>spoken</em> <em>old-fashioned</em> used when something bad has happened that stops you from doing what you intended to do:</div><ul class=\"examples\"><li><em>Oh, no, that’s torn it! I’ve left my keys in the car!</em></li></ul></div></div>","6898":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tiːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[laugh]</strong> <span class=\"gram\">[intransitive, transitive]</span> to laugh at someone and make jokes in order to have fun by embarrassing them, either in a friendly way or in an unkind way: RegisterIn everyday English, people often say make fun of rather than tease:· Stop making fun of me!</div><ul class=\"examples\"><li><em>Don’t get upset. I was only teasing.</em></li><li><em>He used to tease her mercilessly.</em></li><li><strong><em>tease somebody about something</strong>: She used to tease me about my hair.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[annoy an animal]</strong> <span class=\"gram\">[transitive]</span> to deliberately annoy an animal:</div><ul class=\"examples\"><li><em>Stop teasing the cat!</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[sex]</strong> <span class=\"gram\">[intransitive, transitive]</span> to deliberately make someone sexually excited without intending to have sex with them, in a way that seems unkind</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[hair]</strong> <span class=\"gram\">[transitive]</span> <em>American English</em> to comb your hair in the opposite direction to which it grows, so that it looks thicker SYN backcomb<em>British English</em></div></div>","6899":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tea‧spoon</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiːspuːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small spoon that you use for mixing sugar into tea and coffee</div><div class=\"sense\"><span class=\"snum\">2</span> (also teaspoonful /ˈtiːspuːnfʊl/) (written abbreviation tsp) the amount that a teaspoon can hold, used as a unit for measuring food or liquid in cooking</div><ul class=\"examples\"><li><strong><em>teaspoon of</strong>: Add a teaspoon of salt.</em></li></ul></div>","6900":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tech‧ni‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteknɪkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[machines]</strong> connected with knowledge of how machines work:</div><ul class=\"examples\"><li><em>Our staff will be available to give you technical support.</em></li><li><em>I have no technical knowledge at all.</em></li><li><em>technical training</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>technical problem/hitch</strong> a problem involving the way a machine or system works:</div><ul class=\"examples\"><li><em>We’ve been having some technical problems with the new hardware.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[language]</strong> technical language is language that is difficult for most people to understand because it is connected with one particular subject or used in one particular job:</div><ul class=\"examples\"><li><em>I didn’t understand all the technical terms.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[details/rules]</strong> relating to small exact details or rules that say how a system should work:</div><ul class=\"examples\"><li><em>He called for the legislation to be delayed on a technical point.</em></li><li><em>This is a technical violation of the treaty.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[skills]</strong> technical ability is the ability to do the difficult things that you have to do in order to play music, do a sport etc:</div><ul class=\"examples\"><li><em>a young player with a lot of technical ability</em></li></ul></div>","6901":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tech‧ni‧cally</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteknɪkli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> according to the exact details of a rule or law</div><ul class=\"examples\"><li><em><span class=\"gram\">[sentence adverb]</span>: Technically, the two countries are still at war, as a peace treaty was never signed.</em></li><li><em><span class=\"gram\">[+adjective/adverb]</span>: What you have done is technically illegal.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[+adjective/adverb]</span> concerning the special skills that are needed to play music, do a sport etc:</div><ul class=\"examples\"><li><em>a technically brilliant pianist</em></li><li><em>The dance looks simple, but is technically very difficult.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> concerning the way machines are used to do work:</div><ul class=\"examples\"><li><em>Agriculture is becoming more and more technically advanced.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>technically possible/difficult/feasible etc</strong> possible, difficult etc using the scientific knowledge that is available now:</div><ul class=\"examples\"><li><em>It could soon be technically possible to produce a human being by cloning.</em></li></ul></div>","6902":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tech‧ni‧cian</span><span class=\"meta-item\"><strong>IPA:</strong> /tekˈnɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone whose job is to check equipment or machines and make sure that they are working properly:</div><ul class=\"examples\"><li><em>a laboratory technician</em></li><li><em>a hospital technician</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is very good at the skills of a particular sport, music, art etc:</div><ul class=\"examples\"><li><em>Whether he was a great artist or not, Dali was a superb technician.</em></li></ul></div>","6903":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tech‧nique</span><span class=\"meta-item\"><strong>IPA:</strong> /tekˈniːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a special way of doing something → method ► see thesaurus at method, way</div><ul class=\"examples\"><li><strong><em>technique for</strong>: There are various techniques for dealing with industrial pollution.</em></li><li><strong><em>technique of</strong>: In mathematics, we use many techniques of problem-solving.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the special way in which you move your body when you are playing music, doing a sport etc, which is difficult to learn and needs a lot of skill → technical:</div><ul class=\"examples\"><li><em>He’s a great player, with brilliant technique.</em></li></ul></div>","6904":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tech‧no‧lo‧gi‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌteknəˈlɒdʒɪkəl◂ $ -ˈlɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">relating to technology:</div><ul class=\"examples\"><li><em>The steam engine was the greatest technological advance of the 19th century</em></li></ul></div>","6905":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tech‧nol‧o‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /tekˈnɒlədʒi $ -ˈnɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural technologies)</span></div><div class=\"entry-body\"><div class=\"sense\">new machines, equipment, and ways of doing things that are based on modern knowledge about science and computers:</div><ul class=\"examples\"><li><em>Modern technology makes moving money around much easier than it used to be.</em></li><li><em>Advances in technology have improved crop yields by over 30%.</em></li><li><em>There have been major new developments in satellite technology.</em></li><li><em>Many people are unwilling to embrace new technologies.</em></li></ul></div>","6906":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> te‧di‧ous</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiːdiəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">something that is tedious continues for a long time and is not interesting <em>SYN boring</em>: ► see thesaurus at boring</div><ul class=\"examples\"><li><em>The work was tiring and tedious.</em></li></ul></div>","6907":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tiːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>American English</em> <em>informal</em> a teenager</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>teens</strong> <span class=\"gram\">[plural]</span> your teens is the period of your life when you are between 13 and 19 years old</div><ul class=\"examples\"><li><strong><em>be in your teens</strong>: She was in her teens when she met him.</em></li><li><strong><em>early/late teens</strong>: We moved to York when I was in my early teens.</em></li></ul></div>","6908":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> teen‧age</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiːneɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> aged between 13 and 19: ► see thesaurus at young</div><ul class=\"examples\"><li><em>a teenage boy</em></li><li><em>my teenage daughter</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> relating to or affecting people aged between 13 and 19:</div><ul class=\"examples\"><li><em>the teenage years</em></li><li><em>teenage rebellion</em></li><li><em>the problem of teenage pregnancy</em></li></ul></div>","6909":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> teen‧ag‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtiːneɪdʒə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who is between 13 and 19 years old: ► see thesaurus at child</div><ul class=\"examples\"><li><em>a TV sex education series aimed at teenagers</em></li></ul></div>","6910":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tel‧e‧com‧mu‧ni‧ca‧tions</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌtelikəmjuːnəˈkeɪʃənz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the sending and receiving of messages by telephone, radio, television etc:</div><ul class=\"examples\"><li><em>a new telecommunications system</em></li><li><em>the telecommunications industry</em></li></ul></div>","6911":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tel‧e‧phone</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteləfəʊn $ -foʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the telephone</strong> the system of communication that you use to have a conversation with someone in another place <em>SYN phone</em> RegisterIn everyday English, people usually say phone rather than telephone:· She’s been on the phone all evening.</div><ul class=\"examples\"><li><strong><em>by telephone</strong>: Reservations can be made by telephone.</em></li><li><strong><em>on the telephone</strong>: I’ve never met him, but I’ve spoken to him on the telephone.</em></li><li><strong><em>over the telephone</strong>: I read the names out to him over the telephone.</em></li><li><strong><em>down the telephone<em>British English</em></strong>: He shouted at me down the telephone.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the piece of equipment that you use when you are talking to someone by telephone <em>SYN phone</em>:</div><ul class=\"examples\"><li><em>The telephone rang just as I was leaving.</em></li><li><em>She picked up the telephone and dialled a number.</em></li><li><em>I said goodbye and put down the telephone.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be on the telephone</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be talking to someone, using the telephone:</div><ul class=\"examples\"><li><em>I was on the telephone when he came in.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to have a telephone in your home, office etc</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>British English</em> <em>formal</em> to talk to someone by telephone <em>SYN phone</em> <em>, call</em>: ► see thesaurus at phone</div><ul class=\"examples\"><li><em>Sammy telephoned to say that he would be late.</em></li><li><em>I’ll telephone you later.</em></li></ul></div></div>","6912":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tel‧e‧scope</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteləskəʊp $ -skoʊp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of equipment shaped like a tube, used for making distant objects look larger and closer → radio telescope</div><ul class=\"examples\"><li><strong><em>through a telescope</strong>: Details on the Moon’s surface can only be seen through a telescope.</em></li></ul></div>","6913":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tel‧e‧vise</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteləvaɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to broadcast something on television <em>SYN show</em>:</div><ul class=\"examples\"><li><em>The game was televised live on ABC.</em></li></ul></div>","6914":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tel‧e‧vi‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteləˌvɪʒən, ˌteləˈvɪʒən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> (also television set<em>formal</em>) a piece of electronic equipment shaped like a box with a screen, on which you can watch programmes <em>SYN TV</em>: RegisterIn everyday English, people usually say TV rather than television:· What’s on TV tonight?</div><ul class=\"examples\"><li><em>Lucy turned on the television to watch the evening news.</em></li><li><em>They have a television in every room.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the programmes broadcast in this way <em>SYN TV</em>:</div><ul class=\"examples\"><li><em>In the evenings I like to relax and watch television.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on (the) television</strong> broadcast or being broadcast on television:</div><ul class=\"examples\"><li><em>What’s on television tonight?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the business of making and broadcasting programmes on television <em>SYN TV</em></div><ul class=\"examples\"><li><strong><em>in television</strong>: Jean works in television.</em></li><li><em>a television film crew</em></li></ul></div>","6915":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tel/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle told)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[communicate something]</strong> <span class=\"gram\">[transitive]</span> if someone tells you something, they communicate information, a story, their feelings etc to you ► see thesaurus at explain, reveal → see Thesaurus box on<em>000000</em> RegisterIn written English, people often prefer to say that another writer describes something, rather than using tell:· His book describes how the human brain has developed.</div><ul class=\"examples\"><li><strong><em>tell somebody (that)</strong>: I wish someone had told me the meeting was canceled. / The Chief of Police told reporters that two people were killed in the blast.</em></li><li><strong><em>tell somebody what/how/where/who etc</strong>: Jack had to go, but he didn’t tell me why. / I think you’d better tell me exactly what’s been going on around here.</em></li><li><strong><em>tell somebody about something</strong>: No one had told them about the drug’s side effects. / I’ll tell you all about it when I get back.</em></li><li><strong><em>tell somebody something</strong>: Tell me your phone number again.</em></li><li><strong><em>tell (somebody) a story/joke/secret/lie</strong>: She told us some funny stories about her sister.</em></li><li><em>Sheppard was telling the truth.</em></li><li><strong><em>tell somebody straight</strong> (=tell someone the truth, even though it might upset them): Tell me straight, Adam. Just answer yes or no.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[show something]</strong> <span class=\"gram\">[transitive]</span> to give information in ways other than talking</div><ul class=\"examples\"><li><strong><em>tell somebody how/what/where/who etc</strong>: The light tells you when the machine is ready. / The bear’s sense of smell tells it where prey is hiding.</em></li><li><strong><em>tell somebody about something</strong>: What do these fossils tell us about climate change?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[what somebody should do]</strong> <span class=\"gram\">[transitive]</span> to say that someone must do something ► see thesaurus at advise, order, recommend</div><ul class=\"examples\"><li><strong><em>tell somebody (not) to do something</strong>: The teacher told the children to sit down quietly. / I thought I told you not to touch anything!</em></li><li><strong><em>tell somebody (that)</strong>: Bernice was told she had to work late this evening.</em></li><li><strong><em>tell somebody what/how etc</strong>: Stop trying to tell me what to do all the time.</em></li><li><em>Do as you are told (=obey me) and don’t ask questions.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[know]</strong> <span class=\"gram\">[intransitive, transitive not in progressive]</span> to know something or be able to recognize something because of certain signs that show this</div><ul class=\"examples\"><li><strong><em>can/can’t tell</strong>: She might have been lying. Benjy couldn’t tell.</em></li><li><strong><em>tell (that)</strong>: The moment Kramer walked in, I could tell that things were not going well.</em></li><li><strong><em>tell (something) a mile off</strong> (=know easily): You could tell a mile off that he was lying.</em></li><li><strong><em>tell when/how/whether/if etc</strong>: It’s hard to tell how long the job will take.</em></li><li><strong><em>tell something by something/from something</strong>: I could tell from his tone of voice that Ken was disappointed.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[recognize difference]</strong> <span class=\"gram\">[transitive not in progressive]</span> to be able to see how one person or thing is different from another → tell</div><ul class=\"examples\"><li><strong><em>tell something from something</strong>: How can you tell a fake Vuitton handbag from the real thing?</em></li><li><em>Can you tell the difference between sparkling wine and champagne?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>tell yourself something</strong> to persuade yourself that something is true:</div><ul class=\"examples\"><li><em>I keep telling myself there is nothing I could have done to save him.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[warn]</strong> <span class=\"gram\">[transitive usually in past tense]</span> to warn someone that something bad might happen</div><ul class=\"examples\"><li><strong><em>tell somebody (that)</strong>: I told you it was a waste of time talking to him.</em></li><li><strong><em>tell somebody (not) to do something</strong>: My mother told me not to trust Robert.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[tell somebody about bad behaviour]</strong> <span class=\"gram\">[intransitive]</span> <em>informal</em> to tell someone in authority about something wrong that someone you know has done – used especially by children <em>SYN tell on somebody</em>: → kiss-and-tell</div><ul class=\"examples\"><li><em>If you hit me, I’ll tell.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>tell tales</strong> <em>British English</em> to say something that is not true about someone else, in order to cause trouble for them – used especially about children: → telltale2</div><ul class=\"examples\"><li><em>an unpopular boy, who was always telling tales on the other children</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>all told</strong> altogether, when everyone or everything has been counted:</div><ul class=\"examples\"><li><em>There must have been eight cars in the accident, all told.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[affect]</strong> <span class=\"gram\">[intransitive not in progressive]</span> to have an effect on someone, especially a harmful one</div><ul class=\"examples\"><li><strong><em>tell on somebody</strong>: These late nights are really beginning to tell on him.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>tell the time</strong> <em>British English</em>, tell time<em>American English</em> to be able to know what time it is by looking at a clock</div></div>","6916":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tel‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈteli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural tellies)</span></div><div class=\"entry-body\"><div class=\"sense\">television</div><ul class=\"examples\"><li><strong><em>on telly</strong>: Is there anything good on telly tonight?</em></li></ul></div>","6917":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tem‧per</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtempə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a tendency to become angry suddenly or easily:</div><ul class=\"examples\"><li><em>That temper of hers will get her into trouble one of these days.</em></li><li><em>According to Nathan, Robin has quite a temper.</em></li><li><em>Theo needs to learn to control his temper.</em></li><li><strong><em>quick/bad/fiery etc temper</strong>: Be careful, he’s got a pretty violent temper.</em></li><li><strong><em>tempers flare<strong> (also</strong>tempers become frayed<em>)British English</em></strong> (=people become angry): Mason’s temper flared when he spotted his girlfriend kissing another man.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>lose your temper</strong> to suddenly become very angry so that you cannot control yourself:</div><ul class=\"examples\"><li><em>I’ve never seen Vic lose his temper.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular, uncountable]</span> the way you are feeling at a particular time, especially when you are feeling angry for a short time</div><ul class=\"examples\"><li><strong><em>in a temper</strong>: It’s no use talking to him when he’s in a temper.</em></li><li><em>Pete hit his brother in a fit of temper.</em></li><li><strong><em>be in a bad/foul temper</strong> (=to be angry): Watch out – she’s been in a foul temper all day.</em></li><li><strong><em>fly into a temper</strong>: Her boss would fly into a temper if a project wasn’t done on time.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>keep your temper</strong> to stay calm when it would be easy to get angry:</div><ul class=\"examples\"><li><em>I was finding it increasingly difficult to keep my temper.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>good-tempered/foul-tempered/quick-tempered etc</strong> having a good, bad temper etc:</div><ul class=\"examples\"><li><em>Minnie was always good-tempered and agreeable.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[singular]</span> <em>formal</em> the general attitude that people have in a particular place at one time</div><ul class=\"examples\"><li><strong><em>temper of</strong>: the temper of life in Renaissance Italy</em></li></ul></div>","6918":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tem‧pe‧ra‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtempərəmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the emotional part of someone’s character, especially how likely they are to be happy, angry etc</div><ul class=\"examples\"><li><strong><em>artistic/nervous/good etc temperament</strong>: Jill has such a lovely relaxed temperament.</em></li><li><strong><em>by temperament</strong>: Tolkien was, by temperament, a very different man from Lewis.</em></li></ul></div>","6919":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tem‧pera‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtemprətʃə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a measure of how hot or cold a place or thing is:</div><ul class=\"examples\"><li><em>The temperature of the water was just right for swimming.</em></li><li><em>Water boils at a temperature of 100ºC.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>somebody’s temperature</strong> the temperature of your body, especially used as a measure of whether you are sick or not:</div><ul class=\"examples\"><li><em>The nurse took (=measured) my temperature.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>have a temperature</strong> (also be running a temperature) to have a body temperature that is higher than normal, especially because you are sick:</div><ul class=\"examples\"><li><em>Susie has a temperature and has gone to bed.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> the temperature of a situation is the way people are reacting, for example whether they are behaving angrily or calmly:</div><ul class=\"examples\"><li><em>The referee’s decision to give a penalty raised the temperature of the match.</em></li></ul></div>","6920":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tem‧ple</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtempəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a building where people go to worship, in the Jewish, Hindu, Buddhist, Sikh, and Mormon religions</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually plural]</span> one of the two fairly flat areas on each side of your forehead</div></div>","6921":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tem‧po‧ra‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtempərəri, -pəri $ -pəreri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> continuing for only a limited period of time <em>OPP permanent</em>:</div><ul class=\"examples\"><li><em>temporary pain relief</em></li><li><em>I’m living with my parents, but it’s only temporary.</em></li><li><em>You might want to consider temporary work until you decide what you want to do.</em></li><li><em>She was employed on a temporary basis.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> intended to be used for only a limited period of time <em>OPP permanent</em>:</div><ul class=\"examples\"><li><em>temporary accommodation</em></li><li><em>The bridge was erected as a temporary measure.</em></li></ul></div>","6922":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tempt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to try to persuade someone to do something by making it seem attractive</div><ul class=\"examples\"><li><strong><em>tempt somebody into doing something</strong>: The new program is designed to tempt young people into studying engineering.</em></li><li><strong><em>tempt somebody to do something</strong>: It would take a lot of money to tempt me to quit this job.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone want to have or do something, even though they know they really should not:</div><ul class=\"examples\"><li><em>If you leave valuables in your car it will tempt thieves.</em></li><li><strong><em>be tempted to do something</strong>: I’m tempted to buy that dress.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>tempt fate</strong> (also tempt providence<em>British English</em>)</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to do something that involves unnecessary risk and may cause serious problems:</div><ul class=\"examples\"><li><em>Fire officials said developers are tempting fate by building deep into the scenic canyons.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to say too confidently that something will have a good result, that there will be no problems etc, when it is likely there will be problems</div></div>","6923":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> temp‧ta‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /tempˈteɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a strong desire to have or do something even though you know you should not</div><ul class=\"examples\"><li><strong><em>temptation to do something</strong>: There might be a temptation to cheat if students sit too close together.</em></li><li><em>Resist the temptation to buy the item until you’re certain you need it.</em></li><li><em>I finally gave in to the temptation and had a cigarette.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something that makes you want to have or do something, even though you know you should not:</div><ul class=\"examples\"><li><em>Selling alcohol at truck stops is an unnecessary temptation for drivers.</em></li></ul></div>","6924":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> temp‧ting</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtemptɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">something that is tempting seems very good and you would like to have it or do it:</div><ul class=\"examples\"><li><em>a tempting job offer</em></li><li><em>That pie looks tempting.</em></li><li><strong><em>be tempting to do something</strong>: It’s tempting to believe her story.</em></li></ul></div>","6925":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ten/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the number 10:</div><ul class=\"examples\"><li><em>Snow had been falling steadily for ten days.</em></li><li><em>I need to be home by ten (=ten o&#x27;clock).</em></li><li><em>At the time, she was about ten (=ten years old).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>ten to one</strong> <em>informal</em> used to say that something is very likely:</div><ul class=\"examples\"><li><em>Ten to one he’ll have forgotten all about it tomorrow.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be ten a penny</strong> <em>British English</em> <em>informal</em> to be very common and therefore not special or unusual → be a dime a dozen at dime(2)</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>(get) ten out of ten (for something)</strong> <em>British English</em> used in schools to give a perfect mark, or humorously to praise someone:</div><ul class=\"examples\"><li><em>You get ten out of ten for effort, Simon.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a piece of paper money that is worth ten dollars or ten pounds:</div><ul class=\"examples\"><li><em>I reached inside my purse and handed him a ten.</em></li></ul></div>","6926":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ten‧ant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtenənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who lives in a house, room etc and pays rent to the person who owns it → landlord:</div><ul class=\"examples\"><li><em>The desk was left by the previous tenant.</em></li></ul></div>","6927":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>tend to do something</strong> if something tends to happen, it happens often and is likely to happen again:</div><ul class=\"examples\"><li><em>People tend to need less sleep as they get older.</em></li><li><em>My car tends to overheat in the summer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also tend to somebody/something) <span class=\"gram\">[transitive]</span> <em>old-fashioned</em> to look after someone or something:</div><ul class=\"examples\"><li><em>Sofia was in the bedroom tending to her son.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>tend towards something</strong> to have one particular quality or feature more than others:</div><ul class=\"examples\"><li><em>Charles tends towards obesity.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>tend bar</strong> <em>especially American English</em> to work as a bartender</div><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>formal</em> to move or develop in a particular direction</div><ul class=\"examples\"><li><strong><em>tend upwards/downwards</strong>: Interest rates are tending upwards.</em></li></ul></div>","6928":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ten‧den‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtendənsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural tendencies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if someone or something has a tendency to do or become a particular thing, they are likely to do or become it</div><ul class=\"examples\"><li><strong><em>a tendency to do something</strong>: Greg’s tendency to be critical made him unpopular with his co-workers.</em></li><li><em>The drug is effective but has a tendency to cause headaches.</em></li><li><strong><em>tendency to/towards</strong>: Some people may inherit a tendency to alcoholism.</em></li><li><strong><em>tendency for</strong>: Researchers believe that the tendency for diabetes is present at birth.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a general change or development in a particular direction</div><ul class=\"examples\"><li><strong><em>there is a tendency (for somebody) to do something</strong>: There is an increasing tendency for women to have children later in life.</em></li><li><strong><em>tendency to/towards</strong>: a general tendency towards conservation and recycling</em></li><li><strong><em>tendency among</strong>: a tendency among Americans to get married at a later age</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>aggressive/suicidal/criminal/artistic etc tendencies</strong> a part of someone’s character that makes them likely to behave in a certain way or become an artist, criminal etc:</div><ul class=\"examples\"><li><em>children with aggressive or anti-social tendencies</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a group within a larger political group that supports ideas that are usually more extreme than those of the main group: GRAMMAR: Singular or plural verb?• In this meaning, tendency is usually followed by a singular verb: · The extremist tendency is becoming more powerful.• In British English, you can also use a plural verb: · The extremist tendency are becoming more powerful.Grammar guide ‒ NOUNS</div><ul class=\"examples\"><li><em>the growing fascist tendency</em></li></ul></div>","6929":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ten‧der</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtendə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[food]</strong> tender food is easy to cut and eat, especially because it has been well cooked <em>OPP tough</em>: ► see thesaurus at soft</div><ul class=\"examples\"><li><em>Continue cooking until the meat is tender.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[part of your body]</strong> a part of your body that is tender is painful if someone touches it: ► see thesaurus at painful</div><ul class=\"examples\"><li><em>My arm is still tender where I bruised it.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[gentle]</strong> gentle and careful in a way that shows love:</div><ul class=\"examples\"><li><em>Her voice was tender and soft.</em></li><li><em>a slow, tender kiss</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[easily damaged]</strong> easily damaged – used especially about plants or flowers:</div><ul class=\"examples\"><li><em>tender plants that were killed by the harsh winter</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>tender loving care</strong> <em>usually spoken</em> sympathetic treatment and a lot of attention <em>SYN TLC</em></div><div class=\"sense\"><span class=\"snum\">6</span> <strong>tender age</strong> the time when you are young or do not have much experience</div><ul class=\"examples\"><li><strong><em>at the tender age of four/five/six etc</strong>: Nicholas was sent to boarding school at the tender age of seven.</em></li></ul></div>","6930":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ten‧nis</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtenɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a game for two people or two pairs of people who use rackets to hit a small soft ball backwards and forwards over a net</div></div>","6931":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tens/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a tense situation is one in which you feel very anxious and worried because of something bad that might happen → tension ► see thesaurus at nervous</div><ul class=\"examples\"><li><strong><em>tense situation/atmosphere/moment etc</strong>: Marion spoke, eager to break the tense silence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> feeling worried, uncomfortable, and unable to relax <em>OPP relaxed</em>:</div><ul class=\"examples\"><li><em>Is anything wrong? You look a little tense.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> unable to relax your body or part of your body because your muscles feel tight → tension:</div><ul class=\"examples\"><li><em>Massage is great if your neck and back are tense.</em></li><li><em>She tried to relax her tense muscles.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">any of the forms of a verb that show the time, continuance, or completion of an action or state that is expressed by the verb. ‘I am’ is in the present tense, ‘I was’ is past tense, and ‘I will be’ is future tense.</div></div></div>","6932":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ten‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtenʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[nervous feeling]</strong> <span class=\"gram\">[uncountable]</span> a nervous worried feeling that makes it impossible for you to relax → tense:</div><ul class=\"examples\"><li><em>The tension was becoming unbearable, and I wanted to scream.</em></li><li><strong><em>reduce/relieve/ease etc tension</strong>: Exercise is the ideal way to relieve tension after a hard day.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[no trust]</strong> <span class=\"gram\">[countable usually plural, uncountable]</span> the feeling that exists when people or countries do not trust each other and may suddenly attack each other or start arguing</div><ul class=\"examples\"><li><strong><em>political/racial/social etc tension</strong>: In those days, there was a great deal of racial tension on campus.</em></li><li><strong><em>tension between</strong>: The obvious tension between Warren and Anne made everyone else uncomfortable.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[different influences]</strong> <span class=\"gram\">[countable, uncountable]</span> if there is tension between two things, there is a difference between the needs or influences of each, and that causes problems</div><ul class=\"examples\"><li><strong><em>tension between</strong>: In business, there’s always a tension between the needs of customers and shareholders.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[tightness]</strong> <span class=\"gram\">[uncountable]</span> tightness or stiffness in a wire, rope, muscle etc:</div><ul class=\"examples\"><li><em>Tension in the neck muscles can cause headaches.</em></li><li><em>Muscle tension can be a sign of stress.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[force]</strong> <span class=\"gram\">[uncountable]</span> the amount of force that stretches something:</div><ul class=\"examples\"><li><em>This wire will take 50 pounds tension.</em></li><li><strong><em>tension on</strong>: There was a lot of tension on the wire before it snapped.</em></li></ul></div>","6933":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tent/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a shelter consisting of a sheet of cloth supported by poles and ropes, used especially for camping:</div><ul class=\"examples\"><li><em>We looked for a flat spot where we could pitch our tent (=put up our tent).</em></li></ul></div>","6934":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ten‧ta‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtentətɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not definite or certain, because you may want to change things <em>SYN provisional</em> <em>OPP definite</em>:</div><ul class=\"examples\"><li><em>I passed on my tentative conclusions to the police.</em></li><li><em>The government is taking tentative steps towards tackling the country’s economic problems.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> done without confidence <em>SYN hesitant</em>:</div><ul class=\"examples\"><li><em>a tentative smile</em></li></ul></div>","6935":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tenθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\">coming after nine other things in a series:</div><ul class=\"examples\"><li><em>in the tenth century</em></li><li><em>her tenth birthday</em></li></ul></div>","6936":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɜːm $ tɜːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>in terms of something</strong> if you explain or describe something in terms of a particular fact or event, you are explaining or describing it only in relation to that fact or event</div><ul class=\"examples\"><li><strong><em>describe/measure/evaluate etc something in terms of something</strong>: Femininity is still defined in terms of beauty. / It’s a mistake to think of Florida only in terms of its tourist attractions.</em></li><li><em>It’s too early to start talking in terms of casualties.</em></li><li><strong><em>in terms of what/how/who etc</strong>: Did the experiment find any differences in terms of what children learned?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>in general/practical/financial etc terms</strong> used to show that you are describing or considering a subject in a particular way or from a particular point of view</div><ul class=\"examples\"><li><strong><em>in general/broad/simple etc terms</strong>: We explain in simple terms what the treatment involves.</em></li><li><em>It would be wrong to describe society purely in economic terms.</em></li><li><em>The war, although successful in military terms, left the economy in ruins.</em></li><li><em>What do these statistics mean in human terms?</em></li><li><strong><em>in somebody’s terms</strong>: In our terms, the scheme has not been a success.</em></li><li><strong><em>in real/absolute terms</strong> (=accurate, true, or including any related changes): Rail fares have fallen 17 per cent in real terms.</em></li><li><strong><em>in relative terms</strong> (=compared with other, similar things): Students have less money in relative terms, but spend more on books.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[word]</strong> <span class=\"gram\">[countable]</span> a word or expression with a particular meaning, especially one that is used for a specific subject or type of language → a contradiction in terms at contradiction(3) ► see thesaurus at word</div><ul class=\"examples\"><li><strong><em>term for</strong>: ‘Multimedia’ is the term for any technique combining sounds and images.</em></li><li><strong><em>in no uncertain terms</strong> (=in very clear and angry language): Journalists were told in no uncertain terms that they were not welcome.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[period of time]</strong> <span class=\"gram\">[countable]</span> a fixed period of time during which someone does something or something happens → fixed-term</div><ul class=\"examples\"><li><strong><em>term of/in office</strong> (=the time someone spends doing an important job in government): The mayor was coming to the end of his term in office.</em></li><li><strong><em>term of</strong>: the maximum term of imprisonment / The lease runs for a term of 99 years.</em></li><li><strong><em>prison/jail term</strong>: The men each received a 30-year prison term.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[school/university]</strong> <span class=\"gram\">[countable, uncountable]</span> <em>especially British English</em> one of the periods of time that the school or university year is divided into. In Britain, there are usually three terms in a year. → half-term, semester, quarter</div><ul class=\"examples\"><li><strong><em>summer/autumn/spring term</strong>: The exams are at the end of the summer term.</em></li><li><em>Teachers often feel overworked in term time (=during the term).</em></li><li><strong><em>first/last day of term</strong>: that all-important first day of term</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>in the long/short/medium term</strong> used to say what will happen or what happens generally over a long, short, or medium period of time: → long-term, short-term</div><ul class=\"examples\"><li><em>The cost of living will go up in the short term.</em></li><li><em>In the long term, alcohol causes high blood pressure.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[end]</strong> <span class=\"gram\">[singular, uncountable]</span> <em>technical</em> the end of a particular period of time:</div><ul class=\"examples\"><li><em>The agreement reaches its term next year.</em></li><li><em>a child born two months before full term (=of pregnancy)</em></li><li><em>We can prolong life beyond its natural term.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>come to terms with something</strong> to accept an unpleasant or sad situation and no longer feel upset or angry about it:</div><ul class=\"examples\"><li><em>George and Elizabeth have come to terms with the fact that they will never have children.</em></li><li><em>Counselling helped her come to terms with her grief.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[conditions]</strong> <strong>terms</strong> <span class=\"gram\">[plural]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the conditions that are set for an agreement, contract, arrangement etc:</div><ul class=\"examples\"><li><em>Under the terms of the agreement, the debt would be repaid over 20 years.</em></li><li><em>your terms and conditions of employment</em></li><li><em>Delivery is within the terms of this contract.</em></li><li><strong><em>equal/unequal/the same etc terms</strong> (=conditions that are equal, unequal etc): Small businesses have to compete on equal terms with large organisations. / Men and women should be able to work on level terms.</em></li><li><strong><em>on somebody’s (own) terms</strong> (=according to the conditions that someone wants): He wanted our relationship to be only on his terms.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the arrangements for payment that you agree to when you buy or sell something</div><ul class=\"examples\"><li><strong><em>reasonable/favourable/cheaper etc terms</strong>: Some insurance companies offer very reasonable terms. / This allowed tenant farmers to buy land on easy terms (=by paying small sums of money over a long period).</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[relationship]</strong> <strong>terms</strong> <span class=\"gram\">[plural]</span> if you are on good, bad etc terms with someone, you have a good, bad etc relationship with them</div><ul class=\"examples\"><li><strong><em>be on good/bad/friendly etc terms (with somebody)</strong>: By now, Usha and I were on familiar terms. / He is barely on speaking terms with his father (=they are angry and almost never speak to each other). / We were soon on first-name terms (=using each other’s first names, as a sign of friendship).</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>terms of reference</strong> <em>formal</em> the subjects that a person or group of people agree to consider:</div><ul class=\"examples\"><li><em>the committee’s terms of reference</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[number/sign]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> one of the numbers or signs used in a mathematical calculation</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to use a particular word or expression to name or describe something GRAMMAR Term is often used in the passive.</div><ul class=\"examples\"><li><strong><em>be termed something</strong>: This condition is sometimes termed RSI, or repetitive strain injury. / These developments are loosely termed ‘advanced manufacturing techniques’.</em></li><li><strong><em>term yourself something</strong>: Roosevelt termed himself and his policies ‘liberal’.</em></li></ul></div></div>","6937":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɜːmɪnəl $ ˈtɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a big building where people wait to get onto planes, buses, or ships, or where goods are loaded:</div><ul class=\"examples\"><li><em>the airport’s passenger terminal</em></li><li><strong><em>ferry/bus terminal</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a piece of computer equipment consisting of at least a keyboard and a screen, that you use for putting in or taking out information from a large computer</div><div class=\"sense\"><span class=\"snum\">3</span> one of the points at which you can connect wires in an electrical circuit</div><ul class=\"examples\"><li><strong><em>positive/negative terminal</em></strong></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧mi‧nal</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a terminal illness cannot be cured, and causes death → fatal:</div><ul class=\"examples\"><li><em>terminal cancer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>(in) terminal decline</strong> <em>British English</em> in a state of becoming worse and worse and never getting better:</div><ul class=\"examples\"><li><em>The once great industry is now in terminal decline.</em></li></ul></div></div>","6938":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧mi‧nate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɜːməneɪt $ ˈtɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> if something terminates, or if you terminate it, it ends <em>SYN end</em>:</div><ul class=\"examples\"><li><em>The court ruled that the contract must be terminated.</em></li><li><em>a woman’s decision on whether or not to terminate the pregnancy</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> if a train, bus, or ship terminates at a particular place, its journey ends there:</div><ul class=\"examples\"><li><em>The train from Paris terminates at St Pancras International.</em></li></ul></div>","6939":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧mi‧nol‧o‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌtɜːməˈnɒlədʒi $ ˌtɜːrməˈnɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural terminologies)</span></div><div class=\"entry-body\"><div class=\"sense\">the technical words or expressions that are used in a particular subject:</div><ul class=\"examples\"><li><em>computer terminology</em></li></ul></div>","6940":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧race</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[houses]</strong> <em>British English</em> a row of houses that are joined to each other, or a street with one of these rows in it</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>[place you can sit]</strong> a flat outdoor area next to a building or on a roof, where you can sit outside to eat, relax etc</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[football]</strong> <strong>the terraces</strong> <span class=\"gram\">[plural]</span> <em>British English</em> the wide steps that the people watching a football match can stand on</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[flat land]</strong> one of a series of flat areas cut out of a hill like steps, and used to grow crops</div></div>","6941":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧rain</span><span class=\"meta-item\"><strong>IPA:</strong> /teˈreɪn, tə-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a particular type of land: ► see thesaurus at ground</div><ul class=\"examples\"><li><em>rocky terrain</em></li></ul></div>","6942":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ri‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> extremely severe in a way that causes harm or damage <em>SYN horrible</em> <em>, awful</em>: ► see thesaurus at horrible</div><ul class=\"examples\"><li><em>Their son had been injured in a terrible accident.</em></li><li><em>We’re worried that something terrible might have happened to Greg.</em></li><li><em>a terrible storm</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very bad <em>SYN awful</em>: ► see thesaurus at bad</div><ul class=\"examples\"><li><em>The hotel was absolutely terrible.</em></li><li><em>I’d better write this down; I have a terrible memory.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> making you feel afraid or shocked:</div><ul class=\"examples\"><li><em>There was a terrible noise and the roof caved in.</em></li><li><em>She wept when she heard the terrible news.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to a very great degree <em>SYN grave</em>:</div><ul class=\"examples\"><li><em>You’re making a terrible mistake.</em></li></ul></div>","6943":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ri‧bly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterəbli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[+adjective/adverb]</span> <em>especially British English</em> very <em>SYN extremely</em>:</div><ul class=\"examples\"><li><em>I’m terribly sorry to have kept you waiting.</em></li><li><em>The coach was not terribly worried about his team’s poor performance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very badly <em>SYN severely</em>:</div><ul class=\"examples\"><li><em>The little boy missed his mother terribly.</em></li></ul></div>","6944":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧rif‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /təˈrɪfɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>informal</em> very good, especially in a way that makes you feel happy and excited <em>SYN great</em>: ► see thesaurus at good</div><ul class=\"examples\"><li><em>That’s a terrific idea!</em></li><li><em>The actress who played the lawyer was terrific.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very large in size or degree:</div><ul class=\"examples\"><li><em>a terrific bang</em></li><li><em>He drank a terrific amount of beer.</em></li></ul></div>","6945":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ri‧fied</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterɪfaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">very frightened: ► see thesaurus at frightened</div><ul class=\"examples\"><li><em>a terrified little girl</em></li><li><strong><em>terrified of</strong>: Sid is terrified of heights. / She was terrified of being caught.</em></li><li><strong><em>terrified (that)</strong>: We were terrified that the bridge would collapse.</em></li><li><strong><em>terrified at</strong>: He was terrified at the thought of being stranded in the woods.</em></li><li><strong><em>terrified to do something</strong>: He was terrified to stay home alone.</em></li></ul></div>","6946":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ri‧fy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterɪfaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle terrified, present participle terrifying, third person singular terrifies)</span></div><div class=\"entry-body\"><div class=\"sense\">to make someone extremely afraid:</div><ul class=\"examples\"><li><em>Her husband’s violence terrified her.</em></li></ul></div>","6947":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ri‧fy‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterəfaɪ-ɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">extremely frightening ► see thesaurus at frightening</div><ul class=\"examples\"><li><strong><em>terrifying experience/ordeal</strong>: He told her of his terrifying experience.</em></li><li><em>terrifying screams</em></li><li><em>It was absolutely terrifying.</em></li></ul></div>","6948":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ri‧to‧ri‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌterəˈtɔːriəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to land that is owned or controlled by a particular country:</div><ul class=\"examples\"><li><em>a territorial dispute</em></li><li><em>territorial claims</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> animals or people that are territorial are careful to guard the area of land that they consider to be their own, and prevent others from using it</div></div>","6949":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ri‧to‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterətəri $ -tɔːri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\">(plural territories)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[government/military]</strong> <span class=\"gram\">[countable, uncountable]</span> land that is owned or controlled by a particular country, ruler, or military force: ► see thesaurus at land</div><ul class=\"examples\"><li><em>Hong Kong became Chinese territory in 1997.</em></li><li><strong><em>occupied/enemy/disputed/hostile territory</strong>: The plane was flying over enemy territory.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[type of land]</strong> <span class=\"gram\">[uncountable]</span> land of a particular type</div><ul class=\"examples\"><li><strong><em>uncharted/unexplored territory</strong>: an expedition through previously unexplored territory</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[animal]</strong> <span class=\"gram\">[countable, uncountable]</span> the area that an animal, bird etc regards as its own and will defend against other animals:</div><ul class=\"examples\"><li><em>A tiger has a large territory to defend.</em></li><li><em>A dog uses urine to mark its territory.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[new or familiar experience]</strong> <span class=\"gram\">[uncountable]</span> a particular area of experience or knowledge</div><ul class=\"examples\"><li><strong><em>new/unfamiliar/uncharted territory</strong>: The company is moving into unfamiliar territory with this new software.</em></li><li><em>Actor Patrick Bergin returns to more familiar territory to play a menacing killer.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[business]</strong> <span class=\"gram\">[countable, uncountable]</span> an area in a town, country etc that someone is responsible for as part of their job, especially someone whose job is to sell products:</div><ul class=\"examples\"><li><em>a sales territory</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>come/go with the territory</strong> to be a natural and accepted part of a particular job, situation, place etc:</div><ul class=\"examples\"><li><em>I’m a cop – getting shot at goes with the territory.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[land that is not a state]</strong> <span class=\"gram\">[countable]</span> land that belongs to the United States, Canada etc but that is not a state:</div><ul class=\"examples\"><li><em>the US territory of Guam</em></li></ul></div>","6950":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ror</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[fear]</strong> <span class=\"gram\">[uncountable]</span> a feeling of extreme fear ► see thesaurus at fear</div><ul class=\"examples\"><li><strong><em>in terror</strong>: People fled in terror as fire tore through the building. / Shots rang out, and I screamed in terror. / We lived in terror of our father when he was drinking.</em></li><li><em>There was a look of sheer terror (=complete terror) on his face.</em></li><li><strong><em>strike terror into somebody/somebody’s heart</strong>: The sound of enemy planes struck terror into our hearts.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[frightening situation]</strong> <span class=\"gram\">[countable]</span> an event or situation that makes people feel extremely frightened, especially because they think they may die</div><ul class=\"examples\"><li><strong><em>terror of</strong>: the terrors of war</em></li><li><em>Death holds no terrors for (=does not frighten) me.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[violent action]</strong> <span class=\"gram\">[uncountable]</span> violent action for political purposes <em>SYN terrorism</em>:</div><ul class=\"examples\"><li><em>The resistance movement started a campaign of terror.</em></li><li><em>The Red Army Faction tried to undermine the state by terror tactics.</em></li><li><em>Pol Pot’s reign of terror in Cambodia</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[person]</strong> <span class=\"gram\">[countable]</span> <em>informal</em> a child who is difficult to control:</div><ul class=\"examples\"><li><em>That Johnson kid’s a real little terror!</em></li></ul></div>","6951":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ror‧is‧m</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterərɪzəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the use of violence such as bombing, shooting, or kidnapping to obtain political demands such as making a government do something:</div><ul class=\"examples\"><li><em>The government is doing everything possible to combat terrorism.</em></li><li><em>a despicable act of terrorism</em></li><li><em>their involvement in international terrorism</em></li></ul></div>","6952":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ter‧ror‧ist</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈterərɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who uses violence such as bombing, shooting etc to obtain political demands:</div><ul class=\"examples\"><li><em>We refuse to talk to terrorists.</em></li><li><strong><em>terrorist attack/activity/offence</strong>: Twenty people were killed in the latest terrorist attack.</em></li><li><strong><em>terrorist group/organization</em></strong></li><li><em>A terrorist bomb that left 168 people dead.</em></li></ul></div>","6953":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /test/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[exam]</strong> a set of questions, exercises, or practical activities to measure someone’s skill, ability, or knowledge ► You take or do a test. Don’t say ‘make a test’. To pass a test means to succeed in it, not simply to take it.</div><ul class=\"examples\"><li><strong><em>test on</strong>: We have a test on irregular verbs tomorrow.</em></li><li><em>Did you get a good mark in the test?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[medical]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a medical examination on a part of your body, or a substance taken from your body, to check your health or to discover what is wrong with you:</div><ul class=\"examples\"><li><em>The doctor said I needed to have a blood test.</em></li><li><em>an eye test</em></li><li><em>a hearing test</em></li><li><em>I’m still waiting for my test results from the hospital.</em></li><li><strong><em>do/run a test</strong>: They don’t know what’s wrong with her yet – they’re doing tests.</em></li><li><strong><em>a test is positive/negative</strong> (=it shows that someone has/does not have a condition, a substance in their blood etc): The tests were negative and the doctor said that she was in perfect health.</em></li><li><strong><em>test for</strong>: a test for HIV</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> an examination of someone’s blood, breath etc carried out by the police, to discover if they have done something illegal:</div><ul class=\"examples\"><li><em>a drugs test</em></li><li><em>The results of the DNA test proved that Simmons was the rapist.</em></li><li><strong><em>breath test</strong> (=to find out if someone has been drinking alcohol before driving a car)</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> a piece of equipment used for carrying out a medical examination:</div><ul class=\"examples\"><li><em>a pregnancy test</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[machine/product]</strong> a process used to discover whether equipment or a product works correctly, or to discover more about it:</div><ul class=\"examples\"><li><em>nuclear weapons tests</em></li><li><strong><em>test for</strong>: a test for chemicals in the water</em></li><li><em>Laboratory tests show that the new drug is very effective.</em></li><li><em>We went to the test site in Nevada.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[difficult situation]</strong> a difficult situation in which the qualities of someone or something are clearly shown:</div><ul class=\"examples\"><li><em>Chess player Nigel Short faces Anatoly Karpov in the toughest test of his career so far.</em></li><li><strong><em>test of character/strength/courage/endurance etc</strong>: The problems she faced were a real test of character.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>put somebody/something to the test</strong> to force someone or something into a difficult situation in order to discover what the limits of their strength, skills etc are:</div><ul class=\"examples\"><li><em>Living together will soon put their relationship to the test.</em></li><li><em>Paul soon found himself in an emergency situation that put all his training to the test.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[sport]</strong> <em>British English</em> a test match</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[medical]</strong> <span class=\"gram\">[transitive]</span></div><ul class=\"examples\"><li>to examine someone’s blood, body etc in order to find out what is wrong with them, or to see if they have taken an illegal drug:</li><li><em>I must have my eyes tested.</em></li><li><strong><em>test somebody for something</strong>: They tested her for diabetes.</em></li><li><strong><em>test positive/negative (for something)</strong>: Athletes who test positive for steroids are immediately banned.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[substance]</strong> <span class=\"gram\">[intransitive, transitive]</span> to examine a substance or thing in order to find out its qualities or what it contains</div><ul class=\"examples\"><li><strong><em>test (something) for something</strong>: The water should be tested for lead.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[knowledge/ability]</strong> <span class=\"gram\">[transitive]</span> to ask someone spoken or written questions, or make them do a practical activity, to discover what they know about a subject:</div><ul class=\"examples\"><li><em>This task is designed to test your reading skills</em></li><li><strong><em>test somebody on something</strong>: We’re being tested on grammar tomorrow.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[machine/product]</strong> <span class=\"gram\">[transitive]</span> (also test out) to use something for a short time to see if it works in the correct way: ► see thesaurus at check</div><ul class=\"examples\"><li><em>The Ferrari team wanted to test their new car out on the racetrack.</em></li><li><strong><em>test something on somebody/something</strong>: None of this range of cosmetics has been tested on animals.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[show how good/strong]</strong> <span class=\"gram\">[transitive]</span> to show how good or strong someone or something is, especially by putting them in a difficult situation: → testing</div><ul class=\"examples\"><li><em>a game that will test the contestants’ strength and skill</em></li><li><em>The next six months will test your powers of leadership.</em></li><li><em>I felt that she was testing me, leaving all that cash lying around.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[idea/plan]</strong> <span class=\"gram\">[transitive]</span> (also test out) to start to use an idea or plan to find out if it is correct or effective:</div><ul class=\"examples\"><li><em>Dr Lee set up a series of experiments to test out this hypothesis.</em></li><li><strong><em>test something against something</strong>: The theory was then tested against the results of the study.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>test the water/waters</strong> to check people’s reaction to a plan before you decide to use it:</div><ul class=\"examples\"><li><em>The government is clearly testing the water, to gauge the country’s reactions to their proposals.</em></li></ul></div></div>","6954":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tes‧ti‧fy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtestɪfaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(past tense and past participle testified, present participle testifying, third person singular testifies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to make a formal statement of what is true, especially in a court of law:</div><ul class=\"examples\"><li><em>Mr Molto has agreed to testify at the trial.</em></li><li><strong><em>testify against</strong>: Later, the witness who had testified against Muawad withdrew his allegation.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> <em>written</em> to show clearly that something is the case</div><ul class=\"examples\"><li><strong><em>testify to</strong>: The empty shops in the high street testify to the depth of the recession.</em></li><li><strong><em>testify that</strong>: The full ashtrays testify that smoking hasn’t been stubbed out. / Can you testify that you saw the defendant at the scene of the crime?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> <em>American English</em> to stand up and tell people about how God has helped you in your life <em>SYN witness</em></div></div>","6955":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tes‧ti‧mo‧ny</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtestəməni $ -moʊni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural testimonies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a formal statement saying that something is true, especially one a witness makes in a court of law:</div><ul class=\"examples\"><li><em>Barker’s testimony is crucial to the prosecution’s case.</em></li><li><em>In his testimony, he denied that the company had ignored safety procedures.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a fact or situation that shows or proves very clearly that something exists or is true</div><ul class=\"examples\"><li><strong><em>be a testimony to/of something</strong>: These results are a testimony to the coach’s skill and hard work.</em></li></ul></div>","6956":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tekst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> any written material:</div><ul class=\"examples\"><li><em>One disk can store the equivalent of 500 pages of text.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the writing that forms the main part of a book, magazine etc, rather than the pictures or notes → textual:</div><ul class=\"examples\"><li><em>There should not be too much text in children’s books.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a book or other piece of writing that is connected with learning or intended for study:</div><ul class=\"examples\"><li><em>Some of the original text has survived.</em></li><li><em>Literary texts, like all other works of art, have a historical context.</em></li><li><em>‘Hamlet’ is a set text (=one that must be studied for an examination) this year.</em>British English**</li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>American English</em> a textbook:</div><ul class=\"examples\"><li><em>a chemistry text</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the text of something</strong> the exact words of a speech, article etc:</div><ul class=\"examples\"><li><em>Only ‘The Times’ printed the full text of the president’s speech.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable]</span> a text message:</div><ul class=\"examples\"><li><em>He sent me a text saying he would be late.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <span class=\"gram\">[countable]</span> a short piece from the Bible that someone reads and talks about during a religious service</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to send someone a written message on a mobile phone</div></div></div>","6957":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> text‧book</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtekstbʊk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●●</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a book that contains information about a subject that people study, especially at school or college: ► see thesaurus at book</div><ul class=\"examples\"><li><em>a biology textbook</em></li></ul></div>","6958":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tex‧tile</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtekstaɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> any type of woven cloth that is made in large quantities – used especially by people in the business of making clothes etc:</div><ul class=\"examples\"><li><em>Their main exports are textiles, especially silk and cotton.</em></li><li><strong><em>textile industry/design/manufacture etc</strong>: textile design and technology / a textile mill</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>textiles</strong> <span class=\"gram\">[plural]</span> the industry involved in making cloth</div></div>","6959":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tex‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtekstʃə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the way a surface or material feels when you touch it, especially how smooth or rough it is</div><ul class=\"examples\"><li><strong><em>smooth/silky/rough etc texture</strong>: the smooth texture of silk</em></li><li><em>a designer who experiments with different colours and textures</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the way that a particular type of food feels in your mouth</div><ul class=\"examples\"><li><strong><em>creamy/crunchy/meaty etc texture</strong>: This soup has a lovely creamy texture.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> the way the different parts of a piece of writing, music, art etc are combined in order to produce a final effect:</div><ul class=\"examples\"><li><em>the rich texture of Shakespeare’s English</em></li></ul></div>","6960":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðən; strong ðæn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used when comparing two things, people, situations etc:</div><ul class=\"examples\"><li><em>Natalie was prettier than her sister.</em></li><li><em>You need that money more than I do.</em></li><li><em>There were more people there than I expected.</em></li><li><em>If it costs more than $60, I won’t buy it.</em></li><li><em>She had woken even earlier than usual.</em></li><li><em>Divorce is more common than it was a generation ago.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>other than</strong> except for a particular person or thing:</div><ul class=\"examples\"><li><em>We never go to church other than for funerals and weddings.</em></li><li><em>We know he lived in Fleet Road, but other than that we don’t know much about him.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>would rather/would sooner... than</strong> used to say that you prefer one thing to another:</div><ul class=\"examples\"><li><em>I’d rather drive than go by train.</em></li><li><em>She said she’d rather die than live in the city.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>no sooner/hardly had... than</strong> used to say that one thing happens immediately after another thing:</div><ul class=\"examples\"><li><em>No sooner had I got into the house than the phone rang.</em></li><li><em>Hardly had they reached Edinburgh than they were ordered to return to London.</em></li></ul></div>","6961":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θæŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to tell someone that you are pleased and grateful for something they have done, or to be polite about it:</div><ul class=\"examples\"><li><em>I haven’t had a chance to thank him yet.</em></li><li><strong><em>thank somebody for (doing) something</strong>: Did you thank Uncle Ron for the present? / Madeleine thanked everyone for coming.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>thank God/goodness/heavens</strong> used to show that you are very glad about something:</div><ul class=\"examples\"><li><em>Thank God that’s over! I’ve never been so nervous in my life!</em></li><li><strong><em>thank for</strong>: ‘Only ten miles to go.’ ‘Thank heavens for that!’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>thank your lucky stars</strong> <em>spoken</em> used to tell someone that they are very lucky, especially because they have avoided an unpleasant or dangerous situation:</div><ul class=\"examples\"><li><em>You should thank your lucky stars I got here when I did!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>only have yourself to thank (for something)</strong> <em>spoken</em> used to say that you are responsible for something bad that has happened to you:</div><ul class=\"examples\"><li><em>She has only herself to thank if she doesn’t have any friends.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>you’ll thank me</strong> <em>spoken</em> used to tell someone not to be annoyed with you for doing or saying something, because it will be helpful to them later:</div><ul class=\"examples\"><li><em>You’ll thank me for this one day, Laura.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>somebody won’t thank you (for doing something)</strong> used to tell someone that another person will be annoyed because of what they have done:</div><ul class=\"examples\"><li><em>I know you’re just trying to help, but he won’t thank you for telling him how to do it.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>I’ll thank you to do something</strong> <em>spoken</em> <em>formal</em> used to tell someone in an angry way not to do something because it is annoying you:</div><ul class=\"examples\"><li><em>I’ll thank you to mind your own business.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>have somebody to thank for (doing) something</strong> to say that you are grateful to someone who is responsible for something good happening. This expression is sometimes used humorously to mean that you are not grateful for what someone has done:</div><ul class=\"examples\"><li><em>I have Phil to thank for getting me my first job.</em></li><li><em>And who do I have to thank for that mess on my desk?</em></li></ul></div>","6962":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈthank you</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to tell someone that you are grateful for something they have given you or done for you <em>SYN thanks</em>: ► Don’t say ‘I thank you’.</div><ul class=\"examples\"><li><em>Margaret handed him the butter. ‘Thank you,’ said Samuel.</em></li><li><em>Thank you very much, Brian.</em></li><li><strong><em>thank you for (doing) something</strong>: It’s good to see you, Mr Mathias. Thank you for coming. / Dear Grandma, thank you for the lovely shirt you sent me for Christmas.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used as a polite way of accepting something that someone has offered:</div><ul class=\"examples\"><li><em>‘Can I give you a lift into town?’ ‘Oh, thank you.’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used when politely answering someone’s question:</div><ul class=\"examples\"><li><em>‘How was your trip to Paris?’ ‘Very nice, thank you.’</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>no, thank you</strong> used to say politely that you do not want something:</div><ul class=\"examples\"><li><em>‘Would you like some more coffee?’ ‘No, thank you, I’m fine.’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used at the end of a sentence when telling someone firmly that you do not want their help or advice and are slightly annoyed by it:</div><ul class=\"examples\"><li><em>I can manage quite well on my own, thank you!</em></li></ul></div>","6963":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thank‧ful‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθæŋkfəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> used to say that you are glad that something has happened, especially because a difficult situation has ended or been avoided:</div><ul class=\"examples\"><li><em>Thankfully, I managed to pay off all my debts before we got married.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> feeling grateful and glad about something, especially because a difficult situation has ended or been avoided:</div><ul class=\"examples\"><li><em>We came in and collapsed thankfully onto our beds.</em></li></ul></div>","6964":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">interjection</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θæŋks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to tell someone that you are grateful for something they have given you or done for you <em>SYN thank you</em>:</div><ul class=\"examples\"><li><em>‘Pass the salt, please... thanks.’</em></li><li><strong><em>thanks for</strong>: Thanks a lot for the drink. / Thanks very much for your help. / Many thanks for the lovely flowers.</em></li><li><strong><em>thanks for doing something</strong>: I’d love to go to the party. Thanks for asking me.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used as a polite way of accepting something that someone has offered you:</div><ul class=\"examples\"><li><em>‘Do you want another cup of coffee?’ ‘Oh, thanks.’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>spoken</em> used when politely answering someone’s question:</div><ul class=\"examples\"><li><em>‘Hi, Bill, how are you?’ ‘Fine, thanks.’</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>no thanks</strong> used to say politely that you do not want something:</div><ul class=\"examples\"><li><em>‘How about some cake?’ ‘Oh, no thanks, I’m on a diet.’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>thanks a lot</strong> (also thanks a bunch<em>American English</em> <em>spoken</em>) used when really you are annoyed about something and you do not mean ‘thank you’ at all</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the things you say or do to show that you are grateful to someone:</div><ul class=\"examples\"><li><em>Joe got up and left without a word of thanks.</em></li><li><strong><em>thanks to</strong>: My thanks to all of you for your help.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>thanks to somebody/something</strong> <em>informal</em> because of someone or something: ► Don’t say ‘thank to someone/something’.</div><ul class=\"examples\"><li><em>We’ve reached our goal of $50,000, thanks to the generosity of the public.</em></li><li><em>Some ski resorts opened early, thanks to a late-October snowstorm.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>no thanks to somebody/something</strong> <em>spoken</em> an expression meaning ‘in spite of’, used when someone should have helped you but did not:</div><ul class=\"examples\"><li><em>It was no thanks to you that we managed to win the game.</em></li></ul></div></div>","6965":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a public holiday in the US and in Canada when families have a large meal together to celebrate and be thankful for food, health, families etc</div></div>","6966":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">determiner</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðæt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (plural those /ðəʊz $ ðoʊz/) used to refer to a person, thing, idea etc that has already been mentioned or is already known about:</div><ul class=\"examples\"><li><em>‘You never cared about me.’ ‘That’s not true.’</em></li><li><em>I wish you wouldn’t say things like that.</em></li><li><em>What did you do with those sandwiches?</em></li><li><em>Victoria Street? That’s where my sister lives.</em></li><li><em>Do you remember that nice Mr Hoskins who came to dinner?</em></li><li><em>I’ve got that pain in my back again.</em></li><li><em>He killed a man once and that’s why he had to leave Ireland.</em></li><li><em>‘We’ve been cheated,’ she said. Those were her exact words.</em></li><li><em>‘I have to go,’ she said, and with that (=after saying that) she hung up the phone.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> /ðət/ used after a noun as a relative pronoun like ‘who’, ‘whom’, or ‘which’ to introduce a clause: GRAMMAR• In everyday English, that is often omitted when it is the object of the relative clause: · I like the clothes that she wears.· I like the clothes she wears.• You do not omit that when it is the subject of the clause: · The family that lives downstairs is Polish. ✗Don’t say: The family lives downstairs is Polish.</div><ul class=\"examples\"><li><em>There are lots of things that I need to buy before the trip.</em></li><li><em>the people that live next door</em></li><li><em>They’ve got a machine that prints names on badges.</em></li><li><em>the greatest boxer that ever lived</em></li><li><em>Who was it that said ‘The Law’s an Ass’?</em></li><li><em>The day that my father died, I was on holiday in Greece.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> (plural those /ðəʊz $ ðoʊz/) <em>formal</em> used to refer to a particular person or thing of the general type that has just been mentioned:</div><ul class=\"examples\"><li><em>In my opinion, the finest wines are those from France.</em></li><li><strong><em>that of</strong>: His own experience was different from that of his friends.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>those who</strong> people who:</div><ul class=\"examples\"><li><em>There are those who disapprove of all forms of gambling.</em></li><li><em>Those who saw the performance thought it memorable.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>at that</strong> used after adding a piece of information which emphasizes and increases what you have just said:</div><ul class=\"examples\"><li><em>You should be able to answer the question in a single sentence, and a short one at that.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>that is (to say)</strong> used to give more exact information about something or to correct a statement:</div><ul class=\"examples\"><li><em>One solution would be to change the shape of the screen, that is, to make it wider.</em></li><li><em>Languages are taught by the direct method, that is to say, without using the student’s own language.</em></li><li><em>I loved him – that is, I thought I did.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">conjunction</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used after verbs, nouns, and adjectives to introduce a clause which shows what someone says or thinks, or states a fact or reason: GRAMMAR• In everyday English, that is often omitted. Instead of saying · I’m not surprised that you were upset, you say · I’m not surprised you were upset.• In formal English, that is used more often in this situation.</div><ul class=\"examples\"><li><em>If she said that she’d come, she’ll come.</em></li><li><em>I can’t believe that he’s only 17.</em></li><li><em>Are you sure that they live in Park Lane?</em></li><li><em>allegations that he is guilty of war crimes</em></li><li><em>The fact that he is your brother-in-law should not affect your decision.</em></li><li><em>He might have left the money for the simple reason that he didn’t know it was there.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used after a phrase with ‘so’ or ‘such’ to introduce a clause that shows the result of something:</div><ul class=\"examples\"><li><em>I was so tired that I fell asleep.</em></li><li><em>The school was so badly damaged that it had to be pulled down.</em></li><li><em>We had been away for such a long time that I had forgotten her name.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to introduce a clause that refers to a fact, when describing it:</div><ul class=\"examples\"><li><em>It’s odd that I haven’t heard of you.</em></li><li><em>That anyone should want to kill her was unthinkable.</em></li><li><em>The problem is that no-one knows what will happen.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>formal</em> in order that something may happen or someone may do something:</div><ul class=\"examples\"><li><em>Give us strength that we may stand against them.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>literary</em> used to express a wish for something to happen or be true, especially when this is not possible:</div><ul class=\"examples\"><li><em>Oh, that she were alive to see this!</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðæt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[+adjective/adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>spoken</em> used to say how big, how much etc, especially when you are showing the size, amount etc with your hands:</div><ul class=\"examples\"><li><em>It was quite a large fish – about that long.</em></li><li><em>He missed hitting the car in front by that much.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually in negatives]</span> <em>spoken</em> as much as in the present situation or as much as has been stated:</div><ul class=\"examples\"><li><em>I’m sorry, I hadn’t realized the situation was that bad.</em></li><li><em>No one expected it to cost that much.</em></li><li><em>The advanced exam is more difficult, but not many students progress that far.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>not (all) that long/many etc</strong> <em>spoken</em> used to mean fairly short, only a few etc:</div><ul class=\"examples\"><li><em>Will’s not that tall, considering he’s 16.</em></li><li><em>The film wasn’t all that good.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>British English</em> <em>spoken</em> <em>informal</em> used to emphasize how big, bad, much etc something is:</div><ul class=\"examples\"><li><em>I was that embarrassed I didn’t know what to say.</em></li></ul></div></div>","6967":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">definite article</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðə; before vowels ði; strong ðiː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to show that you are talking about a particular thing or person that has already been mentioned, is already known about, or is the only one:</div><ul class=\"examples\"><li><em>The audience clapped and cheered.</em></li><li><em>I ordered a pizza and salad. The pizza was nice but the salad was disgusting.</em></li><li><em>the tallest building in the world</em></li><li><em>sailing across the Pacific</em></li><li><em>The prime minister has intervened personally.</em></li><li><em>Elections will be held later in the year (=this year).</em></li><li><em>How are all the family (=your family)?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used before nouns referring to actions and changes when they are followed by ‘of’:</div><ul class=\"examples\"><li><em>the growth of the steel industry</em></li><li><em>the arrival of our guests</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used when you are about to make it clear which person or thing you mean:</div><ul class=\"examples\"><li><em>That’s the school that Terry went to.</em></li><li><em>She laughed at the birthday card from Myra.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used before the name of a family in the plural to refer to all the members of that family:</div><ul class=\"examples\"><li><em>The Johnsons had lived in this house for many years.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to refer to something that everyone knows because it is part of our natural environment or part of daily life:</div><ul class=\"examples\"><li><em>What was the weather like?</em></li><li><em>I looked out into the darkness.</em></li><li><em>Sometimes the traffic kept her awake at night.</em></li><li><em>The shops open at 9 o’clock.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used before a singular noun to refer to a type of institution, shop, system etc:</div><ul class=\"examples\"><li><em>You used to buy them from the chemist.</em></li><li><em>I heard it on the radio.</em></li><li><em>I’ll put it in the mail for you today.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used to refer to a part of someone’s body:</div><ul class=\"examples\"><li><em>Lieutenant Taylor was wounded in the knee.</em></li><li><em>How’s the ankle? Is it still hurting?</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> used before an adjective to make it into a plural noun when you are referring to all the people that the adjective describes:</div><ul class=\"examples\"><li><em>She devoted her life to helping the poor.</em></li><li><em>a school for the deaf</em></li><li><em>wars between the English and the French</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> used before an adjective to make it into a noun when you are referring to the particular kind of situation or thing that the adjective describes:</div><ul class=\"examples\"><li><em>Come on now, that’s asking for the impossible.</em></li><li><em>fantasy movies that make the unreal seem real</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> used before a singular noun when you are referring to a particular type of thing or person in a general way:</div><ul class=\"examples\"><li><em>The tiger is without doubt the most magnificent of the big cats.</em></li><li><em>The computer has changed everyone’s lives in so many ways.</em></li><li><em>complicated dances like the tango</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to refer to a period of time, especially a period of 10 or 100 years:</div><ul class=\"examples\"><li><em>fashions of the 60s</em></li><li><em>the great novelists of the 1900s</em></li><li><em>She remembers the war years.</em></li><li><em>In the thirties unemployment was widespread.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to mention a date:</div><ul class=\"examples\"><li><em>the 3rd of November</em></li><li><em>The battle took place on March the 21st, 1940.</em></li><li><em>Shall we meet on the twelfth?</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> enough of something for a particular purpose:</div><ul class=\"examples\"><li><em>I haven’t the time to talk just now.</em></li><li><em>Eric didn’t even have the common sense to send for a doctor.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> used to say which type of musical instrument someone plays:</div><ul class=\"examples\"><li><em>Fiona’s learning the flute.</em></li><li><em>He plays the violin.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> used to refer to a type of sport or a sports event, especially in athletics or swimming:</div><ul class=\"examples\"><li><em>Who won the long jump?</em></li><li><em>She swam up and down, practising the crawl.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <em>spoken</em> used before a word or phrase that describes someone or something when you are angry, jealous, surprised etc:</div><ul class=\"examples\"><li><em>He’s stolen my parking space, the bastard!</em></li><li><em>I can’t get this carton open, the stupid thing.</em></li><li><em>‘Jamie’s won a holiday in Hawaii.’ ‘The lucky devil!’</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> used to emphasize that the person, place, or thing you are mentioning is the famous one, or the best or most fashionable one. ‘The’ is pronounced strongly or written in a special way:</div><ul class=\"examples\"><li><em>‘Elizabeth Taylor was there.’ ‘Not the Elizabeth Taylor, surely?’</em></li><li><em>Miami is THE place for girls who like to live life to the full.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> used before the names of certain common illnesses:</div><ul class=\"examples\"><li><em>If one of the children got the measles, we all got the measles.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used before two comparative adjectives or adverbs to show that the degree of one event or situation is related to the degree of another one:</div><ul class=\"examples\"><li><em>The more he eats the fatter he gets.</em></li><li><em>‘When do you want it?’ ‘The sooner the better.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used before an adjective or adverb to emphasize that something is bigger, better etc than all others, or as big, good etc as it is possible for it to be:</div><ul class=\"examples\"><li><em>He likes you the best.</em></li><li><em>I had the worst headache last night.</em></li></ul></div></div>","6968":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thea‧tre</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɪətə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[building]</strong> <span class=\"gram\">[countable]</span> a building or place with a stage where plays and shows are performed:</div><ul class=\"examples\"><li><em>an open-air theatre (=a theatre that is outside)</em></li><li><em>the Mercury Theater</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[plays]</strong> <span class=\"gram\">[uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> plays as a form of entertainment:</div><ul class=\"examples\"><li><em>I enjoy theater and swimming.</em></li><li><strong><em>the theatre</strong>: He’s really interested in literature and the theatre.</em></li><li><em>Yeats’ plays are great poetry but they are not good theatre (=good entertainment).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the work of acting in, writing, or organizing plays:</div><ul class=\"examples\"><li><em>classes in theater and music</em></li><li><strong><em>in the theatre</strong>: She’s been working in the theatre over thirty years.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[place to see a film]</strong> <span class=\"gram\">[countable]</span> <em>American English</em> a building where films are shown SYN movie theater<em>American English</em>, cinema<em>British English</em>:</div><ul class=\"examples\"><li><em>‘Bambi’ was the first movie I ever saw in the theater.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[hospital]</strong> <span class=\"gram\">[countable, uncountable]</span> <em>British English</em> a special room in a hospital where medical operations are done SYN operating room<em>American English</em></div><ul class=\"examples\"><li><strong><em>in theatre</strong>: Marilyn is still in theatre.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[war]</strong> <span class=\"gram\">[countable]</span> <em>formal</em> a large area where a war is being fought:</div><ul class=\"examples\"><li><em>the Pacific theater during World War II</em></li></ul></div>","6969":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> the‧at‧ri‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /θiˈætrɪkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to the performing of plays:</div><ul class=\"examples\"><li><em>a Polish theatrical company</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> behaving in a loud or very noticeable way that is intended to get people’s attention:</div><ul class=\"examples\"><li><em>She gave a theatrical sigh.</em></li></ul></div>","6970":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θeft/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the crime of stealing → thief, burglary, robbery: ► see thesaurus at crime</div><ul class=\"examples\"><li><em>Car theft is on the increase.</em></li><li><em>an arrest for petty theft (=stealing small things)</em></li><li><em>Three men were charged with attempted theft.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an act of stealing something:</div><ul class=\"examples\"><li><em>There have been a number of thefts in the area.</em></li><li><strong><em>theft of</strong>: the theft of £150 from the office</em></li></ul></div>","6971":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðə; strong ðeə $ ðər strong ðer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[possessive form of ‘they’]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> belonging to or connected with people or things that have already been mentioned:</div><ul class=\"examples\"><li><em>They washed their faces and went to bed.</em></li><li><em>The twins spend all their time together.</em></li><li><em>People had moved back into their own homes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used when talking about someone who may be male or female, to avoid saying ‘his or her’:</div><ul class=\"examples\"><li><em>Everyone is free to express their own opinion.</em></li><li><em>Each student will have their own course-work folder.</em></li></ul></div>","6972":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðeəz $ ðerz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[possessive form of ‘they’]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to refer to something that belongs to or is connected with people that have already been mentioned:</div><ul class=\"examples\"><li><em>When our washing machine broke, our neighbours let us use theirs.</em></li><li><em>Our house is number 25, and theirs is just opposite.</em></li><li><em>We compared scores and found that theirs were higher than ours.</em></li><li><strong><em>of theirs</strong>: They shared the prize money with a friend of theirs.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used when talking about someone who may be male or female, to avoid saying ‘his or hers’:</div><ul class=\"examples\"><li><em>Everyone wants what is theirs by right.</em></li></ul></div>","6973":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðəm; strong ðem/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[object form of ‘they’]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to refer to two or more people or things that have already been mentioned or are already known about:</div><ul class=\"examples\"><li><em>Has anyone seen my keys? I can’t find them anywhere.</em></li><li><em>The police were very helpful when I spoke to them.</em></li><li><em>I lent him several books, but he hasn’t read any of them.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used when talking about someone who may be male or female, to avoid saying ‘him or her’:</div><ul class=\"examples\"><li><em>If anyone phones, tell them I’ll be back later.</em></li></ul></div>","6974":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θiːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[subject]</strong> the main subject or idea in a piece of writing, speech, film etc:</div><ul class=\"examples\"><li><em>The book’s theme is the conflict between love and duty.</em></li><li><strong><em>main/central/major etc theme</strong>: Campbell has made health care a central theme in his campaign.</em></li><li><em>Nature is a recurrent theme (=a theme that appears repeatedly) in Frost’s poetry.</em></li><li><em>Most of Kurt’s other pictures were variations on the same theme.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>theme music/song/tune</strong> music or a song that is often played during a film or musical play, or at the beginning and end of a television or radio programme:</div><ul class=\"examples\"><li><em>the theme song from ‘The Brady Bunch’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[repeated tune]</strong> a short simple tune that is repeated and developed in a piece of music:</div><ul class=\"examples\"><li><em>Freia’s theme in Wagner’s opera</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[style]</strong> a particular style:</div><ul class=\"examples\"><li><em>Her bedroom is decorated in a Victorian theme.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[piece of writing]</strong> <em>American English</em> <em>old-fashioned</em> a short piece of writing on a particular subject that you do for school <em>SYN essay</em></div><ul class=\"examples\"><li><strong><em>theme on</strong>: Your homework is to write a two-page theme on pollution.</em></li></ul></div>","6975":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> them‧selves</span><span class=\"meta-item\"><strong>IPA:</strong> /ðəmˈselvz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to show that the people who do something are affected by their own action:</div><ul class=\"examples\"><li><em>Teachers have no choice but to take measures to protect themselves.</em></li><li><em>Our neighbours have just bought themselves a jacuzzi.</em></li><li><em>The kids seem very pleased with themselves.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to emphasize the pronoun ‘they’, a plural noun etc:</div><ul class=\"examples\"><li><em>Doctors themselves are the first to admit the treatment has side effects.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used after words like ‘everyone’, ‘anyone’, ‘no one’ etc when you talk about someone already mentioned and you do not know what sex they are or it is not important. Many teachers think this is not correct English:</div><ul class=\"examples\"><li><em>Someone told me they’d actually seen the accident happen themselves.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in themselves</strong> (also in and of themselves) considered without other related ideas or situations:</div><ul class=\"examples\"><li><em>The carvings are works of art in themselves, even disregarding their religious significance.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>(all) by themselves</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> alone:</div><ul class=\"examples\"><li><em>older people who are living all by themselves</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> without help from anyone else:</div><ul class=\"examples\"><li><em>Did the children make the model all by themselves?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>(all) to themselves</strong> if people have something to themselves, they do not have to share it with anyone:</div><ul class=\"examples\"><li><em>They had the whole beach to themselves.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>not be/feel themselves</strong> if people are not themselves, they do not feel or behave in the way they usually do because they are nervous, upset, or ill</div></div>","6976":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðen/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> at a particular time in the past or future:</div><ul class=\"examples\"><li><em>I wish I had known then what I know now.</em></li><li><em>It was then that I realised she’d tricked me.</em></li><li><em>He started his career in St Petersburg – or Leningrad as it then was.</em></li><li><strong><em>by/until/since then</strong>: They’re sending out the results next week, so we won’t know anything until then. / It was late evening when the doctor arrived, and by then it was too late. / That was in 1970. Since then the place has changed a lot.</em></li><li><em>They met in 1942 and from then on (=starting at that time) they were firm friends.</em></li><li><em>Silently she closed the door. Just then she heard a noise.</em></li><li><em>I was paid £1,000, which was a lot of money back then (=a long time ago when things were different) in the 1950s.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say what happens next or what you do next:</div><ul class=\"examples\"><li><em>Mix the flour and butter, then add the eggs.</em></li><li><em>Byron travelled to Italy and then to Greece.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> used when saying what the result of a situation or action will be:</div><ul class=\"examples\"><li><em>If you won’t tell him, then I will.</em></li><li><em>Start off early, then you won’t have to rush.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>spoken</em> used when you think that something is probably true because of what you know about the situation:</div><ul class=\"examples\"><li><em>Still in your pyjamas? Have you just got out of bed then?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>but then (again)</strong> used to say that although something is true, something else is also true which makes the first thing seem less important:</div><ul class=\"examples\"><li><em>William didn’t succeed first time, but then very few people do.</em></li><li><em>Elaine’s father might lend them the money, but then again he might not.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used at the beginning of a conversation or activity:</div><ul class=\"examples\"><li><em>Now then, what would you like to do today?</em></li><li><em>Right then, shall we start?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used at the end of a conversation, especially to show that something has been agreed:</div><ul class=\"examples\"><li><em>Good, that’s settled then. We’ll all meet here next Wednesday.</em></li><li><em>Okay then, I’ll see you at work.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used to show that you are saying something because of what someone has just said:</div><ul class=\"examples\"><li><em>‘We’re late.’ ‘We’d better hurry, then.’</em></li><li><em>‘Friday’s no good.’ ‘Then how about Saturday?’</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to add something to what you have just mentioned:</div><ul class=\"examples\"><li><em>We have to invite your parents and my parents, and then there’s your brother.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used to refer back to what you have just been talking about:</div><ul class=\"examples\"><li><em>This then was the situation facing the government at the end of the war.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>then and there</strong> (also there and then) immediately:</div><ul class=\"examples\"><li><em>He wasn’t prepared to wait – he wanted the money then and there.</em></li></ul></div>","6977":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> theo‧ret‧i‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /θɪəˈretɪkəl $ ˌθiːə-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to the study of ideas, especially scientific ideas, rather than to practical uses of the ideas or practical experience → theory, practical, applied:</div><ul class=\"examples\"><li><em>theoretical physics</em></li><li><em>Aristotle’s theoretical model of the universe</em></li><li><em>She has theoretical knowledge of teaching, but no practical experience.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a theoretical situation or condition could exist but does not really exist <em>SYN hypothetical</em>:</div><ul class=\"examples\"><li><em>Equality between men and women in our society is still only theoretical.</em></li><li><em>a theoretical risk of an explosion</em></li></ul></div>","6978":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> theo‧ret‧i‧cally</span><span class=\"meta-item\"><strong>IPA:</strong> /θɪəˈretɪkli $ ˌθiːə-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[sentence adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to say what is supposed to be true in a particular situation, especially when the opposite is true <em>OPP in practice</em>:</div><ul class=\"examples\"><li><em>Theoretically, Damian’s the boss, but I coordinate the team on a day-to-day basis.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> according to a scientific idea that has not been proven to be true in a practical way <em>SYN hypothetically</em>:</div><ul class=\"examples\"><li><em>It is theoretically possible for computers to be programmed to think like humans.</em></li></ul></div>","6979":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> theo‧rist</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɪərɪst $ ˈθiːə-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who develops ideas within a particular subject that explain why particular things happen or are true:</div><ul class=\"examples\"><li><em>a leading economic theorist</em></li></ul></div>","6980":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> theo‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɪəri $ ˈθiːəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span><span class=\"meta-item\">(plural theories)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an idea or set of ideas that is intended to explain something about life or the world, especially an idea that has not yet been proved to be true → theoretical</div><ul class=\"examples\"><li><strong><em>theory about/on</strong>: different theories about how the brain works</em></li><li><strong><em>theory of</strong>: Darwin’s theory of evolution</em></li><li><strong><em>theory that</strong>: the theory that light is made up of waves</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> general principles and ideas about a subject:</div><ul class=\"examples\"><li><em>Freudian theory has had a great influence on psychology.</em></li><li><strong><em>political/economic/literary etc theory</strong>: I’m taking a course on political theory.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in theory</strong> something that is true in theory is supposed to be true, but might not really be true or might not be what will really happen <em>OPP in practice</em>:</div><ul class=\"examples\"><li><em>In theory, everyone will have to pay the new tax.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> an idea or opinion that someone thinks is true but for which they have no proof</div><ul class=\"examples\"><li><strong><em>theory that</strong>: Detectives are working on a theory that he knew his murderer.</em></li></ul></div>","6981":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ther‧a‧peu‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌθerəˈpjuːtɪk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> making you feel calm and relaxed:</div><ul class=\"examples\"><li><em>I find swimming very therapeutic.</em></li><li><em>the therapeutic effect of gardening</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually before noun]</span> relating to the treatment or cure of an illness → therapy:</div><ul class=\"examples\"><li><em>Some claim that the herb has therapeutic value for treating pain.</em></li></ul></div>","6982":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ther‧a‧pist</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθerəpɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who has been trained to give a particular form of treatment for physical or mental illness: ► see thesaurus at doctor</div><ul class=\"examples\"><li><em>a speech therapist</em></li></ul></div>","6983":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ther‧a‧py</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθerəpi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural therapies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the treatment of an illness or injury over a fairly long period of time:</div><ul class=\"examples\"><li><em>new drug therapies</em></li><li><em>radiation therapy for cancer treatment</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the treatment or examination of someone’s mental problems by talking to them for a long time about their feelings <em>SYN psychotherapy</em></div><ul class=\"examples\"><li><strong><em>in therapy</strong>: Rob was in therapy for several years.</em></li><li><em>a therapy group</em></li></ul></div>","6984":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">pronoun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðeə, ðə $ ðer, ðər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>there is/exists/remains etc</strong> used to say that something exists or happens:</div><ul class=\"examples\"><li><em>Is there any milk left?</em></li><li><em>There are a few things we need to discuss.</em></li><li><em>There must be easier ways of doing this.</em></li><li><em>There seems to be a lack of communication.</em></li><li><em>There remain several questions still to be answered.</em></li><li><em>Suddenly there was a loud explosion.</em></li><li><em>They were all laughing when there came a knock at the door.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðeə $ ðer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or to a particular place that is not where you are → here: ► Don’t say ‘to there’: We went there (NOT went to there) by car.</div><ul class=\"examples\"><li><em>We could go back to my cottage and have lunch there.</em></li><li><em>Scotland? I’ve always wanted to go there.</em></li><li><em>Hold it right there and don’t move.</em></li><li><em>Can you pass me that wine glass there?</em></li><li><em>Look, there’s that bookshop I was telling you about.</em></li><li><em>Who’s that man over there?</em></li><li><em>It’s too far to drive there and back in one day.</em></li><li><em>Are we going to get there (=arrive) before the banks close?</em></li><li><strong><em>out/in/under etc there</strong>: I know there’s a mouse under there somewhere. / We flew to Miami and from there to La Paz.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if something is there, it exists:</div><ul class=\"examples\"><li><em>The chance was there, but I didn’t take it.</em></li><li><em>The countryside is there for everyone to enjoy.</em></li><li><em>Three months after the operation, the pain was still there.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> at or to a particular point in time, in a process, or in a story:</div><ul class=\"examples\"><li><em>Let’s stop there and I’ll tell you the rest of the story tomorrow.</em></li><li><em>She got a divorce, but her troubles didn’t end there.</em></li><li><em>There’s still a lot of work to do, but we’re getting there (=coming to the end of the process) slowly.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>there and then</strong> (also then and there) immediately:</div><ul class=\"examples\"><li><em>I thought I’d have to wait, but they offered me the job there and then.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">interjection</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðeə $ ðer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>spoken</em> used to express satisfaction that you have been proved right or that you have done what you intended to do:</div><ul class=\"examples\"><li><em>There! I’ve done it! I’ve resigned.</em></li><li><em>There, what did I tell you? I knew it wouldn’t work.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>there, there!</strong> <em>spoken</em> used to comfort someone who is crying, especially a child:</div><ul class=\"examples\"><li><em>There, there, don’t get so upset!</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>so there!</strong> <em>spoken</em> used to show someone that you do not care what they think and you are not going to change your mind – used by children:</div><ul class=\"examples\"><li><em>I’m going to Elly’s party, and you can’t stop me, so there!</em></li></ul></div></div>","6985":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> there‧af‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ðeərˈɑːftə $ ðerˈæftər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">after a particular event or time <em>SYN afterwards</em>:</div><ul class=\"examples\"><li><em>10,000 men had volunteered by the end of September; thereafter, approximately 1,000 men enlisted each month.</em></li><li><em>Sophie was born in France, but shortly thereafter her family moved to the United States.</em></li></ul></div>","6986":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> there‧by</span><span class=\"meta-item\"><strong>IPA:</strong> /ðeəˈbaɪ, ˈðeəbaɪ $ ðerˈbaɪ, ˈðer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">with the result that something else happens</div><ul class=\"examples\"><li><strong><em>thereby doing something</strong>: He became a citizen in 1978, thereby gaining the right to vote.</em></li></ul></div>","6987":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> there‧fore</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈðeəfɔː $ ˈðerfɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1</span></div><div class=\"entry-body\"><div class=\"sense\">as a result of something that has just been mentioned: RegisterIn everyday English, people usually use so rather than therefore:· It was late, so I didn’t stay long.</div><ul class=\"examples\"><li><em>Their car was bigger and therefore more comfortable.</em></li><li><em>Progress so far has been very good. We are, therefore, confident that the work will be completed on time.</em></li></ul></div>","6988":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ther‧mom‧e‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /θəˈmɒmɪtə $ θərˈmɑːmɪtər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of equipment that measures the temperature of the air, of your body etc:</div><ul class=\"examples\"><li><em>The thermometer registered over 100º C.</em></li><li><strong><em>a candy/meat thermometer</strong> (=used in cooking)</em></li></ul></div>","6989":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> the‧sis</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθiːsɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural theses /-siːz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a long piece of writing about a particular subject that you do as part of an advanced university degree such as an MA or a PhD:</div><ul class=\"examples\"><li><em>Cynthia’s still working on her thesis.</em></li><li><strong><em>graduate/master’s/doctoral thesis</strong>: He wrote his doctoral thesis on contemporary French literature.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> an idea or opinion about something, that you discuss in a formal way and give examples for:</div><ul class=\"examples\"><li><em>Their main thesis was that the rise in earnings was due to improvements in education.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> in writing, the thesis is the sentence or group of sentences which state what the main idea of an essay is:</div><ul class=\"examples\"><li><em>a paragraph introducing your thesis statement</em></li></ul></div>","6990":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðeɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[used as the subject of a verb]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to refer to two or more people or things that have already been mentioned or are already known about:</div><ul class=\"examples\"><li><em>Bob and Sue said they wouldn’t be able to come.</em></li><li><em>Ken gave me some flowers. Aren’t they beautiful?</em></li><li><em>They all want to come to the wedding.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>they say/think etc</strong> used to state what people in general say or think:</div><ul class=\"examples\"><li><em>They say it’s bad luck to spill salt.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>spoken</em> used to refer to a particular organization or group of people:</div><ul class=\"examples\"><li><em>Where are they going to build the new highway?</em></li><li><em>They’re going to take an X-ray.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used when talking about someone who may be male or female, to avoid saying ‘he or she’:</div><ul class=\"examples\"><li><em>If anyone has any information related to the crime, will they please contact the police.</em></li><li><em>Every child, whoever they are, deserves to have a mum and a dad.</em></li></ul></div>","6991":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(comparative thicker, superlative thickest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not thin]</strong></div><ul class=\"examples\"><li>if something is thick, there is a large distance or a larger distance than usual between its two opposite surfaces or sides <em>OPP thin</em>:</li><li><em>a thick oak door</em></li><li><em>a thick slice of homemade bread</em></li><li><em>He was wearing thick glasses.</em></li><li><em>short thick fingers</em></li><li><em>thick wool socks (=socks that are heavy and warm)</em></li><li><em>If you want a thicker blanket, there are more here in the closet.</em></li><li><em>The meat is done when the thickest part turns from pink to white.</em></li><li><strong><em>thick with</strong>: The furniture was thick with dust (=there was thick dust on the furniture).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[measurement]</strong> measuring a particular distance between two opposite sides or surfaces of something</div><ul class=\"examples\"><li><strong><em>3 feet/1 cm/two inches etc thick</strong>: The walls are about two meters thick.</em></li><li><em>How thick should the glass in the tank be?</em></li><li><em>This layer of brain tissue is no thicker than 2 mm.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[trees/bushes etc]</strong> growing very close together or having a lot of leaves <em>SYN dense</em>:</div><ul class=\"examples\"><li><em>birds hiding in the thick undergrowth</em></li><li><strong><em>thick with</strong>: The walls were thick with ivy.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[smoke/cloud etc]</strong> filling the air, and difficult to see through or breathe in <em>SYN dense</em>:</div><ul class=\"examples\"><li><em>thick fog</em></li><li><strong><em>thick with</strong>: The air was thick with cigarette smoke.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[liquid]</strong> almost solid, and therefore flowing very slowly, or not flowing at all:</div><ul class=\"examples\"><li><em>For a thicker gravy, add more flour.</em></li><li><em>The paint is too thick.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[hair/fur]</strong> having a lot of hair or fur:</div><ul class=\"examples\"><li><em>She ran her fingers through her thick brown hair.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[stupid]</strong> <em>British English</em> <em>informal</em> a thick person is stupid:</div><ul class=\"examples\"><li><em>He’s a nice guy, but he’s a bit thick.</em></li><li><strong><em>(as) thick as two short planks</strong> (=very stupid)</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[voice]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if someone has a thick accent, the way they speak shows clearly which particular place or part of a country they come from</div><ul class=\"examples\"><li><strong><em>a thick German/Yorkshire etc accent</strong>: Olga speaks English with a thick Russian accent.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if someone’s voice is thick, it is not as clear or high as usual, for example because they are upset:</div><ul class=\"examples\"><li><em>Bill’s voice was thick and gruff.</em></li><li><strong><em>thick with</strong>: Her voice was thick with emotion.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[large amount]</strong> <em>especially written</em> containing a lot of people or things:</div><ul class=\"examples\"><li><em>The cod were so thick in the water that they caught thousands very quickly.</em></li><li><strong><em>thick with</strong>: The roads were thick with holiday traffic.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be thick on the ground</strong> <em>British English</em> to be present or available in large amounts or numbers <em>OPP thin on the ground</em>:</div><ul class=\"examples\"><li><em>Cheap houses aren’t as thick on the ground as they used to be.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>have a thick skin</strong> to not care if people criticize you or do not like you → thick-skinned</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>[friendly]</strong> <strong>be (as) thick as thieves</strong> if two people are as thick as thieves, they are very friendly with each other and seem to share a lot of secrets, making other people think they are hiding or planning something:</div><ul class=\"examples\"><li><em>Lately Nick and Lou have been as thick as thieves.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>give somebody a thick ear/get a thick ear</strong> <em>British English</em> <em>spoken</em> to hit someone or be hit on the head, as a punishment:</div><ul class=\"examples\"><li><em>Any more cheek from you and you’ll get a thick ear.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>be thick with somebody</strong> <em>old-fashioned</em> to be very friendly with someone</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>(it’s) a bit thick</strong> <em>British English</em> <em>old-fashioned</em> used to say something is a little unfair or annoying</div></div>","6992":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thick‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɪknəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> how thick something is:</div><ul class=\"examples\"><li><em>The thickness of the walls is 5 feet.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a layer of something</div><ul class=\"examples\"><li><strong><em>thickness of</strong>: Wrap the cake in a double thickness of foil.</em></li></ul></div>","6993":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θiːf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural thieves /θiːvz/)</span></div><div class=\"entry-body\"><div class=\"sense\">someone who steals things from another person or place → theft, burglar, robber:</div><ul class=\"examples\"><li><em>Thieves broke into the offices and stole some computer equipment.</em></li><li><strong><em>a car/jewel etc thief</em></strong></li><li><em>They were nothing but petty thieves (=thieves who steal small things).</em></li></ul></div>","6994":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the top part of your leg, between your knee and your hip</div><div class=\"sense\"><span class=\"snum\">2</span> the top part of a bird’s leg, used as food:</div><ul class=\"examples\"><li><em>chicken thighs</em></li></ul></div>","6995":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(comparative thinner, superlative thinnest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not thick]</strong> if something is thin, there is only a small distance between its two opposite sides or surfaces <em>OPP thick</em>:</div><ul class=\"examples\"><li><em>a thin gold chain</em></li><li><em>She’s only wearing a thin summer jacket (=a jacket made of light material).</em></li><li><em>two thin slices of bread</em></li><li><em>The road was covered with a thin layer of ice.</em></li><li><em>The skin on the eyelids is the thinnest on the body.</em></li><li><strong><em>paper/wafer thin</strong> (=very thin): Keep your voice down – the walls are paper thin.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not fat]</strong> having little fat on your body <em>OPP fat</em>:</div><ul class=\"examples\"><li><em>He was tall and thin, with short brown hair.</em></li><li><strong><em>thin arms/legs/lips etc</strong>: He has long thin hands.</em></li><li><em>Most high school girls say they want to be thinner.</em></li><li><strong><em>as thin as a rake/rail/whippet</strong> (=very thin)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[hair]</strong> if someone has thin hair, they do not have a lot of hair:</div><ul class=\"examples\"><li><em>a thin straggly beard</em></li><li><em>His hair is quite thin on top.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[liquid]</strong> a liquid that is thin flows very easily because it has a lot of water in it <em>OPP thick</em>:</div><ul class=\"examples\"><li><em>thin paint</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[smoke/mist]</strong> smoke or mist that is thin is easy to see through <em>OPP thick</em>:</div><ul class=\"examples\"><li><em>The fog is quite thin in places.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[air]</strong> air that is thin is more difficult to breathe than usual because it has less oxygen in it:</div><ul class=\"examples\"><li><em>the thinner air high in the mountains</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[excuse/argument/evidence etc]</strong> a thin excuse, argument, or evidence is not good or detailed enough to be useful or effective:</div><ul class=\"examples\"><li><em>Evidence that capital punishment deters crime is pretty thin.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>a thin margin/majority etc</strong> a very small number or amount of something:</div><ul class=\"examples\"><li><em>Engle beat Blanchard by a razor-thin margin (=a very small number of votes) in the race for governor.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[smile]</strong> a thin smile does not seem very happy or sincere:</div><ul class=\"examples\"><li><em>Charlie gave her a thin smile.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[voice/sound]</strong> a thin voice or sound is high and unpleasant to listen to:</div><ul class=\"examples\"><li><em>His thin voice trailed off.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>the thin end of the wedge</strong> <em>British English</em> <em>spoken</em> an expression meaning something that you think is the beginning of a harmful development:</div><ul class=\"examples\"><li><em>Workers believe the job cuts are just the thin end of the wedge.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>be thin on the ground</strong> if a particular type of person or thing is thin on the ground, there are very few available:</div><ul class=\"examples\"><li><em>Taxis seem to be thin on the ground.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be having a thin time (of it)</strong> <em>British English</em> <em>spoken</em> to be in a difficult situation, especially one in which you do not have enough money</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>be (walking/treading/skating) on thin ice</strong> to be in a situation in which you are likely to upset someone or cause trouble:</div><ul class=\"examples\"><li><em>I was on thin ice, and I knew it.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>disappear/vanish into thin air</strong> to disappear completely in a mysterious way:</div><ul class=\"examples\"><li><em>Victor and his kidnappers had vanished into thin air.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>out of thin air</strong> out of nowhere, as if by magic:</div><ul class=\"examples\"><li><em>It seems like researchers have just pulled the numbers out of thin air.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle thinned, present participle thinning)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> (also thin out) to become fewer in number, especially when there were many before, or to remove people, plants, or things so that fewer remain:</div><ul class=\"examples\"><li><em>The crowd had thinned out and only a few people were left.</em></li><li><em>The trees thinned as we got closer to the top of the mountain.</em></li><li><em>Traffic was finally thinning.</em></li><li><em>Thin the carrots to two inches apart.</em></li><li><em>Her hair had been thinned and cut shorter.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to make something thinner or to become thinner <em>OPP thicken</em>:</div><ul class=\"examples\"><li><em>The clouds had begun to thin.</em></li><li><em>A narrow smile thinned his lips.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> (also thin down) to make a liquid weaker by adding water or another liquid:</div><ul class=\"examples\"><li><em>Thin the sauce by adding milk.</em></li><li><strong><em>thin something with something</strong>: The pastels can be thinned with water.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> if someone’s hair is thinning, they have less hair than they used to:</div><ul class=\"examples\"><li><em>a tall man with thinning hair</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>thin the ranks</strong> if something thins the ranks of a group of people, there are fewer of them as a result of it:</div><ul class=\"examples\"><li><em>Illness had thinned our ranks.</em></li></ul></div></div>","6996":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[idea/action/feeling/fact]</strong> <span class=\"gram\">[countable]</span> an idea, action, feeling, or fact that someone thinks, does, says, or talks about, or that happens:</div><ul class=\"examples\"><li><em>People say things they don’t mean when they are angry.</em></li><li><em>It was a horrible thing to happen.</em></li><li><em>I plan to do all the things I’ve been meaning to do for ages.</em></li><li><em>The first thing to do is to give them food and shelter.</em></li><li><em>That’s a terrible thing to say.</em></li><li><strong><em>do the right/decent/honourable etc thing</strong>: I kept wondering if I was doing the right thing.</em></li><li><strong><em>this/that/what sort of thing</strong>: A priest has to arrange funerals, marriages, that sort of thing.</em></li><li><em>Getting more American ideas into British business would be a good thing.</em></li><li><em>‘I did no such thing,’ he protested.</em></li><li><em>I know a thing or two (=a lot) about dogs.</em></li><li><em>In a democracy, it is no bad thing to be able to compromise (=it is good, even though it may not seem good).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[object]</strong> <span class=\"gram\">[countable]</span> an object that you are talking about without saying its name, or whose name you do not know:</div><ul class=\"examples\"><li><em>What’s that red thing?</em></li><li><em>I’ll just switch this thing off.</em></li><li><em>There was a round metal thing on the path.</em></li><li><strong><em>... and things</strong> (=and other similar things): The shed is where we keep our tools and things.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[clothes/possessions]</strong> <strong>things</strong> <span class=\"gram\">[plural]</span> <em>especially British English</em> clothes and possessions SYN stuff<em>American English</em></div><ul class=\"examples\"><li><strong><em>somebody’s things</strong>: Jim began to unpack his things. / I want to sell some of my things, but they aren’t worth much.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[equipment]</strong> <strong>things</strong> <span class=\"gram\">[plural]</span> <em>especially British English</em> the tools, equipment, clothes etc that you need for a particular job, sport etc SYN stuff<em>American English</em></div><ul class=\"examples\"><li><strong><em>somebody’s writing/school/Christmas etc things</strong>: I left my swimming things at home. / the shed where he kept his gardening things</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[situation]</strong> <strong>things</strong> <span class=\"gram\">[plural]</span> life in general and the way it is affecting people:</div><ul class=\"examples\"><li><em>By the end of 1942, things were starting to change.</em></li><li><em>Things could be worse.</em></li><li><em>As things turned out, we didn’t have much time.</em></li><li><em>How are things with you, Sarah?</em></li><li><strong><em>make things easy/difficult/hard</strong>: She would get angry quickly, which made things difficult for me.</em></li><li><em>We can’t change the way things are.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[nothing]</strong> <span class=\"gram\">[singular, uncountable]</span> used as part of a negative statement to mean ‘anything’</div><ul class=\"examples\"><li><strong><em>not a thing</strong>: I couldn’t find a thing that I wanted to buy. / He took his glasses off and couldn’t see a thing. / Don’t worry about a thing.</em></li><li><em>There’s no such thing as ghosts (=they do not exist).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[person/animal]</strong> <span class=\"gram\">[countable]</span> used to talk to or about a person or animal, when you are describing what they are like or showing sympathy for them:</div><ul class=\"examples\"><li><em>The baby is a nice little thing when he’s not screaming.</em></li><li><em>She was terribly upset, poor thing.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[make a comment]</strong> <span class=\"gram\">[countable usually singular]</span> used to say something about a particular part of a situation, person etc</div><ul class=\"examples\"><li><strong><em>thing about</strong>: The thing about teaching is that it takes more time to prepare than most people realize.</em></li><li><strong><em>the funny/strange/best etc thing</strong>: The funny thing is, I really enjoyed it, even though I hadn’t expected to.</em></li><li><em>It’s a good thing you saw her before she saw you.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>the thing is</strong> <em>spoken</em> used when you are going to explain something, give the reason for something, or give an opinion:</div><ul class=\"examples\"><li><em>‘It sounds like a good idea. Why don’t you invest?’ ‘Well, the thing is, I can’t afford to.’</em></li><li><strong><em>the thing is that</strong>: The thing is that you can’t always judge your own work.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>the last thing somebody wants/expects/needs etc</strong> something that someone does not want, expect etc at all:</div><ul class=\"examples\"><li><em>The last thing I want is to upset him.</em></li><li><em>The last thing I should have done was let her move into my house.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>last thing</strong> <em>British English</em> at the end of a day, afternoon, evening etc:</div><ul class=\"examples\"><li><em>She likes a hot bath last thing at night.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>first thing</strong> at the beginning of a day, morning, afternoon etc:</div><ul class=\"examples\"><li><em>Jean liked to go for a swim first thing in the morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>among other things</strong> used when you are giving one fact, reason, effect etc but want to suggest that there are many others:</div><ul class=\"examples\"><li><em>The substance is used in the manufacture of cosmetics and drugs, among other things.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>for one thing</strong> used to give one reason for something:</div><ul class=\"examples\"><li><em>Well, for one thing, it’s too big.</em></li><li><em>He’s not that wonderful. He’s bad-tempered for one thing.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>be a thing of the past</strong> to no longer exist or happen:</div><ul class=\"examples\"><li><em>Before AIDS, many health care experts believed that large-scale infectious diseases were a thing of the past.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>it’s a good thing (that)</strong> <em>spoken</em> used to say that it is lucky or good that something has happened:</div><ul class=\"examples\"><li><em>It’s a good thing we brought some food with us.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>something is just one of those things</strong> used to say that something unpleasant or unlucky cannot be prevented:</div><ul class=\"examples\"><li><em>It wasn’t really the driver’s fault; it was just one of those things.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>the thing about/with somebody/something</strong> used to say what the problem with someone or something is:</div><ul class=\"examples\"><li><em>The thing about talk shows is that you never know how they will turn out.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>all (other) things being equal</strong> used to say that something is true in general, but that other things may cause the situation to change:</div><ul class=\"examples\"><li><em>All things being equal, smaller animals need smaller brains.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>just the thing/the very thing</strong> exactly the thing that you want or that is necessary:</div><ul class=\"examples\"><li><em>A holiday is probably just the thing for you.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>of all things</strong> used to show that you are surprised or shocked by something that someone has done or said:</div><ul class=\"examples\"><li><em>She gave up a promising career as a stockbroker to become a weaver, of all things.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>do your own thing</strong> <em>informal</em> to do something in the way that you like instead of copying other people or following strict rules:</div><ul class=\"examples\"><li><em>I just want to live my own life and do my own thing.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>it’s a girl/football/music etc thing</strong> <em>informal</em> used to say that something involves or affects a particular group of people only:</div><ul class=\"examples\"><li><em>Computer games aren’t just a guy thing.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>all things considered</strong> when you consider all the parts or events of a situation:</div><ul class=\"examples\"><li><em>All things considered, we had surprisingly few injuries.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>be all things to all men/people</strong> to try to please or be useful to all of many different groups, often without succeeding:</div><ul class=\"examples\"><li><em>In order to get votes, he tries to be all things to all men.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>be onto a good thing</strong> <em>informal</em> if you are onto a good thing, you are in a situation that is very helpful, comfortable, or profitable for you</div><ul class=\"examples\"><li><strong><em>think/know you are onto a good thing</strong>: Directors who take dividends instead of salary may think they are onto a good thing but could have problems on retirement.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>make a big thing of/about/out of something</strong> to make something seem more important than it really is:</div><ul class=\"examples\"><li><em>You can apologise without making a big thing out of it.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>the done thing</strong> <em>British English</em> <em>old-fashioned</em> <em>informal</em> the way of behaving or doing something that is socially acceptable:</div><ul class=\"examples\"><li><em>It is not the done thing for teachers to hit children.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>it’s one thing to..., (it’s) another thing to...,</strong> used to say that doing one thing is very different from doing another thing, especially where the second thing is more difficult, important, or serious:</div><ul class=\"examples\"><li><em>It’s one thing being able to run fast, but quite another to win a marathon.</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>what with one thing and another</strong> <em>British English</em> <em>spoken</em> used to explain that you have had a lot of work, problems, or jobs that you had to do:</div><ul class=\"examples\"><li><em>I’ve been so busy these last few days, what with one thing and another.</em></li></ul><div class=\"sense\"><span class=\"snum\">31</span> <strong>have a thing about somebody/something</strong> <em>informal</em> to like or dislike someone or something very much, often without a good reason:</div><ul class=\"examples\"><li><em>She’s always had a thing about Peter.</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>one thing leads to another</strong> used to explain how a series of events caused something to happen without giving any details:</div><ul class=\"examples\"><li><em>One thing led to another and, before I knew it, I had invited her family to stay.</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>the (latest) thing</strong> <em>informal</em> something that is popular or fashionable at the moment:</div><ul class=\"examples\"><li><em>When Amelia bought a new car it had to be the latest thing.</em></li></ul><div class=\"sense\"><span class=\"snum\">34</span> <strong>(do/try) the... thing</strong> <em>American English</em> <em>spoken</em> used to talk about an activity and everything that is involved with it:</div><ul class=\"examples\"><li><em>Jody tried the college thing but finally dropped out.</em></li></ul><div class=\"sense\"><span class=\"snum\">35</span> <strong>there&#x27;s only one thing for it</strong> <em>British English</em> <em>spoken</em> used to say that there is only one action that you can take:</div><ul class=\"examples\"><li><em>There’s only one thing for it. We’ll have to call the police.</em></li></ul><div class=\"sense\"><span class=\"snum\">36</span> <strong>one (damn/damned) thing after another</strong> used to say that a lot of unpleasant or unlucky things keep happening to you</div><div class=\"sense\"><span class=\"snum\">37</span> <strong>taking one thing with another</strong> <em>British English</em> considering all the facts</div><div class=\"sense\"><span class=\"snum\">38</span> <strong>do things to somebody</strong> to have a strong effect on someone</div></div>","6997":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θɪŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle thought /θɔːt $ θɒːt/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[opinion/belief]</strong> <span class=\"gram\">[transitive]</span> to have a particular opinion or to believe that something is true</div><ul class=\"examples\"><li><strong><em>think (that)</strong>: I think that you’re being unfair. / I thought I heard something. / He didn’t think anyone would believe him. / Do you think I should call him? / For some reason, I keep thinking it’s Friday today. / The recession lasted longer than anyone thought it would. / Am I right in thinking that you have a brother? / I can’t help thinking that he’s made a mistake.</em></li><li><em>Do you honestly think I would do something so stupid?</em></li><li><strong><em>what do you think of/about somebody/something?</strong> (=used to ask someone for their opinion): What do you think of your new school?</em></li><li><strong><em>think it necessary/possible/best etc</strong> (=believe it is necessary, possible etc): I thought it best to call first. / I thought it appropriate to invite her to speak at the meeting.</em></li><li><em>We must start thinking in terms of reducing costs.</em></li><li><strong><em>be thought to be (doing) something</strong> (=be believed to be (doing) something): Fraud is thought to be costing software companies millions of dollars a year.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[use your mind]</strong> <span class=\"gram\">[intransitive, transitive]</span> to use your mind to decide about something, form an opinion, imagine something etc:</div><ul class=\"examples\"><li><em>She thought very carefully before answering.</em></li><li><em>Wait a minute – I’m thinking.</em></li><li><strong><em>think about/of</strong>: She lay awake thinking about the money.</em></li><li><strong><em>think what/how/when etc</strong>: I can’t think what else we could have done.</em></li><li><strong><em>think (long and) hard</strong> (=think for a long time): She thought very hard before deciding to leave her job.</em></li><li><em>Holmes sat thinking deeply (=thinking in a serious and careful way).</em></li><li><strong><em>I dread/shudder/hate to think</strong> (=I do not want to think about something because it will be unpleasant): I dread to think how much this call is going to cost.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[have an idea]</strong> <span class=\"gram\">[transitive]</span> to have words or ideas in your mind without telling them to anyone:</div><ul class=\"examples\"><li><em>‘How strange!’ he thought.</em></li><li><em>‘I don’t care!’ she thought to herself.</em></li><li><em>It was impossible to know what he was thinking.</em></li><li><strong><em>think what/how/when etc</strong>: I was just thinking what a lovely time we had yesterday.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[remember]</strong> <span class=\"gram\">[transitive]</span> to remember something</div><ul class=\"examples\"><li><strong><em>think where/what etc</strong>: He was trying to think where he’d seen her before. / I couldn’t think where I’d left my keys.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[consider somebody/something]</strong> <span class=\"gram\">[intransitive, transitive]</span> to consider that someone or something is a particular thing or has a particular quality</div><ul class=\"examples\"><li><strong><em>think of somebody/something as something</strong>: Peter had always thought of Kate as someone to be avoided. / I want you to think of this as your home.</em></li><li><strong><em>think of yourself as something</strong>: I’ve always thought of myself as a sensible person.</em></li><li><strong><em>think somebody (to be) something</strong>: My parents never thought me capable of doing a degree.</em></li><li><em>We have good reason to think kindly of (=consider in an approving way) a school that has provided all our children with an excellent education.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>think of/about doing something</strong> to consider the possibility of doing something:</div><ul class=\"examples\"><li><em>I had never thought of becoming an actor.</em></li><li><em>We did think about moving to Tokyo.</em></li><li><em>Don’t even think about calling him (=used to tell someone strongly not to do something).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>think twice</strong> to think very carefully before deciding to do something, because you know about the dangers or problems:</div><ul class=\"examples\"><li><em>A visible alarm makes burglars think twice.</em></li><li><strong><em>think about</strong>: A previous divorce can make you think twice about getting married again.</em></li><li><strong><em>think twice before doing something/before you do something</strong>: I’d think twice before taking out such a large loan.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>think again</strong> to think carefully about a plan, decision, idea etc, especially with the result that you change your mind or do something differently:</div><ul class=\"examples\"><li><em>If you think car crime can’t happen to you, think again.</em></li><li><strong><em>think about</strong>: Universities may be forced to think again about the courses they provide.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>think better of it</strong> to not do something that you had planned to do, because you realize that it is not a good idea:</div><ul class=\"examples\"><li><em>He started to say something, then thought better of it.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>think nothing of doing something</strong> to think that a particular activity is normal or easy, even though other people think it is unusual or difficult:</div><ul class=\"examples\"><li><em>He thinks nothing of staying up all night in casinos.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>think nothing of something</strong> to think that something is not important and then realize later that it is important:</div><ul class=\"examples\"><li><em>I had a pain in my back but thought nothing of it at the time.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>not think to do something</strong> to not consider doing something, especially when you later wish you had done it:</div><ul class=\"examples\"><li><em>I didn’t think to question the treatment I was given.</em></li><li><em>I never thought to ask him for his address.</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>think for yourself</strong> to have ideas and thoughts of your own rather than believing what other people say:</div><ul class=\"examples\"><li><em>Parents have to teach their children to think for themselves.</em></li></ul><div class=\"sense\"><span class=\"snum\">31</span> <strong>think aloud</strong> (also think out loud) to say what you are thinking, without talking to anyone in particular:</div><ul class=\"examples\"><li><em>Oh, sorry. I was thinking aloud.</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>think straight</strong> <span class=\"gram\">[usually in negatives]</span> to think clearly:</div><ul class=\"examples\"><li><em>I’m so nervous I can’t think straight.</em></li><li><em>How can I think straight with you talking all the time?</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>not think much of somebody/something</strong> to not like someone or something very much:</div><ul class=\"examples\"><li><em>I didn’t think much of his new girlfriend.</em></li></ul><div class=\"sense\"><span class=\"snum\">34</span> <strong>think highly of somebody/something</strong> (also think a lot of somebody/something) to admire or respect someone or something:</div><ul class=\"examples\"><li><em>Your boss must think highly of you if she gives you so much responsibility.</em></li></ul><div class=\"sense\"><span class=\"snum\">35</span> <strong>think the world of somebody</strong> <em>informal</em> to like or love someone very much:</div><ul class=\"examples\"><li><em>The children think the world of her.</em></li></ul><div class=\"sense\"><span class=\"snum\">36</span> <strong>think badly of somebody</strong> (also think less of somebody) <em>formal</em> to disapprove of someone or what they have done:</div><ul class=\"examples\"><li><em>Please don’t think badly of me.</em></li><li><strong><em>think for</strong>: Do you think less of me for agreeing to do it?</em></li></ul><div class=\"sense\"><span class=\"snum\">37</span> <strong>think the best/worst of somebody</strong> to consider someone’s behaviour in a way that makes them seem as good as possible or as bad as possible:</div><ul class=\"examples\"><li><em>He’s determined to think the worst of me.</em></li></ul><div class=\"sense\"><span class=\"snum\">38</span> <strong>think big</strong> <em>informal</em> to plan to do things that are difficult, but will be very impressive, make a lot of profit etc:</div><ul class=\"examples\"><li><em>The company is thinking big.</em></li></ul><div class=\"sense\"><span class=\"snum\">39</span> <strong>think outside the box</strong> to think of new, different, or unusual ways of doing something, especially in business</div><div class=\"sense\"><span class=\"snum\">40</span> <strong>think positive/positively</strong> to believe that you are going to be successful or that good things are going to happen:</div><ul class=\"examples\"><li><em>You have to think positive if you’re going to be successful in this game.</em></li></ul><div class=\"sense\"><span class=\"snum\">41</span> <strong>think on your feet</strong> to think of ideas and make decisions very quickly:</div><ul class=\"examples\"><li><em>In this job you need to be able to think on your feet.</em></li></ul><div class=\"sense\"><span class=\"snum\">42</span> <strong>think to do something</strong> <em>literary</em> to try to do something:</div><ul class=\"examples\"><li><em>They had thought to deceive me.</em></li></ul><div class=\"sense\"><span class=\"snum\">43</span> <strong>anyone would think (that)</strong> used to say that someone behaves as if a particular thing were true, although it is not:</div><ul class=\"examples\"><li><em>Anyone would think he owns the place, the way he talks!</em></li></ul></div>","6998":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> think‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɪŋkə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who thinks carefully about important subjects such as science or philosophy, especially someone who is famous for thinking of new ideas:</div><ul class=\"examples\"><li><em>great thinkers such as Kant and Schopenhauer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>an independent/positive/free etc thinker</strong> a person who thinks in a particular way</div></div>","6999":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> think‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɪŋkɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> your opinion or ideas about something, or your attitude towards it:</div><ul class=\"examples\"><li><em>The Administration’s thinking changed as the war progressed.</em></li><li><em>Well, to my way of thinking (=in my opinion), they should have done that years ago.</em></li><li><em>He laughed and accused me of wishful thinking (=falsely believing that something will happen just because I want it to).</em></li><li><em>the rich countries’ current thinking on aid</em></li><li><strong><em>thinking behind</strong>: the thinking behind the company’s new public relations campaign</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> when you think about something:</div><ul class=\"examples\"><li><em>If it weren’t for Jeff’s quick thinking, Tillie could have been badly hurt.</em></li><li><em>I really needed to do some thinking.</em></li><li><strong><em>clear/critical/analytical etc thinking</strong> (=a particular way of thinking about things)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>put on your thinking cap</strong> <em>informal</em> to try to think seriously about a problem in order to solve it</div></div>","7000":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thin‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɪnli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a way that has a very small distance between two sides or two flat surfaces <em>OPP thickly</em>:</div><ul class=\"examples\"><li><em>thinly sliced bread</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> scattered or spread over a large area, with a lot of space in between:</div><ul class=\"examples\"><li><em>Sow the radish seeds thinly.</em></li><li><em>The mountain regions are more thinly populated than the lowlands.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>thinly disguised/veiled</strong> if something is thinly disguised etc, someone is pretending it is something else, but you can easily see what it really is:</div><ul class=\"examples\"><li><em>He looked at Frank’s new car with thinly veiled envy.</em></li></ul></div>","7001":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θɜːd $ θɜːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2 S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> coming after two other things in a series:</div><ul class=\"examples\"><li><em>in the third century</em></li><li><em>her third birthday</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>third time lucky</strong> <em>British English</em>, (the) third time’s the charm<em>American English</em> <em>spoken</em> used when you have failed to do something twice and hope to be successful the third time</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of three equal parts of something:</div><ul class=\"examples\"><li><em>Divide it into thirds.</em></li><li><strong><em>third of</strong>: A third of these jobs are held by women.</em></li><li><strong><em>one-third/two-thirds</strong>: Two-thirds of the profits are given to charities.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the lowest type of degree that is given by a British university</div></div></div>","7002":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θɜːst $ θɜːrst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular]</span> the feeling of wanting or needing a drink → thirsty, hunger:</div><ul class=\"examples\"><li><em>Ice water is the only thing that really quenches my thirst (=gets rid of it).</em></li><li><em>We had worked up a thirst (=done something that made us thirsty), and so we decided to stop for a beer.</em></li><li><em>Maggie woke up with a raging thirst (=an extremely strong thirst).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the state of not having enough to drink:</div><ul class=\"examples\"><li><em>Many of the animals had died of thirst.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a thirst for knowledge/education/information etc</strong> <em>literary</em> a strong desire for knowledge etc:</div><ul class=\"examples\"><li><em>the thirst for knowledge in Renaissance Italy</em></li></ul></div>","7003":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thirst‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɜːsti $ ˈθɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(comparative thirstier, superlative thirstiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> feeling that you want or need a drink → thirst, hungry:</div><ul class=\"examples\"><li><em>Can I have a glass of water? I’m really thirsty.</em></li><li><em>He’d been working in the garden and was very hot and thirsty.</em></li><li><em>All this digging is thirsty work (=work that makes you want a drink).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>literary</em> having a strong desire for something</div><ul class=\"examples\"><li><strong><em>thirsty for</strong>: a generation thirsty for change</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> fields or plants that are thirsty need water</div></div>","7004":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thir‧teen</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌθɜːˈtiːn◂ $ ˌθɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\">the number 13:</div><ul class=\"examples\"><li><em>They’ve only sold thirteen tickets so far.</em></li><li><em>When it happened, I was thirteen (=13 years old).</em></li></ul></div>","7005":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thir‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɜːti $ ˈθɜːrti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the number 30</div><div class=\"sense\"><span class=\"snum\">2</span> the thirties (also the &#x27;30s, the 1930s) <span class=\"gram\">[plural]</span> the years from 1930 to 1939:</div><ul class=\"examples\"><li><em>In the thirties, air travel really began to take off.</em></li><li><strong><em>the early/mid/late thirties</strong>: The family sold the house in the early thirties.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be in your thirties</strong> to be aged between 30 and 39</div><ul class=\"examples\"><li><strong><em>early/mid/late thirties</strong>: She must be in her early thirties by now.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in the thirties</strong> if the temperature is in the thirties, it is between 30 degrees and 39 degrees</div><ul class=\"examples\"><li><strong><em>in the low/mid/high thirties</strong>: a hot day, with temperatures in the low thirties</em></li></ul></div>","7006":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">determiner</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(plural these /ðiːz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to refer to a person, thing, idea etc that has just been mentioned or to something that has just happened:</div><ul class=\"examples\"><li><em>We must make sure this doesn’t happen again.</em></li><li><em>Is there any way of solving these problems?</em></li><li><em>If young Daly continues to improve at this rate, he’ll soon be in the A Team.</em></li><li><em>This will be discussed in the next chapter.</em></li><li><em>This boyfriend of yours – how old is he?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to talk about the present time or a time that is close to the present:</div><ul class=\"examples\"><li><em>There will be another meeting later this week.</em></li><li><em>This has been the worst year of my life.</em></li><li><em>I thought he would have been back before this.</em></li><li><em>We’ll be seeing Malcolm this Friday (=on Friday of the present week).</em></li><li><em>I’m sorry I was late this morning (=today in the morning).</em></li><li><em>Everyone seems to be in a hurry these days (=at the present period).</em></li><li><em>I want to see you in my office this minute (=immediately).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to talk about the present situation:</div><ul class=\"examples\"><li><em>I hate this cold damp weather.</em></li><li><em>Things have never been as bad as this before.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span><span class=\"meta-item\"><span class=\"gram\">[+adjective/adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>spoken</em> used to say how big, how much etc, when you are showing the size, amount etc with your hands:</div><ul class=\"examples\"><li><em>The table’s about this high and this wide.</em></li><li><em>You need to cut about this much off the end of the pipe.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually in questions and negatives]</span> <em>spoken</em> as good, bad, much etc as in the present situation:</div><ul class=\"examples\"><li><em>I hadn’t realised that things had got this bad.</em></li><li><em>I’ve never had this much money before.</em></li></ul></div></div>","7007":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θɔːn $ θɔːrn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a sharp point that grows on the stem of a plant such as a rose</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a bush or tree that has thorns:</div><ul class=\"examples\"><li><em>a long, low hedge of thorns</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a thorn in somebody’s side</strong> someone or something that annoys you or causes problems for a long period of time:</div><ul class=\"examples\"><li><em>He’s been a thorn in the side of the party leadership for years.</em></li></ul></div>","7008":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thor‧ough</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθʌrə $ ˈθʌroʊ, ˈθʌrə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> including every possible detail → thoroughly:</div><ul class=\"examples\"><li><em>The doctor gave him a thorough check-up.</em></li><li><em>a thorough and detailed biography</em></li><li><em>The police investigation was very thorough.</em></li><li><em>thorough notes of the meeting</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[not usually before noun]</span> careful to do things properly so that you avoid mistakes: ► see thesaurus at careful</div><ul class=\"examples\"><li><em>The screening of applicants must be thorough.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a thorough pest/nuisance/mess</strong> <em>British English</em> used to emphasize the bad qualities of someone or something</div></div>","7009":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thor‧ough‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθʌrəli $ ˈθʌroʊli,ˈθʌrə-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> completely:</div><ul class=\"examples\"><li><em>She sat feeling thoroughly miserable.</em></li><li><em>thoroughly cooked meat</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> carefully, so that nothing is forgotten:</div><ul class=\"examples\"><li><em>The room had been thoroughly cleaned.</em></li></ul></div>","7010":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">conjunction</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðəʊ $ ðoʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to introduce a statement that makes the main statement coming after it seem surprising, unlikely, or unexpected <em>SYN although</em>:</div><ul class=\"examples\"><li><em>Though she’s almost 40, she still plans to compete.</em></li><li><em>Pascal went ahead with the experiment even though he knew it was dangerous.</em></li><li><strong><em>though old/tired etc</strong>: The rooms, though small, were pleasant and airy.</em></li><li><strong><em>old though it is/tired though he was etc</strong>: Strange though it may seem, I like housework.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used like ‘but’ to add a fact or opinion that makes what you have just said seem less definite, less important etc:</div><ul class=\"examples\"><li><em>I thought he’d been drinking, though I wasn’t completely sure.</em></li><li><em>The offenders were dealt with firmly though fairly.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>as though</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in a way that makes you think something is true <em>SYN as if</em>:</div><ul class=\"examples\"><li><em>It looks as though everyone else has gone home.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> in a way that might make you think something was true, although you know it is not true <em>SYN as if</em>:</div><ul class=\"examples\"><li><em>She stared at me as though I were a complete stranger.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\"><em>spoken</em> used after adding a fact, opinion, or question which seems surprising after what you have just said, or which makes what you have just said seem less true:</div><ul class=\"examples\"><li><em>Two heart attacks in a year. It hasn’t stopped him smoking, though.</em></li><li><em>It sounds like a lot of fun. Isn’t it rather risky though?</em></li></ul></div></div>","7011":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[something you think about]</strong> <span class=\"gram\">[countable]</span> something that you think of, remember, or realize <em>SYN idea</em>: ► see thesaurus at idea</div><ul class=\"examples\"><li><em>It’s an interesting thought.</em></li><li><em>The thought that I might not have a job next year is a bit troubling.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[ideas/opinions]</strong> <strong>thoughts</strong> <span class=\"gram\">[plural]</span> a person’s ideas or opinions about something:</div><ul class=\"examples\"><li><em>What are your thoughts, Michael?</em></li><li><strong><em>thought on</strong>: Any thoughts on how we should spend the money?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[careful consideration]</strong> <span class=\"gram\">[uncountable]</span> careful and serious consideration:</div><ul class=\"examples\"><li><em>With more thought and care this would have been a first-class essay.</em></li><li><strong><em>give something thought/give thought to something</strong> (=think carefully about something): I’ve been giving your proposal a lot of thought. / Have you given any more thought to going back to school?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[act of thinking]</strong> <span class=\"gram\">[uncountable]</span> the act or process of thinking</div><ul class=\"examples\"><li><strong><em>lost/deep in thought</strong> (=thinking so much that you do not notice what is happening around you): Derek was staring out of the window, lost in thought.</em></li><li><em>Piaget’s research focused on children’s thought processes (=the way their minds work).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[caring about something]</strong> <span class=\"gram\">[countable, uncountable]</span> a feeling of worrying or caring about something</div><ul class=\"examples\"><li><strong><em>thought for</strong>: He went back into the burning building with no thought for his own safety. / Have you no thought for anyone but yourself?</em></li><li><em>You are always in my thoughts (=used to tell someone that you think and care about them a lot).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[intention]</strong> <span class=\"gram\">[countable, uncountable]</span> intention or hope of doing something</div><ul class=\"examples\"><li><strong><em>thought of doing something</strong>: I had no thought of gaining any personal advantage. / Lucy gave up all thought of finishing the essay that day.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[way of thinking]</strong> <span class=\"gram\">[uncountable]</span> a way of thinking that is typical of a particular group, period of history etc</div><ul class=\"examples\"><li><strong><em>ancient Greek/feminist/18th-century etc thought</strong>: Kant’s ideas had a strong influence on political thought.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>spare a thought for somebody</strong> <em>British English</em> used to tell someone that they should think about someone who is in a worse situation than they are:</div><ul class=\"examples\"><li><em>Spare a thought for those who don’t have enough to eat.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>it’s just a thought</strong> <em>spoken</em> used to say that what you have just said is only a suggestion and you have not thought about it very much:</div><ul class=\"examples\"><li><em>It was just a thought, Duncan. I didn’t mean any offence.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>it’s/that’s a thought!</strong> <em>spoken</em> used to say that someone has made a good suggestion:</div><ul class=\"examples\"><li><em>‘Why don’t you ask Walter?’ ‘That’s a thought! I’ll phone him right away.’</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>don’t give it another thought</strong> <em>spoken</em> used to tell someone not to worry after they have told you they are sorry</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>it’s the thought that counts</strong> <em>spoken</em> used to say that you are grateful for a gift from someone even though it is small or unimportant</div></div>","7012":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thought‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɔːtfəl $ ˈθɒːt-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> always thinking of the things you can do to make people happy or comfortable <em>OPP thoughtless</em>: ► see thesaurus at kind</div><ul class=\"examples\"><li><em>Paul is very thoughtful.</em></li><li><strong><em>it is thoughtful of somebody to do something</strong>: It was really thoughtful of you to remember my birthday.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> serious and quiet because you are thinking a lot:</div><ul class=\"examples\"><li><em>a thoughtful look</em></li><li><em>a thoughtful silence</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> well planned and carefully thought about:</div><ul class=\"examples\"><li><em>a thoughtful analysis</em></li></ul></div>","7013":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thought‧less</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɔːtləs $ ˈθɒːt-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not thinking about the needs and feelings of other people, especially because you are thinking about what you want <em>OPP thoughtful</em>: ► see thesaurus at unkind</div><ul class=\"examples\"><li><em>a selfish and thoughtless man</em></li><li><strong><em>it is thoughtless of somebody to do something</strong>: It was thoughtless of her not to tell you where she was going.</em></li></ul></div>","7014":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thou‧sand</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθaʊzənd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\">(plural thousand or thousands)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the number 1,000:</div><ul class=\"examples\"><li><em>a journey of almost a thousand miles</em></li><li><strong><em>two/three/four etc thousand</strong>: five thousand dollars / The company employs thirty thousand people.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an extremely large number of things or people</div><ul class=\"examples\"><li><strong><em>a thousand</strong>: I’ve been this route a thousand times before.</em></li><li><strong><em>thousands of</strong>: There are thousands of things I want to do.</em></li></ul></div>","7015":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θred/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[for sewing]</strong> <span class=\"gram\">[countable, uncountable]</span> a long thin string of cotton, silk etc used to sew or weave cloth:</div><ul class=\"examples\"><li><em>I’m looking for a needle and thread.</em></li><li><em>hand-sewn with gold and silver thread</em></li><li><em>a spool of thread (=small object that thread is wound around)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[ideas]</strong> <span class=\"gram\">[singular]</span> an idea, feeling, or feature that connects the different parts of an explanation, story etc:</div><ul class=\"examples\"><li><em>a common thread running within his work</em></li><li><em>His mind wandered, and he lost the thread of what she was saying (=was no longer able to understand it).</em></li><li><em>a thread running through the film</em></li><li><strong><em>thread of</strong>: a thread of spirituality in her work</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>pick up the thread(s)</strong> to begin something again after a long period, especially a relationship or way of life:</div><ul class=\"examples\"><li><em>They had known each other as children, and were picking up the threads of their friendship.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[internet]</strong> <span class=\"gram\">[countable]</span> a series of messages concerning the same subject, written by members of an Internet discussion group:</div><ul class=\"examples\"><li><em>I’d like to refer to something that was posted in an earlier thread.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[line]</strong> <span class=\"gram\">[countable]</span> <em>literary</em> a long thin line of something, such as light, smoke etc</div><ul class=\"examples\"><li><strong><em>thread of</strong>: The Colorado River was just a thread of silver, 4,000 feet below.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[on a screw]</strong> <span class=\"gram\">[countable]</span> a continuous raised line of metal that winds around the curved surface of a screw</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>threads</strong> <span class=\"gram\">[plural]</span> <em>American English</em> <em>old-fashioned</em> clothes</div></div>","7016":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θret/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a statement in which you tell someone that you will cause them harm or trouble if they do not do what you want:</div><ul class=\"examples\"><li><em>Your threats don’t scare me.</em></li><li><strong><em>threat of</strong>: the threat of military invasion</em></li><li><strong><em>threat from</strong>: He says his family received phone threats from the group.</em></li><li><em>threats made against his wife and children</em></li><li><em>Nichols never carried out his threat to resign.</em></li><li><em>The government will not give in to terrorist threats.</em></li><li><em>She dismissed the statement as an empty threat.</em></li><li><em>They warned him with veiled threats not to mention anything he had witnessed.</em></li><li><em>The police are investigating death threats made against the two men.</em></li><li><em>Officials at the school say they received a bomb threat at approximately 11:30 a.m. today.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually singular]</span> the possibility that something very bad will happen</div><ul class=\"examples\"><li><strong><em>threat of</strong>: the threat of famine</em></li><li><strong><em>threat from</strong>: According to the Secretary of State, the Russians face no threat from an expanded NATO.</em></li><li><strong><em>under threat</strong>: The area remains under threat from commercial developers.</em></li><li><strong><em>be under threat of closure/attack etc</strong> (=be likely to be closed, attacked etc): The program is under threat of closure due to lack of funding.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable usually singular]</span> someone or something that is regarded as a possible danger</div><ul class=\"examples\"><li><strong><em>threat to</strong>: The fighting is a major threat to stability in the region.</em></li><li><strong><em>present/pose a threat (to somebody/something)</strong>: Pollution poses a threat to fish.</em></li></ul></div>","7017":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> threat‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθretn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to say that you will cause someone harm or trouble if they do not do what you want:</div><ul class=\"examples\"><li><em>Postal workers are threatening a strike if they don’t receive a pay increase.</em></li><li><strong><em>threaten to do something</strong>: He threatened to take them to court.</em></li><li><strong><em>threaten somebody with something</strong>: Doctors are sometimes threatened with violence if they don’t do what patients want.</em></li><li><strong><em>threaten (that)</strong>: Then he became angry and threatened that he would go to the police.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to be likely to harm or destroy something:</div><ul class=\"examples\"><li><em>Poaching threatens the survival of the rhino.</em></li><li><strong><em>threaten to do something</strong>: The incident threatens to ruin his chances in the election.</em></li><li><strong><em>be threatened with something</strong>: Large areas of the jungle are now threatened with destruction.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to be likely to happen or be in a bad situation:</div><ul class=\"examples\"><li><em>Britain’s fishing industry remains threatened.</em></li><li><em>Dark clouds threatened rain.</em></li></ul></div>","7018":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θriː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the number 3:</div><ul class=\"examples\"><li><em>They’ve won their last three games.</em></li><li><em>We’d better go. It’s almost three (=three o&#x27;clock).</em></li><li><em>My little sister’s only three (=three years old).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>in threes</strong> in groups of three people or things: → threesome, third1</div><ul class=\"examples\"><li><em>Teachers taking part will be asked to work in threes.</em></li></ul></div>","7019":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌthree-diˈmensional</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having, or seeming to have, length, depth, and height → two-dimensional:</div><ul class=\"examples\"><li><em>a three-dimensional structure</em></li><li><em>objects that are three-dimensional</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a three-dimensional character in a book, film etc seems like a real person → one-dimensional</div></div>","7020":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thresh‧old</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθreʃhəʊld, -ʃəʊld $ -oʊld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the entrance to a room or building, or the area of floor or ground at the entrance:</div><ul class=\"examples\"><li><em>She opened the door and stepped across the threshold.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the level at which something starts to happen or have an effect:</div><ul class=\"examples\"><li><em>Eighty percent of the vote was the threshold for approval of the plan.</em></li><li><strong><em>a high/low pain/boredom etc threshold</strong> (=the ability or inability to suffer a lot of pain or boredom before you react to it)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> at the beginning of a new and important event or development <em>SYN brink</em></div><ul class=\"examples\"><li><strong><em>be on the threshold of something</strong>: The creature is on the threshold of extinction.</em></li></ul></div>","7021":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θrɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a sudden strong feeling of excitement and pleasure, or the thing that makes you feel this:</div><ul class=\"examples\"><li><em>Winning first place must have been quite a thrill.</em></li><li><strong><em>the thrill of (doing) something</strong> (=the excitement you get from something): the thrill of travelling at high speeds</em></li><li><em>Even though I’ve been acting for years, I still get a thrill out of going on stage.</em></li><li><em>It gave Pat a thrill to finally see the group perform live.</em></li><li><strong><em>a thrill of excitement/anticipation/fear etc</strong>: She felt a thrill of pride as her son stepped forward.</em></li><li><strong><em>do something for the thrill of it</strong> (=do something for excitement and not for any serious reason)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>thrills and spills</strong> (also thrills and chills) <em>informal</em> the excitement and danger involved in an activity, especially a sport</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the thrill of the chase/hunt</strong> the excitement you feel when you are trying to get something that is difficult to get, especially when you are trying to get a romantic relationship with someone</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[transitive]</span> to make someone feel excited and happy → thrilling:</div><ul class=\"examples\"><li><em>His music continues to thrill audiences.</em></li></ul></div></div>","7022":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θrɪld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">very excited, happy, and pleased ► see thesaurus at excited, happy</div><ul class=\"examples\"><li><strong><em>be thrilled to see/hear/learn etc something</strong>: We were so thrilled to hear about the baby.</em></li><li><strong><em>thrilled (that)</strong>: I’m absolutely thrilled that you are coming.</em></li><li><strong><em>thrilled about</strong>: He was thrilled about being asked to play.</em></li><li><strong><em>thrilled to bits/pieces</strong> (=very thrilled)</em></li></ul></div>","7023":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thrill‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθrɪlə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a book or film that tells an exciting story about murder or crime ► see thesaurus at movie</div></div>","7024":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thril‧ling</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθrɪlɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">interesting and exciting: ► see thesaurus at exciting</div><ul class=\"examples\"><li><em>a thrilling 3–2 victory</em></li></ul></div>","7025":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θraɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span><span class=\"meta-item\">(past tense thrived or throve /θrəʊv $ θroʊv/, past participle thrived)</span></div><div class=\"entry-body\"><div class=\"sense\">to become very successful or very strong and healthy: RegisterIn everyday English, people usually say do well rather than thrive:· The whole family seems to be doing well.</div><ul class=\"examples\"><li><em>plants that thrive in tropical rain forests</em></li><li><em>a business which managed to thrive during a recession</em></li></ul></div>","7026":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θrəʊt $ θroʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the passage from the back of your mouth to the top of the tubes that go down to your lungs and stomach:</div><ul class=\"examples\"><li><em>The singer complained of a sore throat after Wednesday’s show.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the front of your neck:</div><ul class=\"examples\"><li><em>She fingered the pearls at her throat.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>clear your throat</strong> to make a noise in your throat, especially before you speak, or in order to get someone’s attention</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>force/ram/shove something down somebody’s throat</strong> <em>informal</em> to force someone to accept or listen to your ideas and opinions</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>be at each other’s throats</strong> if two people are at each other’s throats, they are fighting or arguing</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>cut your own throat</strong> to behave in a way that is certain to harm you, especially because you are proud or angry</div></div>","7027":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θrəʊn $ θroʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a special chair used by a king or queen at important ceremonies</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>the throne</strong> the position and power of being a king or queen:</div><ul class=\"examples\"><li><em>He is next in line to the throne (=will become king when the present ruler dies).</em></li><li><em>In 1913, George V was on the throne (=was ruling).</em></li></ul></div>","7028":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θruː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[door/passage etc]</strong> into one side or end of an entrance, passage, hole etc and out of the other side or end:</div><ul class=\"examples\"><li><em>She smiled at him as he walked through the door.</em></li><li><em>Water will be pumped through a pipe.</em></li><li><em>I managed to squeeze through a gap in the hedge.</em></li><li><em>They were suddenly plunged into darkness as the train went through a tunnel.</em></li><li><em>There were people standing in the doorway and I couldn’t get through.</em></li><li><strong><em>through to</strong>: I went through to the kitchen to see who was there.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[cutting/breaking]</strong> cutting or breaking something, or making a hole from one side of it to the other:</div><ul class=\"examples\"><li><em>A football came crashing through the window.</em></li><li><strong><em>straight/right/clean through</strong>: The bullet passed straight through his skull.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[across an area]</strong> from one side of an area to the other or between a group of things:</div><ul class=\"examples\"><li><em>We passed through France on our way to Italy.</em></li><li><em>We made our way through the village to the farm.</em></li><li><em>The wind howled through the trees.</em></li><li><em>He had to push his way through the crowd to get to her.</em></li><li><em>Let me through – I’m a doctor.</em></li><li><strong><em>get through/make it through</strong> (=reach a place after a difficult journey): You’ll never get through – the snow’s two metres deep. / Rescue teams have finally made it through to the survivors.</em></li><li><em>We drove right through the town centre.</em></li><li><em>Carry on straight through the village.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[see through something]</strong> if you see something through glass, a window etc, you are on one side of the glass etc and it is on the other:</div><ul class=\"examples\"><li><em>I could see her through the window.</em></li><li><em>I could see right through the thin curtains.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[past a place]</strong> past a place where you are supposed to stop:</div><ul class=\"examples\"><li><em>It took us ages to get through passport control.</em></li><li><em>He drove straight through a red light.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[time]</strong> during and to the end of a period of time:</div><ul class=\"examples\"><li><em>The cold weather continued through the spring.</em></li><li><em>He slept right through the day.</em></li><li><em>The fighting went on all through the night.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[process/experience]</strong> from the beginning to the end of a process or experience:</div><ul class=\"examples\"><li><em>The book guides you through the whole procedure of buying a house.</em></li><li><em>When you have been through a terrible experience like that, it takes a long time to recover.</em></li><li><em>It’s a miracle that these buildings came through the war undamaged.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[competitions]</strong> past one stage in a competition to the next stage</div><ul class=\"examples\"><li><strong><em>through to</strong>: This is the first time they’ve ever made it through to the final.</em></li><li><em>They didn’t even get through the first round of the contest.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[because of something]</strong> because of something:</div><ul class=\"examples\"><li><em>How many working days were lost through sickness last year?</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[by means of something/somebody]</strong> by means of a particular method, service, person etc: ► see thesaurus at because</div><ul class=\"examples\"><li><em>She got her first job through an employment agency.</em></li><li><em>a success that was achieved through co-operative effort and wise leadership</em></li><li><em>I heard about it through a friend.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[parliament/congress]</strong> if a proposal passes through a parliament, it is agreed and accepted as a law:</div><ul class=\"examples\"><li><em>A special bill was rushed through Congress to deal with the emergency.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[until]</strong> <strong>May through June/Wednesday through Friday etc</strong> <em>American English</em> from May until June, from Wednesday until Friday etc:</div><ul class=\"examples\"><li><em>The store is open Monday through Saturday.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>halfway through (something)</strong> in the middle of an event or period of time:</div><ul class=\"examples\"><li><em>I left halfway through the film.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[telephone]</strong> <em>British English</em> connected to someone by telephone:</div><ul class=\"examples\"><li><em>I tried phoning you, but I couldn’t get through.</em></li><li><em>Please hold the line and I’ll put you through.</em></li><li><strong><em>through to</strong>: Did you manage to get through to her?</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[completely]</strong> <strong>wet through/cooked through etc</strong> <em>informal</em> completely wet, cooked etc:</div><ul class=\"examples\"><li><em>You’re wet through. What on earth have you been doing?</em></li><li><em>It should only take a few minutes to heat this through.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>through and through</strong> if someone is a particular type of person through and through, they are completely that type of person:</div><ul class=\"examples\"><li><em>I’ll say one thing for Sandra – she’s a professional through and through.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[all the way]</strong> <strong>through to London/Paris etc</strong> as far as London, Paris etc:</div><ul class=\"examples\"><li><em>Does this train go through to Glasgow?</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>[use quickly]</strong> <strong>get/go/run through something</strong> to use a lot of something quickly:</div><ul class=\"examples\"><li><em>George Ward started smoking at the age of nine, and at one time he was getting through 80 a day.</em></li><li><em>By the end of the year he had run through all the money inherited from his father.</em></li></ul></div>","7029":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> through‧out</span><span class=\"meta-item\"><strong>IPA:</strong> /θruːˈaʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in every part of a particular area, place etc:</div><ul class=\"examples\"><li><em>a large organization with offices throughout the world</em></li><li><em>The disease spread rapidly throughout Europe.</em></li><li><em>The house is in excellent condition, with fitted carpets throughout.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> during all of a particular period, from the beginning to the end:</div><ul class=\"examples\"><li><em>We are open every weekend throughout the year.</em></li><li><em>He was involved in politics throughout his life.</em></li><li><em>The debate continued, but Meredith remained silent throughout.</em></li></ul></div>","7030":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θrəʊ $ θroʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense threw /θruː/, past participle thrown /θrəʊn $ θroʊn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[throw a ball/stone etc]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make an object such as a ball move quickly through the air by pushing your hand forward quickly and letting the object go ► You throw something tosomeone when you want them to catch it. You throw something atsomeone when you want to hit them.</div><ul class=\"examples\"><li><strong><em>throw something to somebody</strong>: He threw his shirt to someone in the crowd.</em></li><li><strong><em>throw something at somebody/something</strong>: Someone threw a stone at the car. / a crowd of boys throwing snowballs at each other</em></li><li><strong><em>throw somebody something</strong>: Throw me that towel, would you.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[put something carelessly]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to put something somewhere quickly and carelessly:</div><ul class=\"examples\"><li><em>He threw a handful of money onto the table.</em></li><li><em>Don’t just throw your clothes on the floor – pick them up!</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[push roughly/violently]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to push someone or something roughly and violently:</div><ul class=\"examples\"><li><em>The bus stopped suddenly and we were all thrown forwards.</em></li><li><em>The guards threw Biko to the ground and started kicking him.</em></li><li><em>The bomb exploded, throwing bricks and debris into the air.</em></li><li><em>She drew the curtains and threw open the windows.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[make somebody fall]</strong> <span class=\"gram\">[transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to make your opponent fall to the ground in a sport in which you fight</div><div class=\"subsense\"><span class=\"subnum\">b)</span> if a horse throws its rider, it makes them fall onto the ground</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[move hands/head etc]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to suddenly and quickly move your hands, arms, head etc into a new position:</div><ul class=\"examples\"><li><em>I threw my arms around her and kissed her.</em></li><li><em>He threw his head back and laughed.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[confuse somebody]</strong> <span class=\"gram\">[transitive]</span> to make someone feel very confused:</div><ul class=\"examples\"><li><em>It threw me completely when she said she was coming to stay with us.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>throw yourself at/on/into/down etc</strong> to move or jump somewhere suddenly and with a lot of force:</div><ul class=\"examples\"><li><em>He threw himself down onto the bed.</em></li><li><em>She committed suicide by throwing herself out of a tenth-floor window.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>throw somebody in/into prison/jail</strong> to put someone in prison:</div><ul class=\"examples\"><li><em>Anyone who opposes the regime is thrown in jail.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>throw somebody out of work/office etc</strong> to suddenly take away someone’s job or position of authority:</div><ul class=\"examples\"><li><em>Hundreds of men were thrown out of work when the mine closed down.</em></li><li><em>Elections were held, and the government was thrown out of office.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>throw somebody/something into confusion/chaos/disarray etc</strong> to make people feel very confused and not certain about what they should do:</div><ul class=\"examples\"><li><em>Everyone was thrown into confusion by this news.</em></li><li><em>The transport industry has been thrown into chaos by the strike.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>throw doubt on something</strong> to make people think that something is probably not true:</div><ul class=\"examples\"><li><em>Fresh evidence has thrown doubt on her story.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>throw suspicion on somebody</strong> to make people think that someone is probably guilty:</div><ul class=\"examples\"><li><em>This latest document throws suspicion on the company chairman.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>throw somebody a look/glance/smile etc</strong> to quickly look at someone with a particular expression that shows how you are feeling:</div><ul class=\"examples\"><li><em>He threw Anna a big smile.</em></li><li><em>He threw a glance at Connor.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>throw a fit/tantrum</strong> to react in a very angry way:</div><ul class=\"examples\"><li><em>I can’t tell my parents – they’d throw a fit!</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>throw a question/remark etc (at somebody)</strong> to say something to someone or ask them something roughly:</div><ul class=\"examples\"><li><em>They threw a few awkward questions at me.</em></li><li><em>‘You’re early!’ she threw at him accusingly.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>throw something open</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to allow people to go into a place that is usually kept private</div><ul class=\"examples\"><li><strong><em>throw to</strong>: Plans have been announced to throw the Palace open to the public.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to allow anyone to take part in a competition or a discussion</div><ul class=\"examples\"><li><strong><em>throw to</strong>: I would now like to throw the debate open to our audience.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>throw a switch/handle/lever</strong> to make something start or stop working by moving a control:</div><ul class=\"examples\"><li><em>He threw a switch and the lights all went out.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>throw a party</strong> to organize a party and invite people</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>throw money at something</strong> <em>informal</em> to try to solve a problem by spending a lot of money but without really thinking about the problem:</div><ul class=\"examples\"><li><em>The problem cannot be solved by throwing money at it.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>be thrown back on something</strong> to be forced to have to depend on your own skills, knowledge etc:</div><ul class=\"examples\"><li><em>Once again, we were thrown back on our own resources.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>throw yourself into something</strong> to start doing an activity with a lot of effort and energy:</div><ul class=\"examples\"><li><em>Since her husband died, she’s thrown herself into her work.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>throw your weight around</strong> to use your position of authority to tell people what to do in an unreasonable way:</div><ul class=\"examples\"><li><em>He’s the sort of insensitive bully who enjoys throwing his weight around.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>throw your weight behind somebody/something</strong> to support a plan, person etc and use your power to make sure they succeed:</div><ul class=\"examples\"><li><em>The party leadership is throwing its weight behind the campaign.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>throw light on something</strong> to make something easier to understand by providing new information:</div><ul class=\"examples\"><li><em>Recent investigations have thrown new light on how the two men died.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>throw a light/shadow</strong> to make light or shadow fall on a particular place:</div><ul class=\"examples\"><li><em>The trees threw long, dark shadows across the cornfield.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>throw the book at somebody</strong> <em>informal</em> to punish someone as severely as possible or charge them with as many offences as possible:</div><ul class=\"examples\"><li><em>If you get caught they’ll throw the book at you!</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>throw something (back) in somebody’s face</strong> to be unkind to someone after they have been kind to you or helped you:</div><ul class=\"examples\"><li><em>I felt that everything I’d done for them was thrown back in my face.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>throw up your hands (in horror/dismay etc)</strong> to do something that shows you think something is not good but feel you cannot do anything to change it:</div><ul class=\"examples\"><li><em>Ted threw up his hands in disgust. ‘Can’t you make her change her mind?’ he asked.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>throw in your hand</strong> to stop trying to do something <em>SYN give up</em></div><div class=\"sense\"><span class=\"snum\">30</span> <strong>throw yourself at somebody</strong> <em>informal</em> to try very hard to attract someone’s attention because you want to have a sexual relationship with them</div><div class=\"sense\"><span class=\"snum\">31</span> <strong>throw a punch</strong> to try to hit someone with your hand in a fight:</div><ul class=\"examples\"><li><em>We need to sort this out before people start throwing punches.</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>throw a match/game/fight</strong> to deliberately lose a fight or sports game that you could have won:</div><ul class=\"examples\"><li><em>He was allegedly offered £20,000 to throw the match.</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>throw dice/a six/a four etc</strong> to roll dice or to get a particular number by rolling dice:</div><ul class=\"examples\"><li><em>You have to throw a six to start.</em></li></ul><div class=\"sense\"><span class=\"snum\">34</span> <strong>throw a pot</strong> to make a pot by shaping clay as it turns round on a special wheel</div><div class=\"sense\"><span class=\"snum\">35</span> <strong>throw your voice</strong> to use a special trick to make your voice seem to be coming from a different place from the place you are standing</div><div class=\"sense\"><span class=\"snum\">36</span> <strong>throw caution to the wind(s)</strong> to ignore the risks and deliberately behave in a way that may cause trouble or problems:</div><ul class=\"examples\"><li><em>I threw caution to the winds and followed him.</em></li></ul><div class=\"sense\"><span class=\"snum\">37</span> <strong>throw the baby out with the bath water</strong> to get rid of good useful parts of a system, organization etc when you are changing it in order to try and make it better</div><div class=\"sense\"><span class=\"snum\">38</span> <strong>throw shapes</strong> <em>informal</em> to dance to popular music, for example in a nightclub, making shapes with your arms</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an action in which someone throws something:</div><ul class=\"examples\"><li><em>That was a great throw!</em></li><li><em>a throw of over 80 metres</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an action in which someone rolls a dice in a game:</div><ul class=\"examples\"><li><em>It’s your throw.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a large piece of cloth that you put loosely over a chair to cover it and make it look attractive:</div><ul class=\"examples\"><li><em>a brightly-coloured cotton throw</em></li></ul></div></div>","7031":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θrʌst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle thrust)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to push something somewhere roughly: ► see thesaurus at put</div><ul class=\"examples\"><li><em>She thrust a letter into my hand.</em></li><li><em>He thrust me roughly towards the door.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to make a sudden movement forward with a sword or knife</div><ul class=\"examples\"><li><strong><em>thrust at</strong>: He skipped aside as his opponent thrust at him.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a sudden strong movement in which you push something forward:</div><ul class=\"examples\"><li><em>He jumped back to avoid another thrust of the knife.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> the main meaning or aim of what someone is saying or doing</div><ul class=\"examples\"><li><strong><em>thrust of</strong>: the main thrust of the government’s education policy</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>technical</em> the force of an engine that makes a car, train, or plane move forward</div></div></div>","7032":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θʌɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a violent man:</div><ul class=\"examples\"><li><em>He was beaten up by a gang of young thugs.</em></li></ul></div>","7033":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θʌm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the part of your hand that is shaped like a thick short finger and helps you to hold things:</div><ul class=\"examples\"><li><em>a baby sucking its thumb</em></li><li><em>She held the coin carefully between finger and thumb.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the part of a glove that fits over your thumb</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>be all fingers and thumbs</strong> <em>British English</em>, be all thumbs<em>American English</em> <em>informal</em> to be unable to do something in which you have to make small careful movements with your fingers:</div><ul class=\"examples\"><li><em>Would you do up these buttons for me? I seem to be all thumbs today.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the thumbs up/down</strong> <em>informal</em> when an idea or plan is officially accepted or not accepted:</div><ul class=\"examples\"><li><em>The project was finally given the thumbs up.</em></li><li><em>Her performance got the thumbs down from the critics.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be under somebody’s thumb</strong> to be so strongly influenced by someone that they control you completely:</div><ul class=\"examples\"><li><em>He was still under his father’s thumb.</em></li></ul></div>","7034":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θʌmp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> <em>informal</em> to hit someone very hard with your hand closed: ► see thesaurus at hit</div><ul class=\"examples\"><li><em>If you don’t shut up, I’m going to thump you!</em></li><li><em>She thumped the table with her fist.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> to hit against something loudly:</div><ul class=\"examples\"><li><em>His feet thumped loudly on the bare boards.</em></li><li><em>He thumped his cup down on the table.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to walk or run with your feet making a loud heavy sound as they touch the ground:</div><ul class=\"examples\"><li><em>Stella came thumping down the stairs.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> if your heart thumps, it beats very strongly and quickly because you are frightened or excited:</div><ul class=\"examples\"><li><em>My heart was thumping inside my chest.</em></li></ul></div>","7035":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thun‧der</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθʌndə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the loud noise that you hear during a storm, usually after a flash of lightning:</div><ul class=\"examples\"><li><em>We were woken in the night by thunder.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> a loud deep noise:</div><ul class=\"examples\"><li><em>She heard the thunder of hooves behind her.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a face like thunder</strong> if someone has a face like thunder, they look very angry</div></div>","7036":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> thun‧der‧storm</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθʌndəstɔːm $ -dərstɔːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a storm with thunder and lightning ► see thesaurus at storm</div></div>","7037":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> Thurs‧day</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈθɜːzdi, -deɪ $ ˈθɜːrz-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the day between Wednesday and Friday</div><ul class=\"examples\"><li><strong><em>on Thursday</strong>: I went to Edinburgh on Thursday.</em></li><li><em>She was working Thursday. </em>American English**</li><li><strong><em>Thursday morning/afternoon etc</strong>: There’s a meeting on Thursday night.</em></li><li><strong><em>last Thursday</strong>: He was arrested last Thursday.</em></li><li><strong><em>this Thursday</strong>: Mark and I are driving south this Thursday.</em></li><li><strong><em>next Thursday</strong> (=Thursday of next week): I’ll see you next Thursday.</em></li><li><strong><em>a Thursday</strong> (=one of the Thursdays in the year): Christmas Day is on a Thursday this year.</em></li></ul></div>","7038":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ðʌs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> as a result of something that you have just mentioned: ► see thesaurus at therefore</div><ul class=\"examples\"><li><em>Most of the evidence was destroyed in the fire. Thus it would be almost impossible to prove him guilty.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in this manner or way:</div><ul class=\"examples\"><li><em>They diluted the drug, thus reducing its effectiveness.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>thus far</strong> until now: RegisterThus is formal or literary. In everyday English, people usually say so:· So it was decided that he should be chairman.· We haven’t had any problems so far.</div><ul class=\"examples\"><li><em>Her political career thus far had remained unblemished.</em></li></ul></div>","7039":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /θwɔːt $ θwɔːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to prevent someone from doing what they are trying to do:</div><ul class=\"examples\"><li><em>Fierce opposition thwarted the government’s plans.</em></li><li><em>thwarted ambition</em></li></ul></div>","7040":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> (also tick away) if a clock or watch ticks, it makes a short repeated sound:</div><ul class=\"examples\"><li><em>The old clock ticked noisily.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>British English</em> to mark a test, list of questions etc with a tick, in order to show that something is correct, to choose something etc SYN check<em>American English</em>:</div><ul class=\"examples\"><li><em>Tick the description that best fits you.</em></li><li><em>Just tick the box on your order form.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>what makes somebody tick</strong> <em>informal</em> the thoughts, feelings, opinions etc that give someone their character or make them behave in a particular way:</div><ul class=\"examples\"><li><em>I’ve never really understood what makes her tick.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>tick all the right boxes</strong> <em>informal</em> if something ticks all the right boxes, it does everything that you wanted it to do or is everything you wanted it to be</div></div>","7041":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tick‧et</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɪkɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[cinema/bus/train etc]</strong> a printed piece of paper which shows that you have paid to enter a cinema, travel on a bus, plane etc → season ticket</div><ul class=\"examples\"><li><strong><em>ticket for</strong>: How much are tickets for the concert?</em></li><li><strong><em>ticket to</strong>: I’d like two tickets to Berlin.</em></li><li><strong><em>a ticket to do something</strong>: a ticket to watch the US Open</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[for a prize]</strong> a printed piece of paper with a number on it that you buy because you will get a prize if that number is chosen</div><ul class=\"examples\"><li><strong><em>raffle/lottery ticket</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[driving offence]</strong> a printed note ordering you to pay money because you have done something illegal while driving or parking your car</div><ul class=\"examples\"><li><strong><em>parking/speeding ticket</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[in shops]</strong> a piece of paper fastened to something in a shop that shows its price, size etc SYN tag<em>American English</em>:</div><ul class=\"examples\"><li><em>How much does it say on the price ticket?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[election]</strong> <span class=\"gram\">[usually singular]</span> <em>especially American English</em> a list of the people supported by a particular political party in an election:</div><ul class=\"examples\"><li><em>He ran for governor on the Republican ticket.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>ticket to success/fame/stardom etc</strong> <em>especially American English</em> a way of becoming successful, famous etc:</div><ul class=\"examples\"><li><em>Michael thought an MBA would be a ticket to success.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be (just) the ticket</strong> <em>old-fashioned</em> to be exactly what is needed</div></div>","7042":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tick‧le</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɪkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to move your fingers gently over someone’s body in order to make them laugh: ► see thesaurus at touch</div><ul class=\"examples\"><li><em>Stop tickling me!</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> if something touching your body tickles you, it makes you want to rub your body because it is slightly uncomfortable:</div><ul class=\"examples\"><li><em>Mommy, this blanket tickles.</em></li><li><em>Mazie’s fur collar was tickling her neck.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> if a situation, remark etc tickles you, it amuses or pleases you</div><ul class=\"examples\"><li><strong><em>be tickled pink</strong> (=be very pleased or amused): The kids were tickled pink to see you on TV!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>tickle somebody’s fancy</strong> <em>informal</em> if something tickles your fancy, you want to have it or to try doing it:</div><ul class=\"examples\"><li><em>If I see something that tickles my fancy, I’m going to buy it.</em></li></ul></div>","7043":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the tide</strong> the regular rising and falling of the level of the sea → high tide(1), low tide</div><ul class=\"examples\"><li><strong><em>the tide is in/out</strong> (=the sea is at a high/low level)</em></li><li><em>Is the tide going out or coming in?</em></li><li><em>We went for a walk and got cut off by the tide.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a current of water caused by the tide:</div><ul class=\"examples\"><li><em>Strong tides make swimming dangerous.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable usually singular]</span> the way in which events or people’s opinions are developing</div><ul class=\"examples\"><li><strong><em>tide of</strong>: With the tide of public opinion against him, the president may lose.</em></li><li><em>It was their first major victory. The tide had turned (=changed).</em></li><li><em>The tide of battle turned against the Mexican army.</em></li><li><strong><em>swim with/against the tide</strong> (=support or oppose what most people think)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable usually singular]</span> a large amount of something that is increasing and is difficult to control</div><ul class=\"examples\"><li><strong><em>tide of violence/crime etc</strong>: The crisis prompted a rising tide of protest.</em></li><li><em>She swallowed back a tide of emotion.</em></li><li><em>efforts to stem the tide of hysteria caused by the shootings (=prevent it from getting worse)</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[singular]</span> a large number of people or things moving along together</div><ul class=\"examples\"><li><strong><em>tide of</strong>: the tide of refugees flowing over the border</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>Christmastide/eveningtide/morningtide etc</strong> <em>old use</em> a particular time of the year or day</div></div>","7044":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ti‧dy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪdi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(comparative tidier, superlative tidiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a room, house, desk etc that is tidy is neatly arranged with everything in the right place <em>SYN neat</em> <em>OPP untidy</em> <em>, messy</em>:</div><ul class=\"examples\"><li><em>a tidy desk</em></li><li><em>I try to keep the garden tidy.</em></li><li><em>Ellen’s room is always neat and tidy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is tidy keeps their house, clothes etc neat and clean:</div><ul class=\"examples\"><li><em>Chris is a naturally tidy person.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a tidy sum/profit</strong> <em>informal</em> a large amount of money:</div><ul class=\"examples\"><li><em>We sold the house for a tidy sum and moved south.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a tidy mind</strong> <em>British English</em> if someone has a tidy mind, the way they think is very organized and clear</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span><span class=\"meta-item\">(past tense and past participle tidied, present participle tidying, third person singular tidies)</span></div><div class=\"entry-body\"><div class=\"sense\">to make a place look tidy:</div><ul class=\"examples\"><li><em>Tidy your room!</em></li><li><em>It’s time we tidied up the office.</em></li><li><strong><em>tidy up after somebody</strong>: I’m tired of tidying up after you boys (=tidying somewhere that someone else has made untidy).</em></li></ul></div></div>","7045":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(past tense and past participle tied, present participle tying, third person singular ties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[string/rope]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[transitive]</span> to fasten things together or hold them in a particular position using a piece of string, rope etc <em>OPP untie</em></div><ul class=\"examples\"><li><strong><em>tie something to/behind/onto etc something</strong>: Tie this label to your suitcase.</em></li><li><strong><em>tie somebody to something</strong>: They tied him to a tree and beat him up.</em></li><li><strong><em>tie something together (with something)</strong>: I kept all his letters tied together with a ribbon.</em></li><li><strong><em>tie somebody’s hands/arms/legs/feet</strong>: One of them tied her hands behind her back.</em></li><li><em>I tie my hair back when I’m jogging.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[transitive]</span> to fasten something around, over etc something else and tie the ends together <em>OPP untie</em></div><ul class=\"examples\"><li><strong><em>tie something around/over/under etc something</strong>: He had only a towel tied around his waist. / She tied a scarf over her head.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <span class=\"gram\">[transitive]</span> to make a knot in a piece of string, rope etc, for example to fasten shoes or other clothes:</div><ul class=\"examples\"><li><em>Can you tie your shoelaces by yourself?</em></li><li><strong><em>tie a knot/bow</strong>: She pulled the ribbon tightly and tied a bow.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">d)</span> <span class=\"gram\">[intransitive]</span> if a piece of clothing ties in a particular place, you fasten it there using a belt, bow etc:</div><ul class=\"examples\"><li><em>This dress ties at the back.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[game/competition]</strong> <span class=\"gram\">[intransitive]</span> (also be tied) if two players, teams etc tie or are tied in a game or competition, they finish it with an equal number of points</div><ul class=\"examples\"><li><strong><em>tie with</strong>: At the end of the season, we were tied with the Tigers.</em></li><li><strong><em>tie for first/second etc place</strong>: Woosnam and Lyle tied for fourth place on 264.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be tied to something</strong> to be related to something and dependent on it:</div><ul class=\"examples\"><li><em>The flat is tied to the job.</em></li><li><em>Interest rates are tied to the rate of inflation.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be tied to/by something</strong> to be restricted by a particular situation, job etc, so that you cannot do exactly what you want:</div><ul class=\"examples\"><li><em>Many women felt tied to the house.</em></li><li><strong><em>be tied to doing something</strong>: I didn’t want to be tied to commuting to London.</em></li><li><em>With children, you’re tied by school holidays.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>tie the knot</strong> <em>informal</em> to get married</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>tie yourself (up) in knots</strong> <em>informal</em> to become very upset because you are confused, nervous, or worried</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>tie one on</strong> <em>American English</em> <em>informal</em> to get drunk</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[men’s clothes]</strong> a long narrow piece of cloth tied in a knot around the neck, worn by men: → black-tie, bow tie</div><ul class=\"examples\"><li><em>I wear a shirt and tie at work.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[connection/relationship]</strong> <span class=\"gram\">[usually plural]</span> a strong relationship between people, groups, or countries → old school tie</div><ul class=\"examples\"><li><strong><em>close/strong ties</strong>: the importance of strong family ties</em></li><li><strong><em>tie between/with</strong>: close ties between the two countries</em></li><li><strong><em>economic/diplomatic/personal etc ties</strong>: Japan’s strong economic ties with Taiwan</em></li><li><strong><em>the ties of marriage/friendship/love etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[result]</strong> <span class=\"gram\">[usually singular]</span> the result of a game, competition, or election when two or more people or teams get the same number of points, votes etc SYN draw<em>British English</em>:</div><ul class=\"examples\"><li><em>The match ended in a tie.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[for closing something]</strong> a piece of string, wire etc used to fasten or close something such as a bag</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[game]</strong> <em>British English</em> one game, especially of football, that is part of a larger competition</div><ul class=\"examples\"><li><strong><em>tie against</strong>: England’s World Cup tie against Argentina</em></li><li><strong><em>first round/second round etc tie</em></strong></li><li><strong><em>home/away tie</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[prevent you from doing something]</strong> something that means you must stay in one place, job etc or prevents you from being free to do what you want:</div><ul class=\"examples\"><li><em>If you enjoy travelling, young children can be a tie.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[railway]</strong> <em>American English</em> a heavy piece of wood or metal supporting a railway track SYN sleeper<em>British English</em></div></div></div>","7046":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɪə $ tɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of several levels or layers that rise up one above the other:</div><ul class=\"examples\"><li><em>The lower tier has 10,000 seats.</em></li><li><strong><em>in tiers</strong>: Terraces of olive trees rose in tiers.</em></li><li><strong><em>two-tiered/three-tiered etc</strong> (=having two, three etc levels or layers): a three-tiered wedding cake</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> one of several levels in an organization or system</div><ul class=\"examples\"><li><strong><em>tier of</strong>: the most senior tier of management</em></li><li><strong><em>the first/second etc tier</strong>: The second tier of the programme is in-house training.</em></li><li><em>a two-tier system of government</em></li></ul></div>","7047":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ti‧ger</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪɡə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a large wild animal that has yellow and black lines on its body and is a member of the cat family → paper tiger</div></div>","7048":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(comparative tighter, superlative tightest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[clothes]</strong> tight clothes fit your body very closely, especially in a way that is uncomfortable <em>OPP loose</em>:</div><ul class=\"examples\"><li><em>tight jeans</em></li><li><em>My shoes were so tight that I could hardly walk.</em></li><li><em>The jacket is rather a tight fit (=it fits too tightly).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[pulled/stretched firmly]</strong> string, wire, cloth etc that is tight has been pulled or stretched firmly so that it is straight or cannot move:</div><ul class=\"examples\"><li><em>The bandage must be tight enough to stop the bleeding.</em></li><li><em>She tied the rope around the post and pulled it tight.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[attached firmly]</strong> a screw, lid etc that is tight is firmly attached and difficult to move:</div><ul class=\"examples\"><li><em>Check that the screws are tight.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[holding something firmly]</strong> <strong>a tight hold/grip</strong> if you keep or have a tight hold on something, you hold it firmly:</div><ul class=\"examples\"><li><em>His mother kept a tight hold on his hand.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[strict]</strong> controlling something very strictly or firmly:</div><ul class=\"examples\"><li><em>The government is keeping tight control on immigration.</em></li><li><strong><em>keep a tight grip/hold/rein on something</strong> (=control it very firmly): The former dictator still keeps a tight grip on power. / Anna was determined to keep a tight hold on her feelings.</em></li><li><em>Security is always tight for the opening day of parliament.</em></li><li><strong><em>run/keep a tight ship</strong> (=manage a company, organization etc strictly and effectively)</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[little money]</strong> if money is tight, you do not have enough of it</div><ul class=\"examples\"><li><strong><em>money is tight/things are tight</strong>: Money was tight and he needed a job badly.</em></li><li><em>As you know, I run the magazine on a pretty tight budget.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[little time]</strong> if time is tight, it is difficult for you to do everything you need to do in the time available:</div><ul class=\"examples\"><li><em>Time is tight, and she has another meeting to go to this afternoon.</em></li><li><em>We should arrive on time, but it’ll be tight.</em></li><li><em>As usual, his schedule on Saturday was tight (=he had arranged to do several things in a short time).</em></li><li><em>I&#x27;m working to a very tight deadline (=I have to finish a piece of work very quickly).</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[little space]</strong> if space is tight, there is only just enough space to fit something into a place</div><ul class=\"examples\"><li><strong><em>be a tight squeeze/fit</strong>: Six in the car will be a tight squeeze.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[not generous]</strong> <em>informal</em> not generous, or trying hard to avoid spending money:</div><ul class=\"examples\"><li><em>Don’t be so tight!</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[close together]</strong> placed or standing closely together:</div><ul class=\"examples\"><li><em>The animal’s body was curled up in a tight little ball.</em></li><li><em>She wore her hair in a tight bun.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[close relationship]</strong> a tight group of people, countries etc have a close relationship with each other <em>SYN tight-knit</em>:</div><ul class=\"examples\"><li><em>Together, the young film-makers formed a tight group.</em></li><li><em>the tight bonds that had grown between them</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[bend/turn]</strong> a tight bend or turn is very curved and turns quickly in another direction:</div><ul class=\"examples\"><li><em>Danny lost control on a tight bend, and the car ran off the road.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[chest/stomach/throat]</strong> if your chest, stomach, or throat feels tight, it feels painful and uncomfortable, because you are ill or worried:</div><ul class=\"examples\"><li><em>Before she went on stage her chest felt tight and her throat hurt.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[expression/smile/voice]</strong> a tight expression, smile, or voice shows that you are annoyed or worried <em>SYN tight-lipped</em>:</div><ul class=\"examples\"><li><em>‘Look, I’m sorry...,’ she said, forcing a tight smile.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[difficult situation]</strong> <strong>in a tight corner/spot</strong> <em>informal</em> in a difficult situation:</div><ul class=\"examples\"><li><em>He’s a good man to have around if ever you’re in a tight corner.</em></li><li><em>‘Did something go wrong?’ ‘Let’s just say I got into a bit of a tight spot.’</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[play/performance]</strong> playing a piece of music or giving a performance very exactly and well, without any pauses or mistakes:</div><ul class=\"examples\"><li><em>The band gave a really tight performance.</em></li><li><em>a tight, well-rehearsed production</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[game/competition]</strong> a tight game, competition etc is one in which the teams, players etc play equally well, and it is not easy to win:</div><ul class=\"examples\"><li><em>The opening quarter of the game was very tight.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>[drunk]</strong> <span class=\"gram\">[not before noun]</span> <em>old-fashioned</em> <em>informal</em> drunk</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\">very firmly or closely <em>SYN tightly</em>:</div><ul class=\"examples\"><li><em>Hold tight to the handrail!</em></li><li><em>I kept my eyes tight shut.</em></li></ul></div></div>","7049":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tight‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪtn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to close or fasten something firmly by turning it <em>OPP loosen</em>:</div><ul class=\"examples\"><li><em>Tighten the screws firmly.</em></li><li><em>I’d put the new tyre on, but I hadn’t tightened up the wheel.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> if you tighten a rope, wire etc, or if it tightens, it is stretched or pulled so that it becomes tight:</div><ul class=\"examples\"><li><em>When you tighten guitar strings, the note gets higher.</em></li><li><em>The rope tightened around his body.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to become stiff or make a part of your body become stiff <em>OPP relax</em>:</div><ul class=\"examples\"><li><em>His mouth tightened into a thin, angry line.</em></li><li><em>Tighten up the muscles of both arms.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>tighten your grip/hold on something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to control a place or situation more strictly:</div><ul class=\"examples\"><li><em>Rebel forces have tightened their hold on the capital.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to hold someone or something more firmly:</div><ul class=\"examples\"><li><em>Sarah tightened her grip on my arm.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[transitive]</span> to make a rule, law, or system more strict <em>OPP relax</em>:</div><ul class=\"examples\"><li><em>Efforts to tighten the rules have failed.</em></li><li><strong><em>tighten up on something</strong>: a range of measures to tighten up on illegal share dealing</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>tighten your belt</strong> <em>informal</em> to try to spend less money than you used to:</div><ul class=\"examples\"><li><em>Businesses were tightening their belts and cutting jobs.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>tighten the screws (on somebody)</strong> <em>informal</em> to try to force someone to do something, by threatening them or making things difficult for them – used in news reports:</div><ul class=\"examples\"><li><em>Closing the border would tighten the screws on the terrorists.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <span class=\"gram\">[intransitive]</span> <em>American English</em> if a race or competition tightens, the distance between the competitors becomes smaller:</div><ul class=\"examples\"><li><em>He expects the presidential race to tighten.</em></li></ul></div>","7050":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tight‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /taɪtli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very firmly or closely:</div><ul class=\"examples\"><li><em>He gripped the steering wheel more tightly.</em></li><li><em>Marie held the baby tightly in her arms.</em></li><li><em>Her eyes were tightly shut.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a strict way:</div><ul class=\"examples\"><li><em>The media is tightly controlled in some countries.</em></li><li><em>tightly guarded government buildings</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> in a way that shows you are annoyed or worried:</div><ul class=\"examples\"><li><em>Caroline smiled tightly.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> with not much space between people or things:</div><ul class=\"examples\"><li><em>The houses were tightly packed together.</em></li></ul></div>","7051":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a flat square piece of baked clay or other material, used for covering walls, floors etc:</div><ul class=\"examples\"><li><em>bathroom tiles</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a thin curved piece of baked clay used for covering roofs</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>on the tiles</strong> <em>British English</em> <em>informal</em> out drinking, dancing etc for enjoyment until late at night</div></div>","7052":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɪl, tl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\">until:</div><ul class=\"examples\"><li><em>I didn’t have a boyfriend till I was 17.</em></li><li><em>The shop’s open till nine o&#x27;clock on Fridays.</em></li></ul></div>","7053":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɪlt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to move a part of your body, especially your head or chin, upwards or to the side <em>SYN tip</em>:</div><ul class=\"examples\"><li><em>My mother tilted her head and smiled.</em></li><li><em>Ned’s mouth tilted upwards slightly at the corners.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to move or make something move into a position where one side is higher than the other <em>SYN tip</em>:</div><ul class=\"examples\"><li><em>As it came in to land, the plane tilted sideways.</em></li><li><em>The man was tilting his chair back.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if an opinion or situation tilts, or if something tilts it, it changes so that people start to prefer one person, belief, or action to others:</div><ul class=\"examples\"><li><em>Crisis situations tend to tilt the balance of power in favour of the president.</em></li><li><strong><em>tilt toward/towards</strong>: Government tax policy has tilted toward industrial development.</em></li></ul></div>","7054":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tim‧ber</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɪmbə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> <em>British English</em> wood used for building or making things SYN lumber<em>American English</em>:</div><ul class=\"examples\"><li><em>a bench made of timber</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> trees that produce wood used for building or making things:</div><ul class=\"examples\"><li><em>the timber trade</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a wooden beam, especially one that forms part of the main structure of a house</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>timber!</strong> <em>spoken</em> used to warn people that a tree being cut down is about to fall</div></div>","7055":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[minutes/hours etc]</strong> <span class=\"gram\">[uncountable]</span> the thing that is measured in minutes, hours, days, years etc using clocks: ► see thesaurus at period</div><ul class=\"examples\"><li><em>Einstein changed the way we think about space and time.</em></li><li><em>close relationships established over a long period of time</em></li><li><em>Customers have only a limited amount of time to examine the goods.</em></li><li><strong><em>time passes/goes by</strong>: Their marriage got better as time went by.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[on a clock]</strong> <span class=\"gram\">[singular]</span> a particular point in time shown on a clock in hours and minutes:</div><ul class=\"examples\"><li><em>‘What time is it?’ ‘It’s about two thirty.’</em></li><li><em>What time are you going out tonight?</em></li><li><strong><em>what time do you make it?<em>British English,</em></strong> <strong>what time do you have?</em>American English</strong><em> (=used to ask someone with a watch what time it is)</em></li><li><strong><em>have you got the time?<em>British English,</em></strong> <strong>do you have the time?</em>American English</strong><em> (=used to ask someone if they know what time it is)</em></li><li><strong><em>tell the time<em>British English,</em></strong> <strong>tell time</em>American English</strong><em> (=be able to understand a clock): Robin’s just learning to tell the time.</em></li><li><strong><em>look at the time</strong> (=used when you realize that it is later than you thought it was): Oh no. Look at the time. I’ll be late.</em></li><li><strong><em>is that the time?</strong> (=used when you suddenly realize what the time is): Is that the time? I must go.</em></li><li><strong><em>this time tomorrow/last week etc</strong>: By this time tomorrow I’ll know whether I’ve got the job.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[occasion]</strong> <span class=\"gram\">[countable]</span> an occasion when something happens or someone does something: GRAMMARYou say: · The first time I saw it, I loved it. ✗Don’t say: At the first time I saw it, I loved it.</div><ul class=\"examples\"><li><em>That was the only time we disagreed.</em></li><li><em>Do you remember the time I hit Tom Benson?</em></li><li><em>Mary had seen the film many times.</em></li><li><strong><em>(for) the first/second/last etc time</strong>: It was the first time that he had lost a game. / Gerry had just had back surgery for the third time in two years.</em></li><li><strong><em>(the) next time/(the) last time/this time</strong>: Why don’t you drop in for a drink next time you’re over this way? / The last time (=the most recent time) I saw Jonathan was Thursday evening. / The freezing weather did not return until February but this time we were prepared.</em></li><li><strong><em>the first/second/next/last etc time round</strong> (=the first, second etc time something happens): I missed their concert the first time round so I’m going next week.</em></li><li><strong><em>every/each time</strong>: I meet up with Julie every time I go to Washington.</em></li><li><strong><em>how many times...?</strong>: How many times did you take your driving test? / How many times have I told you not to wander off like that? (=I have told you many times)</em></li><li><em>One time (=once) I went to a garage sale and bought fifteen books.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[point when something happens]</strong> <span class=\"gram\">[countable, uncountable]</span> the particular minute, hour, day etc when something happens or should happen</div><ul class=\"examples\"><li><strong><em>at the time of something</strong>: She was three months pregnant at the time of Stephen’s death.</em></li><li><strong><em>at some/any/that time</strong>: He is performing as well as at any time in his career. / The UK has 500,000 stray dogs on its streets at any one time (=at any particular time).</em></li><li><strong><em>at a/the time when...</strong>: At the time when this scheme was introduced, it was recognised that there might be problems.</em></li><li><strong><em>by the time...</strong>: The phone was ringing but by the time she got indoors, it had stopped.</em></li><li><strong><em>it’s time to do something</strong>: Rosie – it’s time to get up.</em></li><li><strong><em>it’s time for something</strong>: Come on, it’s time for bed. / He glanced at his watch. ‘It’s time for me to go.’</em></li><li><strong><em>it’s time somebody did something</strong>: It’s time I fed the dog.</em></li><li><em>Now is the right time for us to move to London.</em></li><li><strong><em>a good/bad time</strong>: This might be a good time to start planning the new garden.</em></li><li><strong><em>not the time/hardly the time</strong>: Now is not the time to annoy Peter.</em></li><li><strong><em>there’s no time like the present</strong> (=used to say that now is a good time to do something): ‘When do you want to meet?’ ‘Well, there’s no time like the present.’</em></li><li><strong><em>dinner/lunch/tea etc time</strong>: It’s nearly dinner time.</em></li><li><strong><em>opening/closing time</strong> (=the time when a shop, bar etc opens or closes): We empty the till each night at closing time.</em></li><li><strong><em>arrival/departure time</strong> (=the time when a train, plane etc arrives or leaves): Our estimated arrival time is 2:30 pm.</em></li><li><strong><em>time of day/year</strong>: England is so lovely at this time of year.</em></li><li><em>We’ll sort that out when the time comes (=when it becomes necessary).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[period of time]</strong> <span class=\"gram\">[singular, uncountable]</span> a period of time during which something happens or someone does something:</div><ul class=\"examples\"><li><em>Dustin wanted to spend as much time as possible with his family.</em></li><li><strong><em>a long/short/limited time</strong>: I first met Jennifer a long time ago. / They stopped for a short time to rest the horses.</em></li><li><em>Andy and Tom talked for some time (=for a fairly short period).</em></li><li><em>Alison was married, for a time (=for a fairly short period), to a comedian.</em></li><li><em>Martin disliked being away from his family for any length of time (=for more than just a short period).</em></li><li><em>It took her a long time to make a decision.</em></li><li><em>Learning a language isn’t easy – it takes time (=takes a long period of time).</em></li><li><strong><em>take time to do something</strong> (=deliberately spend time doing something): While in New York he took time to visit some friends.</em></li><li><strong><em>travel time</strong>: I wanted to make better use of my travel time.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[available time]</strong> <span class=\"gram\">[uncountable]</span> an amount of time that is available for you to do something:</div><ul class=\"examples\"><li><em>I’ll visit him if I have time.</em></li><li><em>Molly would like to do some diving if there is time.</em></li><li><strong><em>have time for something</strong>: She realized she would have time for a coffee before her train left.</em></li><li><em>We don’t have to rush. We have all the time in the world (=have plenty of time).</em></li><li><em>June had little time to spare (=available time) for making her own clothes.</em></li><li><strong><em>free/spare time</strong> (=time when you are not working): He writes poetry in his spare time.</em></li><li><em>Being prepared for meetings will save time.</em></li><li><em>I don’t want to waste time arguing.</em></li><li><em>She spent precious time (=valuable and important time) looking for a telephone.</em></li><li><em>I seem to spend most of my time on the phone.</em></li><li><em>McDuff passed the time writing letters (=wrote letters because he had nothing else to do).</em></li><li><strong><em>have time on your hands/time to kill</strong> (=not have enough to do): Now the children have left home, she has too much time on her hands.</em></li><li><strong><em>make/find time (for something/to do something)</strong> (=plan so that you have time available for something): Make time to talk to your children.</em></li><li><em>Book your ticket soon, as time is running out.</em></li><li><strong><em>time’s up</strong> (=used to say that it is the end of the time allowed for something such as a competition or examination)</em></li><li><strong><em>we’re out of time</strong> (=used on radio and television programmes to say that there is no more time available on the programme)</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>all the time</strong> (also the whole time) continuously or very often:</div><ul class=\"examples\"><li><em>I keep practising and I’m improving all the time.</em></li><li><em>He worries about her the whole time.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>most of the time</strong> very often or almost always:</div><ul class=\"examples\"><li><em>I can speak German but we speak English most of the time.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>half the time</strong> if something happens half the time, especially something annoying, it happens quite often:</div><ul class=\"examples\"><li><em>Half the time you don’t even notice what I’m wearing.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>at times</strong> sometimes:</div><ul class=\"examples\"><li><em>Life is hard at times.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>from time to time</strong> sometimes, but not regularly or very often:</div><ul class=\"examples\"><li><em>These food safety scares happen from time to time.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>time after time/time and time again</strong> often, over a long period:</div><ul class=\"examples\"><li><em>The police were catching the same kids stealing time after time.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>at all times</strong> always – used especially in official rules and statements:</div><ul class=\"examples\"><li><em>Children must be supervised at all times while in the park.</em></li><li><em>Parents are welcome at all times.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>nine times out of ten/99 times out of 100 etc</strong> used to say that something is almost always true or almost always happens:</div><ul class=\"examples\"><li><em>Nine times out of ten she’s right.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>at the time</strong> at a particular moment or period in the past when something happened, especially when the situation is very different now:</div><ul class=\"examples\"><li><em>I was about ten or eleven at the time.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>at one time</strong> at a time in the past but not now:</div><ul class=\"examples\"><li><em>At one time she wanted to be a nurse, but the thought of working at night put her off.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>at this time</strong> <em>American English</em> at this particular moment:</div><ul class=\"examples\"><li><em>The president said his actions were ‘the right ones at this time’.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>at no time</strong> used to say strongly that something never happened or should never happen</div><ul class=\"examples\"><li><strong><em>at no time did/was etc</strong>: At no time did anyone involved speak to the press. / At no time was the company informed.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>for the time being</strong> for a short period of time from now, but not permanently:</div><ul class=\"examples\"><li><em>Now, for the time being, she is living with her father in Tijuana.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>in 10 days’/five years’/a few minutes’ etc time</strong> ten days, five years etc from now:</div><ul class=\"examples\"><li><em>He has an appointment with the doctor in two days’ time.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>in time</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> before the time by which it is necessary for something to be done:</div><ul class=\"examples\"><li><em>Will you be able to finish it in time?</em></li><li><strong><em>in time to do something</strong>: They ran all the way to the corner just in time to see the bus disappearing up the street.</em></li><li><strong><em>time for</strong>: The painting was successfully repaired in time for the opening of the exhibition.</em></li><li><strong><em>in good time/in plenty of time</strong> (=a long time before the necessary time): We arrived at the concert hall in good time.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> after a certain period of time, especially after a gradual process of change and development:</div><ul class=\"examples\"><li><em>He wants to see changes in the company and I am sure he will, in time.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>with time to spare</strong> sooner than expected or necessary:</div><ul class=\"examples\"><li><em>We should arrive in New York with time to spare.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>over time</strong> if something happens over time, it happens gradually during a long period:</div><ul class=\"examples\"><li><em>The research project will be assessed over time.</em></li><li><em>Students are encouraged to consider the way language changes over time.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>with time/given time</strong> after a period of time:</div><ul class=\"examples\"><li><em>These symptoms will start to get better with time.</em></li><li><em>I would have thought of the answer, given time.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>take your time</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to do something slowly or carefully without hurrying</div><ul class=\"examples\"><li><strong><em>take your time doing something</strong>: Marie took her time cutting my hair and did it really well.</em></li><li><strong><em>time over</strong>: He had planned to take his time over the journey.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to do something more slowly than seems reasonable:</div><ul class=\"examples\"><li><em>You’re taking your time with the lab tests. We need the results now.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>five/ten/many etc times...</strong> used to say how much greater, more etc one thing is than another:</div><ul class=\"examples\"><li><em>Sound travels four times faster in water than in air.</em></li><li><em>There were three times as many girls as boys.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>... at a time</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if someone deals with things one, three, ten etc at a time, they deal with them separately or in groups of three, ten etc:</div><ul class=\"examples\"><li><em>If you raise your hands, I’ll answer questions one at a time.</em></li><li><em>Frank took the stairs two at a time.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if something happens for hours, days, months etc at a time, it continues for several hours, months etc:</div><ul class=\"examples\"><li><em>Because of his work, he’s often away for weeks at a time.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>on time</strong> at the correct time or the time that was arranged: USAGE: On time, in time• On time means ‘at the correct or agreed time’: · Please arrive on time. ✗Don’t say: Please arrive in time.• In time means ‘early enough for something or to do something’: · He arrived in time for supper.</div><ul class=\"examples\"><li><em>Jack was worried about whether he’d be able to get there on time.</em></li><li><strong><em>right/bang/dead on time</strong> (=at exactly the right time): The plane arrived right on time.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>ahead of/behind time</strong> earlier or later than the time when something happens, should be done etc:</div><ul class=\"examples\"><li><em>Prepare what you plan to say in the meeting ahead of time (=before the meeting).</em></li><li><em>The train left twenty minutes behind time (=after it should have left).</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>it’s about time</strong> (also it’s high time) <em>spoken</em> used to say strongly that you think something should happen soon or should already have happened:</div><ul class=\"examples\"><li><em>It’s about time our team won.</em></li><li><em>It’s high time we had a party.</em></li></ul><div class=\"sense\"><span class=\"snum\">31</span> <strong>not before time/and about time (too)</strong> <em>spoken</em> used to say that something should have happened sooner:</div><ul class=\"examples\"><li><em>Philip is going to be punished and not before time.</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>the best/biggest etc... of all time</strong> the best, biggest etc of a particular kind of person or thing that has ever existed:</div><ul class=\"examples\"><li><em>He is the greatest athlete of all time, in my opinion.</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>in no time (at all)/in next to no time</strong> very quickly or soon:</div><ul class=\"examples\"><li><em>We’ll be there in no time.</em></li></ul><div class=\"sense\"><span class=\"snum\">34</span> <strong>any time (now)</strong> very soon:</div><ul class=\"examples\"><li><em>‘When is she due back?’ ‘Any time now.’</em></li></ul><div class=\"sense\"><span class=\"snum\">35</span> <strong>it’s (only/just) a matter/question of time</strong> used to say that something will definitely happen at some time in the future, but you do not know when:</div><ul class=\"examples\"><li><em>I’ll find the key eventually. It’s just a question of time.</em></li><li><em>It’s only a matter of time before we catch the person who killed her.</em></li></ul><div class=\"sense\"><span class=\"snum\">36</span> <strong>(only) time will tell</strong> used to say that at some time in the future it will become clear whether or not something is true, right etc:</div><ul class=\"examples\"><li><em>Only time will tell if the treatment has been successful.</em></li></ul><div class=\"sense\"><span class=\"snum\">37</span> <strong>[period in history]</strong> <span class=\"gram\">[countable]</span> (also times<span class=\"gram\">[plural]</span>) a particular period in history:</div><ul class=\"examples\"><li><em>Mankind has used the horse since ancient times.</em></li><li><em>In earlier times, servants would use the bare wooden stairs at the back of the house.</em></li><li><strong><em>at/in/during etc the time of something</strong>: He lived at the time of the Napoleonic wars.</em></li><li><strong><em>our time(s)</strong> (=the present period in history): Air pollution has become one of the most significant health problems of our time.</em></li></ul><div class=\"sense\"><span class=\"snum\">38</span> <strong>behind the times</strong> old-fashioned:</div><ul class=\"examples\"><li><em>Our equipment is a bit behind the times.</em></li></ul><div class=\"sense\"><span class=\"snum\">39</span> <strong>move/change/keep up with the times</strong> to change when other things in society, business etc change:</div><ul class=\"examples\"><li><em>We’ve got to move with the times.</em></li></ul><div class=\"sense\"><span class=\"snum\">40</span> <strong>ahead of your/its time</strong> having or using the most advanced ideas, methods, designs, technology etc:</div><ul class=\"examples\"><li><em>Coleridge was far ahead of his time in his understanding of the unconscious.</em></li></ul><div class=\"sense\"><span class=\"snum\">41</span> <strong>[pleasant/unpleasant]</strong> <span class=\"gram\">[countable]</span> a good time, bad time, difficult time etc is a period or occasion when you have good, bad, difficult etc experiences:</div><ul class=\"examples\"><li><em>This was the happiest time of her life.</em></li><li><strong><em>good/bad/hard etc times</strong>: They had their happy times, but they had their hard times too.</em></li><li><strong><em>have a good/great/lovely etc time</strong> (=enjoy yourself): Did you have a good time at the party?</em></li><li><em>Julie went to a wedding at the weekend and had the time of her life (=enjoyed herself very much).</em></li></ul><div class=\"sense\"><span class=\"snum\">42</span> <strong>somebody’s time in/at/as something</strong> the period of time when you were living in a particular place, working for a particular company etc:</div><ul class=\"examples\"><li><em>In her time at the United Nations she was considered a tough negotiator.</em></li></ul><div class=\"sense\"><span class=\"snum\">43</span> <strong>before your time</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> before you were born or before you started working or living somewhere:</div><ul class=\"examples\"><li><em>They say he was a great actor but that was before my time.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if you do something, especially get old, before your time, you do it before the time when most people usually do it in their lives:</div><ul class=\"examples\"><li><em>He seemed to grow into an old man before his time.</em></li></ul><div class=\"sense\"><span class=\"snum\">44</span> <strong>[in part of the world]</strong> <span class=\"gram\">[uncountable]</span> the way of referring to points in time in one particular part of the world:</div><ul class=\"examples\"><li><em>Eastern Standard Time</em></li><li><em>British Summer Time</em></li><li><em>The flight to Boston arrives at 1.15 pm local time.</em></li></ul><div class=\"sense\"><span class=\"snum\">45</span> <strong>[time taken]</strong> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the amount of time taken by a competitor in a race:</div><ul class=\"examples\"><li><em>The Olympic medallist’s time in the 200 metres final was 19.21 seconds.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>journey time</strong> the amount of time a journey takes:</div><ul class=\"examples\"><li><em>The journey time to London is approximately four hours.</em></li></ul><div class=\"sense\"><span class=\"snum\">46</span> <strong>[sports]</strong> <span class=\"gram\">[uncountable]</span> <em>British English</em> the end of the normal period of playing time in a sports game, especially football <em>SYN full time</em>:</div><ul class=\"examples\"><li><em>Mason’s goal 13 minutes from time earned his team a place in the finals.</em></li></ul><div class=\"sense\"><span class=\"snum\">47</span> <strong>[music]</strong> <span class=\"gram\">[uncountable]</span> the number of beats in each bar in a piece of music:</div><ul class=\"examples\"><li><em>Waltzes are usually in three-four time.</em></li></ul><div class=\"sense\"><span class=\"snum\">48</span> <strong>in time to/with something</strong> if you do something in time to a piece of music, you do it using the same rhythm and speed as the music:</div><ul class=\"examples\"><li><em>Gloria was tapping her feet in time to the music.</em></li></ul><div class=\"sense\"><span class=\"snum\">49</span> <strong>keep/beat time</strong> to show the rhythm and speed that a piece of music should be played at to a group of musicians, using your hands</div><div class=\"sense\"><span class=\"snum\">50</span> <strong>keep perfect/good etc time</strong> if a clock keeps good time, it always shows the correct time</div><div class=\"sense\"><span class=\"snum\">51</span> <strong>[prison]</strong> <strong>do time</strong> to spend a period of time in prison:</div><ul class=\"examples\"><li><em>Paul was doing time for burglary.</em></li></ul><div class=\"sense\"><span class=\"snum\">52</span> <strong>pass the time of day (with somebody)</strong> to say hello to someone and have a short talk with them:</div><ul class=\"examples\"><li><em>People like to pass the time of day with neighbours.</em></li></ul><div class=\"sense\"><span class=\"snum\">53</span> <strong>time was (when)</strong> used to say that there was a time when you used to be able to do something, when something used to happen etc:</div><ul class=\"examples\"><li><em>Time was when no one had television.</em></li></ul><div class=\"sense\"><span class=\"snum\">54</span> <strong>there’s no time to lose</strong> used to say that you must do something quickly because there is very little time</div><div class=\"sense\"><span class=\"snum\">55</span> <strong>make good time</strong> if you make good time on a journey, you travel quickly, especially more quickly than you expected:</div><ul class=\"examples\"><li><em>We made good time and were at the hotel by lunchtime.</em></li></ul><div class=\"sense\"><span class=\"snum\">56</span> <strong>race/work/battle against time</strong> to try to finish or achieve something even though you have very little time:</div><ul class=\"examples\"><li><em>Mark was racing against time to complete the work by Friday.</em></li></ul><div class=\"sense\"><span class=\"snum\">57</span> <strong>time is money</strong> used to say that wasting time or delaying something costs money</div><div class=\"sense\"><span class=\"snum\">58</span> <strong>time is on your side</strong> used to say that someone is young enough to be able to wait before doing something or until something happens</div><div class=\"sense\"><span class=\"snum\">59</span> <strong>time is a great healer/heals all wounds</strong> used to say that someone will become less upset as time passes</div><div class=\"sense\"><span class=\"snum\">60</span> <strong>time flies</strong> used to say that time seems to pass very quickly:</div><ul class=\"examples\"><li><em>Time flies when you’re having fun.</em></li></ul><div class=\"sense\"><span class=\"snum\">61</span> <strong>in your own time</strong> if you study or do work in your own time, you do it outside normal school or work hours:</div><ul class=\"examples\"><li><em>Nurses in training study in their own time.</em></li></ul><div class=\"sense\"><span class=\"snum\">62</span> <strong>in your own (good) time</strong> <em>informal</em> when you are ready:</div><ul class=\"examples\"><li><em>Bobby will tell them about it in his own good time.</em></li></ul><div class=\"sense\"><span class=\"snum\">63</span> <strong>all in good time</strong> used to tell someone to be patient because something they are waiting for will certainly happen after a period of time, and probably quite soon:</div><ul class=\"examples\"><li><em>‘I’d love to see it.’ ‘All in good time.’</em></li></ul><div class=\"sense\"><span class=\"snum\">64</span> <strong>have a lot of/no time for somebody/something</strong> <em>informal</em> if you have a lot of time for someone or something, you like or admire them, and if you have no time for them, you do not like or admire them:</div><ul class=\"examples\"><li><em>He has no time for (=does not like) people who talk too much.</em></li></ul><div class=\"sense\"><span class=\"snum\">65</span> <strong>time of life</strong> used to refer to someone’s age:</div><ul class=\"examples\"><li><em>At my time of life, you can’t take too many shocks like that.</em></li></ul><div class=\"sense\"><span class=\"snum\">66</span> <strong>your time</strong> used in certain expressions to refer to the period when you are alive</div><ul class=\"examples\"><li><strong><em>in your time</strong>: I’ve met some rude women in my time but she’s the worst. / He was many things in his time – musician, pilot, cattle-rancher, industrialist, journalist.</em></li><li><em>If I had my time over again (=lived my life again), I’d probably do exactly the same things.</em></li></ul><div class=\"sense\"><span class=\"snum\">67</span> <strong>time of the month</strong> the time when a woman has her period:</div><ul class=\"examples\"><li><em>It’s that time of the month.</em></li></ul><div class=\"sense\"><span class=\"snum\">68</span> <strong>time out of mind</strong> <em>literary</em> a very long time, or a very long time ago</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to arrange that something should happen at a particular time: GRAMMAR Time is often passive in this meaning.</div><ul class=\"examples\"><li><em>I saw from the station clock that I had timed my arrival perfectly.</em></li><li><strong><em>be timed to do something</strong>: The tour has been timed to allow visitors to attend the opening night of the Verona opera season. / Her book was timed to coincide with (=arranged to be at the same time as) an exhibition of Goya’s paintings at the National Gallery.</em></li><li><strong><em>be timed for something</strong>: The meeting has been timed for three o&#x27;clock.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to measure how fast someone or something is going, how long it takes to do something etc:</div><ul class=\"examples\"><li><em>We had to run up the stairs while the Sergeant timed us.</em></li><li><strong><em>time somebody/something at something</strong>: They timed the winner at 2 minutes and 14.05 seconds.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to hit a ball or make a shot at a particular moment → mistime</div><ul class=\"examples\"><li><strong><em>time something well/badly etc</strong>: Keith timed the pass well. / a beautifully timed shot</em></li></ul></div></div>","7056":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈtime-conˌsuming</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">taking a long time to do:</div><ul class=\"examples\"><li><em>a complex and time-consuming process</em></li></ul></div>","7057":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> time‧less</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪmləs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> remaining attractive and not becoming old-fashioned:</div><ul class=\"examples\"><li><em>the timeless beauty of Venice</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>literary</em> continuing for ever:</div><ul class=\"examples\"><li><em>the timeless universe</em></li></ul></div>","7058":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> time‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪmli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">done or happening at exactly the right time:</div><ul class=\"examples\"><li><em>The fight ended only with the timely arrival of the police.</em></li><li><strong><em>in a timely manner/fashion</strong> (=as quickly as is reasonable in a particular situation): We aim to settle all valid claims in a timely manner.</em></li><li><strong><em>a timely reminder (of something)<em>British English</em></strong> (=one that makes you remember something important): The crash served as a timely reminder of the dangers of drinking and driving.</em></li></ul></div>","7059":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> time‧scale</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪmskeɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the period of time it takes for something to happen or be completed:</div><ul class=\"examples\"><li><em>The timescale for completing the work would be fairly tight.</em></li></ul></div>","7060":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> time‧ta‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪmˌteɪbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a list of the times at which buses, trains, planes etc arrive and leave SYN schedule<em>American English</em></div><ul class=\"examples\"><li><strong><em>a railway/train/bus timetable</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a list of the times of classes in a school, college etc SYN schedule<em>American English</em></div><div class=\"sense\"><span class=\"snum\">3</span> a plan of events and activities, with their dates and times <em>SYN schedule</em></div><ul class=\"examples\"><li><strong><em>timetable for</strong>: The Council has set out a timetable for returning to civilian rule.</em></li></ul></div>","7061":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tim‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪmɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the skill of doing something at exactly the right time</div><ul class=\"examples\"><li><strong><em>perfect/good/bad etc timing</strong>: He was just walking into the restaurant when we got there. Perfect timing.</em></li><li><em>He told jokes with an exquisite sense of timing.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the time when someone does something or when something happens, especially when you are considering how suitable this is</div><ul class=\"examples\"><li><strong><em>timing of</strong>: The president and I did not discuss the timing of my departure.</em></li><li><em>Ferry schedules and precise timings are subject to weather conditions on the day of departure.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the way in which electricity is sent to the spark plugs in a car engine</div></div>","7062":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a soft silver-white metal that is often used to cover and protect iron and steel. It is a chemical element: symbol Sn:</div><ul class=\"examples\"><li><em>an old tin bath</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>British English</em> (also tin can) a small metal container in which food or drink is sold SYN can<em>American English</em>:</div><ul class=\"examples\"><li><em>a sardine tin</em></li><li><strong><em>tin of</strong>: a tin of baked beans</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a metal container with a lid in which food can be stored:</div><ul class=\"examples\"><li><em>a biscuit tin</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>British English</em> a metal container in which food is cooked SYN pan<em>American English</em>:</div><ul class=\"examples\"><li><em>a 7-inch cake tin</em></li><li><em>a roasting tin</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> <em>British English</em> a metal container with a lid, in which paint, glue etc is sold</div><ul class=\"examples\"><li><strong><em>tin of</strong>: a tin of brown paint</em></li></ul></div>","7063":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ti‧ny</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(comparative tinier, superlative tiniest)</span></div><div class=\"entry-body\"><div class=\"sense\">extremely small: ► see thesaurus at small</div><ul class=\"examples\"><li><em>a tiny community in the Midwest</em></li><li><em>The earrings were tiny.</em></li><li><em>a tiny little baby</em></li><li><em>She always felt a tiny bit sad.</em></li><li><em>Bad teachers are a tiny minority.</em></li><li><em>tiny pieces of paper</em></li></ul></div>","7064":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[end]</strong> <span class=\"gram\">[countable]</span> the end of something, especially something pointed → fingertip(1)</div><ul class=\"examples\"><li><strong><em>tip of</strong>: He kissed the tip of her nose. / the southern tip of South America</em></li><li><em>lights on the wing tips of aeroplanes</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[money]</strong> <span class=\"gram\">[countable]</span> a small amount of additional money that you give to someone such as a waiter or a taxi driver:</div><ul class=\"examples\"><li><em>Did you leave a tip?</em></li><li><strong><em>large/generous/big tip</strong>: I gave the guy a big tip.</em></li><li><em>a $5 tip</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[advice]</strong> <span class=\"gram\">[countable]</span> a helpful piece of advice:</div><ul class=\"examples\"><li><em>Perhaps she could give us a few tips.</em></li><li><strong><em>tip on/for</strong>: This week&#x27;s magazine has some tips on healthy eating.</em></li><li><strong><em>handy tip</strong> (=useful tip): handy tips for decorating a small flat</em></li><li><em>gardening tips</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the tip of the iceberg</strong> a small sign of a problem that is much larger:</div><ul class=\"examples\"><li><em>The reported cases of food poisoning are only the tip of the iceberg.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>on the tip of your tongue</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if something is on the tip of your tongue, you really want to say it, but then you decide not to:</div><ul class=\"examples\"><li><em>It was on the tip of my tongue to say, ‘I’d rather have dinner with a snake.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a word, name etc is on the tip of your tongue, you know it but cannot remember it:</div><ul class=\"examples\"><li><em>What is her name? It’s on the tip of my tongue. Joan. Joan Simpson. That’s it!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[waste]</strong> <span class=\"gram\">[countable]</span> <em>British English</em> an area where unwanted waste is taken and left <em>SYN dump</em>:</div><ul class=\"examples\"><li><em>a rubbish tip</em></li><li><em>I’ll take this lot to the tip.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[untidy]</strong> <span class=\"gram\">[singular]</span> <em>British English</em> <em>informal</em> an extremely dirty or untidy place:</div><ul class=\"examples\"><li><em>The house was an absolute tip.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[horse race]</strong> <span class=\"gram\">[countable]</span> <em>informal</em> special information about which horse will win a race</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[warning]</strong> <span class=\"gram\">[countable]</span> a secret warning or piece of information, especially to police about illegal activities:</div><ul class=\"examples\"><li><em>Acting on a tip, the police were able to find and arrest Upton.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\">(past tense and past participle tipped, present participle tipping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[lean]</strong> <span class=\"gram\">[intransitive, transitive]</span> to move into a sloping position, so that one end or side is higher than the other, or to make something do this <em>SYN tilt</em></div><ul class=\"examples\"><li><strong><em>tip forward/back/to etc</strong>: His helmet had tipped forward and the boy pushed it back. / Eric fell asleep, his head gently tipping to one side.</em></li><li><strong><em>tip something forward/back etc</strong>: ‘So what?’ asked Brian, tipping his chair back on its rear legs.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[pour]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to pour something from one place or container into another</div><ul class=\"examples\"><li><strong><em>tip something onto/into something</strong>: Tip the onions and oil into a large ovenproof dish. / Ben tipped the contents of the drawer onto the table.</em></li><li><strong><em>tip something out</strong>: Shall I tip the water out?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[give money]</strong> <span class=\"gram\">[intransitive, transitive]</span> to give an additional amount of money to someone such as a waiter or taxi driver:</div><ul class=\"examples\"><li><em>Did you tip the waiter?</em></li><li><strong><em>tip somebody something</strong>: I tipped him $5.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[be likely to succeed]</strong> <span class=\"gram\">[transitive]</span> if someone or something is tipped to do something, people think that they are most likely to succeed in doing it GRAMMAR Tip is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be tipped to do something</strong>: the man tipped to become the next president</em></li><li><strong><em>be tipped for/as something</strong>: He’s tipped as a future world champion.</em></li><li><strong><em>widely/strongly/hotly tipped</strong>: He had been widely tipped to get the new post of deputy director.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>gold-tipped/steel-tipped/rubber-tipped etc</strong> having a tip that is made of or covered with gold, steel etc:</div><ul class=\"examples\"><li><em>a silver-tipped walking stick</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>tip the balance/scales</strong> to give a slight advantage to someone or something:</div><ul class=\"examples\"><li><em>Three factors helped to tip the balance in favour of the Labour leadership.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>tip the scales at something</strong> to weigh a particular amount, used especially of someone who will be taking part in a sports competition:</div><ul class=\"examples\"><li><em>At today’s weigh-in he tipped the scales at just over 15 stone.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>it’s tipping (it) down</strong> <em>British English</em> <em>spoken</em> said when it is raining very heavily:</div><ul class=\"examples\"><li><em>It was absolutely tipping it down.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>be tipped with something</strong> to have one end covered in something:</div><ul class=\"examples\"><li><em>arrows tipped with poison</em></li><li><em>red petals tipped with white</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>tip your hat/cap (to somebody)</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to touch or raise your hat as a greeting to someone</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>American English</em> to say or do something that shows you admire what someone has done</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>tip somebody the wink</strong> <em>British English</em> <em>informal</em> to give someone secret information</div></div></div>","7065":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tip‧toe</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɪptəʊ $ -toʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>on tiptoe/on (your) tiptoes</strong> if you stand or walk on tiptoe, you stand or walk on your toes, in order to make yourself taller or in order to walk very quietly:</div><ul class=\"examples\"><li><em>She stood on tiptoe to kiss him.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive always + adverb/preposition]</span></span><span class=\"meta-item\">(past tense and past participle tiptoed, present participle tiptoeing)</span></div><div class=\"entry-body\"><div class=\"sense\">to walk quietly and carefully on your toes, so that nobody hears you: ► see thesaurus at walk</div><ul class=\"examples\"><li><em>His mother tiptoed into the room.</em></li><li><em>I tiptoed along the corridor.</em></li></ul></div></div>","7066":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taɪə $ taɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[intransitive, transitive]</span> to start to feel tired, or make someone feel tired: RegisterIn everyday English, people usually say get tired rather than tire:· The climbers were starting to get tired.</div><ul class=\"examples\"><li><em>As we neared the summit, we were tiring fast.</em></li></ul></div>","7067":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taɪəd $ taɪrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> feeling that you want to sleep or rest</div><ul class=\"examples\"><li><strong><em>so tired (that)</strong>: I’m so tired I could sleep for a week.</em></li><li><strong><em>too tired to do something</strong>: He was too tired to argue.</em></li><li><em>He looks tired out (=very tired).</em></li><li><em>‘No,’ Frank said in a tired voice.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>tired of (doing) something</strong> bored with something, because it is no longer interesting, or has become annoying:</div><ul class=\"examples\"><li><em>I’m tired of watching television; let’s go for a walk.</em></li><li><em>I was getting tired of all her negative remarks.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> familiar and boring <em>OPP fresh</em>:</div><ul class=\"examples\"><li><em>tired old speeches</em></li></ul></div>","7068":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tire‧some</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪəsəm $ ˈtaɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">making you feel annoyed or impatient: ► Do not confuse with tiring (=making you feel tired): It was a long, tiring day.</div><ul class=\"examples\"><li><em>the whole tiresome business of filling out the forms</em></li></ul></div>","7069":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tir‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪərɪŋ $ ˈtaɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\">making you feel that you want to sleep or rest:</div><ul class=\"examples\"><li><em>We’ve all had a long tiring day.</em></li></ul></div>","7070":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tis‧sue</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɪʃuː, -sjuː $ -ʃuː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a piece of soft thin paper, used especially for blowing your nose on:</div><ul class=\"examples\"><li><em>a box of tissues</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> (also tissue paper) light thin paper used for wrapping, packing etc</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the material forming animal or plant cells</div><ul class=\"examples\"><li><strong><em>lung/brain etc tissue</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a tissue of lies</strong> <em>British English</em> a story or account that is completely untrue</div></div>","7071":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ti‧tle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪtl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the name given to a particular book, painting, play etc RegisterIn everyday English, people usually say that something is called..., rather than saying its title is...: The play&#x27;s title is &#x27;Blasted&#x27;. ➔ The play is called &#x27;Blasted&#x27;.</div><ul class=\"examples\"><li><strong><em>title of</strong>: The title of this play is ‘Othello’.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a book:</div><ul class=\"examples\"><li><em>the UK’s 20 best-selling titles</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a name such as ‘Sir’ or ‘Professor’, or abbreviations such as ‘Mrs’ or ‘Dr’, that are used before someone’s name to show their rank or profession, whether they are married etc</div><div class=\"subsense\"><span class=\"subnum\">b)</span> a name that describes someone’s job or position:</div><ul class=\"examples\"><li><em>Her official title is editor.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> the position of being the winner of an important sports competition:</div><ul class=\"examples\"><li><em>Tyson won the WBA title in 1987.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[singular, uncountable]</span> <em>law</em> the legal right to have or own something</div><ul class=\"examples\"><li><strong><em>title to</strong>: He has title to the land.</em></li></ul></div>","7072":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ti‧tled</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪtld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">having a title in the aristocracy, such as ‘lord’, duke, earl etc</div></div>","7073":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">entry</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tə; before vowels tʊ; strong tuː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[used before the basic form of a verb to show that it is in the infinitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> used after a verb, noun, or adjective when an infinitive completes its meaning:</div><ul class=\"examples\"><li><em>We tried to explain.</em></li><li><em>It was starting to rain.</em></li><li><em>The manager asked them to leave.</em></li><li><em>an attempt to escape</em></li><li><em>Have you got permission to stay here?</em></li><li><em>Our team’s certain to win.</em></li><li><em>Are you ready to start?</em></li><li><em>This delicious dessert is easy to make (=you can make it easily).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used by itself instead of an infinitive in order to avoid repeating the same verb:</div><ul class=\"examples\"><li><em>You can drive today if you want to (=if you want to drive).</em></li><li><em>I could have helped, but nobody asked me to.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used after a word such as ‘how’, ‘where’, ‘who’, ‘what’, or ‘whether’ to refer to an action about which someone is not certain:</div><ul class=\"examples\"><li><em>I know where to go but I don’t know how to get there.</em></li><li><em>She wondered whether or not to trust him.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to show a purpose or intention: RegisterIn written English, people often use in order to rather than just to when expressing a purpose or intention, because it sounds more formal:· Investment has been increased in order to improve the transport system.</div><ul class=\"examples\"><li><em>They left early to catch the 7.30 train.</em></li><li><em>To find out more about university courses, write to this address.</em></li><li><em>We need more money to improve transport in London.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to refer to an action or state, when describing it:</div><ul class=\"examples\"><li><em>It’s nice to be wanted.</em></li><li><em>He’s finding it hard to cope.</em></li><li><em>To say I am disappointed is an understatement.</em></li><li><em>The simplest solution would be to increase the price.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to say what can or cannot be done, or what should be done:</div><ul class=\"examples\"><li><em>You’ll soon be old enough to vote in elections.</em></li><li><em>He did not have the energy to resist.</em></li><li><em>I’m too tired to go out tonight.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used after the verb ‘be’ to give an order or to state arrangements for the future:</div><ul class=\"examples\"><li><em>You are to wait here until I return.</em></li><li><em>They are to be married on May 25th.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used to say what someone discovers or experiences when they do something:</div><ul class=\"examples\"><li><em>He arrived there to find that the last train had already left.</em></li><li><em>The princess stepped ashore to be greeted by an enthusiastic crowd of admirers.</em></li><li><em>She woke to see Ben standing by the window.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> used to say what your attitude or purpose is in saying something:</div><ul class=\"examples\"><li><em>I’ve never heard of him, to be quite honest.</em></li><li><em>To begin with, let’s look at Chapter 3.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to say where someone or something goes:</div><ul class=\"examples\"><li><em>She stood up and walked to the window.</em></li><li><em>the road to London</em></li><li><em>our weekly trip to the supermarket</em></li><li><em>sending a spaceship to Mars</em></li><li><em>These people go from house to house selling goods (=visit many different houses).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say who receives something or is told or shown something:</div><ul class=\"examples\"><li><em>He sent presents to the children.</em></li><li><em>She whispered something to the girl beside her.</em></li><li><em>Give my best wishes to your parents when you see them.</em></li><li><em>Don’t show these letters to anyone else.</em></li><li><em>a message from the Emperor to his people</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to show in which direction something is in relation to something else:</div><ul class=\"examples\"><li><em>Knutsford is about 16 miles to the south of Manchester.</em></li><li><em>There was a table to the left of the doorway.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to show the purpose, event, or activity for which you go somewhere:</div><ul class=\"examples\"><li><em>Sophie goes to gymnastics every Friday.</em></li><li><em>Did you get an invitation to their wedding?</em></li><li><em>Don’t forget, we’re going to a party tomorrow night.</em></li><li><em>If he needed help, Mother came rushing to the rescue.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to say what state someone or something is in as a result of an action or change:</div><ul class=\"examples\"><li><em>She sang the baby to sleep.</em></li><li><em>Wait until the lights change to green.</em></li><li><em>a return to a traditional way of life</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to say that one thing is touching another:</div><ul class=\"examples\"><li><em>He held a knife to her throat.</em></li><li><em>They danced cheek to cheek.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used to say where something is fastened or connected:</div><ul class=\"examples\"><li><em>He tied the rope to a tree.</em></li><li><em>Attach a recent photograph to your application form.</em></li><li><em>Cash machines are linked up to a central computer.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> facing something or in front of it:</div><ul class=\"examples\"><li><em>I sat with my back to the window.</em></li><li><em>We were standing face to face.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> used to show a relationship with someone or something:</div><ul class=\"examples\"><li><em>George’s sister was married to an Italian.</em></li><li><em>He was first cousin to King Philip VI.</em></li><li><em>The robbery may be linked to other crimes of violence.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> as far as a particular point or limit:</div><ul class=\"examples\"><li><em>She can already count from one to twenty.</em></li><li><em>The water came right up to our knees.</em></li><li><em>Temperatures dropped to 25 degrees below zero.</em></li><li><em>It’s ten kilometres from here to the coast.</em></li><li><em>She read the novel from beginning to end.</em></li><li><em>Does your interest in nuclear physics extend to nuclear weaponry?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> until and including a particular time or date:</div><ul class=\"examples\"><li><em>They stayed from Friday night to Sunday morning.</em></li><li><em>I’ll be on duty from 8 am to 10 pm.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> used to say what or who an action, attitude, situation etc affects or is related to:</div><ul class=\"examples\"><li><em>The factory clearly represents a danger to health.</em></li><li><em>She’s always been kind to animals.</em></li><li><em>his attitude to life</em></li><li><em>What have you done to the radio? It’s not working.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> used to say who someone works for:</div><ul class=\"examples\"><li><em>Jane is secretary to the managing director.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> used to say what something is needed for:</div><ul class=\"examples\"><li><em>I’m still waiting for an answer to my question.</em></li><li><em>Have you seen the key to the back door?</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> used when comparing two things, numbers etc:</div><ul class=\"examples\"><li><em>England beat Scotland by two goals to one.</em></li><li><em>Yes, she was punished, but it was nothing to what she deserved.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> used to say who has a particular attitude or opinion about something:</div><ul class=\"examples\"><li><em>The whole thing sounds very suspicious to me.</em></li><li><em>Tickets cost £10 each and to some people that’s a lot of money.</em></li><li><em>To my mind, age does not matter; love is what matters.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> used to say what someone’s reaction is when something happens:</div><ul class=\"examples\"><li><em>Much to everyone’s surprise she passed the exam with distinction.</em></li><li><em>I discovered to my horror that my passport was missing.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> used when saying how much time there is before a particular event or time:</div><ul class=\"examples\"><li><em>It’s only two weeks to Christmas.</em></li><li><em>How long is it to dinner?</em></li><li><strong><em>ten to five/twenty to one etc</strong> (=ten minutes, twenty minutes etc before a particular hour)</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> used when talking about a rate or quantity to say how many smaller units equal a larger unit:</div><ul class=\"examples\"><li><em>We’re only getting 130 yen to the dollar at the moment.</em></li><li><em>There are just over four and a half litres to a gallon.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to show the relationship between two different measurements or quantities:</div><ul class=\"examples\"><li><em>The car will do over 40 miles to the gallon.</em></li><li><em>The scale of your map is one inch to the mile.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> used to say that a particular sound is heard at the same time as something happens:</div><ul class=\"examples\"><li><em>I woke to the sound of torrential rain.</em></li><li><em>The royal couple arrived to a fanfare of trumpets.</em></li><li><em>I like to exercise to music.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> used between two numbers when you do not know exactly what the real number or amount is:</div><ul class=\"examples\"><li><em>There must have been eighteen to twenty thousand people at the concert.</em></li><li><em>He drowned in 10 to 12 feet of water.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>(all) to yourself</strong> if you have something or someone to yourself, you do not have to share them with other people:</div><ul class=\"examples\"><li><em>It was the first time I’d had a room to myself.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> used to say what the chances of something happening are:</div><ul class=\"examples\"><li><em>I’ll bet you ten to one he’ll forget all about it.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tuː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">if a door is pushed to, it closes or almost closes:</div><ul class=\"examples\"><li><em>The wind blew the door to.</em></li></ul></div></div>","7074":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /təʊst $ toʊst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> bread that has been heated so that it is brown on both sides and no longer soft:</div><ul class=\"examples\"><li><em>I had a piece of toast for breakfast.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> if you drink a toast to someone, you drink something in order to thank them, wish them luck etc: ► see thesaurus at drink</div><ul class=\"examples\"><li><em>I’d like to propose a toast (=ask people to drink a toast) to the bride and groom.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be the toast of Broadway/Hollywood etc</strong> to be very popular and praised by many people for something you have done in a particular field of work</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>warm as toast</strong> <em>British English</em> very warm and comfortable:</div><ul class=\"examples\"><li><em>They sat near the fire, warm as toast.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be toast</strong> <em>informal</em> to be in trouble because of something you have done:</div><ul class=\"examples\"><li><em>If you challenge her, you’re toast.</em></li></ul></div>","7075":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> toast‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtəʊstə $ ˈtoʊstər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a machine you use for toasting bread</div></div>","7076":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> to‧bac‧co</span><span class=\"meta-item\"><strong>IPA:</strong> /təˈbækəʊ $ -koʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the dried brown leaves that are smoked in cigarettes, pipes etc</div><div class=\"sense\"><span class=\"snum\">2</span> the plant that produces these leaves</div></div>","7077":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> to‧day</span><span class=\"meta-item\"><strong>IPA:</strong> /təˈdeɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> on the day that is happening now → yesterday, tomorrow:</div><ul class=\"examples\"><li><em>I couldn’t go shopping yesterday so I’ll have to go today.</em></li><li><em>Ed has his music lesson today.</em></li><li><strong><em>a week from today<strong> (also</strong>today week/a week today<em>)British English</em></strong>: We’re going on holiday today week.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> at the present time:</div><ul class=\"examples\"><li><em>Students today seem to know very little about geography.</em></li></ul></div>","7078":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tod‧dler</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɒdlə $ ˈtɑːdlər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a very young child who is just learning to walk ► see thesaurus at baby</div></div>","7079":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /təʊ $ toʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of the five movable parts at the end of your foot → finger:</div><ul class=\"examples\"><li><em>He stubbed his toe (=hurt it by kicking it against something) on a rock.</em></li><li><strong><em>big toe</strong> (=the largest of your toes)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the part of a shoe or sock that covers the front part of your foot</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>tread on somebody’s toes</strong> <em>British English</em>, step on somebody’s toes <em>American English</em> to offend someone, especially by becoming involved in something that they are responsible for</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>keep somebody on their toes</strong> to make sure that someone is ready for anything that might happen:</div><ul class=\"examples\"><li><em>They do random checks to keep workers on their toes.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>make somebody’s toes curl</strong> to make someone feel very embarrassed or uncomfortable</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>touch your toes</strong> to bend downwards so that your hands touch your toes, without bending your knees</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>put/dip a toe in the water</strong> to try a little of something or try an activity for a short time to see if you like it</div></div>","7080":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> toe‧nail</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtəʊneɪl $ ˈtoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the hard part that covers the top of each of your toes</div></div>","7081":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> to‧geth‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /təˈɡeðə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[with each other]</strong> if two or more people do something together, they do it with each other <em>OPP alone</em> <em>, separately</em>:</div><ul class=\"examples\"><li><em>We’ve very much enjoyed working together.</em></li><li><em>They’ve decided to spend more time together.</em></li><li><em>He and my father were at school together.</em></li><li><em>Together they went back inside the villa.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[make one thing]</strong> if you put two or more things together, you join them so that they touch or form one whole thing or group <em>OPP apart</em>:</div><ul class=\"examples\"><li><em>He’d tried to glue the broken pieces together.</em></li><li><em>Mix the butter and sugar together.</em></li><li><em>She clasped her hands together.</em></li><li><em>He took the engine apart and then put it back together again.</em></li><li><em>The model was held together with string.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[be a couple]</strong> if two people are together, they are married, or are having a romantic or sexual relationship:</div><ul class=\"examples\"><li><em>Mark and I have been together eight years now.</em></li><li><em>Are those two together?</em></li><li><em>A lot of people live together before getting married.</em></li><li><em>Sometimes I don’t know what keeps us together.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[in one place]</strong> if you keep, collect etc things together, you keep or collect them all in one place:</div><ul class=\"examples\"><li><em>She keeps all the important documents together in one file.</em></li><li><em>Embarrassed, she gathered her things together and left.</em></li><li><em>Goods of a similar kind should be stored together.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>close/packed/crowded etc together</strong> if people or objects are close together, packed together etc, they are placed very near to each other:</div><ul class=\"examples\"><li><em>The trees had been planted a little too close together.</em></li><li><em>The climbers were sitting huddled together for warmth.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[against each other]</strong> if you rub or hit things together, you rub or hit them against each other:</div><ul class=\"examples\"><li><em>Max was rubbing his hands together with glee.</em></li><li><em>Knock the brushes together to clean them.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[in agreement]</strong> if people are together, come together etc, they are or become united, especially in order to try and achieve something:</div><ul class=\"examples\"><li><em>Together we can win.</em></li><li><em>The Conference called on all good men to come together to resist socialism.</em></li><li><em>He said that the main purpose of the Baha&#x27;i faith was to bring people together.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[at the same time]</strong> at the same time:</div><ul class=\"examples\"><li><em>Both letters should have arrived. I mailed them together.</em></li><li><em>‘Oh!’ they said together.</em></li><li><strong><em>all together (now)</strong> (=used to tell a group of people to all say or do something at the same time): Right men. All together now... push!</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[combine amounts]</strong> when two amounts or quantities are added together, they are combined:</div><ul class=\"examples\"><li><em>Add these numbers together and then divide the total by 7.</em></li><li><em>Together they won only 21% of the votes.</em></li><li><em>The table and chairs are together worth about £200.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>together with something/somebody</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in addition to something else:</div><ul class=\"examples\"><li><em>Just bring it back to the store, together with your receipt.</em></li><li><em>Becoming self-employed meant giving up a secure salary, together with sick leave and long vacation time.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to mention someone else who is also involved in an activity or situation:</div><ul class=\"examples\"><li><em>He, together with Bill Dunn, decided to climb out of the canyon.</em></li></ul></div>","7082":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> toi‧let</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɔɪlɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a large bowl that you sit on to get rid of waste liquid or waste matter from your body:</div><ul class=\"examples\"><li><em>He flushed the toilet (=pulled the handle so that water ran into the toilet to clean it).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>British English</em> a room or building containing a toilet SYN bathroom, restroom<em>American English</em>:</div><ul class=\"examples\"><li><em>public toilets</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>go to the toilet</strong> <em>especially British English</em> to pass waste liquid or waste matter from your body:</div><ul class=\"examples\"><li><em>Mummy, I need to go to the toilet!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> <em>old-fashioned</em> the act of washing and dressing yourself:</div><ul class=\"examples\"><li><em>She finished her toilet.</em></li></ul></div>","7083":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈtoilet ˌpaper</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">soft thin paper used for cleaning yourself after you have used the toilet</div></div>","7084":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> to‧ken</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtəʊkən $ ˈtoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a round piece of metal that you use instead of money in some machines</div><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> something that represents a feeling, fact, event etc → by the same token at same1(8)</div><ul class=\"examples\"><li><strong><em>a token of your gratitude/respect/appreciation etc</strong>: Please accept this gift as a small token of our appreciation.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>book/record/gift token</strong> <em>British English</em> a special piece of paper that you can exchange for a book, record etc in a shop SYN gift certificate<em>American English</em>:</div><ul class=\"examples\"><li><em>a £10 book token</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a token action, change etc is small and not very important, and is usually only done so that someone can pretend that they are dealing with a problem:</div><ul class=\"examples\"><li><em>The government thinks it can get away with token gestures on environmental issues.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>token woman/black etc</strong> someone who is included in a group to make everyone think that the group has all types of people in it, when this is not really true</div><div class=\"sense\"><span class=\"snum\">3</span> done as a first sign that an agreement, promise etc will be kept and that more will be done later:</div><ul class=\"examples\"><li><em>A small token payment will keep the bank happy.</em></li></ul></div></div>","7085":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tol‧e‧rance</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɒlərəns $ ˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> willingness to allow people to do, say, or believe what they want without criticizing or punishing them <em>OPP intolerance</em> → tolerate</div><ul class=\"examples\"><li><strong><em>tolerance of/towards/for</strong>: tolerance towards religious minorities</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the degree to which someone can suffer pain, difficulty etc without being harmed or damaged → tolerate</div><ul class=\"examples\"><li><strong><em>tolerance to</strong>: Many old people have a very limited tolerance to cold.</em></li></ul></div>","7086":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tol‧e‧rant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɒlərənt $ ˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> allowing people to do, say, or believe what they want without criticizing or punishing them <em>OPP intolerant</em> → tolerate</div><ul class=\"examples\"><li><strong><em>tolerant of/towards</strong>: Luckily, my parents were tolerant of my choice of music.</em></li><li><em>a tolerant society</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> plants that are tolerant of particular weather or soil conditions can exist in those conditions</div><ul class=\"examples\"><li><strong><em>tolerant of</strong>: trees that are tolerant of salt sea winds</em></li></ul></div>","7087":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tol‧e‧rate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɒləreɪt $ ˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to allow people to do, say, or believe something without criticizing or punishing them → tolerant, tolerance:</div><ul class=\"examples\"><li><em>We simply will not tolerate vigilante groups on our streets.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to be able to accept something unpleasant or difficult, even though you do not like it → tolerant, tolerance <em>SYN stand</em> <em>, bear</em>: RegisterIn everyday English, people usually say stand rather than tolerate:· I don’t know how she can stand working there.</div><ul class=\"examples\"><li><em>I couldn’t tolerate the long hours.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if a plant tolerates particular weather or soil conditions, it can exist in them:</div><ul class=\"examples\"><li><em>plants that tolerate drought</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> if a person or their body can tolerate a food or other substance, it can use it without becoming ill:</div><ul class=\"examples\"><li><em>Women’s bodies can tolerate less alcohol than men’s.</em></li></ul></div>","7088":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /təʊl $ toʊl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually singular]</span> the number of people killed or injured in a particular accident, by a particular illness etc:</div><ul class=\"examples\"><li><em>The death toll has risen to 83.</em></li><li><em>The bombings took a heavy toll, killing hundreds of Londoners.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a very bad effect that something has on something or someone over a long period of time</div><ul class=\"examples\"><li><strong><em>toll on</strong>: Years of smoking have taken their toll on his health. / a heavy toll on the environment</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the money you have to pay to use a particular road, bridge etc ► see thesaurus at cost</div><div class=\"sense\"><span class=\"snum\">4</span> the sound of a large bell ringing slowly</div></div>","7089":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> to‧ma‧to</span><span class=\"meta-item\"><strong>IPA:</strong> /təˈmɑːtəʊ $ -ˈmeɪtoʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural tomatoes)</span></div><div class=\"entry-body\"><div class=\"sense\">a round soft red fruit eaten raw or cooked as a vegetable</div></div>","7090":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tuːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a stone structure above or below the ground where a dead person is buried:</div><ul class=\"examples\"><li><em>the family tomb</em></li></ul></div>","7091":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> to‧mor‧row</span><span class=\"meta-item\"><strong>IPA:</strong> /təˈmɒrəʊ $ -ˈmɔːroʊ, -ˈmɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\">on or during the day after today → yesterday, today:</div><ul class=\"examples\"><li><em>Our class is going to London tomorrow.</em></li><li><strong><em>a week from tomorrow<strong> (also</strong>a week tomorrow/tomorrow week<em>)British English</em></strong>: Terry’s new job starts a week tomorrow.</em></li><li><strong><em>tomorrow morning/night etc</strong>: We’re meeting tomorrow evening.</em></li></ul></div>","7092":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tʌn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (plural tons or ton) (written abbreviation t) a unit for measuring weight, equal to 2,240 pounds or 1,016 kilograms in Britain, and 2,000 pounds or 907.2 kilograms in the US → tonne</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>tons of something</strong> <em>informal</em> a lot of something:</div><ul class=\"examples\"><li><em>I’ve got tons of work to do.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>weigh a ton</strong> <em>informal</em> to be very heavy:</div><ul class=\"examples\"><li><em>Your bag weighs a ton!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>come down on somebody like a ton of bricks</strong> <em>informal</em> to get very angry with someone about something they have done</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>hit somebody like a ton of bricks</strong> <em>American English</em> <em>informal</em> to have a strong emotional effect on someone</div></div>","7093":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /təʊn $ toʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[voice]</strong> <span class=\"gram\">[countable]</span> the way your voice sounds, which shows how you are feeling or what you mean</div><ul class=\"examples\"><li><strong><em>in a... tone</strong>: ‘You must be Annie,’ he said in a friendly tone.</em></li><li><strong><em>in somebody’s tone</strong>: There was urgency in his tone.</em></li><li><em>Her tone was sharp with anger.</em></li><li><em>It was obvious from her tone of voice that she didn’t like me.</em></li><li><strong><em>don’t take that tone with me</strong> (=do not speak to me in that rude or unpleasant way)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[sound]</strong> <span class=\"gram\">[countable, uncountable]</span> the quality of a sound, especially the sound of a musical instrument or someone’s voice → pitch, timbre:</div><ul class=\"examples\"><li><em>the guitar’s clean tone</em></li><li><strong><em>in... tones</strong>: They talked in hushed tones.</em></li><li><em>‘No I didn’t,’ he said in a low tone (=quietly).</em></li><li><strong><em>deep-toned/even-toned/shrill-toned etc</strong> (=having a low, calm etc tone): an even-toned voice</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[general feeling/attitude]</strong> <span class=\"gram\">[singular, uncountable]</span> the general feeling or attitude expressed in a piece of writing, a speech, an activity etc</div><ul class=\"examples\"><li><strong><em>tone of</strong>: The tone of the report was radical.</em></li><li><em>The meetings were noted for their deeply religious tone.</em></li><li><strong><em>in tone</strong>: The article was moderate in tone.</em></li><li><strong><em>set the tone (for/of something)</strong> (=establish the general attitude or feeling of an event, activity etc): Opening remarks are important since they set the tone for the rest of the interview.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[colour]</strong> <span class=\"gram\">[countable, uncountable]</span> one of the many types of a particular colour, each slightly darker, lighter, brighter etc than the next <em>SYN shade</em> → tonal → two-tone ► see thesaurus at colour</div><ul class=\"examples\"><li><strong><em>tone of</strong>: different tones of green</em></li><li><em>Perhaps a darker tone would be better.</em></li><li><em>your skin tone (=the colour of your skin)</em></li><li><strong><em>in tone</strong>: The dried colour is slightly deeper in tone than it appears when first applied.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[electronic sound]</strong> <span class=\"gram\">[countable]</span> a sound made by electronic equipment, such as a telephone:</div><ul class=\"examples\"><li><em>Please leave a message after the tone.</em></li><li><strong><em>dialling tone<em>British English,</em></strong> <strong>dial tone</em>American English</strong><em> (=the sound you hear when you pick up the telephone that lets you know that you can make a call)</em></li><li><strong><em>engaged tone<em>British English,</em></strong> <strong>busy tone</em>American English</strong><em> (=the sound you hear when you telephone someone but they are already talking to someone else)</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>raise/lower the tone (of something)</strong> to make a place or event more or less socially acceptable, attractive etc:</div><ul class=\"examples\"><li><em>That horrible building lowers the whole tone of the neighborhood.</em></li><li><em>Trust you to lower the tone of the conversation (=by making rude remarks etc).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[body]</strong> <span class=\"gram\">[uncountable]</span> <em>technical</em> how firm and strong your muscles or skin are:</div><ul class=\"examples\"><li><em>A regular brisk walk will improve muscle tone.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[music]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> the difference in pitch between two musical notes that are separated by one key on the piano SYN step<em>American English</em></div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[voice level]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> how high or low your voice is when you produce different sounds:</div><ul class=\"examples\"><li><em>There is a falling tone on the first syllable and a rising tone on the other.</em></li></ul></div>","7094":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tʌŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[mouth]</strong> <span class=\"gram\">[countable]</span> the soft part inside your mouth that you can move about and use for eating and speaking:</div><ul class=\"examples\"><li><em>Joe ran his tongue over his dry lips.</em></li><li><em>The taste of the chocolate was still on her tongue.</em></li><li><em>The girl scowled at me, then stuck out her tongue.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>click your tongue</strong> to make a sharp noise with your tongue to show that you are annoyed or disappointed:</div><ul class=\"examples\"><li><em>She clicked her tongue and shook her head.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>sharp tongue</strong> if you have a sharp tongue, you often talk in a way that shows you are angry:</div><ul class=\"examples\"><li><em>Gina’s sharp tongue will get her into trouble one day.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>silver tongue</strong> <em>literary</em> if you have a silver tongue, you can talk in a way that makes people like you or persuades them that you are right</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>sharp-tongued/silver-tongued etc</strong> able to talk in a very angry or pleasant way:</div><ul class=\"examples\"><li><em>a sharp-tongued young teacher</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>with (your) tongue in (your) cheek</strong> if you say something with your tongue in your cheek, you say it as a joke, not seriously → tongue-in-cheek</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>slip of the tongue</strong> a small mistake in something you say:</div><ul class=\"examples\"><li><em>Did I say $100? It must have been a slip of the tongue.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>bite your tongue</strong> to stop yourself saying something because you know it would not be sensible to say it:</div><ul class=\"examples\"><li><em>I wanted to argue, but I had to bite my tongue.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>Cat got your tongue?</strong> (also Lost your tongue?) <em>spoken</em> used to ask someone why they are not talking</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>get your tongue around something</strong> <em>informal</em> to be able to say a difficult word or phrase:</div><ul class=\"examples\"><li><em>I couldn’t get my tongue around the names of the villages we’d visited.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>trip/roll off the tongue</strong> <em>informal</em> if a name or phrase trips or rolls off your tongue, it is easy or pleasant to say:</div><ul class=\"examples\"><li><em>Their names trip off the tongue very easily.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>loosen somebody’s tongue</strong> <em>informal</em> if something such as alcohol loosens your tongue, it makes you talk a lot:</div><ul class=\"examples\"><li><em>The wine had certainly loosened her tongue.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>find your tongue</strong> <em>informal</em> to say something after you have been silent for a time because you were afraid or shy:</div><ul class=\"examples\"><li><em>Polly found her tongue at last and told them about the attack.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>set tongues wagging</strong> to do something that people will talk about in an unkind way:</div><ul class=\"examples\"><li><em>Angela’s divorce will certainly set tongues wagging.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>keep a civil tongue in your head</strong> <em>old-fashioned</em> <em>spoken</em> used to tell someone that they should talk politely to people</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>speak with forked tongue</strong> to say things that are not true – used humorously</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>speak in tongues</strong> to talk using strange words as part of a religious experience</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>[language]</strong> <em>literary</em> a language:</div><ul class=\"examples\"><li><em>Anton lapsed into his own tongue when he was excited.</em></li><li><strong><em>mother/native tongue</strong> (=the language you learn as a child): She felt more comfortable talking in her native tongue.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>[food]</strong> <span class=\"gram\">[uncountable]</span> the tongue of a cow or sheep, cooked and eaten cold</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>[shape]</strong> <span class=\"gram\">[countable]</span> something that has a long thin shape</div><ul class=\"examples\"><li><strong><em>tongue of</strong>: Huge tongues of fire were licking the side of the building.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>[shoe]</strong> <span class=\"gram\">[countable]</span> the part of a shoe that lies on top of your foot, under the part where you tie it</div></div>","7095":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> to‧night</span><span class=\"meta-item\"><strong>IPA:</strong> /təˈnaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\">during the night of this day:</div><ul class=\"examples\"><li><em>I think I’ll go to bed early tonight.</em></li><li><em>We’re meeting him at 9 o&#x27;clock tonight.</em></li></ul></div>","7096":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tuː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[+adjective/adverb]</span> more than is acceptable or possible: GRAMMARWord orderThe correct word order is too + adjective + a + noun: · It is too high a price to pay.· It’s too big a risk. ✗Don’t say: It is a too high price to pay. | It’s a too big risk.Comparisontoo• You use too before an adjective. You say: · The house is too expensive.too much• You use too much before a noun. You say: · The house costs too much money.• Don’t use too much before an adjective. ✗Don’t say: The house is too much expensive.</div><ul class=\"examples\"><li><em>Do you think the music’s too loud?</em></li><li><em>You’ve put too much salt in the soup.</em></li><li><em>There are too many cars on the road.</em></li><li><strong><em>much/far too</strong>: Amanda is far too young to get married.</em></li><li><strong><em>too... for something/somebody</strong>: I was getting too old for romantic relationships. / My boots were three sizes too big for me.</em></li><li><strong><em>too... to do something</strong>: He was too ill to travel.</em></li><li><strong><em>too... for somebody to do something</strong>: The box was too heavy for me to lift.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> also: GRAMMAR: Word order• Too is usually used at the end of a sentence or clause: · He was a teacher too.• In more formal English, too is also used near the beginning of a sentence, after the subject, or after an adverb or phrase: · We too must play our part.· Here, too, there are problems with the economy.</div><ul class=\"examples\"><li><em>There were people from all over Europe, and America too.</em></li><li><em>Can I come too?</em></li><li><em>‘I’m feeling hungry.’ ‘Me too.’</em></li><li><em>It’s a more efficient system and it’s cheaper too.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[+adjective/adverb]</span> <em>spoken</em> used with a negative to mean ‘not very’:</div><ul class=\"examples\"><li><em>She doesn’t seem too upset about it.</em></li><li><em>‘What was the weather like?’ ‘Oh, not too bad.’</em></li><li><em>She was none too pleased (=not at all pleased) when I told her.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>all too/only too</strong> used to emphasize that a particular situation exists when you wish it did not exist:</div><ul class=\"examples\"><li><em>Beggars are becoming an all too familiar sight in our cities.</em></li><li><em>I regret to say that these rumours are only too true.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to emphasize a remark that you are adding:</div><ul class=\"examples\"><li><em>‘He’s been banned from driving.’ ‘A good thing too!’</em></li><li><em>‘A woman farmer?’ asked Gabriel. ‘Yes, and a rich one too.’</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>I am/he is/you are etc too!</strong> <em>especially American English</em> <em>informal</em> used to emphasize that you disagree with what someone has said about someone or something:</div><ul class=\"examples\"><li><em>‘You’re not smart enough to use a computer.’ ‘I am too!’</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be too much for somebody</strong> used to say that something is so difficult, tiring, upsetting etc that someone cannot do it or bear it:</div><ul class=\"examples\"><li><em>Working full-time was too much for her.</em></li><li><em>The shock was too much for him.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <span class=\"gram\">[+adjective/adverb]</span> <em>spoken</em> <em>formal</em> very:</div><ul class=\"examples\"><li><em>Thank you. You are too kind.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>be only too glad/pleased to do something</strong> to be very willing to do something:</div><ul class=\"examples\"><li><em>I’d be only too pleased to assist you.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>too little, too late</strong> used to complain that not enough is being done to solve a problem and that the action did not start early enough:</div><ul class=\"examples\"><li><em>Doctors have criticized the government’s response to the crisis as too little, too late.</em></li></ul></div>","7097":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tuːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that you hold in your hand and use to do a particular job:</div><ul class=\"examples\"><li><em>I don’t have the right tools to start fiddling around with the engine.</em></li><li><em>a shop selling garden tools</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a piece of equipment or a skill that is useful for doing your job:</div><ul class=\"examples\"><li><em>Television is an important tool for the modern teacher.</em></li><li><em>These books are the tools of my trade (=the things I need to do my job).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> someone who is used unfairly by another person and who has to do things they do not really want to do – used to show disapproval</div><ul class=\"examples\"><li><strong><em>tool of</strong>: The king was merely a tool of the military government.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>informal</em> <em>not polite</em> a man’s penis (=sex organ)</div></div>","7098":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tuːθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural teeth /tiːθ/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[in mouth]</strong> one of the hard white objects in your mouth that you use to bite and eat food: → baby tooth, → canine tooth at canine2(1), eye tooth(2), milk tooth, wisdom tooth, buck teeth, false teeth, gap-toothed</div><ul class=\"examples\"><li><em>Sugar is bad for your teeth.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[on a tool etc]</strong> one of the sharp or pointed parts that sticks out from the edge of a comb or saw</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[power]</strong> <strong>have teeth</strong> if a law or an organization has teeth, it has the power to force people to obey it:</div><ul class=\"examples\"><li><em>We need an Environment Agency that really has teeth.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>fight tooth and nail</strong> to try with a lot of effort or determination to do something:</div><ul class=\"examples\"><li><em>We fought tooth and nail to get these plans accepted.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>get your teeth into something</strong> <em>informal</em> to start to do something with a lot of energy and determination:</div><ul class=\"examples\"><li><em>I can’t wait to get my teeth into the new course.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>in the teeth of something</strong> in spite of opposition or danger from something:</div><ul class=\"examples\"><li><em>Permission for the development was granted in the teeth of opposition from local shopkeepers.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>set somebody’s teeth on edge</strong> if a sound or taste sets your teeth on edge, it gives you an uncomfortable feeling in your mouth:</div><ul class=\"examples\"><li><em>a horrible scraping sound that set my teeth on edge</em></li></ul></div>","7099":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tooth‧ache</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtuːθ-eɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a pain in a tooth:</div><ul class=\"examples\"><li><em>I’ve got toothache.</em></li><li><em>I had terrible toothache all last night.</em></li></ul></div>","7100":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tooth‧brush</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtuːθbrʌʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small brush that you use for cleaning your teeth</div></div>","7101":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tooth‧paste</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtuːθpeɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a thick substance that you use to clean your teeth</div></div>","7102":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɒp $ tɑːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[highest part]</strong> the highest part of something <em>OPP bottom</em></div><ul class=\"examples\"><li><strong><em>top of</strong>: The tops of the mountains were still covered with snow. / She could only just see over the tops of their heads.</em></li><li><strong><em>at the top (of something)</strong>: He was standing at the top of the stairs. / We’ll sit down once we’re at the top. / Write your name at the top of the page.</em></li><li><strong><em>to the top (of something)</strong>: Stop and wait for us when you get to the top of the slope. / I filled the glass right to the top.</em></li><li><em>The book I wanted was at the very top of the pile.</em></li><li><strong><em>cliff top/mountaintop/hilltop/treetop</strong>: We could just see the white cliff tops in the distance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[upper surface]</strong> the flat upper surface of an object:</div><ul class=\"examples\"><li><em>a low wooden table with a glass top</em></li><li><strong><em>top of</strong>: We walked along the top of the ancient city walls.</em></li><li><strong><em>on (the) top of something</strong>: She put the papers down on the top of the piano.</em></li><li><em>Her fingers drummed on the table top.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[best position]</strong> <strong>the top</strong> the best, most successful, or most important position in an organization, company, or profession <em>OPP bottom</em></div><ul class=\"examples\"><li><strong><em>top of</strong>: He has reached the top of his profession.</em></li><li><strong><em>at the top (of something)</strong>: It’s the people at the top who make the decisions.</em></li><li><strong><em>to the top (of something)</strong>: All young footballers dream of making it to the top.</em></li><li><em>the groups that are currently at the top of the tree (=the highest position in a profession) in the pop world</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[cover]</strong> something that you put on or over an object to cover it, protect it, or prevent liquid coming out of it:</div><ul class=\"examples\"><li><em>I can’t get the top off the jar.</em></li><li><em>You’ve left the top off the toothpaste again!</em></li><li><em>Can you put the top back on the bottle when you’ve finished with it?</em></li><li><strong><em>bottle top/pen top etc</strong>: Has anyone seen my pen top?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[clothes]</strong> a piece of clothing that you wear on the upper part of your body:</div><ul class=\"examples\"><li><em>She was wearing a stripy knitted top.</em></li><li><em>a skirt with a matching top</em></li><li><em>a bikini top</em></li><li><em>I can’t find my pyjama top.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be (at the) top of the list/agenda</strong> something that is at the top of a list will be dealt with or discussed first:</div><ul class=\"examples\"><li><em>Europe is once again at the top of the political agenda.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>on top</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> on the highest part or surface of something:</div><ul class=\"examples\"><li><em>The cake was a bit burnt on top.</em></li><li><em>a high roof with a chimney on top</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> on the highest part of your head:</div><ul class=\"examples\"><li><em>Can you cut it quite short on top, please.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> winning in a game or competition:</div><ul class=\"examples\"><li><em>After the first set, the Australian was comfortably on top.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>on top of something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> on the highest surface of something:</div><ul class=\"examples\"><li><em>There should be an envelope on top of the fridge.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> in complete control of a situation:</div><ul class=\"examples\"><li><em>Don’t worry; I’m back on top of things now.</em></li><li><em>I should be more on top of my work next week.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> if something bad happens to you on top of something else, it happens when you have other problems:</div><ul class=\"examples\"><li><em>On top of everything else, I now have to go to work next Saturday!</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>one on top of the other</strong> (also on top of one another) in a pile:</div><ul class=\"examples\"><li><em>We stacked the crates one on top of the other.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>on top of somebody</strong> if something dangerous or threatening is on top of you, it is very near you:</div><ul class=\"examples\"><li><em>The truck was almost on top of us.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>get on top of somebody</strong> if your work or a problem gets on top of you, it begins to make you feel unhappy and upset:</div><ul class=\"examples\"><li><em>Things are starting to get on top of him.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>come out on top</strong> to win a difficult struggle or argument, especially one that has continued for a long time:</div><ul class=\"examples\"><li><em>It’s difficult to predict who will come out on top.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>on top of the world</strong> <em>informal</em> extremely happy:</div><ul class=\"examples\"><li><em>When I heard she’d been released I felt on top of the world!</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[plant]</strong> the part of a fruit or vegetable where it was attached to the plant, or the leaves of a plant whose root you can eat:</div><ul class=\"examples\"><li><em>Cut the tops off the tomatoes.</em></li><li><em>I’ve found a recipe for beetroot tops.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[street/field etc]</strong> the part of the street or of a piece of land that is the furthest away from you:</div><ul class=\"examples\"><li><em>I waited at the top of East Street.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>the top of the milk</strong> <em>British English</em> the cream that rises to the top of a bottle of milk</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>the top of the table</strong> the part of a long dinner table where the most important people sit</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>off the top of your head</strong> <em>informal</em> if you say something off the top of your head, you say it immediately, without thinking carefully about it or checking the facts:</div><ul class=\"examples\"><li><em>Just off the top of my head, I’d say there were about 50.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>sing/shout at the top of your voice</strong> to sing or shout as loudly as you can:</div><ul class=\"examples\"><li><em>Angela ran out of the house, shouting at the top of her voice.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>be at the top of your game</strong> (also be on top of your game) to be doing your job, especially playing a sport, very well</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>from the top</strong> <em>spoken</em> an expression meaning from the beginning, used especially in the theatre:</div><ul class=\"examples\"><li><em>Right, let’s take it from the top once more.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>from top to bottom</strong> if you clean or search somewhere from top to bottom, you do it very thoroughly:</div><ul class=\"examples\"><li><em>The whole house needs cleaning from top to bottom.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>from top to toe</strong> if a person is dressed or covered in something from top to toe, they are completely dressed or covered in it:</div><ul class=\"examples\"><li><em>They were covered in mud from top to toe.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>the top and bottom of it</strong> <em>British English</em> <em>spoken</em> the general result or meaning of a situation, expressed in a few words:</div><ul class=\"examples\"><li><em>He’s trying to embarrass you, that’s the top and bottom of it.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>not have much up top</strong> <em>British English</em> <em>spoken</em> to be not very intelligent:</div><ul class=\"examples\"><li><em>Poor Nigel, he doesn’t have very much up top.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>[toy]</strong> a child’s toy that spins around on its point when you twist it</div><div class=\"sense\"><span class=\"snum\">27</span> <strong>spin like a top</strong> to spin or turn round very quickly: → tops</div><ul class=\"examples\"><li><em>The impact of the blow sent me spinning like a top.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[highest]</strong> <span class=\"gram\">[only before noun]</span> nearest to the top of something <em>OPP bottom</em>:</div><ul class=\"examples\"><li><em>We have a flat on the top floor of the building.</em></li><li><em>the top button of his shirt</em></li><li><em>I managed to scrape off the top layer of paint.</em></li><li><em>I found the letter in the top drawer of his desk.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[best]</strong> <span class=\"gram\">[usually before noun]</span> best or most successful:</div><ul class=\"examples\"><li><em>our top tennis players</em></li><li><em>a top New York salon</em></li><li><em>one of the world’s top engineering companies</em></li><li><em>people in top jobs</em></li><li><em>She got top marks.</em></li><li><em>The top score was 72.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[winning]</strong> winning in a game or competition</div><ul class=\"examples\"><li><strong><em>top of</strong>: Barcelona remain top of the league after beating Real Madrid.</em></li><li><em>Despite losing last night, Manchester United are still top (=the highest in a list of clubs in a competition).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>top left/right/centre</strong> expressions meaning the picture at the top of a page on the left or right or in the centre, used in magazines and newspapers:</div><ul class=\"examples\"><li><em>Top right: silk blouse £195 from Harrods.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>top speed</strong> the fastest speed a vehicle can move at:</div><ul class=\"examples\"><li><em>We tore down the motorway at top speed.</em></li><li><em>a sports car with a top speed of 140 miles per hour</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>top priority</strong> the thing that you think is most important:</div><ul class=\"examples\"><li><em>Education is this government’s top priority.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[good]</strong> <em>British English</em> <em>spoken</em> <em>informal</em> very good:</div><ul class=\"examples\"><li><em>Clive’s a top bloke.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>top copy</strong> <em>British English</em> a letter or document from which copies can be made</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle topped, present participle topping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[be higher]</strong> to be higher than a particular amount:</div><ul class=\"examples\"><li><em>Their profits have reportedly topped £1,000,000 this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[be most successful]</strong> to be in the highest position in a list because you are the most successful:</div><ul class=\"examples\"><li><em>The Tower of London tops the list of London’s most popular tourist attractions.</em></li><li><em>the team that has topped the Premiership for the last three seasons</em></li><li><em>In 1998 the group topped the charts with the song ‘Don’t Stop Loving Me’.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[do better]</strong> if you top something, you do something that is better than it:</div><ul class=\"examples\"><li><em>He topped his previous best performance, coming second in the 100 metres.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>top an offer/a bid etc</strong> to offer more money than someone else:</div><ul class=\"examples\"><li><em>A rival company topped our offer by $5 million.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be topped by something</strong> to have something on top:</div><ul class=\"examples\"><li><em>The roof was topped by a chimney.</em></li><li><em>a hill topped by pine trees</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be topped (off) with something</strong> if food is topped with something, it has that thing on it or over the top of it:</div><ul class=\"examples\"><li><em>a strawberry tart topped with whipped cream</em></li><li><em>The cake can be topped off with fresh fruit.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>to top it all</strong> <em>spoken</em> in addition to other bad things that have happened to you:</div><ul class=\"examples\"><li><em>To top it all I lost my job.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>top that</strong> <em>spoken</em> used when you are asking someone if they have done something more exciting or successful than you:</div><ul class=\"examples\"><li><em>Well, I’ve been asked to appear on a TV show later this year, so top that!</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>top and tail</strong> <em>British English</em> to cut the top and bottom off a piece of fruit or a vegetable</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>top yourself</strong> <em>British English</em> <em>informal</em> to kill yourself deliberately</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[reach the top]</strong> <em>literary</em> if you top a hill, you reach the top of it:</div><ul class=\"examples\"><li><em>We topped the hill and looked down towards the valley below us.</em></li></ul></div></div>","7103":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> top‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɒpɪk $ ˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a subject that people talk or write about:</div><ul class=\"examples\"><li><em>The environment is a popular topic these days.</em></li><li><strong><em>topic of</strong>: We shall return to the topic of education in Chapter 7.</em></li><li><strong><em>topic of conversation/debate etc</strong>: The wedding has been the only topic of conversation for weeks.</em></li><li><em>The main topic for discussion will be the proposed new supermarket.</em></li><li><em>a wide range of topics</em></li></ul></div>","7104":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> top‧ple</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɒpəl $ ˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to become unsteady and then fall over, or to make something do this</div><ul class=\"examples\"><li><strong><em>topple over</strong>: A stack of plates swayed, and began to topple over.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to take power away from a leader or government, especially by force <em>SYN overthrow</em>:</div><ul class=\"examples\"><li><em>This scandal could topple the government.</em></li></ul></div>","7105":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɔːtʃ $ tɔːrtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a small electric lamp that you carry in your hand SYN flashlight<em>American English</em>:</div><ul class=\"examples\"><li><em>We shone our torches around the cavern.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a long stick with burning material at one end that produces light:</div><ul class=\"examples\"><li><em>the Olympic torch</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>carry a torch for somebody</strong> <em>old-fashioned</em> to secretly love and admire someone</div></div>","7106":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tor‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɔːtʃə $ ˈtɔːrtʃər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an act of deliberately hurting someone in order to force them to tell you something, to punish them, or to be cruel:</div><ul class=\"examples\"><li><em>He died after five days of excruciating torture.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> severe physical or mental suffering:</div><ul class=\"examples\"><li><em>The waiting must be torture for you.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to deliberately hurt someone in order to force them to give you information, to punish them, or to be cruel:</div><ul class=\"examples\"><li><em>Political opponents of the regime may be tortured.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if a feeling or knowledge tortures you, it makes you suffer a lot mentally <em>SYN torment</em>:</div><ul class=\"examples\"><li><em>Rachel sat alone for hours at home, tortured by jealousy.</em></li></ul></div></div>","7107":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɒs $ tɒːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to throw something, especially something light, with a quick gentle movement of your hand ► see thesaurus at throw</div><ul class=\"examples\"><li><strong><em>toss something into/onto etc something</strong>: She crumpled the letter and tossed it into the fire.</em></li><li><strong><em>toss something aside/over etc</strong>: Toss that book over, will you?</em></li><li><strong><em>toss something to somebody</strong>: ‘Catch!’ said Sandra, tossing her bag to him.</em></li><li><strong><em>toss somebody something</strong>: Frank tossed her the newspaper.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to move about continuously in a violent or uncontrolled way, or to make something do this</div><ul class=\"examples\"><li><strong><em>toss something around/about</strong>: The small boat was tossed about like a cork.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>toss and turn</strong> to keep changing your position in bed because you cannot sleep:</div><ul class=\"examples\"><li><em>I’ve been tossing and turning all night.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive]</span> (also toss up) <em>especially British English</em> to throw a coin in the air, so that a decision will be made according to the side that faces upwards when it comes down SYN flip<em>American English</em>:</div><ul class=\"examples\"><li><em>They tossed a coin to decide who would go first.</em></li><li><strong><em>toss (somebody) for it</strong>: We couldn’t make up our minds, so we decided to toss for it.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[transitive]</span> to throw something up into the air and let it fall to the ground:</div><ul class=\"examples\"><li><em>The crowd cheered, banging pots and tossing confetti into the air.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>toss a pancake</strong> <em>British English</em> to throw a pancake upwards so that it turns over in the air and lands on the side that you want to cook SYN flip<em>American English</em></div><div class=\"sense\"><span class=\"snum\">7</span> <span class=\"gram\">[transitive]</span> to move pieces of food about in a small amount of liquid so that they become covered with the liquid:</div><ul class=\"examples\"><li><em>Toss the carrots in some butter before serving.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>toss your head/hair</strong> <em>written</em> to move your head or hair back suddenly, often with a shaking movement showing anger:</div><ul class=\"examples\"><li><em>He tossed his head angrily and left the room.</em></li></ul></div>","7108":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> to‧tal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtəʊtl $ ˈtoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually before noun]</span> complete, or as great as is possible</div><ul class=\"examples\"><li><strong><em>total failure/disaster</strong>: The sales campaign was a total disaster.</em></li><li><em>a total ban on cigarette advertising</em></li><li><em>He looked at her with a total lack of comprehension.</em></li><li><em>a sport that demands total commitment</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>total number/amount/cost etc</strong> the number, amount etc that is the total:</div><ul class=\"examples\"><li><em>total sales of 200,000 per year</em></li><li><em>Her total income was £10,000 a year.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the final number or amount of things, people etc when everything has been counted:</div><ul class=\"examples\"><li><em>That’s £7 and £3.50, so the total is £10.50.</em></li><li><strong><em>a total of 20/100 etc</strong>: A total of thirteen meetings were held to discuss the issue.</em></li><li><strong><em>in total</strong>: There were probably about 40 people there in total.</em></li><li><strong><em>the sum total</strong> (=the whole of an amount when everything is considered together)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>grand total</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the final total, including all the totals added together → subtotal</div><div class=\"subsense\"><span class=\"subnum\">b)</span> used humorously when you think the final total is small:</div><ul class=\"examples\"><li><em>I earned a grand total of $4.15.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle totalled, present participle totalling British English, totaled, totaling American English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[linking verb, transitive]</span> to reach a particular total: RegisterTotal is used especially in journalism. In everyday English, people usually say that something makes or adds up to a particular total:· Three and six make nine.</div><ul class=\"examples\"><li><em>The group had losses totalling $3 million this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>especially American English</em> <em>informal</em> to damage a car so badly that it cannot be repaired:</div><ul class=\"examples\"><li><em>Chuck totaled his dad’s new Toyota.</em></li></ul></div></div>","7109":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tot‧al‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtəʊtl-i $ ˈtoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[+adjective/adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\">completely:</div><ul class=\"examples\"><li><em>That’s a totally different matter.</em></li><li><em>It’s like learning a totally new language.</em></li><li><strong><em>totally unacceptable/unnecessary/unsuitable etc</strong>: Terrorism is totally unacceptable in a civilised world.</em></li><li><em>I totally agree.</em></li></ul></div>","7110":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tʌtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[feel]</strong> <span class=\"gram\">[transitive]</span> to put your hand, finger etc on someone or something:</div><ul class=\"examples\"><li><em>She reached out to touch his arm.</em></li><li><em>If your house has been burgled, you shouldn’t touch anything until the police arrive.</em></li><li><em>‘Don’t touch me!’ she yelled.</em></li><li><strong><em>touch somebody on the arm/leg etc</strong>: A hand touched her on the shoulder.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[no space between]</strong> <span class=\"gram\">[intransitive, transitive]</span> if two things touch, or one thing touches another thing, they reach each other so that there is no space between them: GRAMMAR: Reciprocal verbsTouch is a reciprocal verb. This type of verb is used when saying that two or more people or things do something that involves both or all of them. It does not need to have an object: · Their hands touched. In this sentence, touch is intransitive and does not have an object.You can also say: · Their hands touched each other.· His hand touched hers. In these sentences, touch is transitive.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><em>As our glasses touched, he said ‘Cheers!’</em></li><li><em>Her dress was so long that it was touching the ground.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>touch something to something</strong> <em>literary</em> to move something so that it reaches something else with no space between the two things:</div><ul class=\"examples\"><li><em>She touched the handkerchief to her nose.</em></li><li><em>He touched his lips to her hair.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[affect somebody’s feelings]</strong> <span class=\"gram\">[transitive]</span> to affect someone’s emotions, especially by making them feel sympathy or sadness: → touched, touching1</div><ul class=\"examples\"><li><em>Her plight has touched the hearts of people around the world.</em></li><li><em>She could sense his concern and it touched her.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[have an effect]</strong> <span class=\"gram\">[transitive]</span> to have an effect on someone or something, especially by changing or influencing them:</div><ul class=\"examples\"><li><em>He has touched the lives of many people.</em></li><li><em>Unemployment remains an evil that touches the whole community.</em></li><li><em>He was often touched by doubt (=doubt affected him).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[use]</strong> <span class=\"gram\">[transitive usually in negatives]</span> to use or handle something:</div><ul class=\"examples\"><li><em>The law doesn’t allow him to touch any of the money.</em></li><li><em>It’s a long time since I’ve touched a piano.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>not touch something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to not eat or drink something:</div><ul class=\"examples\"><li><em>What’s wrong? You’ve hardly touched your food.</em></li><li><em>My grandfather was an alcoholic but I never touch the stuff (=never drink alcohol).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to not deal with something that you should deal with:</div><ul class=\"examples\"><li><em>I brought home loads of work, but I haven’t touched any of it yet.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>not touch somebody/something</strong> to not hurt someone or not damage something:</div><ul class=\"examples\"><li><em>The older boys swore they hadn’t touched the child.</em></li><li><em>Parma had not been touched.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[deal with somebody/something]</strong> <span class=\"gram\">[transitive]</span> to become involved with or deal with a particular problem, situation, or person:</div><ul class=\"examples\"><li><em>He was the only lawyer who would touch the case.</em></li><li><em>Everything he touches turns to disaster.</em></li><li><em>No school would touch a teacher who had been convicted of assault.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[reach an amount]</strong> <span class=\"gram\">[transitive]</span> <em>especially British English</em> to reach a particular amount or level:</div><ul class=\"examples\"><li><em>At the time, the unemployment rate was touching 10 percent and rising.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[hit/kick]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> to gently hit or kick a ball – used especially in reports of sports games:</div><ul class=\"examples\"><li><em>Evans was just able to touch the ball away from Wilkinson.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>not touch something/somebody (with a bargepole)</strong> <em>British English</em>, not touch something/somebody with a ten-foot pole<em>American English</em> used to say that you think someone or something is bad and people should not be involved with them:</div><ul class=\"examples\"><li><em>I wouldn’t touch him with a bargepole.</em></li><li><em>Financial analysts have warned investors not to touch these offers with a ten-foot pole.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be touched with something</strong> <em>literary</em> to have a small amount of a particular quality:</div><ul class=\"examples\"><li><em>His voice was touched with the faintest of Italian accents.</em></li><li><em>Her nails had been manicured and lightly touched with colour.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[expression]</strong> <span class=\"gram\">[transitive]</span> if an expression such as a smile touches your face, your face has that expression for a short time:</div><ul class=\"examples\"><li><em>A smile touched her lips.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[relate to something]</strong> <span class=\"gram\">[transitive]</span> to be about or to deal with a particular subject, situation, or problem:</div><ul class=\"examples\"><li><em>Though the question touched a new vein, Nelson answered promptly.</em></li><li><em>The discourse touches many of the issues which are currently popular.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[light]</strong> <span class=\"gram\">[transitive]</span> <em>literary</em> if light touches something, it shines on it:</div><ul class=\"examples\"><li><em>The sun was just touching the tops of the mountains.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>nothing/no one can touch somebody/something</strong> used for saying that nothing or no one is as good as a particular person or thing:</div><ul class=\"examples\"><li><em>He describes the events with a passion that no other writer can touch.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>touch base (with somebody)</strong> to talk to someone in order to find out how they are or what is happening:</div><ul class=\"examples\"><li><em>I just wanted to touch base and make sure you hadn’t changed your mind about seeing me.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>touch bottom</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to reach the ground at the bottom of a sea, river etc:</div><ul class=\"examples\"><li><em>He swam down but could not touch bottom.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to reach the lowest level or worst condition:</div><ul class=\"examples\"><li><em>The housing market has touched bottom.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[touching somebody/something]</strong> <span class=\"gram\">[countable usually singular]</span> the action of putting your hand, finger, or another part of your body on something or someone:</div><ul class=\"examples\"><li><em>She felt a gentle touch on her shoulder.</em></li><li><strong><em>touch of</strong>: He remembered the touch of her fingers on his face.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[ability to feel things]</strong> <span class=\"gram\">[uncountable]</span> the sense that you use to discover what something feels like, by putting your hand or fingers on it:</div><ul class=\"examples\"><li><em>the sense of touch</em></li><li><strong><em>by touch</strong>: Visually impaired people orient themselves by touch.</em></li><li><em>Bake the cake for 30 minutes until risen and firm to the touch.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in touch (with somebody)</strong> talking or writing to someone: USAGE: In touch, in contact• If you stay/keep in touch or keep in contact with someone, you keep writing to them or calling them:· I hope you&#x27;ll keep in touch while you&#x27;re away.• If two things are in contact or come into contact, they touch each other: · Make sure that the two wires don&#x27;t come into contact. ✗Don’t say in touch in this meaning.</div><ul class=\"examples\"><li><em>We’ll get in touch (=start talking or writing to you) as soon as we know the results of the test.</em></li><li><em>Can I have your phone number in case I need to get in touch with you?</em></li><li><em>Bye. I’ll be in touch.</em></li><li><em>Are you still in touch with John (=are you talking to him regularly)?</em></li><li><em>I’m in close touch with Anna.</em></li><li><strong><em>stay/keep in touch</strong> (=keep writing or talking, even though you do not see each other often): Anyway, we must stay in touch. / I met him when I worked in Madrid, and I’ve kept in touch with him ever since.</em></li><li><em>I lost touch with (=stopped writing or talking to) Julie after we moved.</em></li><li><em>I can put you in touch with a local photography club (=give you their address or phone number so you can talk to them).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be/keep/stay etc in touch (with something)</strong> to have the latest information or knowledge about something:</div><ul class=\"examples\"><li><em>A regular newsletter keeps people in touch with local events.</em></li><li><em>The speech was good and you felt he was in touch with people’s needs.</em></li><li><em>Rescuers were kept in touch through radio links.</em></li><li><em>A head-teacher needs to remain in close touch with teachers’ everyday concerns.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be out of touch</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> (also lose touch (with something)) to not have the latest knowledge about a subject, situation, or the way people feel</div><ul class=\"examples\"><li><strong><em>touch with</strong>: I’m out of touch with modern medicine. / The party cannot afford to lose touch with political reality.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to not know much about modern life:</div><ul class=\"examples\"><li><em>Judges are often accused of being out of touch.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>get in touch with something</strong> <em>especially American English</em> to realize and understand something such as your feelings and attitudes:</div><ul class=\"examples\"><li><em>The first stage is to get in touch with your perceptions and accept responsibility for your relationships.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[detail/addition]</strong> <span class=\"gram\">[countable]</span> a small detail that improves or completes something</div><ul class=\"examples\"><li><strong><em>put the final/finishing touches to something</strong>: Emma was putting the finishing touches to the cake.</em></li><li><em>There was a vase of flowers in the room, which was a nice touch.</em></li><li><em>Brass pans added a decorative touch to the plain brick wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[way of doing something]</strong> <span class=\"gram\">[countable]</span> a particular way of doing something, or the ability to do it in a particular way:</div><ul class=\"examples\"><li><em>The room was decorated with a very artistic touch.</em></li><li><em>Our staff combine efficient service with a personal touch (=they do things in a friendly way).</em></li><li><em>The feminine touch was evident throughout the house.</em></li><li><em>His sure touch (=confident way of doing things) and attention to detail are just as evident now.</em></li><li><em>Barbara has a magic touch in the garden (=she grows things very well).</em></li><li><em>King obviously hasn’t lost his touch (=lost his ability) – his latest book sold in the millions.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>a touch of something</strong> a small amount of something:</div><ul class=\"examples\"><li><em>Our furniture is guaranteed to add a touch of class to your bedroom.</em></li><li><em>Add a lace top for a touch of glamour.</em></li><li><em>‘What?’ asked Hazel, with a touch of irritation.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>a touch disappointed/faster/impatient etc</strong> slightly disappointed, faster etc:</div><ul class=\"examples\"><li><em>He sounded a touch upset when I spoke to him on the phone.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>with/at the touch of a button/key</strong> used to emphasize that something can be done very easily by pressing a button:</div><ul class=\"examples\"><li><em>This card allows you to access your money at the touch of a button.</em></li><li><em>You can get all the latest information with the touch of a button.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>a soft/easy touch</strong> <em>informal</em> if someone is a soft or an easy touch, you can easily persuade them to do what you want, especially give you money</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>[way something feels]</strong> <span class=\"gram\">[countable usually singular]</span> the way that something feels and the effect it has on your skin:</div><ul class=\"examples\"><li><em>the warm touch of his lips</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[soccer/rugby]</strong> <span class=\"gram\">[uncountable]</span> the area outside the lines that mark the playing area</div><ul class=\"examples\"><li><strong><em>into touch</strong>: The ball rolled into touch.</em></li></ul></div></div>","7111":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> touch‧down</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtʌtʃdaʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the moment at which a plane or spacecraft lands</div><div class=\"sense\"><span class=\"snum\">2</span> an act of putting the ball down on the ground behind the opposing team’s goal line in rugby</div><div class=\"sense\"><span class=\"snum\">3</span> an act of moving the ball across the opposing team’s goal line in American football</div></div>","7112":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> touch‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtʌtʃɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">making you feel pity, sympathy, sadness etc:</div><ul class=\"examples\"><li><em>a touching reunion of father and son</em></li></ul></div>","7113":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tʌf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(comparative tougher, superlative toughest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[difficult]</strong> difficult to do or deal with: ► see thesaurus at difficult</div><ul class=\"examples\"><li><em>It was a tough race.</em></li><li><em>She’s had a tough life.</em></li><li><em>The company admitted that it had been a tough year.</em></li><li><em>Tough decisions will have to be made.</em></li><li><em>The reporters were asking a lot of tough questions.</em></li><li><strong><em>have a tough time (of it)</strong> (=face a lot of difficult problems): The family has had a tough time of it these last few months.</em></li><li><strong><em>it’s tough doing something</strong>: It’s tough being married to a cop.</em></li><li><strong><em>be tough on somebody</strong> (=cause problems for someone or make their life difficult): Having to stay indoors all day is tough on a kid.</em></li><li><em>It was a tough call (=a difficult decision), but we had to cancel the game because of the weather.</em></li><li><em>I find his books pretty tough going (=difficult to read).</em></li><li><em>Gage predicted the president’s proposal would be a tough sell (=something that is difficult to persuade someone about) before Congress.</em>American English**</li><li><strong><em>when the going gets tough (the tough get going)<em>informal</em></strong> (=used to say that when a situation becomes difficult, strong people take the necessary action to deal with it)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[strong person]</strong> physically or emotionally strong and able to deal with difficult situations: ► see thesaurus at determined</div><ul class=\"examples\"><li><em>The men who work on the oil rigs are a tough bunch.</em></li><li><strong><em>tough cookie/customer<em>informal</em></strong> (=someone who is very determined to do what they want and not what other people want)</em></li><li><strong><em>as tough as nails/as tough as old boots</strong> (=very tough): He’s as tough as nails – a good man to have on the team.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[strong material]</strong> not easily broken or made weaker: ► see thesaurus at strong</div><ul class=\"examples\"><li><em>tough, durable plastic</em></li><li><em>a very tough, hard-wearing cloth</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[strict/firm]</strong> very strict or firm ► see thesaurus at strict</div><ul class=\"examples\"><li><strong><em>tough on/with</strong>: My mother was very tough on my sister. / It’s time to get tough with drunk drivers.</em></li><li><em>The EU is taking a tough line with the UK over this issue.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[violent area]</strong> a tough part of a town has a lot of crime or violence</div><ul class=\"examples\"><li><strong><em>tough neighborhood/area/part of town etc</strong>: a tough area of Chicago</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>tough!/that’s tough!</strong> <em>spoken</em> used when you do not have any sympathy with someone:</div><ul class=\"examples\"><li><em>‘I’m getting wet.’ ‘Tough! You should’ve brought your umbrella.’</em></li><li><em>She didn’t tell us she was coming, so if this screws up her plans that’s just tough.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>tough luck!</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used when you do not have any sympathy for someone’s problems:</div><ul class=\"examples\"><li><em>Well, that’s just their tough luck! It was their mistake.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> used when you feel sympathy about something bad that has happened to someone:</div><ul class=\"examples\"><li><em>You didn’t get the job? Oh, tough luck!</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>tough shit!</strong> <em>spoken</em> <em>not polite</em> used when you do not have any sympathy for someone’s problems</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[violent person]</strong> likely to behave violently and having no gentle qualities:</div><ul class=\"examples\"><li><em>one of football’s most notorious tough guys</em></li><li><em>tough young thugs looking for trouble</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[food]</strong> difficult to cut or eat <em>OPP tender</em>: ► see thesaurus at hard</div><ul class=\"examples\"><li><em>The meat was tough and hard to chew.</em></li><li><em>the tough outer leaves of the cabbage</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>tough love</strong> a way of helping someone to change their behaviour by treating them in a kind but strict way</div></div>","7114":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tʊə $ tʊr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a journey for pleasure, during which you visit several different towns, areas etc → package tour ► see thesaurus at journey</div><ul class=\"examples\"><li><strong><em>tour of/around/round</strong>: a 10-day tour of China</em></li><li><strong><em>a walking/cycling/sightseeing etc tour</strong>: a cycling tour of Cornwall / We met on a coach tour in Italy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a short trip through a place to see it</div><ul class=\"examples\"><li><strong><em>tour of/around/round</strong>: a guided tour around the Kennedy Space Center</em></li><li><em>Kim worked as a tour guide in Cambridge last summer.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a planned journey made by musicians, a sports team etc in order to perform or play in several places</div><ul class=\"examples\"><li><strong><em>tour of</strong>: the England cricket team’s tour of India</em></li><li><strong><em>on tour</strong>: The Moscow Symphony Orchestra is here on tour.</em></li><li><em>the first leg of the band’s European tour (=the first part of it)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a period during which you go to live somewhere, usually abroad, to do your job, especially military work:</div><ul class=\"examples\"><li><em>his third tour in Northern Ireland</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>tour of inspection</strong> an official visit to a place, institution, group etc in order to check its quality or performance</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to visit several parts of a country or area: ► see thesaurus at travel</div><ul class=\"examples\"><li><em>We’re touring the Greek islands this summer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to go round or be shown round a place:</div><ul class=\"examples\"><li><em>The minister had been invited to tour the new factory.</em></li></ul></div></div>","7115":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tour‧is‧m</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtʊərɪzəm $ ˈtʊr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the business of providing things for people to do, places for them to stay etc while they are on holiday:</div><ul class=\"examples\"><li><em>The country depends on tourism for much of its income.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>medical/sex/libel etc tourism</strong> travel to a foreign country in order to do a particular thing, especially because you cannot do it in your own country or it is more expensive or less easy there</div></div>","7116":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tour‧ist</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtʊərɪst $ ˈtʊr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is visiting a place for pleasure on holiday: ► see thesaurus at travel</div><ul class=\"examples\"><li><em>Cambridge is always full of tourists in the summer.</em></li><li><em>The Statue of Liberty is a major tourist attraction.</em></li><li><em>What effect will this have on the local tourist industry?</em></li><li><strong><em>tourist centre/destination/resort etc</strong>: Durham, with its cathedral and castle, is a popular tourist centre.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>medical/sex/libel etc tourist</strong> someone who travels to a foreign country in order to do a particular thing, especially because they cannot do it in their own country or it is more expensive or less easy there</div></div>","7117":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tour‧na‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtʊənəmənt, ˈtɔː- $ ˈtɜːr-, ˈtʊr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a competition in which players compete against each other in a series of games until there is one winner:</div><ul class=\"examples\"><li><em>I feel I can win this tournament.</em></li><li><strong><em>tennis/chess/badminton etc tournament</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a competition to show courage and fighting skill between soldiers in the Middle Ages</div></div>","7118":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to praise something or someone in order to persuade people that they are important or worth a lot:</div><ul class=\"examples\"><li><em>his much touted musical</em></li><li><strong><em>be touted as something</strong>: Nell is being touted as the next big thing in Hollywood.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> <em>especially British English</em> to try to persuade people to buy goods or services you are offering</div><ul class=\"examples\"><li><strong><em>tout for business/custom<em>British English</em></strong> (=look for customers): Minicab drivers are not allowed to tout for business.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> <em>American English</em> to give someone information about a horse in a race</div></div>","7119":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /təʊ $ toʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to pull a vehicle or ship along behind another vehicle, using a rope or chain: ► see thesaurus at pull</div><ul class=\"examples\"><li><em>The ship had to be towed into the harbor.</em></li><li><strong><em>tow something away</strong>: Our car had been towed away.</em></li></ul></div>","7120":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> to‧wards</span><span class=\"meta-item\"><strong>IPA:</strong> /təˈwɔːdz $ tɔːrdz, twɔːrdz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[direction]</strong> used to say that someone or something moves, looks, faces etc in the direction of someone or something:</div><ul class=\"examples\"><li><em>He noticed two policemen coming towards him.</em></li><li><em>All the windows face toward the river.</em></li><li><em>He was standing with his back towards me.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[producing a result]</strong> in a process that will produce a particular result:</div><ul class=\"examples\"><li><em>These negotiations are the first step toward reaching an agreement.</em></li><li><em>The crisis continued as Britain drifted towards war.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[feeling/attitude]</strong> your feeling, attitude, or behaviour towards someone or something is how you feel or think about them or how you treat them:</div><ul class=\"examples\"><li><em>Brian’s attitude towards his work has always been very positive.</em></li><li><em>Her parents had been more sympathetic towards her.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[help pay for]</strong> money put, saved, or given towards something is used to pay for it:</div><ul class=\"examples\"><li><em>The money collected will be put towards repairing the church roof.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[before]</strong> just before a particular time:</div><ul class=\"examples\"><li><em>Toward the end of the afternoon it began to rain.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[near]</strong> near a particular place:</div><ul class=\"examples\"><li><em>Uncle Dick and Aunt Mavis live at High Burnton out towards the coast.</em></li></ul></div>","7121":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tow‧el</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaʊəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of cloth that you use for drying your skin or for drying things such as dishes:</div><ul class=\"examples\"><li><em>Have you got a clean towel I could use?</em></li><li><strong><em>bath/beach/kitchen towel</strong>: She dried her hands on the kitchen towel.</em></li></ul></div>","7122":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tow‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaʊə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a tall narrow building either built on its own or forming part of a castle, church etc:</div><ul class=\"examples\"><li><em>the Eiffel Tower</em></li><li><em>a castle with tall towers</em></li><li><strong><em>bell/clock tower</strong>: The bell tower was added to the church in 1848.</em></li><li><strong><em>tower of</strong>: the leaning tower of Pisa</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a tall structure, often made of metal, used for signalling, broadcasting etc:</div><ul class=\"examples\"><li><em>an air traffic control tower</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>tower of strength</strong> someone who gives you a lot of help, sympathy, and support when you are in trouble:</div><ul class=\"examples\"><li><em>Her father was a tower of strength to her when her marriage broke up.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a tall piece of furniture that you use to store things:</div><ul class=\"examples\"><li><em>a CD tower</em></li></ul></div>","7123":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[place]</strong> <span class=\"gram\">[countable]</span> a large area with houses, shops, offices etc where people live and work, that is smaller than a city and larger than a village: ► see thesaurus at city</div><ul class=\"examples\"><li><em>an industrial town in the Midlands</em></li><li><strong><em>town of</strong>: the town of Norwalk, Connecticut</em></li><li><em>I walked to the nearest town.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[main centre]</strong> <span class=\"gram\">[uncountable]</span> the business or shopping centre of a town:</div><ul class=\"examples\"><li><em>We’re going into town tonight to see a film.</em></li><li><em>They have a small apartment in town.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[people]</strong> <span class=\"gram\">[singular]</span> all the people who live in a particular town:</div><ul class=\"examples\"><li><em>The whole town turned out to watch the procession.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[where you live]</strong> <span class=\"gram\">[uncountable]</span> the town or city where you live:</div><ul class=\"examples\"><li><em>Cam left town about an hour ago, so he should be out at the farm by now.</em></li><li><em>I’ll be out of town for about a week.</em></li><li><em>Guess who’s in town? Jodie’s sister!</em></li><li><em>Do you know of a good place to eat? I’m from out of town (=from a different town).</em></li><li><em>We’re moving to another part of town.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[village]</strong> <span class=\"gram\">[countable]</span> <em>American English</em> several houses forming a small group around a church, shops etc SYN village<em>British English</em>:</div><ul class=\"examples\"><li><em>Rowayton is a small town of around 4,000 people.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[not country]</strong> <strong>the town</strong> life in towns and cities in general:</div><ul class=\"examples\"><li><em>Which do you prefer, the town or the country?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>go to town (on something)</strong> <em>informal</em> to do something in a very eager or thorough way:</div><ul class=\"examples\"><li><em>Angela really went to town on buying things for her new house.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>(out) on the town</strong> <em>informal</em> going to restaurants, bars, theatres etc for entertainment in the evening:</div><ul class=\"examples\"><li><em>Frank is taking me out for a night on the town.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>town and gown</strong> used to describe the situation in which the people living in a town and the students in a town seem to be separate and opposing groups</div></div>","7124":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌtown ˈhall</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a public building used for a town’s local government</div></div>","7125":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tox‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɒksɪk $ ˈtɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> containing poison, or caused by poisonous substances → toxin: ► see thesaurus at harmful</div><ul class=\"examples\"><li><em>fumes from a toxic waste dump</em></li><li><strong><em>toxic chemicals/substances/fumes/gases</strong>: Toxic chemicals were spilled into the river.</em></li><li><em>a highly toxic pesticide</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>toxic debt/loan/asset</strong> money that has been lent to someone that is unlikely to be paid back or bring the lender any profit</div><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> very unpleasant and causing a lot of harm or unhappiness:</div><ul class=\"examples\"><li><em>You are clearly in a toxic relationship and you need to get out of it.</em></li></ul></div>","7126":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɔɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an object for children to play with:</div><ul class=\"examples\"><li><em>some toys for the baby</em></li><li><strong><em>toy car/soldier/gun etc</em></strong></li><li><strong><em>soft/cuddly toy<em>British English</em></strong> (=a toy that looks like an animal and is covered in fur)</em></li><li><em>Annie was playing happily with her toys.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an object that you buy because it gives you pleasure and enjoyment, especially one that you don’t really need:</div><ul class=\"examples\"><li><em>The food mixer is her latest toy.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>sex toy</strong> an object that adults use to obtain sexual pleasure</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">toy toy 2 ●○○ verb Verb Table Examples Thesaurus Collocations toy with somebody/something phrasal verb 1 to think about an idea or possibility, usually for a short time and not very seriously toy with the idea of doing something I’ve been toying with the idea of going to Japan to visit them. 2 to keep moving and touching an object or food: He spoke casually and toyed with his pen. Laura was toying with her food and looking increasingly bored. 3 to lie to someone or trick them, for example saying that you love them when you do not</div></div></div>","7127":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /treɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[find somebody/something]</strong> to find someone or something that has disappeared by searching for them carefully: ► see thesaurus at find</div><ul class=\"examples\"><li><em>She had given up all hope of tracing her missing daughter.</em></li><li><em>Police are trying to trace a young woman who was seen near the accident.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[origins]</strong> to find the origins of when something began or where it came from</div><ul class=\"examples\"><li><strong><em>trace something (back) to something</strong>: They’ve traced their ancestry to Scotland. / The style of these paintings can be traced back to early medieval influences.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[history/development]</strong> to study or describe the history, development, or progress of something:</div><ul class=\"examples\"><li><em>Sondheim’s book traces the changing nature of the relationship between men and women.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[copy]</strong> to copy a drawing, map etc by putting a piece of transparent paper over it and then drawing the lines you can see through the paper ► see thesaurus at draw</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[with your finger]</strong> to draw real or imaginary lines on the surface of something, usually with your finger or toe</div><ul class=\"examples\"><li><strong><em>trace something on/in/across something</strong>: Rosie’s fingers traced a delicate pattern in the sand.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>trace a call</strong> to find out where a telephone call is coming from by using special electronic equipment:</div><ul class=\"examples\"><li><em>His call was traced and half an hour later police arrested him.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[sign of something]</strong> <span class=\"gram\">[countable, uncountable]</span> a small sign that shows that someone or something was present or existed:</div><ul class=\"examples\"><li><em>There was no trace of anyone having entered the room since then.</em></li><li><em>Petra’s lost all trace of her German accent.</em></li><li><em>Officers were unable to find any trace of drugs.</em></li><li><strong><em>disappear/vanish/sink without (a) trace</strong> (=disappear completely, without leaving any sign of what happened): The plane vanished without a trace.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[small amount]</strong> <span class=\"gram\">[countable]</span> a very small amount of a quality, emotion, substance etc that is difficult to see or notice</div><ul class=\"examples\"><li><strong><em>trace of</strong>: I saw the faintest trace of a smile cross Sandra’s face.</em></li><li><em>traces of poison</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[telephone]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> a search to find out where a telephone call came from, using special electronic equipment:</div><ul class=\"examples\"><li><em>The police put a trace on the call.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[information recorded]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> the mark or pattern made on a screen or on paper by a machine that is recording an electrical signal:</div><ul class=\"examples\"><li><em>This trace shows the heartbeat.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[cart/carriage]</strong> <span class=\"gram\">[countable]</span> one of the two pieces of leather, rope etc by which a cart or carriage is fastened to an animal pulling it</div></div></div>","7128":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /træk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[path/road]</strong> <span class=\"gram\">[countable]</span> a narrow path or road with a rough uneven surface, especially one made by people or animals frequently moving through the same place:</div><ul class=\"examples\"><li><em>The road leading to the farm was little more than a dirt track.</em></li><li><em>The track led through dense forest.</em></li><li><em>a steep mountain track</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[marks on ground]</strong> <strong>tracks</strong> <span class=\"gram\">[plural]</span> a line of marks left on the ground by a moving person, animal, or vehicle:</div><ul class=\"examples\"><li><em>We followed the tyre tracks across a muddy field.</em></li><li><em>The tracks, which looked like a fox’s, led into the woods.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[for racing]</strong> <span class=\"gram\">[countable]</span> a circular course around which runners, cars etc race, which often has a specially prepared surface: → dirt track(2)</div><ul class=\"examples\"><li><em>To run a mile, you have to run four circuits of the track.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[train]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable, uncountable]</span> the two metal lines along which trains travel <em>SYN railway line</em>:</div><ul class=\"examples\"><li><em>The track was damaged in several places.</em></li><li><em>That particular section of track was laid last year.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> <em>American English</em> the particular track that a train leaves from or arrives at:</div><ul class=\"examples\"><li><em>The train for Boston is leaving from track 2.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be on the right/wrong track</strong> to think in a way that is likely to lead to a correct or incorrect result:</div><ul class=\"examples\"><li><em>We’ve had the initial test results and it looks as though we’re on the right track.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>keep/lose track of somebody/something</strong> to pay attention to someone or something, so that you know where they are or what is happening to them, or to fail to do this:</div><ul class=\"examples\"><li><em>It’s difficult to keep track of all the new discoveries in genetics.</em></li><li><em>I just lost all track of time.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[music/song]</strong> <span class=\"gram\">[countable]</span> one of the songs or pieces of music on an album (=collection of songs or pieces of music): ► see thesaurus at music</div><ul class=\"examples\"><li><em>There’s a great Miles Davis track on side two.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>stop/halt (dead) in your tracks</strong> to suddenly stop, especially because something has frightened or surprised you</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>cover your tracks</strong> to be careful not to leave any signs that could let people know where you have been or what you have done because you want to keep it a secret, usually because it is illegal:</div><ul class=\"examples\"><li><em>He tried to cover his tracks by burning all the documents.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[sport]</strong> <span class=\"gram\">[uncountable]</span> <em>American English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> sport that involves running on a track:</div><ul class=\"examples\"><li><em>The next year he didn’t run track or play football.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> all the sports in an athletics competition such as running, jumping, or throwing the javelin:</div><ul class=\"examples\"><li><em>a famous track star</em></li><li><em>She went out for track in the spring (=she joined the school’s track team).</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be on track</strong> <em>spoken</em> to be likely to achieve the result you want:</div><ul class=\"examples\"><li><em>We’re still on track for 10% growth.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>get off the track</strong> <em>spoken</em> to begin to deal with a new subject rather than the main one which was being discussed:</div><ul class=\"examples\"><li><em>Don’t get off the track, we’re looking at this year’s figures not last year’s.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be on the track of somebody/something</strong> to hunt or search for someone or something:</div><ul class=\"examples\"><li><em>Police are on the track of the bank robbers.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>make tracks</strong> <em>spoken</em> used to say you must leave a place:</div><ul class=\"examples\"><li><em>It’s time we started making tracks.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[direction]</strong> <span class=\"gram\">[countable]</span> the direction or line taken by something as it moves</div><ul class=\"examples\"><li><strong><em>track of</strong>: islands that lie in the track of North Atlantic storms</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[on a vehicle]</strong> <span class=\"gram\">[countable]</span> a continuous metal band that goes over the wheels of a vehicle such as a bulldozer, allowing it to move over uneven ground</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[search]</strong> <span class=\"gram\">[transitive]</span> to search for a person or animal by following the marks they leave behind them on the ground, their smell etc: ► see thesaurus at follow</div><ul class=\"examples\"><li><em>Police have been tracking the four criminals all over Central America.</em></li><li><strong><em>track somebody to something</strong>: The dogs tracked the wolf to its lair.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[development]</strong> <span class=\"gram\">[transitive]</span> to record or study the behaviour or development of someone or something over time:</div><ul class=\"examples\"><li><em>The progress of each student is tracked by computer.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[aircraft/ship]</strong> <span class=\"gram\">[transitive]</span> to follow the movements of an aircraft or ship by using radar:</div><ul class=\"examples\"><li><em>a tracking station</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[camera]</strong> <span class=\"gram\">[intransitive + in/out]</span> to move a film or television camera away from or towards a scene in order to follow the action that you are recording</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[school]</strong> <span class=\"gram\">[transitive]</span> <em>American English</em> to put schoolchildren in groups according to their ability SYN stream<em>British English</em></div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[mark]</strong> <span class=\"gram\">[transitive]</span> <em>American English</em> to leave behind a track of something such as mud or dirt when you walk:</div><ul class=\"examples\"><li><em>Which of you boys tracked mud all over the kitchen floor?</em></li></ul></div></div>","7129":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trækt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the digestive/reproductive/urinary etc tract</strong> a system of connected organs that have one main purpose in a part of your body</div><div class=\"sense\"><span class=\"snum\">2</span> a large area of land:</div><ul class=\"examples\"><li><em>vast tracts of woodland</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> a short piece of writing, especially about a moral or religious subject:</div><ul class=\"examples\"><li><em>a tract on the dangers of drink</em></li></ul></div>","7130":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trac‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtræktə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a strong vehicle with large wheels, used for pulling farm machinery</div></div>","7131":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /treɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[buying/selling]</strong> <span class=\"gram\">[uncountable]</span> the activity of buying, selling, or exchanging goods within a country or between countries <em>SYN commerce</em> → balance of trade, free trade, → trade war at war(3)</div><ul class=\"examples\"><li><strong><em>trade between</strong>: There has been a marked increase in trade between East and West.</em></li><li><em>international trade agreements</em></li><li><em>unfair trade practices</em></li><li><strong><em>trade in</strong>: Trade in ivory has been banned since 1990.</em></li><li><strong><em>the arms/drug/slave etc trade</strong> (=the buying and selling of weapons, drugs etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the hotel/tourist etc trade</strong> the business done by companies, hotels etc → industry:</div><ul class=\"examples\"><li><em>Working on Saturdays is usual in the retail trade.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[amount of business]</strong> <span class=\"gram\">[uncountable]</span> <em>British English</em> business activity, especially the amount of goods or products that are sold <em>SYN business</em>: → do a roaring trade at roaring(3)</div><ul class=\"examples\"><li><em>A lot of pubs nowadays do most of their trade at lunchtimes.</em></li><li><strong><em>passing trade</strong> (=customers who go into a shop when they are passing it, not regular customers): Souvenir shops rely mainly on passing trade.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[an exchange of things]</strong> <span class=\"gram\">[singular]</span> <em>American English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> when you exchange something you have for something that someone else has:</div><ul class=\"examples\"><li><em>Let’s make a trade – my frisbee for your baseball.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> when a player on a sports team is exchanged for a player from another team:</div><ul class=\"examples\"><li><em>The Celtics star demanded a trade after talks with management broke down.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the trade</strong> a particular kind of business, and the people who are involved in it:</div><ul class=\"examples\"><li><em>I could get Ron to look at your car for you; he works in the trade.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[job/work]</strong> <span class=\"gram\">[countable, uncountable]</span> a particular job, especially one needing special skill with your hands:</div><ul class=\"examples\"><li><em>Brian insisted that his sons learn a trade.</em></li><li><em>My grandfather was a plumber by trade (=that was his job).</em></li><li><strong><em>tools of your trade</strong> (=the things that you need to do your job)</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to buy and sell goods, services etc as your job or business</div><ul class=\"examples\"><li><strong><em>trade with</strong>: India began trading with Europe in the 15th and 16th centuries.</em></li><li><strong><em>trade in</strong>: The company trades in silk, tea, and other items.</em></li><li><em>They had to travel into town to trade the produce from their farm.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> <em>British English</em> to exist and operate as a business:</div><ul class=\"examples\"><li><em>The firm now trades under the name Lanski and Weber.</em></li><li><strong><em>cease trading</strong> (=stop being a business because you are bankrupt)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to buy or sell something on the stock exchange: GRAMMAR Trade is usually passive in this meaning.</div><ul class=\"examples\"><li><em>Over a million shares were traded today.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>trade insults/blows etc</strong> to insult or hit each other during an argument or fight</div><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[intransitive, transitive]</span> <em>especially American English</em> to exchange something you have for something someone else has SYN swap<em>British English</em>:</div><ul class=\"examples\"><li><em>We traded necklaces.</em></li><li><strong><em>trade something with somebody</strong>: I wouldn’t mind trading jobs with her.</em></li><li><strong><em>trade (somebody) something for something</strong>: I’ll trade you my camera for your drill.</em></li></ul></div></div>","7132":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trad‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtreɪdə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who buys and sells goods or stocks → retailer</div><ul class=\"examples\"><li><strong><em>small/local trader</strong>: a small trader who sells hats in Oxford</em></li><li><strong><em>bond/currency/commodity etc trader</strong>: To the surprise of many Wall Street traders, the dollar rose yesterday.</em></li></ul></div>","7133":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trad‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtreɪdɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the activity of buying and selling goods or services</div><ul class=\"examples\"><li><strong><em>Sunday trading<em>British English</em></strong> (=shops being open on Sunday)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the activity of buying and selling stocks etc</div><ul class=\"examples\"><li><strong><em>heavy/light trading</strong> (=a lot of trading or a little trading): Shares dropped 10% in heavy trading.</em></li></ul></div>","7134":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tra‧di‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /trəˈdɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a belief, custom, or way of doing something that has existed for a long time, or these beliefs, customs etc in general: ► see thesaurus at habit</div><ul class=\"examples\"><li><em>the traditions of South East Asia</em></li><li><em>the tradition that the eldest son inherits the property</em></li><li><em>By tradition, it’s the bride’s parents who pay for the wedding.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>(be) in the tradition of somebody/something</strong> to have the same features as something that has been made or done in the past:</div><ul class=\"examples\"><li><em>His paintings are very much in the tradition of Picasso and Matisse.</em></li></ul></div>","7135":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tra‧di‧tion‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /trəˈdɪʃənəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> being part of the traditions of a country or group of people:</div><ul class=\"examples\"><li><em>traditional Italian cooking</em></li><li><em>a traditional Irish folk song</em></li><li><em>a traditional method of brewing beer</em></li><li><strong><em>it is traditional (for somebody) to do something</strong>: It is traditional not to eat meat on Good Friday.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> following ideas and methods that have existed for a long time, rather than doing anything new or different <em>SYN conventional</em>:</div><ul class=\"examples\"><li><em>He has a traditional view of women.</em></li><li><em>I went to a very traditional school.</em></li><li><em>traditional family values</em></li><li><em>a traditional way of life</em></li></ul></div>","7136":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tra‧di‧tion‧al‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /trəˈdɪʃənəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">according to tradition:</div><ul class=\"examples\"><li><em>More women are entering traditionally male jobs.</em></li><li><em>The color black is traditionally associated with mourning.</em></li><li><em><span class=\"gram\">[sentence adverb]</span>: Traditionally, everything is carried in baskets on the head or shoulders.</em></li></ul></div>","7137":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> traf‧fic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtræfɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the vehicles moving along a road or street:</div><ul class=\"examples\"><li><em>There wasn’t much traffic on the roads.</em></li><li><em>The sound of the traffic kept me awake.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the movement of aircraft, ships, or trains from one place to another:</div><ul class=\"examples\"><li><em>air traffic control</em></li><li><em>the problems of air traffic congestion in Europe</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> the movement of people or goods by aircraft, ships, or trains</div><ul class=\"examples\"><li><strong><em>traffic of</strong>: Most long-distance traffic of heavy goods is done by ships.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> the secret buying and selling of illegal goods:</div><ul class=\"examples\"><li><em>drugs traffic</em></li><li><strong><em>traffic in</strong>: traffic in firearms</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle trafficked, present participle trafficking)</span></div><div class=\"entry-body\"><div class=\"sense\">to take someone to another country and force them to work, for example as a prostitute:</div><ul class=\"examples\"><li><em>He had made a fortune by trafficking young women.</em></li></ul></div></div>","7138":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈtraffic ˌjam</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a long line of vehicles on a road that cannot move or can only move very slowly:</div><ul class=\"examples\"><li><em>We were stuck in a traffic jam for two hours.</em></li></ul></div>","7139":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈtraffic ˌlights</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a set of red, yellow, and green lights that control traffic</div></div>","7140":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tra‧ge‧dy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrædʒədi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural tragedies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a very sad event, that shocks people because it involves death:</div><ul class=\"examples\"><li><em>The tragedy happened as they were returning home from a night out.</em></li><li><em>Tragedy struck the family when their two-year-old son was killed in an accident.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>informal</em> something that seems very sad and unnecessary because something will be wasted, lost, or harmed:</div><ul class=\"examples\"><li><em>It’s a tragedy to see so much talent going to waste.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable]</span> a serious play or book that ends sadly, especially with the death of the main character → comedy:</div><ul class=\"examples\"><li><em>‘Hamlet’ is one of Shakespeare’s best known tragedies.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[uncountable]</span> this type of play or book:</div><ul class=\"examples\"><li><em>an actor specializing in tragedy</em></li></ul></div>","7141":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tra‧gic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrædʒɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a tragic event or situation makes you feel very sad, especially because it involves death or suffering → comic:</div><ul class=\"examples\"><li><em>The parents were not to blame for the tragic death of their son.</em></li><li><em>Lillian Board’s death at 22 was a tragic loss for British athletics.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> relating to tragedy in books or plays <em>OPP comic</em>:</div><ul class=\"examples\"><li><em>a great tragic actor</em></li><li><strong><em>tragic hero</strong> (=the main person in a tragedy)</em></li></ul></div>","7142":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /treɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[pull]</strong> <span class=\"gram\">[intransitive, transitive]</span> to pull something behind you, especially along the ground, or to be pulled in this way:</div><ul class=\"examples\"><li><em>A plane trailing a banner was circling overhead.</em></li><li><strong><em>trail in/on/over etc</strong>: She walked slowly along the path, her skirt trailing in the mud.</em></li><li><strong><em>trail something in/across/through etc something</strong>: Rees was leaning out of the boat trailing his hand through the water.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[walk slowly]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to walk slowly, especially behind other people because you are tired or bored</div><ul class=\"examples\"><li><strong><em>trail behind/around</strong>: Susie trailed along behind her parents. / We spent the afternoon trailing around the shops.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[lose a competition]</strong> <span class=\"gram\">[intransitive, transitive usually in progressive]</span> to be losing in a game, competition, or election:</div><ul class=\"examples\"><li><em>The Democratic candidate is still trailing in the opinion polls.</em></li><li><strong><em>trail (somebody) by something</strong>: Manchester United were trailing by two goals to one.</em></li><li><strong><em>trail in/home</strong> (=finish in a bad position): He trailed in last after a disastrous race.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[follow somebody]</strong> <span class=\"gram\">[transitive]</span> to follow someone by looking for signs that they have gone in a particular direction:</div><ul class=\"examples\"><li><em>Police trailed the gang for several days.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a rough path across countryside or through a forest: → nature trail</div><ul class=\"examples\"><li><em>The trail led over Boulder Pass before descending to a lake.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a long line or a series of marks that have been left by someone or something</div><ul class=\"examples\"><li><strong><em>trail of</strong>: a trail of wet footprints / The bus left a trail of black smoke behind it. / The typhoon left a trail of devastation.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a series of unpleasant situations or feelings that have been left by someone or something</div><ul class=\"examples\"><li><strong><em>trail of</strong>: He left a trail of broken hearts and broken promises.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a sign that a person or animal has been in a place, used for finding or catching them:</div><ul class=\"examples\"><li><em>The hunters lost the tiger’s trail in the middle of the jungle.</em></li><li><em>Police tracked him to Valencia and there the trail went cold (=they could not find any signs of him).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be on the trail of somebody/something</strong> to be trying to find someone or something by getting information about them:</div><ul class=\"examples\"><li><em>industrial spies on the trail of technological secrets</em></li><li><em>Police believe they are hot on the trail of a drug-smuggling gang (=they are close to finding them).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> all the places that a particular group of people visit for a particular purpose:</div><ul class=\"examples\"><li><em>a town on the tourist trail</em></li><li><strong><em>campaign/election trail</strong>: politicians on the campaign trail</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> the set of things that someone does to achieve something:</div><ul class=\"examples\"><li><em>New players should put the team back on the winning trail.</em></li></ul></div></div>","7143":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trail‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtreɪlə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a vehicle that can be pulled behind another vehicle, used for carrying something heavy ► see thesaurus at advertisement</div><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> a vehicle that can be pulled behind a car, used for living and sleeping in during a holiday SYN caravan<em>British English</em></div><div class=\"sense\"><span class=\"snum\">3</span> an advertisement for a new film or television show ► see thesaurus at movie</div></div>","7144":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /treɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[railway]</strong> a set of several carriages that are connected to each other and pulled along a railway line by an engine → boat train</div><ul class=\"examples\"><li><strong><em>train to</strong>: the train to Munich</em></li><li><strong><em>by train</strong>: We went all the way to Inverness by train.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[series]</strong> <strong>a train of something</strong> a series of events or actions that are related:</div><ul class=\"examples\"><li><em>The decision set off a train of events which led to his resignation.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>train of thought</strong> a related series of thoughts that are developing in your mind:</div><ul class=\"examples\"><li><em>The phone interrupted my train of thought.</em></li><li><em>I’ve lost my train of thought.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>bring something in its train</strong> <em>formal</em> if an action or event brings something in its train, that thing happens as a result of it:</div><ul class=\"examples\"><li><em>a decision that brought disaster in its train</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>set something in train</strong> <em>British English</em> <em>formal</em> to make a process start happening:</div><ul class=\"examples\"><li><em>Plans to modernize have been set in train.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[people/animals]</strong> a long line of moving people, animals, or vehicles:</div><ul class=\"examples\"><li><em>a camel train</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[dress]</strong> a part of a long dress that spreads out over the ground behind the person wearing it:</div><ul class=\"examples\"><li><em>a wedding dress with a long train</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[servants]</strong> a group of servants or officers following an important person, especially in the past</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[teach somebody]</strong> <span class=\"gram\">[intransitive, transitive]</span> to teach someone the skills of a particular job or activity, or to be taught these skills → training ► see thesaurus at learn, teach</div><ul class=\"examples\"><li><strong><em>train somebody in something</strong>: All staff will be trained in customer service skills.</em></li><li><strong><em>train to do something</strong>: She’s training to be a doctor.</em></li><li><strong><em>train somebody to do something</strong>: Employees are trained to deal with emergency situations.</em></li><li><strong><em>train as</strong>: Nadia trained as a singer.</em></li><li><em>a highly trained workforce</em></li><li><em>Trained staff will be available to deal with your queries.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[teach an animal]</strong> <span class=\"gram\">[transitive]</span> to teach an animal to do something or to behave correctly:</div><ul class=\"examples\"><li><em>a well-trained puppy</em></li><li><strong><em>train something to do something</strong>: These dogs are trained to detect drugs.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[prepare for sport]</strong> <span class=\"gram\">[intransitive, transitive]</span> to prepare for a sports event or tell someone how to prepare for it, especially by exercising → training ► see thesaurus at practise</div><ul class=\"examples\"><li><strong><em>train for</strong>: Brenda spends two hours a day training for the marathon.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[aim something]</strong> <span class=\"gram\">[transitive]</span> to aim something such as a gun or camera at someone or something</div><ul class=\"examples\"><li><strong><em>train something on/at somebody/something</strong>: She trained her binoculars on the bird.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[develop something]</strong> <span class=\"gram\">[transitive]</span> to develop and improve a natural ability or quality:</div><ul class=\"examples\"><li><em>You can train your mind to relax.</em></li><li><em>To the trained eye the difference between these flowers is obvious (=the difference is clear to someone who has developed skills to notice something).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[plant]</strong> <span class=\"gram\">[transitive]</span> to make a plant grow in a particular direction by bending, cutting, or tying it</div></div></div>","7145":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> train‧ee</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌtreɪˈniː◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who is being trained for a job:</div><ul class=\"examples\"><li><em>The trainees start next week.</em></li><li><strong><em>trainee manager/solicitor/teacher etc</strong>: a trainee hairdresser</em></li></ul></div>","7146":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> train‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtreɪnə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who trains people or animals for sport or work → coach: ► see thesaurus at teacher</div><ul class=\"examples\"><li><em>a racehorse trainer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> a type of strong shoe that you wear for sport SYN tennis shoe<em>American English</em></div></div>","7147":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> train‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtreɪnɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> the process of teaching or being taught the skills for a particular job or activity → train</div><ul class=\"examples\"><li><strong><em>training in</strong>: On the course we received training in every aspect of the job.</em></li><li><em>Police drivers have to undergo intensive training.</em></li><li><em>a rigorous training session</em></li><li><em>On-the job training will be supplemented by classroom lectures.</em></li><li><em>The shop opens late on Fridays because of staff training.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> physical exercises that you do to stay healthy or prepare for a competition → train:</div><ul class=\"examples\"><li><em>Lesley does weight training twice a week.</em></li><li><strong><em>be in training for something</strong>: She’s in training for the Olympics.</em></li></ul></div>","7148":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /treɪ, treɪt $ treɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>formal</em> a particular quality in someone’s character</div><ul class=\"examples\"><li><strong><em>personality/character traits</strong>: a mental illness associated with particular personality traits</em></li><li><strong><em>genetic/inherited traits</em></strong></li></ul></div>","7149":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trai‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtreɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who is not loyal to their country, friends, or beliefs → treason</div><ul class=\"examples\"><li><strong><em>traitor to</strong>: a traitor to the cause of women’s rights</em></li><li><em>a politician who turned traitor (=became a traitor) to the government</em></li></ul></div>","7150":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /træm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a vehicle for passengers, which travels along metal tracks in the street SYN streetcar<em>American English</em></div></div>","7151":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧ac‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /trænˈzækʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a business deal or action, such as buying or selling something:</div><ul class=\"examples\"><li><em>The bank charges a fixed rate for each transaction.</em></li><li><em>financial transactions</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the process of doing business:</div><ul class=\"examples\"><li><em>the transaction of his public duties</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>transactions</strong> <span class=\"gram\">[plural]</span> discussions that take place at the meetings of an organization, or a written record of these</div></div>","7152":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tran‧scend</span><span class=\"meta-item\"><strong>IPA:</strong> /trænˈsend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>formal</em> to go beyond the usual limits of something:</div><ul class=\"examples\"><li><em>The desire for peace transcended political differences.</em></li></ul></div>","7153":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tran‧script</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrænskrɪpt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a written or printed copy of a speech, conversation etc</div><ul class=\"examples\"><li><strong><em>transcript of</strong>: A transcript of the tapes was presented in court.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> an official college document that shows a list of a student’s classes and the results they received</div></div>","7154":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧fer</span><span class=\"meta-item\"><strong>IPA:</strong> /trænsˈfɜː $ -ˈfɜːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span><span class=\"meta-item\">(past tense and past participle transferred, present participle transferring)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[move to different place etc]</strong> <span class=\"gram\">[intransitive, transitive]</span> to move from one place, school, job etc to another, or to make someone do this, especially within the same organization</div><ul class=\"examples\"><li><strong><em>transfer (from something) to something</strong>: Swod transferred from MI6 to the Security Service.</em></li><li><strong><em>transfer somebody (from something) to something</strong>: They’re transferring him to a special unit at Great Ormond Street Hospital. / You’ll be transferred to the Birmingham office.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[put something in different place]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> to move from one place to another, or to move something from one place to another</div><ul class=\"examples\"><li><strong><em>transfer (from something) to something</strong>: The exhibition transfers to York City Art Gallery on 23rd January.</em></li><li><strong><em>transfer something (from something) to something</strong>: Transfer the meat to warm plates.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[sports person]</strong> <span class=\"gram\">[transitive]</span> to sell a sports player to another team:</div><ul class=\"examples\"><li><em>He was transferred for a fee of £8 million.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[money]</strong> <span class=\"gram\">[transitive]</span> to move money from one account or institution to another</div><ul class=\"examples\"><li><strong><em>transfer something (from something) to something</strong>: I’d like to transfer $500 to my checking account.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>transfer your affections/loyalty/allegiance etc</strong> to change from loving or supporting one person to loving or supporting a different one</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[skill/idea/quality]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a skill, idea, or quality transfers from one situation to another, or if you transfer it, it can be used in the new situation:</div><ul class=\"examples\"><li><em>Ideas that work well in one school often don’t transfer well to another.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>transfer power/responsibility/control (to somebody)</strong> to officially give power etc to another person or organization:</div><ul class=\"examples\"><li><em>The ageing president is preparing to transfer power to his son.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[phone]</strong> <span class=\"gram\">[transitive]</span> to connect the call of someone who has telephoned you to someone else’s telephone so that that person can speak to them:</div><ul class=\"examples\"><li><em>Hold on one moment while I transfer your call.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[property]</strong> <span class=\"gram\">[transitive]</span> <em>law</em> to officially give property or land to someone else</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[travel]</strong> <span class=\"gram\">[intransitive, transitive]</span> to change from one bus, plane etc to another while you are travelling, or arrange for someone to do this:</div><ul class=\"examples\"><li><em>You will be met on arrival at the airport and transferred to your hotel.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[information/music]</strong> <span class=\"gram\">[transitive]</span> to copy recorded information, music etc from one system to another:</div><ul class=\"examples\"><li><em>Transfer the files onto a memory stick.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[disease]</strong> <span class=\"gram\">[transitive]</span> if a disease is transferred from one person or animal to another, the second person or animal begins to have the disease <em>SYN pass</em></div><ul class=\"examples\"><li><strong><em>transfer something (from somebody/something) to somebody/something</strong>: It is unlikely that the disease will be transferred from animals to humans.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧fer</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrænsfɜː $ -fɜːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable, uncountable]</span> the process by which someone or something moves or is moved from one place, job etc to another</div><ul class=\"examples\"><li><strong><em>transfer of</strong>: the transfer of assets within a group of companies</em></li><li><strong><em>transfer to</strong>: Penny’s applied for a transfer to head office.</em></li><li><em>electronic data transfer</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> someone or something that has been moved in this way</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>transfer of power</strong> a process by which the control of a country is taken from one person or group and given to another:</div><ul class=\"examples\"><li><em>the transfer of power to a civilian government</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> the act of changing from one bus, aircraft etc to another while travelling:</div><ul class=\"examples\"><li><em>Getting there often means a couple of transfers on a bus line.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>especially British English</em> a drawing, pattern etc that can be stuck or printed onto a surface SYN decal<em>American English</em></div><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> <em>especially American English</em> a ticket that allows a passenger to change from one bus, train etc to another without paying more money</div></div></div>","7155":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧form</span><span class=\"meta-item\"><strong>IPA:</strong> /trænsˈfɔːm $ -ˈfɔːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to completely change the appearance, form, or character of something or someone, especially in a way that improves it:</div><ul class=\"examples\"><li><em>Increased population has transformed the landscape.</em></li><li><strong><em>transform somebody/something (from something) into something</strong>: The movie transformed her almost overnight from an unknown schoolgirl into a megastar.</em></li></ul></div>","7156":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧for‧ma‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌtrænsfəˈmeɪʃən $ -fər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a complete change in someone or something:</div><ul class=\"examples\"><li><em>In recent years, the movie industry has undergone a dramatic transformation.</em></li><li><strong><em>transformation from something to/into something</strong>: the gradual transformation from woodland to farmland</em></li><li><strong><em>transformation of</strong>: What leads to the transformation of one economic system to another?</em></li></ul></div>","7157":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tran‧sit</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrænsɪt, -zɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the process of moving goods or people from one place to another:</div><ul class=\"examples\"><li><em>baggage that is lost or damaged in transit (=while it is being moved)</em></li><li><em>transit by air or sea</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a system for moving people from place to place SYN transport<em>British English</em>, transportation<em>American English</em>:</div><ul class=\"examples\"><li><em>rapid transit networks</em></li><li><strong><em>public transit<em>American English</em></strong> (=buses, trains etc): promises to improve public transit</em></li></ul></div>","7158":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tran‧si‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /trænˈzɪʃən,-ˈsɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>formal</em> when something changes from one form or state to another</div><ul class=\"examples\"><li><strong><em>transition from something to something</strong>: the smooth transition from full-time work to full retirement / Making the transition from youth to adulthood can be very painful.</em></li><li><em>a society that is in transition (=changing)</em></li><li><em>the period of transition to full democracy</em></li></ul></div>","7159":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tran‧si‧tion‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /trænˈzɪʃənəl, -ˈsɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to a period during which something is changing from one state or form into another</div><ul class=\"examples\"><li><strong><em>transitional period/stage etc</strong>: a transitional period during the switch to the euro</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>transitional government</strong> a temporary government, usually one that governs until official elections can take place in a country</div></div>","7160":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧late</span><span class=\"meta-item\"><strong>IPA:</strong> /trænsˈleɪt, trænz-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[change languages]</strong> <span class=\"gram\">[intransitive, transitive]</span> to change written or spoken words into another language → interpret</div><ul class=\"examples\"><li><strong><em>translate something (from something) into something</strong>: Translate the text from Italian into English.</em></li><li><em>Poetry doesn’t usually translate well.</em></li><li><strong><em>translate as</strong>: Dagda, an ancient Irish deity, literally translates as ‘the good god’.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[happen as result]</strong> <span class=\"gram\">[intransitive, transitive]</span> if one thing translates into another, the second thing happens as a result of the first</div><ul class=\"examples\"><li><strong><em>translate (something) into something</strong>: A small increase in local spending will translate into a big rise in property tax.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[have same meaning]</strong> <span class=\"gram\">[intransitive]</span> to mean the same as something else</div><ul class=\"examples\"><li><strong><em>translate into/to something</strong>: These rates translate into a return of 8.5% for dollar investors.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[change forms]</strong> <span class=\"gram\">[intransitive, transitive]</span> to change something, or be changed, from one form into another</div><ul class=\"examples\"><li><strong><em>translate (something) into something</strong>: the danger of translating your emotions into actions</em></li><li><em>Jokes often don’t translate well into print.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[use in new situation]</strong> <span class=\"gram\">[intransitive, transitive]</span> to be used in a new situation, or to make something do this <em>SYN adapt</em></div><ul class=\"examples\"><li><strong><em>translate something to something</strong>: It’s amazing how well the play has been translated to film.</em></li></ul></div>","7161":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧la‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /trænsˈleɪʃən, trænz-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> when you translate something, or something that has been translated</div><ul class=\"examples\"><li><strong><em>translation of</strong>: a new translation of the Bible</em></li><li><strong><em>translation from</strong>: a literal translation from Arabic</em></li><li><em>She read the letter and gave us a rough translation (=she did not translate everything exactly).</em></li><li><em>I’ve only read ‘Madame Bovary’ in translation (=not in its original language).</em></li><li><em>Much of the book’s humour has been lost in translation (=is no longer effective when translated).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> the process of changing something into a different form</div></div>","7162":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧la‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /trænsˈleɪtə, trænz- $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who changes writing into a different language → interpreter</div></div>","7163":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧mis‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /trænzˈmɪʃən $ træns-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the process of sending out electronic signals, messages etc, using radio, television, or other similar equipment:</div><ul class=\"examples\"><li><em>worldwide data transmission</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> the process of sending or passing something from one person, place, or thing to another</div><ul class=\"examples\"><li><strong><em>transmission of</strong>: the transmission of disease</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>formal</em> something that is broadcast on television, radio etc <em>SYN broadcast</em>:</div><ul class=\"examples\"><li><em>a live transmission of the tennis championship</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> the parts of a vehicle that take power from the engine to the wheels</div></div>","7164":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧mit</span><span class=\"meta-item\"><strong>IPA:</strong> /trænzˈmɪt $ træns-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\">(past tense and past participle transmitted, present participle transmitting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive usually + adverb/preposition]</span> to send out electronic signals, messages etc using radio, television, or other similar equipment:</div><ul class=\"examples\"><li><em>The US Open will be transmitted live via satellite.</em></li><li><em>The system transmits information over digital phone lines.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to send or pass something from one person, place or thing to another <em>SYN pass</em> → sexually transmitted disease</div><ul class=\"examples\"><li><strong><em>transmit something (from somebody/something) to somebody/something</strong>: Mathematical knowledge is transmitted from teacher to student.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> <em>technical</em> if an object or substance transmits sound or light, it allows sound or light to travel through or along it</div></div>","7165":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧par‧ent</span><span class=\"meta-item\"><strong>IPA:</strong> /trænˈspærənt, -ˈspeər- $ -ˈspær-, -ˈsper-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if something is transparent, you can see through it <em>SYN clear</em> → opaque, translucent:</div><ul class=\"examples\"><li><em>a transparent plastic container</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> language or information that is transparent is clear and easy to understand:</div><ul class=\"examples\"><li><em>The way the system works will be transparent to the user.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a lie, excuse etc that is transparent does not deceive people</div></div>","7166":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧plant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrænsplɑːnt $ -plænt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the operation of transplanting an organ, piece of skin etc → implant:</div><ul class=\"examples\"><li><em>heart transplant surgery</em></li><li><em>a bone marrow transplant</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the organ, piece of skin etc that is moved in a transplant operation → implant</div></div>","7167":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧port</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrænspɔːt $ -ɔːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> <em>British English</em> a system or method for carrying passengers or goods from one place to another SYN transportation<em>American English</em> GRAMMAR: Countable or uncountable?In this meaning, transport is an uncountable noun and has no plural form. You say: · Public transport is very cheap. ✗Don’t say: public transportsGrammar guide ‒ NOUNS</div><ul class=\"examples\"><li><strong><em>air/rail/road transport</strong>: Improved rail transport is essential for business.</em></li><li><em>commuters who travel on public transport (=buses, trains etc)</em></li><li><em>It’s easier to get to the college if you have your own transport (=a car, bicycle etc).</em></li><li><strong><em>means/mode/form of transport</strong>: Horses were the only means of transport.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the process or business of taking goods from one place to another SYN transportation<em>American English</em></div><ul class=\"examples\"><li><strong><em>transport of</strong>: Canals were used for the transport of goods.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a ship or aircraft for carrying soldiers or supplies</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>be in a transport of delight/joy etc</strong> <em>literary</em> to be feeling very strong emotions of pleasure, happiness etc</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧port</span><span class=\"meta-item\"><strong>IPA:</strong> /trænˈspɔːt $ -ɔːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive usually + adverb/preposition]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to take goods, people etc from one place to another in a vehicle: ► see thesaurus at take</div><ul class=\"examples\"><li><em>trucks used for transporting oil</em></li><li><strong><em>transport somebody/something to something</strong>: The statue was transported to London.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be transported back to/into something</strong> to imagine that you are in another place or time because of something that you see or hear:</div><ul class=\"examples\"><li><em>One look, and I was transported back to childhood.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be transported with delight/joy etc</strong> <em>literary</em> to feel very strong emotions of pleasure, happiness etc</div><div class=\"sense\"><span class=\"snum\">4</span> to send a criminal to a distant country such as Australia as a punishment in the past</div></div></div>","7168":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trans‧por‧ta‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌtrænspɔːˈteɪʃən $ -spər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>American English</em> a system or method for carrying passengers or goods from one place to another SYN transport<em>British English</em>:</div><ul class=\"examples\"><li><em>The city needs to improve its public transportation (=buses, trains etc).</em></li><li><strong><em>means/mode/form of transportation</strong>: People need to get out of their cars and use other modes of transportation.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> the process or business of taking goods from one place to another SYN transport<em>British English</em></div><ul class=\"examples\"><li><strong><em>transportation of</strong>: the transportation of dangerous chemicals by road</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the punishment of sending a criminal to a distant country, especially Australia, in the past</div></div>","7169":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /træp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[for animals]</strong> a piece of equipment for catching animals: → mousetrap</div><ul class=\"examples\"><li><em>The only way to catch mice is to set a trap.</em></li><li><em>He stepped into a bear trap covered in snow.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[clever trick]</strong> a clever trick that is used to catch someone or to make them do or say something that they did not intend to</div><ul class=\"examples\"><li><strong><em>lay/set a trap (for somebody)</strong>: Police had set a trap for hooligans at the match.</em></li><li><strong><em>fall/walk into a trap</strong>: Mr Smith has walked straight into a trap laid by the Tories.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[bad situation]</strong> an unpleasant or difficult situation that is difficult to escape from:</div><ul class=\"examples\"><li><em>Amanda felt that marriage was a trap.</em></li><li><strong><em>debt/unemployment etc trap</strong>: people caught in the unemployment trap</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>fall into/avoid the trap of doing something</strong> to do something that seems good at the time but is not sensible or wise, or to avoid doing this:</div><ul class=\"examples\"><li><em>Don’t fall into the trap of investing all your money in one place.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>keep your trap shut</strong> <em>spoken</em> a rude way of telling someone to not say anything about things that are secret:</div><ul class=\"examples\"><li><em>Just keep your trap shut.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>shut your trap!</strong> <em>spoken</em> a rude way of telling someone to stop talking</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[vehicle]</strong> a vehicle with two wheels, pulled by a horse</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[sport]</strong> <em>American English</em> sandtrap SYN bunker<em>British English</em></div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[dog race]</strong> a special gate from which a greyhound is set free at the beginning of a race</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle trapped, present participle trapping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[in a dangerous place]</strong> to prevent someone from escaping from somewhere, especially a dangerous place: GRAMMAR Trap is often passive in this meaning.</div><ul class=\"examples\"><li><em>Twenty miners were trapped underground.</em></li><li><em>The building collapsed, trapping dozens of people in the rubble.</em></li><li><em>There’s no way out! We’re trapped!</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in a bad situation]</strong> <strong>be/feel trapped</strong> to be in a bad situation from which you cannot escape</div><ul class=\"examples\"><li><strong><em>trap in</strong>: Julia felt trapped in her role of wife and mother.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[animal]</strong> to catch an animal or bird using a trap</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[catch somebody]</strong> to catch someone by forcing them into a place from which they cannot escape: ► see thesaurus at catch</div><ul class=\"examples\"><li><em>The police trapped the terrorists at a roadblock.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[trick]</strong> to trick someone so that you make them do or say something that they did not intend to</div><ul class=\"examples\"><li><strong><em>trap somebody into (doing) something</strong>: I was trapped into signing a confession.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[crush]</strong> <em>British English</em> to get a part of your body crushed between two objects SYN pinch<em>American English</em>:</div><ul class=\"examples\"><li><em>Mind you don’t trap your fingers in the door.</em></li><li><em>pain from a trapped nerve</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[gas/water etc]</strong> to prevent something such as gas or water from getting away:</div><ul class=\"examples\"><li><em>solar panels that trap the sun’s heat</em></li></ul></div></div>","7170":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /træʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>American English</em> things that you throw away, such as empty bottles, used papers, food that has gone bad etc SYN rubbish<em>British English</em>:</div><ul class=\"examples\"><li><em>Will someone take out the trash (=take it outside the house)?</em></li><li><em>Just put it in the trash.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> something that is of very poor quality:</div><ul class=\"examples\"><li><em>How can you read that trash?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> <em>informal</em> <em>not polite</em> someone from a low social class who you do not respect because you think they are lazy or immoral → white trash</div></div>","7171":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trau‧ma</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrɔːmə, ˈtraʊmə $ ˈtraʊmə, ˈtrɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an unpleasant and upsetting experience that affects you for a long time:</div><ul class=\"examples\"><li><em>traumas such as death or divorce</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a mental state of extreme shock caused by a very frightening or unpleasant experience</div><ul class=\"examples\"><li><strong><em>trauma of</strong>: the trauma of being a young refugee / the emotional trauma of rape</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> <em>technical</em> an injury:</div><ul class=\"examples\"><li><em>the hospital’s trauma unit</em></li></ul></div>","7172":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trau‧mat‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /trɔːˈmætɪk $ trɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">a traumatic experience is so shocking and upsetting that it affects you for a long time:</div><ul class=\"examples\"><li><em>His son’s death was the most traumatic event in Stan’s life.</em></li></ul></div>","7173":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trav‧el</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrævəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(past tense and past participle travelled, present participle travelling British English, traveled, traveling American English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[journey]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive]</span> to go from one place to another, or to several places, especially ones that are far away:</div><ul class=\"examples\"><li><em>Someday I’d like to travel abroad.</em></li><li><strong><em>travel to/across/through/around etc</strong>: We’re planning to travel across America this summer.</em></li><li><strong><em>travel widely/extensively</strong>: He has travelled extensively in China.</em></li><li><strong><em>travel by train/car/air etc</strong>: We travelled by train across Eastern Europe.</em></li><li><em>He’d travelled far, but he’d travelled light (=without taking many possessions).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>travel the world/country</strong> to go to most parts of the world or of a particular country</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>[distance]</strong> <span class=\"gram\">[intransitive, transitive]</span> to go a particular distance or at a particular speed</div><ul class=\"examples\"><li><strong><em>travel at</strong>: The train was travelling at 100 mph.</em></li><li><em>They travelled 200 miles on the first day.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>well-travelled</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> (also widely-travelled) having travelled to many different countries:</div><ul class=\"examples\"><li><em>a well-travelled businesswoman</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> having been travelled on by many people:</div><ul class=\"examples\"><li><em>a well-travelled road</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[news]</strong> <span class=\"gram\">[intransitive]</span> to be passed quickly from one person or place to another:</div><ul class=\"examples\"><li><em>News travels fast.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>travel well</strong> to remain in good condition or be equally successful when taken to another country:</div><ul class=\"examples\"><li><em>Exporters have to find wines that travel well.</em></li><li><em>Many British television programmes don’t travel well.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[eyes]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>written</em> if your eyes travel over something, you look at different parts of it:</div><ul class=\"examples\"><li><em>His gaze travelled over her face.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[light/sound]</strong> <span class=\"gram\">[intransitive]</span> to move at a particular speed or in a particular direction:</div><ul class=\"examples\"><li><em>Light travels faster than sound.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[sport]</strong> <span class=\"gram\">[intransitive]</span> to take more than three steps while you are holding the ball in basketball</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the activity of travelling: ► see thesaurus at journey</div><ul class=\"examples\"><li><em>The new job involves a fair amount of travel.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>travels</strong> <span class=\"gram\">[plural]</span> journeys to places that are far away, usually for pleasure</div><ul class=\"examples\"><li><strong><em>on somebody’s travels</strong>: We met some very interesting people on our travels in Thailand.</em></li></ul></div></div>","7174":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trav‧el‧ler</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrævələ $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is on a journey or someone who travels often: ► see thesaurus at tourist, travel</div><ul class=\"examples\"><li><em>frequent travellers to France</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> someone who travels around from place to place living in a caravan → gipsy</div></div>","7175":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trav‧el‧ling</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrævəlɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>travelling expenses</strong> money that is used to pay for the cost of travelling while someone is on a trip for their company</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>travelling companion</strong> someone you are on a journey with</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>travelling musician/circus/exhibition etc</strong> someone or something that goes from place to place</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>travelling rug/clock etc</strong> <em>British English</em> a clock etc designed to be used when you are travelling</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>travelling people/folk</strong> <em>British English</em> travellers</div></div>","7176":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /treɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a flat piece of plastic, metal, or wood, with raised edges, used for carrying things such as plates, food etc:</div><ul class=\"examples\"><li><em>The waiter brought drinks on a tray.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a flat open container with three sides used for holding papers, documents etc on a desk</div><ul class=\"examples\"><li><strong><em>in tray</strong> (=for holding documents you still have to deal with)</em></li><li><strong><em>out tray</strong> (=for holding documents you have dealt with)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>especially British English</em> a flat open container with four sides used for holding certain things:</div><ul class=\"examples\"><li><em>a cat litter tray</em></li><li><strong><em>seed tray</strong> (=a tray in which you plant seeds)</em></li></ul></div>","7177":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tred/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(past tense trod /trɒd $ trɑːd/, past participle trodden /ˈtrɒdn $ ˈtrɑːdn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[step in/on]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>British English</em> to put your foot on or in something while you are walking <em>SYN step</em></div><ul class=\"examples\"><li><strong><em>tread in/on</strong>: Sorry, did I tread on your foot? / She trod barefoot on the soft grass.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>tread carefully/warily/cautiously etc</strong> to be very careful about what you say or do in a difficult situation:</div><ul class=\"examples\"><li><em>If I wanted to keep my job, I knew I’d have to tread lightly.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[crush]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[transitive]</span> <em>British English</em> to press or crush something into the floor or ground with your feet SYN track<em>American English</em></div><ul class=\"examples\"><li><strong><em>tread something into/onto/over something</strong>: Stop treading mud all over my clean kitchen floor! / Bits of the broken vase got trodden into the carpet.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>tread grapes</strong> to crush grapes with your feet in order to produce juice for making wine</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>tread a path</strong> <em>British English</em> <em>written</em> to take a particular action or series of actions:</div><ul class=\"examples\"><li><em>Getting the right balance between home and work is a difficult path to tread.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>tread water</strong> (past tense and past participle treaded)</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to stay floating upright in deep water by moving your legs as if you are riding a bicycle</div><div class=\"subsense\"><span class=\"subnum\">b)</span> to make no progress in a particular situation, especially because you are waiting for something to happen:</div><ul class=\"examples\"><li><em>All I could do was tread water until the contracts arrived.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[walk]</strong> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> <em>literary</em> to walk:</div><ul class=\"examples\"><li><em>David trod wearily along behind the others.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>tread the boards</strong> <em>humorous</em> to work as an actor</div></div>","7178":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trea‧sure</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtreʒə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a group of valuable things such as gold, silver, jewels etc</div><ul class=\"examples\"><li><strong><em>buried/hidden/sunken treasure</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a very valuable and important object such as a painting or ancient document:</div><ul class=\"examples\"><li><em>The Book of Kells is Trinity College’s greatest treasure.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> <em>informal</em> someone who is very useful or important to you:</div><ul class=\"examples\"><li><em>Our housekeeper is a real treasure.</em></li></ul></div>","7179":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /triːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[behave towards somebody/something]</strong> <span class=\"gram\">[always + adverb/preposition]</span> to behave towards someone or something in a particular way → treatment</div><ul class=\"examples\"><li><strong><em>treat somebody like/as something</strong>: She treats me like one of the family. / Penny doesn’t think her co-workers treat her as an equal. / He treated his automobiles almost as tenderly as he did his wife.</em></li><li><strong><em>badly treated/well treated</strong>: The prisoners were well treated by their guards.</em></li><li><strong><em>treat somebody with respect/contempt/courtesy etc</strong>: Despite her seniority, Margot was never treated with much respect.</em></li><li><strong><em>treat somebody like dirt/a dog</strong> (=treat someone unkindly and without respect): I don’t know why he stays with her – she treats him like dirt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[deal with something]</strong> <span class=\"gram\">[always + adverb/preposition]</span> to deal with, regard, or consider something in a particular way → treatment</div><ul class=\"examples\"><li><strong><em>treat something as something</strong>: Please treat this information as completely confidential. / She treats everything I say as a joke.</em></li><li><strong><em>treat something favourably/seriously/carefully etc</strong>: Any complaint about safety standards must be treated very seriously.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[illness/injury]</strong> to try to cure an illness or injury by using drugs, hospital care, operations etc → treatment:</div><ul class=\"examples\"><li><em>It was difficult to treat patients because of a shortage of medicine.</em></li><li><strong><em>treat somebody/something with something</strong>: Nowadays, malaria can be treated with drugs.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[buy something for somebody]</strong> to buy or do something special for someone that you know they will enjoy</div><ul class=\"examples\"><li><strong><em>treat somebody to something</strong>: We treated Mom to lunch at the Savoy.</em></li><li><em>I treated myself to a new dress.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[protect/clean]</strong> to put a special substance on something or use a chemical process in order to protect, clean, or preserve it → treatment:</div><ul class=\"examples\"><li><em>sewage treated so that it can be used as fertilizer</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something special that you give someone or do for them because you know they will enjoy it</div><ul class=\"examples\"><li><strong><em>as a treat</strong>: Steven took his son to a cricket match as a birthday treat.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> an event that gives you a lot of pleasure and is usually unexpected:</div><ul class=\"examples\"><li><em>When we were kids, a trip to the beach was a real treat.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a special food that tastes good, especially one that you do not eat very often:</div><ul class=\"examples\"><li><em>The cafe serves an assortment of gourmet treats.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>my treat</strong> <em>spoken</em> used to tell someone that you will pay for something such as a meal for them:</div><ul class=\"examples\"><li><em>Let’s go out to lunch – my treat.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>go down a treat</strong> <em>British English</em> <em>informal</em> if something goes down a treat, people like it very much:</div><ul class=\"examples\"><li><em>That new vegetarian restaurant seems to be going down a treat.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>look/work a treat</strong> <em>British English</em> <em>informal</em> to look very good or work very well:</div><ul class=\"examples\"><li><em>The sports ground looked a treat, with all the flags flying.</em></li></ul></div></div>","7180":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> treat‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtriːtmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[medical]</strong> <span class=\"gram\">[countable, uncountable]</span> something that is done to cure someone who is injured or ill → treat</div><ul class=\"examples\"><li><strong><em>treatment of/for</strong>: There have been great advances in the treatment of cancer. / The best treatment for a cold is to rest and drink lots of fluids.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[behaviour towards somebody]</strong> <span class=\"gram\">[uncountable]</span> a particular way of behaving towards someone or of dealing with them → treat</div><ul class=\"examples\"><li><strong><em>treatment of</strong>: Civil rights groups have complained about the harsh treatment of prisoners.</em></li><li><strong><em>special/preferential treatment</strong> (=when one person is treated better than another): The two young princes were not singled out for special treatment at school.</em></li><li><em>Just lately, Kyra has been giving me the silent treatment (=refusing to speak to me because she is angry with me).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[of a subject]</strong> <span class=\"gram\">[countable, uncountable]</span> a particular way of dealing with or talking about a subject → treat:</div><ul class=\"examples\"><li><em>I didn’t think the film gave the issue serious treatment.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[clean/protect]</strong> <span class=\"gram\">[countable, uncountable]</span> a process by which something is cleaned, protected etc → treat</div><ul class=\"examples\"><li><strong><em>treatment of</strong>: the treatment of polluted rivers</em></li></ul></div>","7181":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> treat‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtriːti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\">(plural treaties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable]</span> a formal written agreement between two or more countries or governments:</div><ul class=\"examples\"><li><em>Both sides have agreed to sign the treaty.</em></li><li><em>The peace treaty ends nearly four years of violence.</em></li><li><strong><em>treaty on</strong>: a treaty on political union</em></li></ul></div>","7182":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /triː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a very tall plant that has branches and leaves, and lives for many years:</div><ul class=\"examples\"><li><em>As a kid, I loved to climb trees.</em></li><li><strong><em>a cherry/peach/apple etc tree</strong>: We planted a peach tree in the backyard. / the trunk of an old oak tree (=the main central part, from which the branches grow)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a drawing that connects things with lines to show how they are related to each other → family tree</div></div>","7183":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trek/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a long and difficult journey, made especially on foot as an adventure <em>SYN hike</em>: ► see thesaurus at journey</div><ul class=\"examples\"><li><em>a lonely trek through the forest</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> a distance that seems long when you walk it:</div><ul class=\"examples\"><li><em>I’m afraid it’s a bit of a trek to the station.</em></li></ul></div>","7184":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trem‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrembəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to shake slightly in a way that you cannot control, especially because you are upset or frightened:</div><ul class=\"examples\"><li><em>His lip started to tremble and then he started to cry.</em></li><li><strong><em>tremble with anger/fear etc</strong>: Greene was on his feet now, his body trembling with rage.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to shake slightly:</div><ul class=\"examples\"><li><em>The whole house trembled as the train went by.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if your voice trembles, it sounds nervous and unsteady</div><div class=\"sense\"><span class=\"snum\">4</span> to be worried or frightened about something:</div><ul class=\"examples\"><li><em>I tremble to think what will happen when she finds out.</em></li></ul></div>","7185":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tre‧men‧dous</span><span class=\"meta-item\"><strong>IPA:</strong> /trɪˈmendəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very big, fast, powerful etc: ► see thesaurus at big</div><ul class=\"examples\"><li><em>Suddenly, there was a tremendous bang, and the whole station shook.</em></li><li><em>She was making a tremendous effort to appear calm.</em></li><li><em>She praised her husband for the tremendous support he had given her.</em></li><li><em>Sales have been tremendous so far this year.</em></li><li><em>This plan could save us a tremendous amount of money.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> excellent:</div><ul class=\"examples\"><li><em>She’s got a tremendous voice, hasn’t she?</em></li></ul></div>","7186":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trentʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a long narrow hole dug into the surface of the ground:</div><ul class=\"examples\"><li><em>Workers dug a trench for gas lines.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> a long narrow valley in the ground beneath the sea</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[usually plural]</span> a deep trench dug in the ground as a protection for soldiers:</div><ul class=\"examples\"><li><em>the trenches of World War I</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the trenches</strong> the place or situation where most of the work or action in an activity takes place:</div><ul class=\"examples\"><li><em>Lane left teaching after 30 years in the trenches.</em></li></ul></div>","7187":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a general tendency in the way a situation is changing or developing</div><ul class=\"examples\"><li><strong><em>trend towards</strong>: Lately there has been a trend towards hiring younger, cheaper employees.</em></li><li><strong><em>trend in</strong>: recent trends in education</em></li><li><em>The current trend is towards more part-time employment.</em></li><li><em>the general trend towards the centralization of political power</em></li><li><em>A disturbing trend is that victims of violence are getting younger.</em></li><li><em>The growing trend is for single mothers to bring up children by themselves.</em></li><li><em>Even so, the underlying trend is positive.</em></li><li><em>national and international economic trends</em></li><li><em>the downward trend in the price of gold</em></li><li><em>Successive presidents have tried to reverse this trend, but without success.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>set the trend</strong> to start doing something that other people copy:</div><ul class=\"examples\"><li><em>Larger corporations are setting the trend for better maternity benefits.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on trend</strong> fashionable – used especially in magazines:</div><ul class=\"examples\"><li><em>This striped dress is bang on trend.</em></li></ul></div>","7188":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tri‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtraɪəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[court]</strong> <span class=\"gram\">[countable, uncountable]</span> a legal process in which a judge and often a jury in a court of law examine information to decide whether someone is guilty of a crime → try: → show trial</div><ul class=\"examples\"><li><em>The trial is due to start next week.</em></li><li><strong><em>on trial (for something)</strong>: Brady was on trial for assault.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[test]</strong> <span class=\"gram\">[countable, uncountable]</span> a process of testing to find out whether something works effectively and is safe:</div><ul class=\"examples\"><li><em>a new drug that is undergoing clinical trials</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[try somebody/something]</strong> <span class=\"gram\">[countable, uncountable]</span> a short period during which you use or do something or employ someone to find out whether they are satisfactory for a particular purpose or job → try</div><ul class=\"examples\"><li><strong><em>on trial</strong>: They let me have the computer on trial for thirty days.</em></li><li><em>The security system will be reviewed after a three-month trial period.</em></li><li><em>Smith was hired on a six-month trial basis.</em></li><li><strong><em>trial separation</strong> (=a period of time in which a husband and wife do not live together, to find out whether they want to stay married)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>by/through trial and error</strong> if you do something by trial and error, you test many different methods of doing something in order to find the best:</div><ul class=\"examples\"><li><em>I learned most of what I know about gardening through trial and error.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[difficulty]</strong> <span class=\"gram\">[countable usually plural]</span> something that is difficult to deal with, and that is worrying or annoying → trying:</div><ul class=\"examples\"><li><em>the daily trials of living in a poor country</em></li><li><strong><em>be a trial (to/for somebody)</strong>: My brothers and I were always a real trial to my parents.</em></li><li><em>the trials and tribulations of running a business</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[sports]</strong> <strong>trials</strong> <span class=\"gram\">[plural]</span> <em>British English</em> a special sports competition in which people who want to be on a team are tested, so that the best can be chosen SYN tryout<em>American English</em></div><ul class=\"examples\"><li><strong><em>horse/sheepdog trials</strong> (=a sporting competition in which horses or dogs compete)</em></li></ul></div>","7189":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tri‧an‧gle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtraɪæŋɡəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●●</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a flat shape with three straight sides and three angles</div><div class=\"sense\"><span class=\"snum\">2</span> something that is shaped like a triangle:</div><ul class=\"examples\"><li><em>a triangle of land</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a musical instrument made of metal bent into the shape of a triangle. You hit it with a metal stick to make a ringing sound.</div><div class=\"sense\"><span class=\"snum\">4</span> <em>American English</em> a flat plastic object with three sides that has one angle of 90° and is used for drawing angles SYN set-square<em>British English</em></div></div>","7190":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tri‧an‧gu‧lar</span><span class=\"meta-item\"><strong>IPA:</strong> /traɪˈæŋɡjələ $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> shaped like a triangle</div><div class=\"sense\"><span class=\"snum\">2</span> involving three people or teams:</div><ul class=\"examples\"><li><em>a triangular sporting competition</em></li></ul></div>","7191":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trib‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtraɪbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">relating to a tribe or tribes:</div><ul class=\"examples\"><li><em>a tribal dance</em></li><li><em>tribal cultures</em></li></ul></div>","7192":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /traɪb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a social group consisting of people of the same race who have the same beliefs, customs, language etc, and usually live in one particular area ruled by their leader:</div><ul class=\"examples\"><li><em>a tribe of Aborigines known as the Dolphin People</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a group of people with the same interests – used especially to show disapproval:</div><ul class=\"examples\"><li><em>tribes of journalists</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a group of related animals or plants:</div><ul class=\"examples\"><li><em>the cat tribe</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>humorous</em> a large family:</div><ul class=\"examples\"><li><em>We were only expecting Jack and his wife, but the whole tribe turned up.</em></li></ul></div>","7193":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tri‧bu‧nal</span><span class=\"meta-item\"><strong>IPA:</strong> /traɪˈbjuːnl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a type of court that is given official authority to deal with a particular situation or problem:</div><ul class=\"examples\"><li><em>The case of your redundancy will be heard by an independent tribunal.</em></li></ul></div>","7194":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trib‧ute</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrɪbjuːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that you say, do, or give in order to express your respect or admiration for someone:</div><ul class=\"examples\"><li><em>The players wore black armbands as a tribute to their late teammate.</em></li><li><em>I’d like to pay tribute to (=praise and admire publicly) the party workers for all their hard work.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be a tribute to somebody/something</strong> to be a clear sign of the good qualities that someone or something has:</div><ul class=\"examples\"><li><em>It was a tribute to her teaching methods that so many children passed the test.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a payment of goods or money by one ruler or country to another more powerful one, especially in order to be protected</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>floral tribute</strong> <em>British English</em> flowers sent to a funeral</div></div>","7195":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[something that deceives somebody]</strong> something you do in order to deceive someone:</div><ul class=\"examples\"><li><em>Pretending he doesn’t remember is an old trick of his.</em></li><li><em>He didn’t really lose his wallet – that’s just a trick.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[joke]</strong> something you do to surprise someone and to make other people laugh:</div><ul class=\"examples\"><li><em>I’m getting tired of your silly tricks.</em></li><li><em>The girls were playing tricks on their teacher.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[something that makes things appear different]</strong> something that makes things appear to be different from the way they really are:</div><ul class=\"examples\"><li><em>After walking for hours in the hot sun, his mind began playing tricks on him.</em></li><li><em>At first he thought someone was coming towards him, but it was just a trick of the light.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a dirty/rotten/mean trick</strong> an unkind or unfair thing to do:</div><ul class=\"examples\"><li><em>He didn’t turn up? What a dirty trick!</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>do the trick</strong> <em>spoken</em> if something does the trick, it solves a problem or provides what is needed to get a good result:</div><ul class=\"examples\"><li><em>A bit more flour should do the trick.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[magic]</strong> a skilful set of actions that seem like magic, done to entertain people:</div><ul class=\"examples\"><li><em>My uncle was always showing me card tricks when I was a kid.</em></li><li><em>a magic trick</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[clever method]</strong> a way of doing something that works very well but may not be easy to notice:</div><ul class=\"examples\"><li><em>The trick is to bend your knees as you catch the ball.</em></li><li><em>a salesman who knew all the tricks of the trade (=clever methods used in a particular job)</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>use/try every trick in the book</strong> to use every method that you know, even dishonest ones, to achieve what you want</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>teach/show somebody a trick or two</strong> <em>informal</em> used to say that someone knows more than someone else or can do something better than them:</div><ul class=\"examples\"><li><em>Experienced teachers can show new teachers a trick or two.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>somebody is up to their (old) tricks</strong> <em>informal</em> to be doing the same dishonest things that you have often done before</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[cards]</strong> the cards played or won in one part of a game of cards:</div><ul class=\"examples\"><li><em>He won the first three tricks easily.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[habit]</strong> <strong>have a trick of doing something</strong> <em>British English</em> to have a habit of using a particular expression or of moving your face or body in a particular way:</div><ul class=\"examples\"><li><em>She had this trick of raising her eyebrows at the end of a question.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>never miss a trick</strong> <em>spoken</em> to always know exactly what is happening even if it does not concern you:</div><ul class=\"examples\"><li><em>Dave’s found out. He never misses a trick, does he?</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>how’s tricks?</strong> <em>old-fashioned</em> <em>spoken</em> used to greet someone in a friendly way:</div><ul class=\"examples\"><li><em>Hello, Bill! How’s tricks?</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[sex]</strong> <em>American English</em> <em>old-fashioned</em> <em>informal</em> someone who pays a prostitute to have sex</div><ul class=\"examples\"><li><strong><em>turn a trick</strong> (=to have sex with someone for money)</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to deceive someone in order to get something from them or to make them do something:</div><ul class=\"examples\"><li><em>She knew she’d been tricked, but it was too late.</em></li><li><strong><em>trick somebody into doing something</strong>: He claimed he was tricked into carrying drugs.</em></li><li><strong><em>trick somebody out of something</strong>: The corporation was tricked out of $20 million.</em></li><li><strong><em>trick your way into/past/onto etc something</strong>: He tricked his way into her home by pretending to be a policeman.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be tricked out with/in something</strong> <em>British English</em> <em>literary</em> to be decorated with something:</div><ul class=\"examples\"><li><em>a hat tricked out with ribbons</em></li></ul></div></div>","7196":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trick‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrɪki/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\">(comparative trickier, superlative trickiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that is tricky is difficult to deal with or do because it is complicated and full of problems: ► see thesaurus at difficult</div><ul class=\"examples\"><li><em>I can get you tickets for the show but it’ll be tricky.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a tricky person is clever and likely to deceive you <em>SYN crafty</em></div></div>","7197":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trig‧ger</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrɪɡə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make something happen very quickly, especially a series of events: ► see thesaurus at cause</div><ul class=\"examples\"><li><em>The assassination triggered off a wave of rioting.</em></li><li><em>Certain forms of mental illness can be triggered by food allergies.</em></li><li><strong><em>trigger a memory</strong> (=make you suddenly remember something)</em></li><li><em>His action triggered a massive response from the government.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make something such as a bomb or electrical system start to operate <em>SYN set off</em>:</div><ul class=\"examples\"><li><em>The burglars fled after triggering the alarm.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the part of a gun that you pull with your finger to fire it</div><ul class=\"examples\"><li><strong><em>pull/squeeze the trigger</strong>: He took aim and squeezed the trigger.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be the trigger (point) (for something)</strong> to be the thing that quickly causes a serious problem:</div><ul class=\"examples\"><li><em>The hijacking became a trigger point for military action.</em></li></ul></div></div>","7198":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tril‧lion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrɪljən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural trillion or trillions)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the number 1,000,000,000,000:</div><ul class=\"examples\"><li><em>In a short time the number of cells is more than a trillion.</em></li><li><strong><em>two/three/four etc trillion</strong>: $5.3 trillion / Japan’s exports were worth $43 trillion last year.</em></li><li><strong><em>trillions of pounds/dollars etc</strong>: the trillions of dollars in the bond markets</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> an extremely large number of people or things</div><ul class=\"examples\"><li><strong><em>a trillion</strong>: a shirt with a trillion holes in it</em></li><li><strong><em>trillions of</strong>: We’ve made this mistake trillions of times before.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> <em>old use</em> the number 1,000,000,000,000,000,000</div></div>","7199":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle trimmed, present participle trimming)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[cut]</strong> to make something look neater by cutting small pieces off it: ► see thesaurus at cut</div><ul class=\"examples\"><li><em>Pete was trimming the lawn around the roses.</em></li><li><em>I have my hair trimmed every six weeks.</em></li><li><strong><em>trim something away/off</strong>: Trim away any excess glue with a knife.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[reduce]</strong> to reduce a number, amount, or the size of something:</div><ul class=\"examples\"><li><em>We need to trim costs by £500m.</em></li><li><em>The bill would trim the number of immigrants to the US.</em></li><li><strong><em>trim something from/off something</strong>: The company trimmed £46,000 from its advertising budget.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[decorate]</strong> to decorate something, especially clothes, by adding things that look pretty GRAMMAR Trim is often passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be trimmed with something</strong>: a dress trimmed with lace</em></li><li><em>At Christmas, the whole family helps trim the tree.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[sail]</strong> to move the sails of a boat in order to go faster</div></div>","7200":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a visit to a place that involves a journey, for pleasure or a particular purpose ► see thesaurus at journey</div><ul class=\"examples\"><li><strong><em>trip to</strong>: Did you enjoy your trip to Disneyland?</em></li><li><strong><em>trip from</strong>: The Palace is only a short trip from here.</em></li><li><strong><em>business/school/shopping etc trip</strong>: a business trip to Japan</em></li><li><em>Two lucky employees won a round-the-world trip.</em></li><li><strong><em>coach/boat/bus trip</strong>: a boat trip up the Thames</em></li><li><strong><em>day trip</strong> (=a pleasure trip done in one day)</em></li><li><em>It’s an 80-mile round trip (=a journey to a place and back again) to Exeter.</em></li><li><strong><em>return trip</strong> (=when you are travelling back to where you started)</em></li><li><em>I’m afraid you’ve had a wasted trip (=a trip in which you do not achieve your purpose), Mr Burgess has already left.</em></li><li><strong><em>go on/take a trip</strong>: We’re thinking of taking a trip to the mountains.</em></li><li><em>He was unable to make the trip to accept the award.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>informal</em> the strange mental experiences someone has when they take a drug such as LSD:</div><ul class=\"examples\"><li><em>a bad trip</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> <em>American English</em> <em>informal</em> a person or experience that is amusing and unusual:</div><ul class=\"examples\"><li><em>Julie’s such a trip!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> an act of falling as a result of hitting something with your foot:</div><ul class=\"examples\"><li><em>accidents caused by trips or falls</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle tripped, present participle tripping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[fall]</strong> (also trip up) <span class=\"gram\">[intransitive]</span> to hit something with your foot by accident so that you fall or almost fall <em>SYN stumble</em>:</div><ul class=\"examples\"><li><em>He tripped and fell.</em></li><li><strong><em>trip over</strong>: Clary tripped over a cable and broke his foot.</em></li><li><strong><em>trip on</strong>: He tripped on the bottom step.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[make somebody fall]</strong> (also trip up) <span class=\"gram\">[transitive]</span> to make someone fall by putting your foot in front of them when they are moving:</div><ul class=\"examples\"><li><em>Baggio was tripped inside the penalty area.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[switch on]</strong> <span class=\"gram\">[transitive]</span> to switch on a piece of electrical equipment by accident:</div><ul class=\"examples\"><li><em>An intruder had tripped the alarm.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[walk/dance]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>literary</em> to walk, run, or dance with quick light steps:</div><ul class=\"examples\"><li><em>a little girl tripping down the lane</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>trip off the tongue</strong> to be easy to say or pronounce:</div><ul class=\"examples\"><li><em>Monofluorophosphate! It doesn’t exactly trip off the tongue, does it?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[drug]</strong> (also trip out) <span class=\"gram\">[intransitive]</span> <em>informal</em> to experience the mental effects of a drug such as LSD:</div><ul class=\"examples\"><li><em>They must have been tripping.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>trip the light fantastic</strong> to dance – used humorously</div></div></div>","7201":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trip‧le</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrɪpəl ˌzɪərəʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having three parts or involving three groups, people, events etc → double:</div><ul class=\"examples\"><li><em>a triple murder investigation</em></li><li><em>a triple bill of horror movies</em></li><li><em>the triple world champion</em></li><li><em>a triple bypass heart operation</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> three times more than a particular number → double:</div><ul class=\"examples\"><li><em>The rail system has triple the average number of accidents.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to increase by three times as much, or to make something do this → double: ► see thesaurus at increase</div><ul class=\"examples\"><li><em>The company has tripled in size.</em></li><li><em>We expect to triple our profits next year.</em></li></ul></div></div>","7202":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tri‧umph</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtraɪəmf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an important victory or success after a difficult struggle: ► see thesaurus at victory</div><ul class=\"examples\"><li><em>Winning the championship is a great personal triumph.</em></li><li><strong><em>triumph for</strong>: a tremendous diplomatic triumph for France</em></li><li><strong><em>triumph over</strong>: the triumph over hardship</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a feeling of pleasure and satisfaction that you get from victory or success:</div><ul class=\"examples\"><li><em>a shout of triumph</em></li><li><strong><em>in triumph</strong>: He rode in triumph to the Tsar.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> a very successful example of something</div><ul class=\"examples\"><li><strong><em>triumph of</strong>: The gallery is a triumph of design.</em></li></ul></div>","7203":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tri‧um‧phant</span><span class=\"meta-item\"><strong>IPA:</strong> /traɪˈʌmfənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> showing pleasure and pride because of a victory or success:</div><ul class=\"examples\"><li><em>I feel exhausted, but also triumphant.</em></li><li><strong><em>triumphant look/smile/expression etc</strong>: a triumphant grin</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> having gained a victory or success:</div><ul class=\"examples\"><li><em>the triumphant army</em></li><li><em>The Nationalists emerged triumphant from the political crisis.</em></li></ul></div>","7204":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> triv‧i‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrɪviəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">not serious, important, or valuable ► see thesaurus at unimportant</div><ul class=\"examples\"><li><strong><em>trivial problem/matter/complaint etc</strong>: We were punished for the most trivial offences.</em></li><li><em>a trivial sum</em></li><li><em>Her feelings for Simon seemed trivial by comparison.</em></li></ul></div>","7205":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trol‧ley</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrɒli $ ˈtrɑːli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a large basket on wheels that you use for carrying bags, shopping etc SYN cart<em>American English</em>:</div><ul class=\"examples\"><li><em>a supermarket trolley</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> a small table on wheels used for serving food SYN cart<em>American English</em>:</div><ul class=\"examples\"><li><em>a drinks trolley</em></li><li><em>the sweet trolley (=one for serving sweet dishes, cakes etc in a restaurant)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> an electric vehicle for carrying passengers which moves along the street on metal tracks SYN tram<em>British English</em></div><div class=\"sense\"><span class=\"snum\">4</span> a trolleybus</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>be off your trolley</strong> <em>British English</em> <em>informal</em> <em>humorous</em> to be crazy</div></div>","7206":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /truːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>troops</strong> <span class=\"gram\">[plural]</span> soldiers in an organized group:</div><ul class=\"examples\"><li><em>Both countries agreed to withdraw their troops.</em></li><li><strong><em>French/UN/government etc troops</strong>: Johnson took the popular step of sending in American troops.</em></li><li><em>troops stationed in Hawaii</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>troop movement/withdrawal etc</strong> movements etc of troops:</div><ul class=\"examples\"><li><em>increased troop deployment (=when troops are moved to places where they are needed)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a group of soldiers, especially on horses or in tanks:</div><ul class=\"examples\"><li><em>the troop commander</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a group of people or animals that do something together:</div><ul class=\"examples\"><li><em>a troop of monkeys</em></li><li><em>a Scout troop</em></li></ul></div>","7207":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tro‧phy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrəʊfi $ ˈtroʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural trophies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large object such as a silver cup or plate that someone receives as a prize for winning a competition:</div><ul class=\"examples\"><li><em>walls lined with banners and athletic trophies</em></li><li><strong><em>Football League/Masters/Heisman etc Trophy</strong> (=the name given to a particular competition for which the prize is a trophy)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something that you keep to prove your success in something, especially in war or hunting:</div><ul class=\"examples\"><li><em>A lion’s head was among the trophies of his African trip.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>trophy wife</strong> <em>informal</em> a young beautiful woman who is married to a rich successful man who is much older than her – used to show disapproval</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>trophy property/artwork/client etc</strong> <em>informal</em> a property, piece of art, client etc that is very desirable and gives a lot of status to the person who has it:</div><ul class=\"examples\"><li><em>a rare opportunity to acquire a trophy property in this prestigious location</em></li></ul></div>","7208":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trop‧i‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrɒpɪkəl $ ˈtrɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> coming from or existing in the hottest parts of the world:</div><ul class=\"examples\"><li><em>the tropical rain forests</em></li><li><em>tropical fruit</em></li><li><strong><em>tropical diseases/medicine</strong> (=diseases that are common in hot countries or the study of these diseases)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> weather that is tropical is very hot and wet:</div><ul class=\"examples\"><li><em>a steamy tropical night</em></li></ul></div>","7209":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trɒt $ trɑːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(past tense and past participle trotted, present participle trotting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> if a horse trots, it moves fairly quickly with each front leg moving at the same time as the opposite back leg → canter, gallop</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if a person or animal trots, they run fairly slowly, taking short regular steps: ► see thesaurus at run</div><ul class=\"examples\"><li><em>She came trotting down the steps from the library.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>informal</em> to walk or go somewhere, especially fairly quickly:</div><ul class=\"examples\"><li><em>He trotted off and came back a couple of minutes later, holding a parcel.</em></li></ul></div>","7210":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> troub‧le</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrʌbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[problems]</strong> <span class=\"gram\">[uncountable]</span> (also troubles<span class=\"gram\">[plural]</span>) problems or difficulties ► see thesaurus at problem</div><ul class=\"examples\"><li><strong><em>trouble with</strong>: We’re having a lot of trouble with the new computer system.</em></li><li><em>Recent stock market losses point to trouble ahead.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[bad point]</strong> <span class=\"gram\">[singular]</span> used when saying what is bad about a person or situation or what causes problems:</div><ul class=\"examples\"><li><em>The trouble with you is that you don’t listen.</em></li><li><em>The trouble is there are too many people and not enough places.</em></li><li><em>But no one ever remembers – that’s the trouble.</em></li><li><em>You never think, that’s your trouble.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[bad situation]</strong> <strong>in/into/out of trouble</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if someone or something is in trouble, they are in a situation with a lot of problems:</div><ul class=\"examples\"><li><em>He admitted that their marriage was in trouble.</em></li><li><strong><em>get/run into trouble</strong>: The company ran into trouble when it tried to expand too quickly.</em></li><li><strong><em>in serious/deep trouble</strong>: The economy was in serious trouble.</em></li><li><em>the dangers of trying to borrow your way out of trouble</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if someone is in trouble, they have done something which someone will punish them for or be angry about</div><ul class=\"examples\"><li><strong><em>in deep/big trouble</strong>: We’ll be in big trouble if Mr Elliott finds out.</em></li><li><strong><em>in trouble with somebody</strong>: I think I’m in trouble with Dad.</em></li><li><em>I didn’t say anything because I didn’t want to get into trouble.</em></li><li><strong><em>keep/stay out of trouble</strong>: I hope Tim stays out of trouble this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[fighting]</strong> <span class=\"gram\">[uncountable]</span> fighting, violence, or violent behaviour:</div><ul class=\"examples\"><li><em>If the kids start to cause trouble, ask them to move on.</em></li><li><em>A handful of people came looking for trouble.</em></li><li><em>If you start any trouble, you’ll regret it.</em></li><li><em>There was crowd trouble before the match.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[worries]</strong> <span class=\"gram\">[uncountable]</span> (also troubles<span class=\"gram\">[plural]</span>) problems in your life which you are worried about:</div><ul class=\"examples\"><li><em>He poured out all his troubles to me (=told me all about his problems).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[effort]</strong> <span class=\"gram\">[uncountable]</span> an amount of effort and time that is needed to do something</div><ul class=\"examples\"><li><strong><em>take the trouble to do something</strong> (=make a special effort to do something): The teacher took the trouble to learn all our names on the first day.</em></li><li><em>They’ve obviously gone to a lot of trouble to arrange everything.</em></li><li><strong><em>save somebody the trouble (of doing something)</strong>: If you’d asked me first, I could have saved you the trouble.</em></li><li><em>I find that making my own clothes is more trouble than it’s worth (=takes too much time and effort).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>no trouble</strong> used to say politely that you are happy to do something for someone:</div><ul class=\"examples\"><li><em>‘Are you sure you don’t mind?’ ‘It’s no trouble.’</em></li><li><em>The kids were no trouble (=used to say you were happy to look after them because they were well-behaved).</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[health]</strong> <span class=\"gram\">[uncountable]</span> a problem that you have with your health: ► see thesaurus at illness</div><ul class=\"examples\"><li><em>He has trouble with his breathing.</em></li><li><strong><em>heart/stomach/skin etc trouble</strong>: He suffers from back trouble.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[machine/system]</strong> <span class=\"gram\">[uncountable]</span> when something is wrong with a machine, vehicle, or system:</div><ul class=\"examples\"><li><em>engine trouble</em></li><li><strong><em>trouble with</strong>: He had to retire from the race because of trouble with the gearbox.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[worry]</strong> if a problem troubles you, it makes you feel worried or upset:</div><ul class=\"examples\"><li><em>There is one thing that’s been troubling me.</em></li><li><em>They have been deeply troubled by the allegations.</em></li><li><em>His conscience troubled him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[inconvenience]</strong> <em>formal</em> to say something or ask someone to do something which may use or waste their time or upset them <em>SYN bother</em>:</div><ul class=\"examples\"><li><em>I promise not to trouble you again.</em></li><li><strong><em>trouble somebody with something</strong>: I don’t want to trouble the doctor with it. / I won’t trouble you with the details.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>may I trouble you?/sorry to trouble you</strong> <em>spoken</em> <em>formal</em> used when politely asking someone to do something for you or give you something:</div><ul class=\"examples\"><li><em>Sorry to trouble you, but could you tell me the way to the station, please?</em></li><li><em>May I trouble you for the salt?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>don’t trouble yourself</strong> <em>spoken</em> used to politely tell someone not to help you:</div><ul class=\"examples\"><li><em>Please don’t trouble yourself. I can manage.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>not trouble to do something</strong> to not do something because it needs too much effort: RegisterIn everyday English, people usually say not bother to do something rather than not trouble to do something:· They didn’t bother to ask me what I thought.</div><ul class=\"examples\"><li><em>They never troubled to ask me what I would like.</em></li><li><em>Luke didn’t trouble to hide his disgust.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[health problem]</strong> if a medical problem troubles you, it causes you pain or problems:</div><ul class=\"examples\"><li><em>He is still being troubled by an ankle injury.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[cause problems]</strong> to cause someone problems or difficulties:</div><ul class=\"examples\"><li><em>They look good enough to trouble most teams in the competition.</em></li></ul></div></div>","7211":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> troub‧led</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrʌbəld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> worried or anxious ► see thesaurus at worried</div><ul class=\"examples\"><li><strong><em>troubled face/eyes/look</em></strong></li><li><em>Benson looked troubled when he heard the news.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> having many problems:</div><ul class=\"examples\"><li><em>These are troubled times for the coal industry.</em></li><li><em>the troubled electronics company</em></li><li><strong><em>troubled marriage/relationship</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>troubled waters</strong> a difficult situation, especially where there is a lot of disagreement and problems:</div><ul class=\"examples\"><li><em>We don’t want to enter the troubled waters of race and religion.</em></li><li><strong><em>pour oil on troubled waters</strong> (=try to make an angry situation calmer)</em></li></ul></div>","7212":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> troub‧le‧some</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrʌbəlsəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">causing problems, in an annoying way:</div><ul class=\"examples\"><li><em>a troublesome child</em></li><li><em>troublesome itching</em></li></ul></div>","7213":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trou‧sers</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtraʊzəz $ -ərz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of clothing that covers the lower half of your body, with a separate part fitting over each leg SYN pants<em>American English</em>:</div><ul class=\"examples\"><li><em>His trousers were slightly too short.</em></li><li><em>I need a new pair of trousers for work.</em></li></ul></div>","7214":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /traʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (plural trout) <span class=\"gram\">[countable, uncountable]</span> a common river-fish, often used for food, or the flesh of this fish</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>old trout</strong> <em>British English</em> <em>spoken</em> an unpleasant or annoying old person, especially a woman</div></div>","7215":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /truːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an agreement between enemies to stop fighting or arguing for a short time, or the period for which this is arranged → ceasefire:</div><ul class=\"examples\"><li><em>They agreed to call a truce.</em></li><li><strong><em>truce with/between</strong>: There was an uneasy truce between Alex and Dave over dinner.</em></li></ul></div>","7216":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trʌk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large road vehicle used to carry goods SYN lorry<em>British English</em>:</div><ul class=\"examples\"><li><em>a truck driver</em></li><li><strong><em>pick-up/fork-lift/delivery etc truck</strong> (=large vehicles used for particular purposes): His car was taken away on the back of a breakdown truck.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> a railway vehicle that is part of a train and carries goods SYN car<em>American English</em>:</div><ul class=\"examples\"><li><em>coal trucks</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a simple piece of equipment on wheels used to move heavy objects</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>have/hold/want no truck with somebody/something</strong> to refuse to be involved with someone or to accept an idea</div></div>","7217":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /truː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not false]</strong> based on facts and not imagined or invented <em>OPP false</em> → truly, truth → too good to be true at good1(24), → not ring true at ring2(5)</div><ul class=\"examples\"><li><strong><em>it is true (that)</strong>: It’s not true that I’m going to marry him.</em></li><li><em>No, honestly, it’s a true story.</em></li><li><em>Students decide if statements are true or false.</em></li><li><strong><em>true of</strong>: The same is true of all political parties.</em></li><li><strong><em>true for</strong>: This is especially true for old people.</em></li><li><em>It’s generally true to say that fewer people are needed nowadays.</em></li><li><em>The results appear to hold true (=still be correct) for other countries.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[real]</strong> <span class=\"gram\">[only before noun]</span> the true nature of something is its real nature, which may be hidden or not known <em>SYN real</em></div><ul class=\"examples\"><li><strong><em>true value/cost etc (of something)</strong>: The house was sold for only a fraction of its true value.</em></li><li><em>We need to understand the true extent of the problem.</em></li><li><strong><em>true nature/meaning/identity etc (of something)</strong>: She wasn’t aware of the true nature of their relationship.</em></li><li><em>She managed to conceal her true feelings.</em></li><li><em>After a couple of days she showed her true self (=real character).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[admitting something]</strong> <em>especially spoken</em> used when you are admitting that something is correct, but saying that something else, often opposite, is also correct:</div><ul class=\"examples\"><li><em>‘He’s very hard-working.’ ‘True, but I still don’t think he’s the right man for the job.’</em></li><li><strong><em>it is true (that)</strong>: It is true that there have been improvements in some areas.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[proper]</strong> <span class=\"gram\">[only before noun]</span> having all the qualities which a type of thing or person should have: ► see thesaurus at genuine</div><ul class=\"examples\"><li><em>The heroine finally finds true love.</em></li><li><em>She’s been a true friend to me.</em></li><li><em>It’s an amateur sport in the true sense of the word (=with the exact meaning of this word).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>come true</strong> if wishes, dreams etc come true, they happen in the way that someone has said or hoped that they would: → be a dream come true at dream1(5)</div><ul class=\"examples\"><li><em>The prediction seems to have come true.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[loyal]</strong> faithful and loyal to someone, whatever happens</div><ul class=\"examples\"><li><strong><em>true to</strong>: Throughout the whole ordeal, she remained true to her husband.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>true to form/type</strong> used to say that someone is behaving in the bad way that you expect them to:</div><ul class=\"examples\"><li><em>True to form, Henry turned up late.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>true to your word/principles etc</strong> behaving in the way you said you would or according to principles which you believe in:</div><ul class=\"examples\"><li><em>He was true to his word and said nothing about it to Lisa.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>true to life/true-to-life</strong> a book, play, description etc that is true to life seems very real and natural <em>SYN realistic</em>:</div><ul class=\"examples\"><li><em>The film is frighteningly true-to-life and very funny.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>(all/only) too true</strong> used to say that you know something is true, when you do not like it:</div><ul class=\"examples\"><li><em>‘It’s not as easy as it looks.’ ‘Too true!’</em></li><li><em>It is only too true that people are judged by their accents.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[straight/level]</strong> <span class=\"gram\">[not before noun]</span> <em>technical</em> fitted, placed, or formed in a way that is perfectly flat, straight, correct etc:</div><ul class=\"examples\"><li><em>If the door’s not true, it won’t close properly.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>somebody’s aim is true</strong> if your aim is true, you hit the thing that you were throwing or shooting at</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>your true colours</strong> if you show your true colours, you do something which shows what your real attitudes and qualities are, especially when they are bad</div><ul class=\"examples\"><li><strong><em>show/reveal your true colours</strong>: He was forced to reveal his true colours when asked how he would vote.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>(there’s) many a true word spoken in jest</strong> <em>old-fashioned</em> used to say that when people are joking they sometimes say things that are true and important</div></div>","7218":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tru‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtruːli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[+adjective/adverb]</span> used to emphasize that the way you are describing something is really true <em>SYN really</em>:</div><ul class=\"examples\"><li><em>His work is truly original.</em></li><li><em>Fawcett was a truly remarkable man.</em></li><li><em>a truly great work of medieval literature</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> sincerely:</div><ul class=\"examples\"><li><em>I am truly sorry.</em></li><li><em>She truly believed he was innocent.</em></li><li><em>I can truly say I’ve never enjoyed myself so much.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> in an exact or correct way:</div><ul class=\"examples\"><li><em>Is it a truly representative sample?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>well and truly</strong> <em>especially spoken</em> completely:</div><ul class=\"examples\"><li><em>We were well and truly beaten.</em></li><li><em>The party was well and truly over.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>really and truly</strong> <em>British English</em> <em>spoken</em> used to emphasize that something is definitely or completely true:</div><ul class=\"examples\"><li><em>I couldn’t believe we were really and truly going at last.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>yours truly</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used at the end of a letter, before the signature</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>informal</em> used humorously to mean yourself:</div><ul class=\"examples\"><li><em>So, yours truly was left to clean up.</em></li></ul></div>","7219":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trum‧pet</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrʌmpɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable]</span> a musical instrument that you blow into, which consists of a curved metal tube that is wide at the end, and three buttons you press to change the notes → blow your own trumpet at blow1(19)</div></div>","7220":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trʌŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[tree]</strong> the thick central woody stem of a tree:</div><ul class=\"examples\"><li><em>He left his bicycle leaning against a tree trunk.</em></li><li><strong><em>trunk of</strong>: the trunk of an old oak tree</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[car]</strong> <em>American English</em> the part at the back of a car where you can put bags, tools etc SYN boot<em>British English</em>:</div><ul class=\"examples\"><li><em>Put your suitcase in the trunk.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[elephant]</strong> the very long nose of an elephant</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[clothes]</strong> swim trunks<em>American English</em>, swimming trunks<em>British English</em> <span class=\"gram\">[plural]</span> a piece of clothing like very short trousers, worn by men for swimming</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[box]</strong> a very large box made of wood or metal, in which clothes, books etc are stored or packed for travel</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[body]</strong> <em>technical</em> the main part of your body, not including your head, arms, or legs <em>SYN torso</em></div></div>","7221":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /trʌst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[belief]</strong> <span class=\"gram\">[uncountable]</span> a strong belief in the honesty, goodness etc of someone or something: → breach of trust at breach1(3)</div><ul class=\"examples\"><li><em>At first there was a lack of trust between them.</em></li><li><em>an agreement made on the basis of mutual trust (=when people trust each other)</em></li><li><strong><em>put/place your trust in somebody/something</strong>: You shouldn’t put your trust in a man like that.</em></li><li><em>You betrayed your father’s trust (=did something bad even though he trusted you).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[organization]</strong> <span class=\"gram\">[countable usually singular]</span> an organization or group that has control over money that will be used to help someone else:</div><ul class=\"examples\"><li><em>a charitable trust</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[financial arrangement]</strong> <span class=\"gram\">[countable, uncountable]</span> an arrangement by which someone has legal control of your money or property, either until you are old enough to use it or to invest it for you: → trust fund, unit trust</div><ul class=\"examples\"><li><em>The money your father left you will be held in trust until you are 21.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>take something on trust</strong> to believe that something is true without having any proof:</div><ul class=\"examples\"><li><em>I just had to take it on trust that he would deliver the money.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>position of trust</strong> a job or position in which you have been given the responsibility of making important decisions</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[companies]</strong> <span class=\"gram\">[countable]</span> <em>especially American English</em> a group of companies that illegally work together to reduce competition and control prices:</div><ul class=\"examples\"><li><em>anti-trust laws</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[people]</strong> to believe that someone is honest or will not do anything bad or wrong <em>OPP distrust</em> <em>, mistrust</em>:</div><ul class=\"examples\"><li><em>I just don’t trust him.</em></li><li><strong><em>trust somebody to do something</strong>: Can they be trusted to look after the house? / I didn’t trust myself not to say something rude, so I just kept quiet.</em></li><li><strong><em>trust somebody completely/implicitly</strong>: He was a good driver and I trusted him implicitly.</em></li><li><strong><em>not trust somebody an inch/not trust somebody as far as you can throw them</strong> (=not trust someone at all)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[facts/judgment]</strong> to be sure that something is correct or right <em>SYN believe in</em> <em>, rely on</em>:</div><ul class=\"examples\"><li><em>Can we trust these statistics?</em></li><li><em>I trust his judgement completely.</em></li><li><em>Trust your instincts (=do what you feel is the right thing)!</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[things]</strong> to be sure that something will work properly <em>SYN rely on</em>:</div><ul class=\"examples\"><li><em>Not trusting her voice, she shook her head.</em></li><li><strong><em>trust something to do something</strong>: You can’t trust the trains to run on time. / He sat down suddenly, as if he didn’t trust his legs to support him.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>trust you/him/them etc (to do something)!</strong> <em>spoken</em> used to say that someone has behaved in a bad or stupid way that is typical of them:</div><ul class=\"examples\"><li><em>Trust you to write down the wrong number!</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>I trust (that)</strong> <em>spoken</em> <em>formal</em> used to say politely that you hope something is true:</div><ul class=\"examples\"><li><em>I trust that from now on you will take greater precautions.</em></li></ul></div></div>","7222":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trust‧ee</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌtrʌˈstiː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who has control of money or property that is in a trust for someone else</div><div class=\"sense\"><span class=\"snum\">2</span> a member of a group that controls the money of a company, college, or other organization</div></div>","7223":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> trust‧wor‧thy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtrʌstˌwɜːði $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">able to be trusted and depended on</div></div>","7224":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /truːθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[true facts]</strong> <strong>the truth</strong> the true facts about something, rather than what is untrue, imagined, or guessed <em>OPP lie</em> <em>, falsehood</em> <em>, untruth</em>:</div><ul class=\"examples\"><li><em>How do we know you’re telling us the truth?</em></li><li><strong><em>truth about</strong>: She hoped to find out the truth about her family.</em></li><li><strong><em>truth behind</strong>: We’ll never know the truth behind what happened.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[being true]</strong> <span class=\"gram\">[uncountable]</span> the state or quality of being true</div><ul class=\"examples\"><li><strong><em>truth in</strong>: There was some truth in the accusations.</em></li><li><strong><em>grain/element of truth</strong> (=small amount of truth): There wasn’t a grain of truth in what he said.</em></li><li><em>There was an element of truth (=a small amount of truth) in what he said.</em></li><li><em>There is no truth in the rumour.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[important ideas]</strong> <span class=\"gram\">[countable usually plural]</span> <em>formal</em> an important fact or idea that is accepted as being true:</div><ul class=\"examples\"><li><em>The experience has taught us some basic truths.</em></li><li><strong><em>an unhappy/unpleasant/unwelcome truth</strong> (=an unpleasant or disappointing fact): It is in his interest to hide unhappy truths about his agency’s performance.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in truth</strong> in fact <em>SYN really</em>:</div><ul class=\"examples\"><li><em>Early independence leaders were in truth little better than rebels.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>if (the) truth be known/told</strong> used when telling someone the real facts about a situation, or your real opinion:</div><ul class=\"examples\"><li><em>If the truth be known, I felt a little left out at school.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>to tell (you) the truth</strong> <em>spoken</em> used when giving your personal opinion or admitting something:</div><ul class=\"examples\"><li><em>To tell the truth, I was frightened to death.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>nothing could be further from the truth</strong> used to say that something is definitely not true</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>the truth will out</strong> <em>old-fashioned</em> used to say that even if you try to stop people from knowing something, they will find out in the end</div></div>","7225":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /traɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle tried, present participle trying, third person singular tries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[attempt]</strong> <span class=\"gram\">[intransitive, transitive]</span> to take action in order to do something that you may not be able to do:</div><ul class=\"examples\"><li><em>Let’s have a rest and then we’ll try again.</em></li><li><strong><em>try to do something</strong>: He tried to control his voice. / She was trying not to cry.</em></li><li><strong><em>try and do something</strong>: Try and take some form of daily exercise.</em></li><li><strong><em>try hard/desperately (to do something)</strong> (=make a lot of effort to do something): She dabbed at her face and tried hard not to sniff.</em></li><li><em>I tried everything to lose weight with no success.</em></li><li><strong><em>try your best/hardest (to do something)</strong> (=make as much effort as possible to do something): I tried my best to comfort her.</em></li><li><em>I tried and tried (=kept making an effort) and eventually I was offered a job.</em></li><li><em>Try as he might (=as hard as he could), he could not get the incident out of his mind.</em></li><li><strong><em>it wasn’t for lack/want of trying</strong> (=used to say that if someone does not achieve something it is not because they have not tried): They didn’t get any goals, but it wasn’t for lack of trying.</em></li><li><strong><em>you couldn’t do something if you tried</strong> (=used to say that someone does not have the skill or ability to do something): She couldn’t speak French if she tried.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[test/use]</strong> <span class=\"gram\">[transitive]</span> to do or use something for a short while to discover if it is suitable, successful, enjoyable etc:</div><ul class=\"examples\"><li><em>It works really well – you should try it.</em></li><li><strong><em>try doing something</strong>: They decided they would try living in America for a while. / Try logging off and logging on again.</em></li><li><strong><em>try something new/different</strong> (=do or use something that is different from what you usually do or use): If I’m going out for a meal, I prefer to try something different.</em></li><li><strong><em>try something on somebody/something</strong>: We tried the machine on hardwood and soft wood.</em></li><li><strong><em>try somebody on something</strong>: Petra’s trying the baby on solid foods.</em></li><li><strong><em>try something for size</strong> (=put on a piece of clothing or test something to find out if it is the correct size or suitable): Always try a sleeping bag for size before you buy it.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[food/drink]</strong> <span class=\"gram\">[transitive]</span> to taste food or drink to find out if you like it <em>SYN taste</em>:</div><ul class=\"examples\"><li><em>Would you like to try some crisps?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[try to find somebody/something]</strong> <span class=\"gram\">[intransitive, transitive]</span> to go to a place or person, or call them, in order to find something or someone:</div><ul class=\"examples\"><li><em>Sorry, he’s not in. Would you like to try again later?</em></li><li><em>Let’s try Mouncy Street. He could be there.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[door/window]</strong> <span class=\"gram\">[transitive]</span> to attempt to open a door, window etc in order to see if it is locked:</div><ul class=\"examples\"><li><em>She tried the door and it opened.</em></li><li><em>He tried the handle but the door was locked.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[law]</strong> <span class=\"gram\">[transitive]</span> to examine and judge a legal case, or someone who is thought to be guilty of a crime in a court → trial GRAMMAR Try is often passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be tried for something</strong>: He was tried for attempting to murder his wife.</em></li><li><em>The defence argued that a regional court was not competent to try their case.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>try somebody’s patience</strong> to make someone feel impatient → trying:</div><ul class=\"examples\"><li><em>The programs take too long to load and try the patience of young pupils.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>try your hand at something</strong> to try a new activity in order to see whether it interests you or whether you are good at it:</div><ul class=\"examples\"><li><em>I tried my hand at water-skiing for the first time.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>try your luck</strong> to try to achieve something or get something you want, usually by taking a risk:</div><ul class=\"examples\"><li><em>After the war my father went to Canada to try his luck at farming.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>try it on (with somebody)</strong> <em>British English</em> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to behave badly in order to find out how bad you can be before people become angry:</div><ul class=\"examples\"><li><em>She is naughty, that one. She tries it on with me sometimes!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to attempt to start a sexual relationship with someone:</div><ul class=\"examples\"><li><em>When I came back in, one of the men was trying it on with my wife!</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural tries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an attempt to do something:</div><ul class=\"examples\"><li><em>She didn’t manage to break the record, but it was a good try.</em></li><li><em>‘You really think you can do that?’ ‘I’m going to have a try.’</em></li><li><em>‘What are the chances for getting tickets now?’ ‘I guess I could give it a try.’</em></li><li><em>It might sound a ludicrous excuse but he thought it was worth a try.</em></li><li><strong><em>on the first/second etc try</strong>: Only half the students passed the test on their first try.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a test of something to see if it is suitable or successful or to find out if you like it:</div><ul class=\"examples\"><li><em>I decided to give modelling a try.</em></li><li><em>Wines from Apulia’s ancient vineyards are well worth a try.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> four points won by putting the ball on the ground behind the opponents’ goal line in rugby</div></div></div>","7226":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> try‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtraɪ-ɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">annoying or difficult in a way that makes you feel worried, tired etc:</div><ul class=\"examples\"><li><em>That child is very trying.</em></li><li><em>The beginning of the show is often a trying time because of latecomers.</em></li><li><em>They do the best they can in trying circumstances.</em></li></ul></div>","7227":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tʌb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[container]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a small container made of paper or plastic with a lid, in which food is bought or stored</div><ul class=\"examples\"><li><strong><em>tub of</strong>: a tub of ice cream</em></li><li><em>a margarine tub</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> an open container that is usually round, used for washing, storing things in etc:</div><ul class=\"examples\"><li><em>trees growing in tubs</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[amount]</strong> (also tubful) the amount of liquid, food etc that a tub can contain</div><ul class=\"examples\"><li><strong><em>tub of</strong>: We ate a tub of ice cream.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[bath]</strong> <em>American English</em> a large container in which you sit to wash yourself <em>SYN bathtub</em>:</div><ul class=\"examples\"><li><em>I had a long soak in the tub.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[boat]</strong> <em>British English</em> <em>informal</em> an old boat that travels slowly</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[person]</strong> <strong>tub of lard</strong> <em>informal</em> <em>not polite</em> someone who is short and fat</div></div>","7228":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tjuːb $ tuːb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[pipe for liquid]</strong> <span class=\"gram\">[countable]</span> a round pipe made of metal, glass, rubber etc, especially for liquids or gases to go through → inner tube, test tube</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a long hollow object that is usually round:</div><ul class=\"examples\"><li><em>pasta tubes</em></li><li><em>a toilet roll tube</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[container]</strong> <span class=\"gram\">[countable]</span> a narrow container made of plastic or soft metal and closed at one end, that you press between your fingers in order to push out the soft substance that is inside:</div><ul class=\"examples\"><li><em>a tube of toothpaste</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[in your body]</strong> <span class=\"gram\">[countable]</span> a tube-shaped part inside your body:</div><ul class=\"examples\"><li><em>the bronchial tubes</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[trains]</strong> <strong>the tube</strong> <em>British English</em> the system of trains that run under the ground in London SYN subway<em>American English</em></div><ul class=\"examples\"><li><strong><em>take/catch the tube</strong>: Take the tube to Acton.</em></li><li><em>a tube station</em></li><li><strong><em>by tube</strong>: It’s best to travel by tube.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>go down the tubes</strong> <em>informal</em> if a situation goes down the tubes, it quickly becomes ruined or spoiled:</div><ul class=\"examples\"><li><em>When Moira turned up, Tess could see all her good work going down the tubes.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[television]</strong> <strong>the tube</strong> <em>American English</em> <em>spoken</em> the television:</div><ul class=\"examples\"><li><em>What’s on the tube tonight?</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[electrical equipment]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> the part of a television that produces the picture on the screen <em>SYN cathode ray tube</em></div></div>","7229":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tʌk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to push something, especially the edge of a piece of cloth or paper, into or behind something so that it looks tidier or stays in place</div><ul class=\"examples\"><li><strong><em>tuck something in</strong>: Jack tucked his shirt in.</em></li><li><strong><em>tuck something into/under/behind etc something</em></strong></li><li><em>She tucked an unruly lock of hair behind her ear.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to put something into a small space, especially in order to protect, hide, carry, or hold it</div><ul class=\"examples\"><li><strong><em>tuck something behind/under/into etc something</strong>: Giles was tucking his pile of books under his arm. / He took the glasses off and tucked them in his pocket.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to put a tuck (=special fold) in a piece of clothing</div></div>","7230":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> Tues‧day</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtjuːzdi, -deɪ $ ˈtuːz-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the day between Monday and Wednesday</div><ul class=\"examples\"><li><strong><em>on Tuesday</strong>: The sale starts on Tuesday.</em></li><li><em>I’ll see you Tuesday. </em>American English**</li><li><strong><em>Tuesday morning/afternoon etc</strong>: He first heard the news on Tuesday evening.</em></li><li><strong><em>last Tuesday</strong>: It was my birthday last Tuesday.</em></li><li><strong><em>this Tuesday</strong>: I’m sorry I can’t make it this Tuesday.</em></li><li><strong><em>next Tuesday</strong> (=Tuesday of next week): Shall we meet next Tuesday?</em></li><li><strong><em>a Tuesday</strong> (=one of the Tuesdays in the year): We left Miami on a Tuesday.</em></li></ul></div>","7231":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tʌɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle tugged, present participle tugging)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to pull with one or more short, quick pulls: ► see thesaurus at pull</div><ul class=\"examples\"><li><em>The woman gently tugged his arm.</em></li><li><strong><em>tug at/on something</strong>: Joe was tugging at her sleeve.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> <em>British English</em> to pull a piece of clothing quickly onto your body</div><ul class=\"examples\"><li><strong><em>tug something on</strong>: Alice was tugging on a sweater.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>tug at somebody’s heart/heartstrings</strong> <em>written</em> to make someone feel sympathy for someone or something</div></div>","7232":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tu‧i‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /tjuˈɪʃən $ tu-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> teaching, especially in small groups:</div><ul class=\"examples\"><li><em>I had to have extra tuition in maths.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em>, tuition fees<em>British English</em> the money you pay for being taught:</div><ul class=\"examples\"><li><em>When I started college, tuition was $350 a quarter.</em></li></ul></div>","7233":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tum‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtʌmbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[always + adverb/preposition]</span> to fall down quickly and suddenly, especially with a rolling movement</div><ul class=\"examples\"><li><strong><em>tumble over/backwards/down</strong>: She lost her balance and tumbled backwards. / A few stones came tumbling down the cliff.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[always + adverb/preposition]</span> to move in an uncontrolled way</div><ul class=\"examples\"><li><strong><em>tumble into/through/out etc</strong>: We tumbled out into the street.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if prices or figures tumble, they go down suddenly and by a large amount:</div><ul class=\"examples\"><li><em>Oil prices have tumbled.</em></li><li><strong><em>tumble to</strong>: Mortgage rates tumbled to their lowest level for 25 years.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[always + adverb/preposition]</span> <em>literary</em> if someone’s hair tumbles down, it is long, thick, and curly:</div><ul class=\"examples\"><li><em>Her long dark hair tumbled over her shoulders.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>literary</em> if words tumble out of someone’s mouth, they speak very quickly because they are excited or upset</div><ul class=\"examples\"><li><strong><em>tumble out/over</strong>: The words tumbled out as if he hardly knew what to say first.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[always + adverb/preposition]</span> if water tumbles somewhere, it flows there quickly:</div><ul class=\"examples\"><li><em>A narrow stream tumbled over the rocks.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>come tumbling down</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if something comes tumbling down, it falls suddenly to the ground:</div><ul class=\"examples\"><li><em>Removing the debris could cause the rest of the building to come tumbling down.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a system, problem etc comes tumbling down, it suddenly stops working or existing:</div><ul class=\"examples\"><li><em>In the last year, barriers have come tumbling down.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <em>American English</em> to do tumbling</div></div>","7234":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tum‧my</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtʌmi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural tummies)</span></div><div class=\"entry-body\"><div class=\"sense\">stomach – used especially by or to children:</div><ul class=\"examples\"><li><em>He was up all night with tummy ache.</em></li><li><strong><em>tummy bug/upset<em>British English</em></strong> (=an illness of the stomach that makes you vomit)</em></li></ul></div>","7235":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tu‧mour</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtjuːmə $ ˈtuːmər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a mass of diseased cells in your body that have divided and increased too quickly:</div><ul class=\"examples\"><li><em>a brain tumour</em></li><li><strong><em>malignant/benign tumour</strong> (=caused by or not caused by cancer)</em></li></ul></div>","7236":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tu‧na</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtjuːnə $ ˈtuːnə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural tuna)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a large sea fish caught for food</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> (also tuna fish) the flesh of this fish, usually sold cooked in tins</div></div>","7237":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tjuːn $ tuːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a series of musical notes that are played or sung and are nice to listen to <em>SYN melody</em>: ► see thesaurus at music</div><ul class=\"examples\"><li><em>That’s a nice tune.</em></li><li><em>She sang some old classics and a few new tunes.</em></li><li><strong><em>to the tune of something</strong> (=using the same tune as another song): The song was sung to the tune of ‘Amazing Grace’.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>in tune</strong> playing or singing the correct musical note:</div><ul class=\"examples\"><li><em>They sang perfectly in tune.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>out of tune</strong> playing or singing higher or lower than the correct musical note:</div><ul class=\"examples\"><li><em>Greg’s bass guitar was out of tune.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in tune with somebody/something, out of tune with somebody/something</strong> able or unable to realize, understand, or agree with what someone else thinks or wants:</div><ul class=\"examples\"><li><em>The industry is changing in tune with changing demand.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>to the tune of $1,000/£2 million etc</strong> <em>informal</em> used to emphasize how large an amount or number is:</div><ul class=\"examples\"><li><em>Canada is funding the programme to the tune of $30 million.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make a musical instrument play at the right pitch:</div><ul class=\"examples\"><li><em>Someone’s coming tomorrow to tune the piano.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also tune up) to make small changes to an engine so that it works as well as possible</div><div class=\"sense\"><span class=\"snum\">3</span> to make a radio or television receive broadcasts from a particular place → stay tuned at stay1(8)</div><ul class=\"examples\"><li><strong><em>tune something to something</strong>: The radio was tuned to a classical station.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>finely/highly tuned</strong> finely tuned feelings, senses, or systems are extremely sensitive and able to react quickly</div><ul class=\"examples\"><li><strong><em>be tuned to something</strong>: a species finely tuned to life in the desert</em></li></ul></div></div>","7238":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tun‧nel</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtʌnl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a passage that has been dug under the ground for cars, trains etc to go through:</div><ul class=\"examples\"><li><em>a railway tunnel</em></li><li><em>the Channel Tunnel (=between England and France)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a passage under the ground that animals have dug to live in</div></div>","7239":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tur‧bu‧lence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɜːbjələns $ ˈtɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> irregular and violent movements of air or water that are caused by the wind</div><div class=\"sense\"><span class=\"snum\">2</span> a political or emotional situation that is very confused <em>SYN turmoil</em>:</div><ul class=\"examples\"><li><em>A period of political turbulence followed the civil war.</em></li></ul></div>","7240":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tur‧bu‧lent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɜːbjələnt $ ˈtɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a turbulent situation or period of time is one in which there are a lot of sudden changes:</div><ul class=\"examples\"><li><em>the turbulent times of the French Revolution</em></li><li><em>He has had a turbulent political career.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> turbulent air or water moves around a lot:</div><ul class=\"examples\"><li><em>the dark turbulent waters of the river</em></li></ul></div>","7241":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɜːf $ tɜːrf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural turfs or turves)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> <em>especially British English</em> a surface that consists of soil with grass on top, or an artificial surface that looks like this:</div><ul class=\"examples\"><li><em>soft green turf</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>British English</em> a square piece of turf cut out of the ground</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the turf</strong> the sport of horse racing, or the track on which horses race</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> <em>informal</em> an area that you think of as being your own:</div><ul class=\"examples\"><li><em>How vigorously will the local companies defend their turf?</em></li><li><strong><em>somebody’s own/home turf</strong> (=the place that someone comes from or lives in): We beat Canada on their home turf.</em></li><li><strong><em>turf war/battle</strong> (=a fight or argument over the areas or things you think belong to you): turf wars among government bureaucracies</em></li></ul></div>","7242":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tur‧key</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɜːki $ ˈtɜːrki/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a bird that looks like a large chicken and is often eaten at Christmas and at Thanksgiving</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the meat from a turkey eaten as food:</div><ul class=\"examples\"><li><em>roast turkey</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>American English</em> <em>informal</em> an unsuccessful film or play</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>talk turkey</strong> <em>especially American English</em> <em>informal</em> to talk seriously about details, especially in business</div></div>","7243":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tur‧moil</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɜːmɔɪl $ ˈtɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a state of confusion, excitement, or anxiety</div><ul class=\"examples\"><li><strong><em>political/emotional/economic/religious etc turmoil</strong>: the prospect of another week of political turmoil</em></li><li><strong><em>in (a) turmoil</strong>: Ashley gazed at him, her thoughts in turmoil.</em></li></ul></div>","7244":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tɜːn $ tɜːrn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[your body]</strong> <span class=\"gram\">[intransitive, transitive]</span> to move your body so that you are looking in a different direction → twist:</div><ul class=\"examples\"><li><em>Ricky turned and walked away.</em></li><li><em>She turned her head in surprise.</em></li><li><strong><em>turn around/round/away</strong>: Dan turned away, hiding the fear in his eyes.</em></li><li><strong><em>turn (your head/face) to do something</strong>: He turned around to look at Kim. / ‘No,’ she said, turning her head to see David’s reaction.</em></li><li><em>Brigitte glared at him, turned on her heel (=turned away suddenly because of anger), and stomped out of the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[object]</strong> <span class=\"gram\">[transitive usually + adverb/preposition]</span> to move something so that it is pointing or aiming in a different direction</div><ul class=\"examples\"><li><strong><em>turn something around/over/upside down etc</strong>: You may turn over your exam papers now.</em></li><li><strong><em>turn something on something/somebody</strong>: The firemen turned their hoses on the blaze.</em></li><li><strong><em>turn something to face something/somebody</strong>: Could you turn your chairs to face this way?</em></li><li><strong><em>turn a/the page</strong> (=move a page in a book over so that you can read the next page)</em></li><li><strong><em>turn something down/up</strong>: He turned down the corner of the sheet to peep at the baby.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[direction]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive, transitive]</span> to go in a new direction when you are walking, driving etc, or to make the vehicle you are using do this:</div><ul class=\"examples\"><li><em>I watched until he turned the corner.</em></li><li><strong><em>turn left/right</strong>: Turn left at the church.</em></li><li><strong><em>turn into/onto/down etc</strong>: She cycled up the street and turned into Long Road. / Turning the car around, we headed home.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive]</span> if a road, river etc turns, it curves and starts to go in a new direction:</div><ul class=\"examples\"><li><em>Further on, the river turns east.</em></li><li><em>The road turns sharply at the top of the hill.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[move around central point]</strong> <span class=\"gram\">[intransitive, transitive]</span> to move around a central or fixed point, or to make something move in this way:</div><ul class=\"examples\"><li><em>The wheels turned slowly, then picked up speed.</em></li><li><em>For some reason, the key wouldn’t turn.</em></li><li><strong><em>turn the handle/knob/key/tap etc</strong>: She gently turned the handle of the bedroom door.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[change]</strong> <span class=\"gram\">[linking verb, transitive]</span> to start to have a different quality, or to make something do this ► see thesaurus at become GRAMMAR: Linking verbsTurn is a linking verb in this meaning. It links the subject of the sentence with an adjective: · His face turned pale.· Their relationship turned sour.</div><ul class=\"examples\"><li><strong><em>turn (something) red/blue/white etc</strong>: Rose’s hair was already turning grey. / In October the leaves turn orange and yellow. / The sun had turned the sky a glowing pink.</em></li><li><strong><em>the weather turns cold/nasty etc</strong> (also<strong>it turns cold/nasty etc)</strong>: Then it turned cold and started to rain.</em></li><li><strong><em>turn nasty/mean/violent etc</strong> (=suddenly become angry, violent etc): The police are worried that the situation could turn violent.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[attention/thoughts]</strong> <span class=\"gram\">[intransitive, transitive]</span> to start to think about, deal with, look at etc a particular person, thing, or subject, instead of what you were thinking about etc before</div><ul class=\"examples\"><li><strong><em>turn your attention/thoughts/efforts etc to something/somebody</strong>: Many investors have turned their attention to opportunities abroad. / Phil turned his gaze towards the older man.</em></li><li><strong><em>turn to/towards etc something</strong>: As usual, the conversation turned back to her children. / Now is the time of year when thoughts turn in the direction of summer holidays. / Next the Senator turned to education.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>turn your back (on somebody/something)</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to refuse to help, support, or be involved with someone or something:</div><ul class=\"examples\"><li><em>How can you turn your back on your own mother?</em></li><li><em>In his twenties he turned his back on his Catholic faith.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to turn so that your back is pointing towards someone or something, and you are not looking at them:</div><ul class=\"examples\"><li><em>Angrily, she turned her back on him.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[age/time]</strong> <span class=\"gram\">[transitive]</span> to become a particular age, or to reach a particular time</div><ul class=\"examples\"><li><strong><em>somebody turns 15/20/40 etc</strong>: My son’s just turned 18.</em></li><li><strong><em>it’s turned 2 o&#x27;clock/5/midday etc</strong>: It’s just turned three.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>turn something inside out</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to pull a piece of clothing, bag etc so that the inside is facing out:</div><ul class=\"examples\"><li><em>Turn the sweater inside out before you wash it.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> (also turn something upside down) to search everywhere for something, in a way that makes a place very untidy:</div><ul class=\"examples\"><li><em>Thieves had turned the house upside down.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> (also turn something upside down/turn something on its head) to completely change the way that something is done, organized, thought about etc:</div><ul class=\"examples\"><li><em>New approaches to marketing turn old practices upside down.</em></li><li><em>Her opinion of him had been turned on its head.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>have turned the corner</strong> to start to improve after going through a difficult period or experience:</div><ul class=\"examples\"><li><em>The manager of the hotel chain claims that they have turned the corner.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[make/let go out]</strong> <span class=\"gram\">[transitive]</span> to make or let someone or something go out from where they are</div><ul class=\"examples\"><li><strong><em>turn somebody/something out/outside/into etc (something)</strong>: Turn the dough out onto a lightly floured board. / There are some criminals who cannot be turned loose onto the streets.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[tide]</strong> <span class=\"gram\">[intransitive]</span> if the tide turns, the sea starts to come in or go out again</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>[change development]</strong> <span class=\"gram\">[intransitive, transitive]</span> if something such as a war, situation, game of sport etc turns, or someone turns it, something happens to change the way it is developing:</div><ul class=\"examples\"><li><em>Mills turned the game by scoring twice.</em></li><li><em>The victory turned the tide of the war in North Africa.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>turn traitor</strong> to be disloyal to a person, group, or idea that you have strongly supported before</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>turn your ankle</strong> to twist your ankle in a way that injures it <em>SYN sprain</em>:</div><ul class=\"examples\"><li><em>Wright turned his ankle in the first minutes of the game.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>an actor turned politician/a housewife turned author etc</strong> someone who has done one job and then does something completely different → poacher turned gamekeeper at poacher</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>turn somebody’s head</strong> to be attractive in a romantic or sexual way:</div><ul class=\"examples\"><li><em>She turned heads whenever she walked into a room.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>turn (people’s) heads</strong> if something turns people’s heads, they are surprised by it:</div><ul class=\"examples\"><li><em>It did turn some heads when he moved back to the village.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>turn a profit</strong> <em>American English</em> to make a profit</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>turn a phrase</strong> to say something in a particular way:</div><ul class=\"examples\"><li><em>Cohen knows how to turn a phrase in his lyrics.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>[land]</strong> <span class=\"gram\">[transitive]</span> to break up soil so that it is ready for growing crops:</div><ul class=\"examples\"><li><em>a distant tractor turning the soil</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>[wood/metal]</strong> <span class=\"gram\">[transitive]</span> to shape a wooden or metal object using a special tool</div><div class=\"sense\"><span class=\"snum\">23</span> <strong>[milk]</strong> <span class=\"gram\">[intransitive]</span> <em>British English</em> if milk turns, it becomes sour</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[chance to do something]</strong> <span class=\"gram\">[countable]</span> the time when it is your chance, duty, or right to do something that each person in a group is doing one after the other SYN go<em>British English</em> RegisterIn everyday English, people often say that it is someone’s go in a game rather than turn:· Whose go is it now?· Wait until it’s your go.</div><ul class=\"examples\"><li><strong><em>turn to do something</strong>: Whose turn is it to set the table?</em></li><li><em>It’s your turn. Roll the dice.</em></li><li><em>I think it’s our turn to drive the kids to school this week.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>take turns</strong> (also take it in turns) <em>British English</em> if two or more people take turns doing work, using something etc, they do it one after the other, for example in order to share the work or play fairly:</div><ul class=\"examples\"><li><em>You’ll have to take turns on the swing.</em></li><li><strong><em>take turns doing something</strong>: The students were taking turns reading aloud.</em></li><li><strong><em>take turns in doing something<em>British English</em></strong>: We took turns in pushing the bike along.</em></li><li><strong><em>take turns to do something</strong>: Dan and I usually take turns to cook.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in turn</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> as a result of something:</div><ul class=\"examples\"><li><em>Interest rates were cut and, in turn, share prices rose.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> one after the other, especially in a particular order:</div><ul class=\"examples\"><li><em>Each of us in turn had to describe how alcohol had affected our lives.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[road]</strong> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>American English</em> a place where one road goes in a different direction from the one you are on SYN turning<em>British English</em>:</div><ul class=\"examples\"><li><em>According to the map we missed our turn back there.</em></li><li><strong><em>take the first/a wrong etc turn</strong> (=go along the first etc road): I think we took a wrong turn coming out of town. / Take the second turn on the left.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a curve in a road, path etc:</div><ul class=\"examples\"><li><em>There’s a sharp turn coming up ahead.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[change direction]</strong> <span class=\"gram\">[countable]</span> a change in the direction you are moving</div><ul class=\"examples\"><li><strong><em>make a left/right turn</strong>: Make a left turn at the station.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[change in events]</strong> <span class=\"gram\">[countable]</span> a sudden or unexpected change that makes a situation develop in a different way</div><ul class=\"examples\"><li><strong><em>take a dramatic/fresh/different etc turn</strong>: From then on, our fortunes took a downward turn. / My career had already taken a new turn. / The president was stunned by the sudden turn of events.</em></li><li><strong><em>take a turn for the worse/better</strong>: Two days after the operation, Dad took a turn for the worse.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>the turn of the century/year</strong> the beginning of a new century or year:</div><ul class=\"examples\"><li><em>the short period from the turn of the century until World War One</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>at every turn</strong> happening again and again, especially in an annoying way:</div><ul class=\"examples\"><li><em>problems that presented themselves at every turn</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[act of turning something]</strong> <span class=\"gram\">[countable]</span> the act of turning something completely around a fixed point:</div><ul class=\"examples\"><li><em>I gave the screw another two or three turns.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>by turns</strong> changing from one quality, feeling etc to another:</div><ul class=\"examples\"><li><em>By turns, a 14 year old is affectionate then aggressive, silent then outspoken.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>turn of phrase</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the ability to say things in a clever or funny way:</div><ul class=\"examples\"><li><em>Kate has a colourful turn of phrase.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a particular way of saying something <em>SYN expression</em>:</div><ul class=\"examples\"><li><em>What a strange turn of phrase!</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>speak/talk out of turn</strong> to say something you should not say in a particular situation, especially because you do not have enough authority to say it:</div><ul class=\"examples\"><li><em>I’m sorry if I spoke out of turn, Major Karr.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>do somebody a good/bad turn</strong> to do something that is helpful or unhelpful for someone:</div><ul class=\"examples\"><li><em>You did me a good turn by driving Max home last night.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>one good turn deserves another</strong> used to say that if someone does something nice for you, you should do something nice for them</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>turn of mind</strong> the particular way that someone usually thinks or feels</div><ul class=\"examples\"><li><strong><em>an academic/practical etc turn of mind</strong>: youngsters with an independent turn of mind</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>on the turn</strong> <em>British English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if the tide is on the turn, the sea is starting to come in or go out</div><div class=\"subsense\"><span class=\"subnum\">b)</span> starting to change, or in the process of changing:</div><ul class=\"examples\"><li><em>Hopefully my luck was on the turn.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> if milk, fish, or other food is on the turn, it is no longer fresh</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>turn of speed</strong> <em>British English</em> a sudden increase in your speed, or the ability to increase your speed suddenly:</div><ul class=\"examples\"><li><em>He’s a top goalkicker with a surprising turn of speed.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>be done to a turn</strong> <em>British English</em> to be perfectly cooked</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>take a turn in/on etc something</strong> <em>old-fashioned</em> to walk somewhere for pleasure</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>give somebody a turn</strong> <em>old-fashioned</em> to frighten someone</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>have a turn</strong> <em>British English</em> <em>old-fashioned</em> to feel slightly ill</div></div></div>","7245":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> turn‧out</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɜːnaʊt $ ˈtɜːrn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular]</span> the number of people who vote in an election → turn out</div><ul class=\"examples\"><li><strong><em>high/low turnout</strong>: the low turn-out of 54 percent in the March elections</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> the number of people who go to a party, meeting, or other organized event:</div><ul class=\"examples\"><li><em>I was disappointed by the turn-out for our home match.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>American English</em> a place at the side of a narrow road where cars can wait to let others pass</div></div>","7246":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> turn‧o‧ver</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɜːnˌəʊvə $ ˈtɜːrnˌoʊvər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> <em>British English</em> the amount of business done during a particular period ► see thesaurus at profit</div><ul class=\"examples\"><li><strong><em>turnover of</strong>: The illicit drugs industry has an annual turnover of some £200 billion.</em></li><li><strong><em>turnover rose/fell</strong>: Turnover rose 9%.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular, uncountable]</span> the rate at which a particular kind of goods is sold</div><ul class=\"examples\"><li><strong><em>turnover of</strong>: Tri-Star’s fast turnover of stock</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular, uncountable]</span> the rate at which people leave an organization and are replaced by others</div><ul class=\"examples\"><li><strong><em>turnover of</strong>: Low pay accounts for the high turnover.</em></li><li><strong><em>staff/labour turnover</strong>: a high degree of labour turnover among women</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a small fruit pie:</div><ul class=\"examples\"><li><em>an apple turnover</em></li></ul></div>","7247":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tur‧tle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɜːtl $ ˈtɜːrtl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a reptile that lives mainly in water and has a soft body covered by a hard shell</div><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> any reptile that has a hard shell covering its body, for example a tortoise</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>turn turtle</strong> a ship or boat that turns turtle turns upside down</div></div>","7248":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tu‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtjuːtə $ ˈtuːtər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who gives private lessons to one student or a small group, and is paid directly by them: ► see thesaurus at teacher</div><ul class=\"examples\"><li><em>The children were educated at home by a succession of tutors.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a teacher in a British university or college → tutorial:</div><ul class=\"examples\"><li><em>She was my tutor at Durham.</em></li></ul></div>","7249":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> tu‧to‧ri‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /tjuːˈtɔːriəl $ tuː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a period of teaching and discussion with a tutor, especially in a British university:</div><ul class=\"examples\"><li><em>the tutorial system</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a computer program that is designed to teach you how to use another program</div></div>","7250":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˌtiː ˈviː◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">television</div><ul class=\"examples\"><li><strong><em>on TV</strong>: I watched the film on TV.</em></li><li><strong><em>TV series/programme/show/station/channel etc</strong>: a TV series based on the novel</em></li><li><strong><em>cable/satellite TV</em></strong></li><li><em>a new TV set</em></li><li><em>He’s the top TV presenter for children’s programmes.</em></li></ul></div>","7251":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /twelv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\">the number 12 → dozen:</div><ul class=\"examples\"><li><em>He received a twelve-month jail sentence.</em></li><li><em>Come at twelve (=12 o&#x27;clock).</em></li><li><em>Their son Dylan is twelve (=12 years old).</em></li></ul></div>","7252":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> twen‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtwenti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the number 20:</div><ul class=\"examples\"><li><em>a small village twenty miles from Nairobi</em></li><li><em>I’m nearly twenty (=20 years old).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the twenties</strong> <span class=\"gram\">[plural]</span> (also the 20s, the 1920s) the years from 1920 to 1929:</div><ul class=\"examples\"><li><em>In the twenties the business expanded.</em></li><li><strong><em>the early/mid/late twenties</strong>: The photograph was taken in the late twenties.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be in your twenties</strong> to be aged between 20 and 29</div><ul class=\"examples\"><li><strong><em>early/mid/late twenties</strong>: She was in her early twenties when I met her.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in the twenties</strong> if the temperature is in the twenties, it is between 20 degrees and 29 degrees</div><ul class=\"examples\"><li><strong><em>in the low/mid/high twenties</strong>: a warm day, with temperatures in the low twenties</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a piece of paper money that is worth £20 or $20:</div><ul class=\"examples\"><li><em>I offered the driver a twenty.</em></li></ul></div>","7253":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /twaɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> two times:</div><ul class=\"examples\"><li><em>He was questioned by police twice yesterday.</em></li><li><strong><em>twice a day/week/year etc</strong> (=two times in the same day, week etc): Letters were delivered twice a week only.</em></li><li><em>None of our dinner menus are exactly the same twice over.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> two times more, bigger, better etc than something else</div><ul class=\"examples\"><li><strong><em>twice as many/much (as something)</strong>: They employ 90 people, twice as many as last year.</em></li><li><strong><em>twice as high/big/large etc (as something)</strong>: Interest rates are twice as high as those of our competitors.</em></li><li><strong><em>twice the size/number/rate/amount etc</strong>: an area twice the size of Britain</em></li></ul></div>","7254":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /twɪɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small very thin stem of wood that grows from a branch on a tree</div></div>","7255":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> twi‧light</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtwaɪlaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the small amount of light in the sky as the day ends</div><ul class=\"examples\"><li><strong><em>in the twilight</strong>: The end of the cigarette glowed in the twilight.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the time when day is just starting to become night <em>SYN dusk</em></div><ul class=\"examples\"><li><strong><em>at twilight</strong>: romantic walks along the beach at twilight</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> the period just before the end of the most active part of someone’s life</div><ul class=\"examples\"><li><strong><em>twilight of</strong>: in the twilight of her acting career</em></li><li><em>Depression in the twilight years (=the last years of your life) is usually related to illness.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>twilight world</strong> <em>literary</em> a strange situation involving mystery, dishonesty etc</div><ul class=\"examples\"><li><strong><em>twilight of</strong>: the twilight world of espionage</em></li></ul></div>","7256":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /twɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">one of two children born at the same time to the same mother:</div><ul class=\"examples\"><li><em>The twins are now eight months old.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to describe one of two children who are twins</div><ul class=\"examples\"><li><strong><em>twin sister/brother</strong>: Meet my twin sister.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to describe two things that happen at the same time and are related to each other:</div><ul class=\"examples\"><li><em>the twin problems of poverty and unemployment</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>twin room/bedroom</strong> a room that contains two single beds:</div><ul class=\"examples\"><li><em>All the twin rooms have private bathrooms.</em></li></ul></div></div>","7257":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /twɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[move]</strong> <span class=\"gram\">[intransitive, transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to turn a part of your body around or change your position by turning:</div><ul class=\"examples\"><li><em>He twisted his head slightly, and looked up at her.</em></li><li><strong><em>twist round/around</strong>: She twisted round, so that she could see the dog better.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if you twist your mouth or features, you smile in an unpleasant way or look angry, disapproving etc:</div><ul class=\"examples\"><li><em>His mouth twisted in a humourless smile.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[bend]</strong> <span class=\"gram\">[transitive]</span> to bend or turn something, such as wire, hair, or cloth, into a particular shape</div><ul class=\"examples\"><li><strong><em>twist something into something</strong>: She twisted her handkerchief into a knot.</em></li><li><strong><em>twist something together</strong>: Twist the two ends of the wire together.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[wind]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to wind something around or through an object</div><ul class=\"examples\"><li><strong><em>twist something round/around/through etc something</strong>: She twisted a silk scarf round her neck. / Ann twisted some daisies through Katherine’s thick brown hair.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[turn]</strong> <span class=\"gram\">[transitive]</span> to turn something in a circle using your hand</div><ul class=\"examples\"><li><strong><em>twist something off (something)</strong>: Jack twisted the cap off the bottle.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[road/river]</strong> <span class=\"gram\">[intransitive]</span> if a road, river etc twists, it changes direction in a series of curves:</div><ul class=\"examples\"><li><em>The road twisted between spectacular mountains.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[words]</strong> <span class=\"gram\">[transitive]</span> to change the true or intended meaning of a statement, especially in order to get some advantage for yourself:</div><ul class=\"examples\"><li><em>He’s always trying to twist my words and make me look bad.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>twist your ankle/wrist/knee</strong> to hurt your wrist etc by pulling or turning it too suddenly while you are moving: ► see thesaurus at hurt</div><ul class=\"examples\"><li><em>Harriet slipped on the stairs and twisted her ankle.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>twist and turn</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if a path, road, stream etc twists and turns, it has a lot of bends in it:</div><ul class=\"examples\"><li><em>The river twists and turns through the green fields.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a person or animal twists and turns, they make twisting movements</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>twist somebody’s arm</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>informal</em> to persuade someone to do something they do not want to do:</div><ul class=\"examples\"><li><em>No one twisted my arm about coming to see you.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to bend someone’s arm upwards behind their back in order to hurt them:</div><ul class=\"examples\"><li><em>The policeman twisted my arm behind me and arrested me.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an unexpected feature or change in a situation or series of events</div><ul class=\"examples\"><li><strong><em>a new/cruel/unexpected/strange etc twist</strong>: The robbery took a deadly new twist as the robber pulled out a gun. / an unexpected twist in the plot</em></li><li><em>By an amazing twist of fate, we met again in Madrid five years later.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a twisting action or movement:</div><ul class=\"examples\"><li><em>He smiled, a slow cynical twist of his lips.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a bend in a river or road</div><div class=\"sense\"><span class=\"snum\">4</span> a small piece of something that is twisted into a particular shape</div><ul class=\"examples\"><li><strong><em>twist of</strong>: a twist of lemon</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the twist</strong> a popular fast dance from the 1960s in which you twist your body from side to side</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>round the twist</strong> <em>British English</em> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> crazy:</div><ul class=\"examples\"><li><em>‘The woman’s mad,’ she told herself. ‘She’s round the twist.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> very angry</div></div></div>","7258":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> twist‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtwɪstɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something twisted has been bent in many directions or turned many times, so that it has lost its original shape:</div><ul class=\"examples\"><li><em>the plane’s twisted wreckage</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> seeming to enjoy things that are cruel or shocking, in a way that is not normal <em>SYN sick</em>:</div><ul class=\"examples\"><li><em>Whoever sent those letters has a twisted mind.</em></li></ul></div>","7259":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /tuː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the number 2:</div><ul class=\"examples\"><li><em>I’ll be away for almost two weeks.</em></li><li><em>We have to be there by two (=two o&#x27;clock).</em></li><li><em>His family moved to Australia when he was two (=two years old).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>in twos</strong> in groups of two people or things: → twosome</div><ul class=\"examples\"><li><em>I’d like you to line up in twos, please.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>put two and two together</strong> to guess the meaning of something you have heard or seen:</div><ul class=\"examples\"><li><em>I saw him leaving her house and I put two and two together.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>that makes two of us</strong> <em>spoken</em> used to tell someone that you are in the same situation and feel the same way:</div><ul class=\"examples\"><li><em>‘But I don’t know anything about children!’ ‘Well, that makes two of us.’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>two can play at that game</strong> <em>spoken</em> used to tell someone that they will not have an advantage over you by doing something because you can do it too</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>a year/a week/a moment/an hour etc or two</strong> <em>spoken</em> one or a few years, weeks etc</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>two sides of the same coin</strong> used to talk about two ways of looking at the same situation</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>two heads are better than one</strong> used to say that two people are more likely to solve a problem or think of an idea than one person working alone</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>be in two minds (about something)</strong> <em>British English</em>, be of two minds (about something)<em>American English</em> to be unable to decide what to do, or what you think about something:</div><ul class=\"examples\"><li><em>I was in two minds about whether to go with him.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>two cents (worth)</strong> <em>American English</em> <em>informal</em> your opinion or what you want to say about a subject:</div><ul class=\"examples\"><li><em>Everyone had to put in their two cents worth.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>two’s company, three’s a crowd</strong> used to say that it is better to leave two people alone to spend time with each other</div></div>","7260":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌtwo-diˈmensional</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> flat:</div><ul class=\"examples\"><li><em>a two-dimensional shape</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a two-dimensional character in a book, play etc does not seem like a real person</div></div>","7261":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> one member of a group of people or things that have similar features or qualities GRAMMAR: Countable or uncountable?Type is a countable noun and should be plural after words such as ‘these’, ‘those’, and ‘many’: · this type of building· these types of building ✗Don’t say: these type of building</div><ul class=\"examples\"><li><strong><em>of this/that/each etc type</strong>: I’ve already seen a few movies of this type.</em></li><li><strong><em>type of</strong>: What type of music do you like? / There are two main types of sleep.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> a person who has, or seems to have, a particular character:</div><ul class=\"examples\"><li><em>Jo’s not really the sporty type.</em></li><li><em>Beth is not the type to make a fuss.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be somebody’s type</strong> <em>especially spoken</em> to be the kind of person someone is sexually attracted to:</div><ul class=\"examples\"><li><em>He wasn’t my type really.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> printed letters:</div><ul class=\"examples\"><li><em>italic type</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable, uncountable]</span> a small block with a raised letter on it that is used to print with, or a set of these</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to write something using a computer or a typewriter:</div><ul class=\"examples\"><li><em>He types with two fingers.</em></li><li><em>Type your password, then press ‘Return’.</em></li><li><strong><em>type something up</strong> (=type a copy of something written by hand, in note form, or recorded): I went home to type up the report.</em></li><li><strong><em>type something in</strong> (=write information on a computer): Please wait while I type in your details.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>technical</em> to find out what group something such as blood, cells, or a disease belong to:</div><ul class=\"examples\"><li><em>DNA typing</em></li></ul></div></div>","7262":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> typ‧i‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɪpɪkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having the usual features or qualities of a particular group or thing:</div><ul class=\"examples\"><li><em>typical British weather</em></li><li><strong><em>typical of</strong>: This painting is typical of his work.</em></li><li><em>This advertisement is a typical example of their marketing strategy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> happening in the usual way:</div><ul class=\"examples\"><li><em>On a typical day, our students go to classes from 7.30 am to 1 pm.</em></li><li><em>Try calculating your budget for a typical week.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> behaving in the way that you expect:</div><ul class=\"examples\"><li><em>Bennett accepted the award with typical modesty.</em></li><li><strong><em>it is typical of somebody to do something</strong>: It’s not typical of Gill to be so critical.</em></li><li><em>Mr Stevens’ appointment was a typical case of promoting a man beyond his level of competence.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>typical!</strong> <em>spoken</em> used to show that you are annoyed when something bad happens again, or when someone does something bad again</div></div>","7263":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> typ‧i‧cally</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtɪpɪkli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a way that a person or group is generally believed to behave:</div><ul class=\"examples\"><li><em>Typically, he didn’t even bother to tell anyone he was going.</em></li><li><em>Al was his typically cheerful self again.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that shows the usual or expected features of someone or something:</div><ul class=\"examples\"><li><em>a delightful, typically Dutch hotel</em></li><li><em>The male of the species is typically smaller than the female.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> in the way that a particular type of thing usually happens <em>SYN generally</em>:</div><ul class=\"examples\"><li><em>Women in developing countries typically have their first child when they are very young.</em></li><li><em>I typically get around 30 emails a day.</em></li></ul></div>","7264":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ty‧rant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈtaɪərənt $ ˈtaɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a ruler who has complete power and uses it in a cruel and unfair way:</div><ul class=\"examples\"><li><em>The country had long been ruled by tyrants.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who has power over other people, and uses it cruelly or unfairly:</div><ul class=\"examples\"><li><em>My headmaster was a real tyrant.</em></li></ul></div>","7265":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /taɪə $ taɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a thick rubber ring that fits around the wheel of a car, bicycle etc: → spare tyre</div><ul class=\"examples\"><li><em>I had a flat tyre (=all the air went out of it) on the way home.</em></li><li><em>The spare tyre&#x27;s in the boot.</em></li><li><strong><em>front/rear/back tyre</strong>: a punctured front tyre</em></li></ul></div>"};